INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38777, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏は、ベランダが野菜を育てるのが楽しい。", "corrected_sentence": "夏は、ベランダで野菜を育てるのが楽しい。", "error_description": "「育てる」の場所はで格で示す。ベランダが（が格）にすると、ベランダが育てる主体になり意味が崩れる。正しくはベランダで。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38777, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "休日は、ベランダを鉢植えを並べて楽しむ。", "corrected_sentence": "休日は、ベランダに鉢植えを並べて楽しむ。", "error_description": "「並べる」の場所はに格で示す。ベランダを（を格）にすると、ベランダを並べる対象のように読まれ文が崩れる。正しくはベランダに。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38778, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「衛生に気をつけて」の「に」。気をつける対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語の形だが、「気をつける」には「に」が要るので、ここでは合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。「衛生で気をつける」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「衛生へ気をつけて」は対象を示せず不自然。"}], "correct_answer": "に", "explanations": {"に": "「衛生に気をつけて」の「に」。気をつける対象を示す。", "を": "「を」は目的語の形だが、「気をつける」には「に」が要るので、ここでは合わない。", "で": "「で」は場所や手段を表す。「衛生で気をつける」は意味が通らない。", "へ": "「へ」は方向を表す。「衛生へ気をつけて」は対象を示せず不自然。"}, "error_tags": {"を": "目的語（気をつけるの対象には不適）", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38778, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「衛生が悪いと」の「が」。「悪い」の主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は条件や相手を表すが、「衛生と悪いと」では主語が成り立たず意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「衛生へ悪い」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表す。「衛生より悪い」では比べる対象が示せず、文の主語も決まらない。"}], "correct_answer": "が", "explanations": {"が": "「衛生が悪いと」の「が」。「悪い」の主語を示す。", "と": "「と」は条件や相手を表すが、「衛生と悪いと」では主語が成り立たず意味が通らない。", "へ": "「へ」は方向を表す。「衛生へ悪い」は意味が通らない。", "より": "「より」は比較を表す。「衛生より悪い」では比べる対象が示せず、文の主語も決まらない。"}, "error_tags": {"と": "条件・相手（主語が成り立たない）", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38778, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "体のことを清潔にしたり、病気にならないようにすること。", "primary_collocate": null, "pronunciation": "えいせい", "ipa": "eːseː", "syllable_count": 4, "sentences": [{"text": "食事の前に手を洗うのは、衛生のためにも大切だ。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "食事[しょくじ]の前[まえ]に手[て]を洗[あら]うのは、衛生[えいせい]のためにも大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "衛生に気をつけて、毎日お風呂に入る。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "衛生[えいせい]に気[き]をつけて、毎日[まいにち]お風呂[ふろ]に入[はい]る。", "sentence_source": "generated"}, {"text": "夏は汗をこまめにふくなど、体の衛生に気をつけている。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "夏は汗[あせ]をこまめにふくなど、体の衛生[えいせい]に気[き]をつけている。", "sentence_source": "generated"}, {"text": "衛生を守らないと、病気になりやすい。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "衛生[えいせい]を守[まも]らないと、病気[びょうき]になりやすい。", "sentence_source": "generated"}, {"text": "外から帰ったら必ず手を洗うなど、体の衛生には特に注意しています。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "外[そと]から帰[かえ]ったら必[かなら]ず手[て]を洗[あら]うなど、体[からだ]の衛生[えいせい]には特[とく]に注意[ちゅうい]しています。", "sentence_source": "generated"}, {"text": "旅行先では、手洗いやうがいなどで体の衛生を保つように心がけていた。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "旅行先[りょこうさき]では、手洗[てあら]いやうがいなどで体[からだ]の衛生[えいせい]を保[たも]つように心[こころ]がけていた。", "sentence_source": "generated"}, {"text": "先生は、歯をみがくことも衛生の一つだと教えてくれた。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "先生[せんせい]は、歯[は]をみがくことも衛生[えいせい]の一[ひと]つだと教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "衛生が悪いと、ばい菌がふえて病気の原因になる。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "衛生[えいせい]が悪[わる]いと、ばい菌[きん]がふえて病気[びょうき]の原因[げんいん]になる。", "sentence_source": "generated"}, {"text": "手術をする人は、衛生に十分気をつけなければならない。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]をする人[ひと]は、衛生[えいせい]に十分[じゅうぶん]気[き]をつけなければならない。", "sentence_source": "generated"}, {"text": "衛生を考えて、タオルは毎日取りかえている。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "衛生[えいせい]を考[かんが]えて、タオルは毎日[まいにち]取[と]りかえている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "衛生", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "体を清潔にして病気を防ぐこと（手洗い・入浴・歯みがきなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: みがく (Zipf 1.93)','sentence 9 above tier T3: contains vocabulary far above tier T3: 取りかえ (Zipf 1.48)']::text[], '67562c68-4c35-496f-99ad-14c6fca363a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38778, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衛生", "is_correct": true, "explanation": "「衛生のためにも大切」は、手洗いが体を清潔にして病気を防ぐ理由になるので自然に入る。"}, {"text": "通勤", "is_correct": false, "explanation": "「通勤」は会社や学校へ行くことで、手洗いの理由として文が成り立たない。"}, {"text": "読書", "is_correct": false, "explanation": "「読書」は本を読むことで、手洗いの理由にはならず文に合わない。"}, {"text": "会計", "is_correct": false, "explanation": "「会計」はお金の支払いや計算のことで、手洗いの目的として意味が通らない。"}], "explanations": {"衛生": "「衛生のためにも大切」は、手洗いが体を清潔にして病気を防ぐ理由になるので自然に入る。", "通勤": "「通勤」は会社や学校へ行くことで、手洗いの理由として文が成り立たない。", "読書": "「読書」は本を読むことで、手洗いの理由にはならず文に合わない。", "会計": "「会計」はお金の支払いや計算のことで、手洗いの目的として意味が通らない。"}, "sentence_index": 0, "correct_answer": "衛生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この衛生は地球の周りを回りながら、天気の写真を送ってくる。", "explanation": "ここは「衛星」（天体の周りを回る人工物）の意味。「衛生」は清潔にして病気を防ぐことで、天体の意味はないので合わない。"}, {"text": "彼は身だしなみが衛生で、いつも服がきれいだ。", "explanation": "ここは「清潔」の意味（見た目がきれい）。身だしなみには「清潔」を使い、「衛生」は病気を防ぐための清潔さを指すので合わない。"}, {"text": "毎日運動すると、衛生になれる。", "explanation": "ここは「健康」の意味。「衛生」は清潔にして病気を防ぐ取り組みを指し、人の健康状態になるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38778, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衛生", "is_correct": true, "explanation": "歯みがきは体を清潔にして病気を防ぐことの一例なので、「衛生の一つ」に入る。"}, {"text": "寛容", "is_correct": false, "explanation": "「寛容」は心が広く許すことで、歯みがきの一つとは言えず文が成り立たない。"}, {"text": "憶測", "is_correct": false, "explanation": "「憶測」は根拠のない推測で、歯みがきの一つという言い方は成り立たない。"}, {"text": "空想", "is_correct": false, "explanation": "「空想」は頭の中で思い描くことで、歯みがきを空想の一つとは言わない。"}], "explanations": {"衛生": "歯みがきは体を清潔にして病気を防ぐことの一例なので、「衛生の一つ」に入る。", "寛容": "「寛容」は心が広く許すことで、歯みがきの一つとは言えず文が成り立たない。", "憶測": "「憶測」は根拠のない推測で、歯みがきの一つという言い方は成り立たない。", "空想": "「空想」は頭の中で思い描くことで、歯みがきを空想の一つとは言わない。"}, "sentence_index": 6, "correct_answer": "衛生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもが衛生に育つよう、栄養のある食事を用意する。", "explanation": "ここは「健やか」の意味（心身が元気に育つ）。「衛生」は清潔にして病気を防ぐことで、子どもの育ちの良さは表さないので合わない。"}, {"text": "寝不足で衛生を崩し、熱が出た。", "explanation": "ここは「体調」の意味。「衛生」は清潔にして病気を防ぐ取り組みを指し、体の調子を崩すとは言わないので合わない。"}, {"text": "この店は衛生な経営で、利益も安定している。", "explanation": "ここは「健全」の意味（問題がなくしっかりした状態）。「衛生」は清潔さと病気の予防に関わる語で、経営の良し悪しには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38778, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風邪が流行る時期は、衛生を気をつけてうがいをする。", "corrected_sentence": "風邪が流行る時期は、衛生に気をつけてうがいをする。", "error_description": "「気をつける」は「〜に気をつける」と言うので、助詞は「に」。「衛生を」は誤りで、正しくは「衛生に気をつけて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38778, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家の中の衛生を保てため、週に一度は換気をする。", "corrected_sentence": "家の中の衛生を保つため、週に一度は換気をする。", "error_description": "「衛生を保つ」の「保つ」の形が誤り。「保つため」と動詞の形のまま「ため」に続ける。「保てため」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38779, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「衛生の管理」の「の」。「衛生」と「管理」を結んで一つの名詞句にする。"}, {"text": "を", "is_correct": false, "explanation": "「衛生を管理」は目的語の形だが、後ろの「管理がとても厳しい」とつながらず文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や対象を表す。「衛生に管理」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。「衛生で管理」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「衛生の管理」の「の」。「衛生」と「管理」を結んで一つの名詞句にする。", "を": "「衛生を管理」は目的語の形だが、後ろの「管理がとても厳しい」とつながらず文が崩れる。", "に": "「に」は方向や対象を表す。「衛生に管理」は意味が通らない。", "で": "「で」は場所や手段を表す。「衛生で管理」は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "方向・対象", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38779, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「衛生がよくなった」の「が」。「よくなる」の主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すが、「衛生と良くなった」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、「衛生へ良くなった」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、比べる対象がなく「衛生より良くなった」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「衛生がよくなった」の「が」。「よくなる」の主語を示す。", "と": "「と」は並列や相手を表すが、「衛生と良くなった」は意味が通らない。", "へ": "「へ」は方向を表すが、「衛生へ良くなった」は意味が通らない。", "より": "「より」は比較を表すが、比べる対象がなく「衛生より良くなった」は意味が通らない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38779, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "健康を保ち、病気を予防するために、清潔にすることや環境を整えること。", "primary_collocate": null, "pronunciation": "えいせい", "ipa": "eːseː", "syllable_count": 4, "sentences": [{"text": "町の衛生を保つために、毎週みんなでごみを拾っている。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "町[まち]の衛生[えいせい]を保[たも]つために、毎週[まいしゅう]みんなでごみを拾[ひろ]っている。", "sentence_source": "generated"}, {"text": "食品を作る工場では、衛生の管理がとても厳しい。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "食品[しょくひん]を作[つく]る工場[こうじょう]では、衛生[えいせい]の管理[かんり]がとても厳[きび]しい。", "sentence_source": "generated"}, {"text": "トイレが汚れていると、店全体の衛生が疑われる。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "トイレが汚[よご]れていると、店全体[みせぜんたい]の衛生[えいせい]が疑[うたが]われる。", "sentence_source": "generated"}, {"text": "病院は衛生を保ち、感染が広がらないようにしている。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "病院[びょういん]は衛生[えいせい]を保[たも]ち、感染[かんせん]が広[ひろ]がらないようにしている。", "sentence_source": "generated"}, {"text": "衛生を守るため、調理する人はマスクをつける。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "衛生[えいせい]を守[まも]るため、調理[ちょうり]する人[ひと]はマスクをつける。", "sentence_source": "generated"}, {"text": "川の水がよごれて、地域の衛生が悪くなった。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]がよごれて、地域[ちいき]の衛生[えいせい]が悪[わる]くなった。", "sentence_source": "generated"}, {"text": "保健所の人が、飲食店の衛生を調べに来た。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "保健所[ほけんじょ]の人[ひと]が、飲食店[いんしょくてん]の衛生[えいせい]を調[しら]べに来[き]た。", "sentence_source": "generated"}, {"text": "衛生がよくなったおかげで、病気にかかる人が減った。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "衛生[えいせい]がよくなったおかげで、病気[びょうき]にかかる人[ひと]が減[へ]った。", "sentence_source": "generated"}, {"text": "学校では、教室の衛生を保つために毎日そうじをする。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "学校[がっこう]では、教室[きょうしつ]の衛生[えいせい]を保[たも]つために毎日[まいにち]そうじをする。", "sentence_source": "generated"}, {"text": "衛生の問題を解決するには、国の助けも必要だ。", "target_word": "衛生", "complexity_tier": "T3", "furigana": "衛生[えいせい]の問題[もんだい]を解決[かいけつ]するには、国[くに]の助[たす]けも必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "衛生", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "健康維持と病気予防のために環境や施設を清潔に保つこと（町・工場・店・病院の管理）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67562c68-4c35-496f-99ad-14c6fca363a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38779, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衛生", "is_correct": true, "explanation": "「町の衛生」は町の環境の清潔さを指し、ごみ拾いで保つ対象として自然に入る。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は保つものではなく、ごみ拾いの目的として意味が通らない。"}, {"text": "会計", "is_correct": false, "explanation": "「会計」はお金の管理で、ごみ拾いで保つものではない。"}, {"text": "祝日", "is_correct": false, "explanation": "「祝日」は休みの日で、保つ対象にはならない。"}], "explanations": {"衛生": "「町の衛生」は町の環境の清潔さを指し、ごみ拾いで保つ対象として自然に入る。", "天気": "「天気」は保つものではなく、ごみ拾いの目的として意味が通らない。", "会計": "「会計」はお金の管理で、ごみ拾いで保つものではない。", "祝日": "「祝日」は休みの日で、保つ対象にはならない。"}, "sentence_index": 0, "correct_answer": "衛生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "衛生が負傷兵の手当てをして、戦場を走り回った。", "explanation": "ここは「衛生兵」の意味（負傷兵の手当てをする兵士）。「衛生」は人を指さず、手当ても行わないので合わない。"}, {"text": "この衛生は、毎晩町の上空を一周している。", "explanation": "ここは「衛星」（惑星の周りを回る天体）の意味。「衛生」は清潔にして病気を防ぐことで、天体のことは言わないので合わない。"}, {"text": "毎日運動すると、衛生になれる。", "explanation": "ここは「健康」の意味。「衛生」は清潔にして病気を防ぐ取り組みを指し、体の健康状態になるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38779, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衛生", "is_correct": true, "explanation": "保健所が飲食店の清潔さや環境を調べる、という内容に合うので自然に入る。"}, {"text": "天候", "is_correct": false, "explanation": "「天候」は保健所が調べに来る対象ではなく、文の内容が成り立たない。"}, {"text": "運賃", "is_correct": false, "explanation": "「運賃」は保健所が調べるものではなく、意味が通らない。"}, {"text": "歌詞", "is_correct": false, "explanation": "保健所の人が歌詞を調べに来るという内容は成り立たない。"}], "explanations": {"衛生": "保健所が飲食店の清潔さや環境を調べる、という内容に合うので自然に入る。", "天候": "「天候」は保健所が調べに来る対象ではなく、文の内容が成り立たない。", "運賃": "「運賃」は保健所が調べるものではなく、意味が通らない。", "歌詞": "保健所の人が歌詞を調べに来るという内容は成り立たない。"}, "sentence_index": 6, "correct_answer": "衛生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "衛生をつけるため、毎朝公園を走っている。", "explanation": "ここは「体力」の意味（体の力）。「衛生」は清潔と病気の予防に関わる語で、力を身につける意味はないので合わない。"}, {"text": "衛生接種を受けて、病気に備える。", "explanation": "ここは「予防」の意味（病気になる前に防ぐこと）。「衛生」は清潔さを保つ取り組みを指し、接種の名前には使わないので合わない。"}, {"text": "町は衛生な財政を保っている。", "explanation": "ここは「健全」の意味（問題がなくしっかりしていること）。「衛生」は清潔さや病気の予防に関わる語で、財政の状態には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38779, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の衛生が守るため、ごみ箱を増やす。", "corrected_sentence": "町の衛生を守るため、ごみ箱を増やす。", "error_description": "「衛生を守る」の「を」が「が」になっている。「衛生」は守られる対象なので目的語の「を」が必要で、「衛生が守る」は意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38779, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "住民が衛生を破れば、病気は減る。", "corrected_sentence": "住民が衛生を守れば、病気は減る。", "error_description": "「衛生を守る」の「守る」が「破る」になっている。「衛生」は守るものなので、「破る」とは言わず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38780, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「局所に降る」の「に」は、雨が降る場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」。場所を表せず、「局所を降る」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。降る場所を表す文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「局所と降る」は成り立たない。〈と〉は並列や相手を示す。"}], "correct_answer": "に", "explanations": {"に": "「局所に降る」の「に」は、雨が降る場所を示す。", "を": "目的語を示す「を」。場所を表せず、「局所を降る」は不自然。", "へ": "方向を示す「へ」。降る場所を表す文には合わない。", "と": "「局所と降る」は成り立たない。〈と〉は並列や相手を示す。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全体", "is_correct": true, "explanation": "局所の一部分に対し、道路などの全体を表す対義語。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時期の区分で、局所の対義語ではない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は通信の手段で、局所の対義語ではない。"}, {"text": "外国", "is_correct": false, "explanation": "国の外を指す語で、局所との対義関係はない。"}], "correct_answer": "全体", "explanations": {"全体": "局所の一部分に対し、道路などの全体を表す対義語。", "季節": "季節は時期の区分で、局所の対義語ではない。", "電話": "電話は通信の手段で、局所の対義語ではない。", "外国": "国の外を指す語で、局所との対義関係はない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38780, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「局所にとどまる」の「に」は、とどまる場所を示す。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」。とどまる場所は表せず、「局所よりとどまる」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「局所のとどまる」の形にはならず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す「と」。とどまる場所を表せず、文が不自然になる。"}], "correct_answer": "に", "explanations": {"に": "「局所にとどまる」の「に」は、とどまる場所を示す。", "より": "比較を示す「より」。とどまる場所は表せず、「局所よりとどまる」は成り立たない。", "の": "連体修飾の「の」。「局所のとどまる」の形にはならず、文が成り立たない。", "と": "相手や並列を示す「と」。とどまる場所を表せず、文が不自然になる。"}, "error_tags": {"より": "比較", "の": "連体修飾", "と": "相手"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全体", "is_correct": true, "explanation": "「局所」の狭い範囲に対し、場所の全てを表す対義語。"}, {"text": "中心", "is_correct": false, "explanation": "物事の真ん中を指す語。部分と全体の対比による対義関係にはならない。"}, {"text": "本部", "is_correct": false, "explanation": "組織の中枢の拠点を指す語。狭い範囲と全体の対義にはならない。"}, {"text": "社会", "is_correct": false, "explanation": "人々の集まりを指す語。場所の範囲の対義語にはならない。"}], "correct_answer": "全体", "explanations": {"全体": "「局所」の狭い範囲に対し、場所の全てを表す対義語。", "中心": "物事の真ん中を指す語。部分と全体の対比による対義関係にはならない。", "本部": "組織の中枢の拠点を指す語。狭い範囲と全体の対義にはならない。", "社会": "人々の集まりを指す語。場所の範囲の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38780, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある場所や時間の、ほんの一部だけのこと。", "primary_collocate": null, "pronunciation": "きょくしょ", "ipa": "kʲokɯɕo", "syllable_count": 3, "sentences": [{"text": "台風の影響で、局所に強い風が吹き、看板が倒れた。", "target_word": "局所", "complexity_tier": "T3", "furigana": "台風[たいふう]の影響[えいきょう]で、局所[きょくしょ]に強[つよ]い風[かぜ]が吹[ふ]き、看板[かんばん]が倒[たお]れた。", "sentence_source": "generated"}, {"text": "今日の雨は局所に降っただけで、隣の駅は晴れていた。", "target_word": "局所", "complexity_tier": "T3", "furigana": "今日[きょう]の雨[あめ]は局所[きょくしょ]に降[ふ]っただけで、隣[となり]の駅[えき]は晴[は]れていた。", "sentence_source": "generated"}, {"text": "痛みが体の局所にだけ出て、他の場所は何ともない。", "target_word": "局所", "complexity_tier": "T3", "furigana": "痛[いた]みが体[からだ]の局所[きょくしょ]にだけ出[で]て、他[ほか]の場所[ばしょ]は何[なん]ともない。", "sentence_source": "generated"}, {"text": "局所の工事なので、道路全体を閉鎖する必要はない。", "target_word": "局所", "complexity_tier": "T3", "furigana": "局所[きょくしょ]の工事[こうじ]なので、道路[どうろ]全体[ぜんたい]を閉鎖[へいさ]する必要[ひつよう]はない。", "sentence_source": "generated"}, {"text": "光は局所にだけ当たり、ほかの部分は暗いままだった。", "target_word": "局所", "complexity_tier": "T3", "furigana": "光[ひかり]は局所[きょくしょ]にだけ当[あ]たり、ほかの部分[ぶぶん]は暗[くら]いままだった。", "sentence_source": "generated"}, {"text": "木が枯れたのは局所に限られ、原因を調べている。", "target_word": "局所", "complexity_tier": "T3", "furigana": "木[き]が枯[か]れたのは局所[きょくしょ]に限[かぎ]られ、原因[げんいん]を調[しら]べている。", "sentence_source": "generated"}, {"text": "この映像は局所に限られた場面だけで、本当の流れは分からない。", "target_word": "局所", "complexity_tier": "T3", "furigana": "この映像[えいぞう]は局所[きょくしょ]に限[かぎ]られた場面[ばめん]だけで、本当[ほんとう]の流[なが]れは分[わ]からない。", "sentence_source": "generated"}, {"text": "火は局所にとどまっていたため、すぐに消すことができた。", "target_word": "局所", "complexity_tier": "T3", "furigana": "火[ひ]は局所[きょくしょ]にとどまっていたため、すぐに消[け]すことができた。", "sentence_source": "generated"}, {"text": "強い光を局所に当てると、その部分だけ温度が上がる。", "target_word": "局所", "complexity_tier": "T3", "furigana": "強[つよ]い光[ひかり]を局所[きょくしょ]に当[あ]てると、その部分[ぶぶん]だけ温度[おんど]が上[あ]がる。", "sentence_source": "generated"}, {"text": "夜の間、局所に霧が出て、車の運転が危なかった。", "target_word": "局所", "complexity_tier": "T3", "furigana": "夜[よる]の間[あいだ]、局所[きょくしょ]に霧[きり]が出[で]て、車[くるま]の運転[うんてん]が危[あぶ]なかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "局所", "label": "基本形"}, {"form": "局所的", "label": "形状詞形"}], "register": "書き言葉", "sense_fingerprint": "ある場所や時間の中の、ごく狭い一部分（天気・体・現場などの具体的な範囲）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e5117e-6210-437d-8c4a-90abcde11eb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38780, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "局所", "is_correct": true, "explanation": "ある場所の一部だけを指す「局所」。「風が吹く」範囲として合う。"}, {"text": "湯船", "is_correct": false, "explanation": "「湯船に強い風が吹く」は成り立たない。"}, {"text": "黒板", "is_correct": false, "explanation": "「黒板に強い風が吹く」は意味をなさない。"}, {"text": "人形", "is_correct": false, "explanation": "「人形に強い風が吹く」は不自然で、文の内容に合わない。"}], "explanations": {"局所": "ある場所の一部だけを指す「局所」。「風が吹く」範囲として合う。", "湯船": "「湯船に強い風が吹く」は成り立たない。", "黒板": "「黒板に強い風が吹く」は意味をなさない。", "人形": "「人形に強い風が吹く」は不自然で、文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "局所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議は終盤の局所に入った。", "explanation": "ここは〈局面〉の意味。局所は範囲を指す語で、会議の進行の段階は表さない。"}, {"text": "彼女の電話番号を、局所まで正確に覚えていた。", "explanation": "ここは〈局番〉の意味。局所は場所の範囲を指す語で、電話番号の区切りは表さない。"}, {"text": "市長が新しい局所を任命した。", "explanation": "ここは〈局長〉の意味。局所は範囲を指す語で、役職に人を任命する文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38780, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "局所", "is_correct": true, "explanation": "「局所に限られた場面」の形で、ごく狭い範囲を表す。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖に限られた場面」は意味をなさない。"}, {"text": "天井", "is_correct": false, "explanation": "「天井に限られた場面」は成り立たない。"}, {"text": "電池", "is_correct": false, "explanation": "「電池に限られた場面」は文脈に合わない。"}], "explanations": {"局所": "「局所に限られた場面」の形で、ごく狭い範囲を表す。", "砂糖": "「砂糖に限られた場面」は意味をなさない。", "天井": "「天井に限られた場面」は成り立たない。", "電池": "「電池に限られた場面」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "局所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火事で、局所の建物が全国に一斉に焼けた。", "explanation": "ここは〈広域〉の意味。局所は狭い範囲を指す語で、全国に一斉に広がる被害とは合わない。"}, {"text": "郵便局の局所が、手紙を届けてくれた。", "explanation": "ここは〈局員〉の意味。局所は場所の範囲を指す語で、郵便局で働く人は表さない。"}, {"text": "彼は新聞社の局所に、三年間勤めた。", "explanation": "ここは〈支局〉の意味。局所は場所の範囲を指す語で、新聞社の地方の拠点は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38780, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この事故は局所を限られ、被害は町全体には及ばなかった。", "corrected_sentence": "この事故は局所に限られ、被害は町全体には及ばなかった。", "error_description": "「限られる」は場所を「に」で示す。「局所を限られ」は誤りで、正しくは「局所に限られ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38780, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨は局所に集中するて、山あいの道だけが通行止めになった。", "corrected_sentence": "大雨は局所に集中して、山あいの道だけが通行止めになった。", "error_description": "「集中する」の連用形は「集中して」。「集中するて」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
