INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38781, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全身", "is_correct": true, "explanation": "体の一部を指す「局所」に対し、体全体を表す対義語。"}, {"text": "中心", "is_correct": false, "explanation": "物事の真ん中を指す語。部分と全体の対比による対義関係にはならない。"}, {"text": "本部", "is_correct": false, "explanation": "組織の中枢の拠点を指す語。体の範囲を表す「局所」の対義語にはならない。"}, {"text": "社会", "is_correct": false, "explanation": "人々の集まりを指す語。体の一部と全身の対比には合わない。"}], "correct_answer": "全身", "explanations": {"全身": "体の一部を指す「局所」に対し、体全体を表す対義語。", "中心": "物事の真ん中を指す語。部分と全体の対比による対義関係にはならない。", "本部": "組織の中枢の拠点を指す語。体の範囲を表す「局所」の対義語にはならない。", "社会": "人々の集まりを指す語。体の一部と全身の対比には合わない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38781, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の一部分や、限られた範囲だけを指すこと。", "primary_collocate": null, "pronunciation": "きょくしょ", "ipa": "kʲokɯɕo", "syllable_count": 3, "sentences": [{"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所の意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "局所", "complexity_tier": "T4", "furigana": "グローバルな金融[きんゆう]市場[しじょう]やサプライチェーンといった社会[しゃかい]経済的[けいざいてき]文脈[ぶんみゃく]において、個々[ここ]の企業[きぎょう]や投資家[とうしか]といったミクロな主体[しゅたい]による局所[きょくしょ]の意思決定[いしけってい]は、決[けっ]して単純[たんじゅん]な線形[せんけい]モデルでは捉[とら]えきれない。", "sentence_source": "generated"}, {"text": "全体を見ずに局所だけを見ると、問題の本当の原因を見落とす。", "target_word": "局所", "complexity_tier": "T3", "furigana": "全体[ぜんたい]を見[み]ずに局所[きょくしょ]だけを見[み]ると、問題[もんだい]の本当[ほんとう]の原因[げんいん]を見落[みお]とす。", "sentence_source": "generated"}, {"text": "その議論は局所にとどまり、全体の見直しには至らなかった。", "target_word": "局所", "complexity_tier": "T3", "furigana": "その議論[ぎろん]は局所[きょくしょ]にとどまり、全体[ぜんたい]の見直[みなお]しには至[いた]らなかった。", "sentence_source": "generated"}, {"text": "筆者は、局所に起きた出来事から社会全体を語るべきではないと述べた。", "target_word": "局所", "complexity_tier": "T3", "furigana": "筆者[ひっしゃ]は、局所[きょくしょ]に起[お]きた出来事[できごと]から社会[しゃかい]全体[ぜんたい]を語[かた]るべきではないと述[の]べた。", "sentence_source": "generated"}, {"text": "この主張は局所にだけ当てはまり、全体には当てはまらない。", "target_word": "局所", "complexity_tier": "T3", "furigana": "この主張[しゅちょう]は局所[きょくしょ]にだけ当[あ]てはまり、全体[ぜんたい]には当[あ]てはまらない。", "sentence_source": "generated"}, {"text": "局所に限られた問題ではなく、組織全体の問題だ。", "target_word": "局所", "complexity_tier": "T3", "furigana": "局所[きょくしょ]に限[かぎ]られた問題[もんだい]ではなく、組織[そしき]全体[ぜんたい]の問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "この理論は、全体ではなく局所の動きを説明するために作られた。", "target_word": "局所", "complexity_tier": "T3", "furigana": "この理論[りろん]は、全体[ぜんたい]ではなく局所[きょくしょ]の動[うご]きを説明[せつめい]するために作[つく]られた。", "sentence_source": "generated"}, {"text": "局所だけを直しても、システム全体の不具合は消えなかった。", "target_word": "局所", "complexity_tier": "T3", "furigana": "局所[きょくしょ]だけを直[なお]しても、システム全体[ぜんたい]の不具合[ふぐあい]は消[き]えなかった。", "sentence_source": "generated"}, {"text": "変化は局所にとどまらず、やがて全国に広がった。", "target_word": "局所", "complexity_tier": "T3", "furigana": "変化[へんか]は局所[きょくしょ]にとどまらず、やがて全国[ぜんこく]に広[ひろ]がった。", "sentence_source": "generated"}, {"text": "調査では、体の局所ではなく全身の状態を調べる必要がある。", "target_word": "局所", "complexity_tier": "T3", "furigana": "調査[ちょうさ]では、体[からだ]の局所[きょくしょ]ではなく全身[ぜんしん]の状態[じょうたい]を調[しら]べる必要[ひつよう]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "局所", "label": "基本形"}, {"form": "局所的", "label": "形状詞形"}], "register": "書き言葉", "sense_fingerprint": "全体に対する、物事の限られた一部分・狭い範囲（論じ方や見方の対象として）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e5117e-6210-437d-8c4a-90abcde11eb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38781, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "局所", "is_correct": true, "explanation": "「局所的な意思決定」の語幹にあたる「局所」。物事の一部分を指す意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「個々の企業による天気の意思決定」は意味をなさない。"}, {"text": "梱包", "is_correct": false, "explanation": "「梱包の意思決定」は文の内容に合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "「掃除の意思決定」は不自然で成り立たない。"}], "explanations": {"局所": "「局所的な意思決定」の語幹にあたる「局所」。物事の一部分を指す意味に合う。", "天気": "「個々の企業による天気の意思決定」は意味をなさない。", "梱包": "「梱包の意思決定」は文の内容に合わない。", "掃除": "「掃除の意思決定」は不自然で成り立たない。"}, "sentence_index": 0, "correct_answer": "局所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい局所が、町の交通の方針を決めた。", "explanation": "ここは〈局長〉の意味。局所は範囲を指す語で、人の役職は表さない。"}, {"text": "新しい局所の番号を、社員全員に知らせた。", "explanation": "ここは〈局番〉の意味。局所は範囲を指す語で、電話の番号の区切りは表さない。"}, {"text": "試合は終盤の局所を迎えた。", "explanation": "ここは〈局面〉の意味。局所は範囲を指す語で、試合の進行の段階は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38781, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "局所", "is_correct": true, "explanation": "「局所の動き」の形で、物事の一部分を指す。"}, {"text": "局所的", "is_correct": false, "explanation": "「局所的の動き」とは続かず、文法的に誤り。"}, {"text": "天井", "is_correct": false, "explanation": "建物の上の面を指す語で、「理論」が説明する「動き」の対象として意味が通らない。"}, {"text": "食卓", "is_correct": false, "explanation": "食事をする台を指す語で、「理論」が説明する「動き」の対象にならず、文が成り立たない。"}], "explanations": {"局所": "「局所の動き」の形で、物事の一部分を指す。", "局所的": "「局所的の動き」とは続かず、文法的に誤り。", "天井": "建物の上の面を指す語で、「理論」が説明する「動き」の対象として意味が通らない。", "食卓": "食事をする台を指す語で、「理論」が説明する「動き」の対象にならず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "局所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい局所が、町の図書館の本を整理した。", "explanation": "ここは〈局員〉の意味。局所は場所の範囲を指す語で、働く人は表さない。"}, {"text": "この病気は局所に広がり、全国で一度に流行した。", "explanation": "ここは〈広域〉の意味。局所は狭い範囲を指す語で、一度に広い地域へ流行が広がる文とは合わない。"}, {"text": "電話の局所を、家族全員で覚えた。", "explanation": "ここは〈局番〉の意味。局所は場所の範囲を指す語で、電話番号の区切りは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38781, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "全体を見ずに局所だけに見ると、大事な変化を見落とす。", "corrected_sentence": "全体を見ずに局所だけを見ると、大事な変化を見落とす。", "error_description": "「見る」の対象は「を」で示す。「局所だけに見る」は誤りで、正しくは「局所だけを見る」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38781, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "局所だけに直しても、会社全体の不具合は消えなかった。", "corrected_sentence": "局所だけを直しても、会社全体の不具合は消えなかった。", "error_description": "「直す」の対象は「を」で示す。「局所だけに直す」は誤りで、正しくは「局所だけを直す」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
