INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38782, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "かんたんで、むずかしくないこと。", "primary_collocate": null, "pronunciation": "かんい", "ipa": "kaɴi", "syllable_count": 3, "sentences": [{"text": "この機械は簡易な操作で動くので、初めての人でも迷いません。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "この機械[きかい]は簡易[かんい]な操作[そうさ]で動[うご]くので、初[はじ]めての人[ひと]でも迷[まよ]いません。", "sentence_source": "generated"}, {"text": "この作業は簡易な方法で済むので、すぐに終わりました。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "この作業[さぎょう]は簡易[かんい]な方法[ほうほう]で済[す]むので、すぐに終[お]わりました。", "sentence_source": "generated"}, {"text": "この機能は簡易な設定だけで使えるので、誰でもすぐに試せます。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "この機能[きのう]は簡易[かんい]な設定[せってい]だけで使[つか]えるので、誰[だれ]でもすぐに試[ため]せます。", "sentence_source": "generated"}, {"text": "子ども向けの本なので、内容は簡易にまとめてあります。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "子[こ]ども向[む]けの本[ほん]なので、内容[ないよう]は簡易[かんい]にまとめてあります。", "sentence_source": "generated"}, {"text": "初めは簡易な計算から始めると、苦手でも続けやすいです。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "初[はじ]めは簡易[かんい]な計算[けいさん]から始[はじ]めると、苦手[にがて]でも続[つづ]けやすいです。", "sentence_source": "generated"}, {"text": "先生は難しい理論を、簡易な図で説明してくれました。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "先生[せんせい]は難[むずか]しい理論[りろん]を、簡易[かんい]な図[ず]で説明[せつめい]してくれました。", "sentence_source": "generated"}, {"text": "この料理は簡易な手順で作れるので、初心者でも失敗しません。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "この料理[りょうり]は簡易[かんい]な手順[てじゅん]で作[つく]れるので、初心者[しょしんしゃ]でも失敗[しっぱい]しません。", "sentence_source": "generated"}, {"text": "この案内は簡易な表示にしてあるので、子どもでもすぐ理解できます。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "この案内[あんない]は簡易[かんい]な表示[ひょうじ]にしてあるので、子[こ]どもでもすぐ理解[りかい]できます。", "sentence_source": "generated"}, {"text": "外国から来た人のために、アプリを簡易な機能だけに絞りました。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "外国[がいこく]から来[き]た人[ひと]のために、アプリを簡易[かんい]な機能[きのう]だけに絞[しぼ]りました。", "sentence_source": "generated"}, {"text": "まずは簡易な方法で試して、慣れてから細かく調整します。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "まずは簡易[かんい]な方法[ほうほう]で試[ため]して、慣[な]れてから細[こま]かく調整[ちょうせい]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "簡易", "label": "語幹"}, {"form": "簡易な", "label": "連体形"}, {"form": "簡易で", "label": "連用形"}, {"form": "簡易だ", "label": "終止形"}], "register": "neutral", "sense_fingerprint": "言葉や内容がやさしく、むずかしくなくて分かりやすいこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6a65927-b447-4fa1-9765-03dbf2c9836d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38782, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "簡易", "is_correct": true, "explanation": "「操作が簡単で、初めての人でも迷わない」という文の内容に合う。"}, {"text": "頑丈", "is_correct": false, "explanation": "壊れにくさを表す語で、操作の手軽さは表せない。後半の「迷いません」ともつながらない。"}, {"text": "高価", "is_correct": false, "explanation": "値段が高いことを表すので、操作の性質としては文が通らない。"}, {"text": "豪華", "is_correct": false, "explanation": "派手で贅沢なことを表し、操作の性質には使えない。"}], "explanations": {"簡易": "「操作が簡単で、初めての人でも迷わない」という文の内容に合う。", "頑丈": "壊れにくさを表す語で、操作の手軽さは表せない。後半の「迷いません」ともつながらない。", "高価": "値段が高いことを表すので、操作の性質としては文が通らない。", "豪華": "派手で贅沢なことを表し、操作の性質には使えない。"}, "sentence_index": 0, "correct_answer": "簡易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は簡易な人で、冗談をすぐ信じてしまう。", "explanation": "ここは〈単純〉の意味。単純は人の性格にも使うが、簡易は手順や内容など物事の手軽さに使い、人の性格には言わない。"}, {"text": "彼は簡易な足取りで部屋を出ていった。", "explanation": "ここは〈軽快〉の意味。軽快は足取りの軽やかさに使い、簡易は手順や作りなど物事の手軽さに使うので、足取りには言えない。"}, {"text": "彼女は簡易な身なりで式に出て、周りに驚かれた。", "explanation": "ここは〈略式〉の意味。略式は服装や形式が正式でないことを表すが、簡易は手順や内容の手軽さに使うので、身なりには言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38782, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "簡易", "is_correct": true, "explanation": "手順が手軽で、初心者でも失敗しないという文の内容に合う。"}, {"text": "上品", "is_correct": false, "explanation": "品があって洗練された様子を表すので、手順の性質には使えない。"}, {"text": "莫大", "is_correct": false, "explanation": "数や量が非常に多いことを表し、手順の性質としては文が通らない。"}, {"text": "貴重", "is_correct": false, "explanation": "数が少なく大切なことを表し、手順の手軽さとは合わない。"}], "explanations": {"簡易": "手順が手軽で、初心者でも失敗しないという文の内容に合う。", "上品": "品があって洗練された様子を表すので、手順の性質には使えない。", "莫大": "数や量が非常に多いことを表し、手順の性質としては文が通らない。", "貴重": "数が少なく大切なことを表し、手順の手軽さとは合わない。"}, "sentence_index": 6, "correct_answer": "簡易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は簡易な気持ちで試験に臨み、結果を気にしなかった。", "explanation": "ここは〈気楽〉の意味。気楽は気持ちの軽さに使い、簡易は手順や作りなど物事に使うので、気持ちには言えない。"}, {"text": "彼は簡易な色の服を好み、派手な服を一枚も持たなかった。", "explanation": "ここは〈地味〉の意味。地味は色や服装の落ち着いた様子に使うが、簡易は手順や作りの手軽さに使うので、色には言えない。"}, {"text": "簡易な笑い声が部屋中に響いた。", "explanation": "ここは〈豪快〉の意味。豪快は笑い声や態度の大きさに使い、簡易は手順や作りに使うので、声には言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38782, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この説明書は簡易言葉で書いてあるので、読みやすい。", "corrected_sentence": "この説明書は簡易な言葉で書いてあるので、読みやすい。", "error_description": "正しくは「簡易な言葉」。簡易は形状詞なので、名詞の前では「な」が必要。「な」が抜けて「簡易言葉」になっている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "簡易な", "is_correct": true, "explanation": "連体形。後ろの名詞「方法」を修飾するので「な」が付く。"}, {"text": "簡易で", "is_correct": false, "explanation": "連用形。「で」で文をつなぐ形で、名詞「方法」の前には置けない。"}, {"text": "簡易だ", "is_correct": false, "explanation": "終止形。文を言い切る形なので、名詞を修飾できない。"}, {"text": "簡易に", "is_correct": false, "explanation": "副詞的な連用形。「方法」を修飾できず、文が通らない。"}], "correct_form": "簡易な", "base_form": "簡易だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"簡易な": "連体形。後ろの名詞「方法」を修飾するので「な」が付く。", "簡易で": "連用形。「で」で文をつなぐ形で、名詞「方法」の前には置けない。", "簡易だ": "終止形。文を言い切る形なので、名詞を修飾できない。", "簡易に": "副詞的な連用形。「方法」を修飾できず、文が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38782, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道具は簡易に構造で、初心者でも扱いやすい。", "corrected_sentence": "この道具は簡易な構造で、初心者でも扱いやすい。", "error_description": "正しくは「簡易な構造」。簡易は形状詞なので名詞を修飾するには「な」が必要。「に」は副詞の形で、名詞「構造」には続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "簡易な", "is_correct": true, "explanation": "連体形。後ろの名詞「表示」を修飾する形なので正しい。"}, {"text": "簡易では", "is_correct": false, "explanation": "「では」は主題や否定の形で、「表示」を直接修飾できない。"}, {"text": "簡易だった", "is_correct": false, "explanation": "過去の終止形で、名詞の前に続けると文が崩れる。"}, {"text": "簡易なら", "is_correct": false, "explanation": "仮定の形で、名詞「表示」を修飾できない。"}], "correct_form": "簡易な", "base_form": "簡易だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"簡易な": "連体形。後ろの名詞「表示」を修飾する形なので正しい。", "簡易では": "「では」は主題や否定の形で、「表示」を直接修飾できない。", "簡易だった": "過去の終止形で、名詞の前に続けると文が崩れる。", "簡易なら": "仮定の形で、名詞「表示」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
