INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38783, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "手順や構造が複雑でなく、すぐにできること。", "primary_collocate": null, "pronunciation": "かんい", "ipa": "kaɴi", "syllable_count": 3, "sentences": [{"text": "簡易な作りの棚なので、三十分で組み立てられました。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "簡易[かんい]な作[つく]りの棚[たな]なので、三十分[さんじゅっぷん]で組[く]み立[た]てられました。", "sentence_source": "generated"}, {"text": "手続きは簡易で、五分もかかりません。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "手続[てつづ]きは簡易[かんい]で、五分[ごふん]もかかりません。", "sentence_source": "generated"}, {"text": "この道具は構造が簡易なので、壊れにくいです。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は構造[こうぞう]が簡易[かんい]なので、壊[こわ]れにくいです。", "sentence_source": "generated"}, {"text": "近くへ送るだけなので、簡易な包装で済ませます。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "近[ちか]くへ送[おく]るだけなので、簡易[かんい]な包装[ほうそう]で済[す]ませます。", "sentence_source": "generated"}, {"text": "簡易な検査なので、結果はその場で分かります。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "簡易[かんい]な検査[けんさ]なので、結果[けっか]はその場[ば]で分[わ]かります。", "sentence_source": "generated"}, {"text": "川の近くに、簡易な橋が急いで作られました。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "川[かわ]の近[ちか]くに、簡易[かんい]な橋[はし]が急[いそ]いで作[つく]られました。", "sentence_source": "generated"}, {"text": "時間がないので、昼ご飯は簡易な方法で済ませました。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "時間[じかん]がないので、昼[ひる]ご飯[はん]は簡易[かんい]な方法[ほうほう]で済[す]ませました。", "sentence_source": "generated"}, {"text": "この申し込みは簡易な書類だけで、すぐにできます。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "この申[もう]し込[こ]みは簡易[かんい]な書類[しょるい]だけで、すぐにできます。", "sentence_source": "generated"}, {"text": "すぐに立てられる簡易なテントを買いました。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "すぐに立[た]てられる簡易[かんい]なテントを買[か]いました。", "sentence_source": "generated"}, {"text": "簡易な仕組みの装置なので、誰でも修理できます。", "target_word": "簡易", "complexity_tier": "T3", "furigana": "簡易[かんい]な仕組[しく]みの装置[そうち]なので、誰[だれ]でも修理[しゅうり]できます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "簡易", "label": "語幹"}, {"form": "簡易な", "label": "連体形"}, {"form": "簡易で", "label": "連用形"}, {"form": "簡易だ", "label": "終止形"}], "register": "neutral", "sense_fingerprint": "手順や作りが複雑でなく、手間をかけずにすぐできること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6a65927-b447-4fa1-9765-03dbf2c9836d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38783, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "簡易", "is_correct": true, "explanation": "手順や作りが複雑でなく、三十分で組み立てられるという文に合う。"}, {"text": "不潔", "is_correct": false, "explanation": "清潔でないことを表し、棚の作りの説明としては文が通らない。"}, {"text": "莫大", "is_correct": false, "explanation": "数や量が非常に多いことを表し、棚の作りには使えない。"}, {"text": "陰湿", "is_correct": false, "explanation": "陰にこもって嫌な感じを表し、作りの説明には合わない。"}], "explanations": {"簡易": "手順や作りが複雑でなく、三十分で組み立てられるという文に合う。", "不潔": "清潔でないことを表し、棚の作りの説明としては文が通らない。", "莫大": "数や量が非常に多いことを表し、棚の作りには使えない。", "陰湿": "陰にこもって嫌な感じを表し、作りの説明には合わない。"}, "sentence_index": 0, "correct_answer": "簡易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は簡易な性格で、誰とでもすぐ仲良くなる。", "explanation": "ここは〈気楽〉の意味。簡易は手順・作り・包装など物事に使い、人の性格には使わない。"}, {"text": "この紅茶は簡易な香りがして、飲むと落ち着く。", "explanation": "ここは〈芳醇〉の意味。芳醇は香りの豊かさに使い、簡易は手順や作りに使うので、香りには言えない。"}, {"text": "彼女は簡易な感性で、季節の変化に気づく。", "explanation": "ここは〈繊細〉の意味。繊細は感じ方の細やかさに使い、簡易は手順や構造に使うので、感性には言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38783, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "簡易", "is_correct": true, "explanation": "手順が手軽で、昼ご飯をすぐ済ませたという文に合う。"}, {"text": "厳粛", "is_correct": false, "explanation": "おごそかで重々しいことを表し、昼ご飯の方法には使えない。"}, {"text": "華美", "is_correct": false, "explanation": "派手で飾り立てた様子を表し、食事の手軽さとは合わない。"}, {"text": "凶暴", "is_correct": false, "explanation": "荒々しく乱暴なことを表し、食事の方法には合わない。"}], "explanations": {"簡易": "手順が手軽で、昼ご飯をすぐ済ませたという文に合う。", "厳粛": "おごそかで重々しいことを表し、昼ご飯の方法には使えない。", "華美": "派手で飾り立てた様子を表し、食事の手軽さとは合わない。", "凶暴": "荒々しく乱暴なことを表し、食事の方法には合わない。"}, "sentence_index": 6, "correct_answer": "簡易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は簡易な笑顔で、みんなに手を振った。", "explanation": "ここは〈無邪気〉の意味。無邪気は表情の素直さに使い、簡易は手順や作りに使うので、笑顔には言えない。"}, {"text": "店員は簡易な態度で客を追い返した。", "explanation": "ここは〈冷淡〉の意味。冷淡は人への思いやりのなさを表す。簡易は物事の手軽さに使うので、態度には言えない。"}, {"text": "この夏は簡易な暑さで、みんなバテてしまった。", "explanation": "ここは〈猛烈〉の意味。猛烈は暑さの激しさに使い、簡易は手順や作りに使うので、暑さの程度には言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38783, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この手続きは簡易な、五分で終わります。", "corrected_sentence": "この手続きは簡易で、五分で終わります。", "error_description": "正しくは「簡易で」。「簡易な」は名詞の前で使う形なので、ここでは後ろに名詞がなく文が成立しない。「簡易で」で文をつなぐ。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "簡易で", "is_correct": true, "explanation": "連用形。「で」で後ろの「五分もかかりません」へつなぐ形。"}, {"text": "簡易に", "is_correct": false, "explanation": "副詞的な形で、「手続きは〜」の述語にならず文が通らない。"}, {"text": "簡易だ", "is_correct": false, "explanation": "終止形。文を言い切るので、後ろに続けると文が崩れる。"}, {"text": "簡易さ", "is_correct": false, "explanation": "名詞化した形で、「手続きは〜」の述語としては不自然。"}], "correct_form": "簡易で", "base_form": "簡易だ", "form_label": "連用形", "sentence_index": 1, "explanations": {"簡易で": "連用形。「で」で後ろの「五分もかかりません」へつなぐ形。", "簡易に": "副詞的な形で、「手続きは〜」の述語にならず文が通らない。", "簡易だ": "終止形。文を言い切るので、後ろに続けると文が崩れる。", "簡易さ": "名詞化した形で、「手続きは〜」の述語としては不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38783, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この装置は簡易だ仕組みなので、誰でも修理できます。", "corrected_sentence": "この装置は簡易な仕組みなので、誰でも修理できます。", "error_description": "正しくは「簡易な仕組み」。名詞を修飾するには「な」が必要。「だ」は文を言い切る形なので、名詞の前には置けない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "簡易な", "is_correct": true, "explanation": "連体形。後ろの名詞「書類」を修飾する形なので正しい。"}, {"text": "簡易では", "is_correct": false, "explanation": "「では」は主題や否定の形で、「書類」を直接修飾できない。"}, {"text": "簡易だった", "is_correct": false, "explanation": "過去の終止形で、名詞の前に続けると文が崩れる。"}, {"text": "簡易じゃ", "is_correct": false, "explanation": "話し言葉の否定形で、「書類」を修飾できず文が通らない。"}], "correct_form": "簡易な", "base_form": "簡易だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"簡易な": "連体形。後ろの名詞「書類」を修飾する形なので正しい。", "簡易では": "「では」は主題や否定の形で、「書類」を直接修飾できない。", "簡易だった": "過去の終止形で、名詞の前に続けると文が崩れる。", "簡易じゃ": "話し言葉の否定形で、「書類」を修飾できず文が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
