INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38784, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分で作ること。", "primary_collocate": null, "pronunciation": "じさく", "ipa": "dʑisakɯ", "syllable_count": 3, "sentences": [{"text": "父は庭の小さな棚を自作した。", "target_word": "自作", "complexity_tier": "T3", "furigana": "父[ちち]は庭[にわ]の小[ちい]さな棚[たな]を自作[じさく]した。", "sentence_source": "generated"}, {"text": "店で買うと高いので、机を自作することにした。", "target_word": "自作", "complexity_tier": "T3", "furigana": "店[みせ]で買[か]うと高[たか]いので、机[つくえ]を自作[じさく]することにした。", "sentence_source": "generated"}, {"text": "このパソコンは部品を集めて自作したものだ。", "target_word": "自作", "complexity_tier": "T3", "furigana": "このパソコンは部品[ぶひん]を集[あつ]めて自作[じさく]したものだ。", "sentence_source": "generated"}, {"text": "自作の本棚は、市販品より安くて丈夫だ。", "target_word": "自作", "complexity_tier": "T3", "furigana": "自作[じさく]の本棚[ほんだな]は、市販品[しはんひん]より安[やす]くて丈夫[じょうぶ]だ。", "sentence_source": "generated"}, {"text": "兄は自作のスピーカーで毎晩音楽を聞いている。", "target_word": "自作", "complexity_tier": "T3", "furigana": "兄[あに]は自作[じさく]のスピーカーで毎晩[まいばん]音楽[おんがく]を聞[き]いている。", "sentence_source": "generated"}, {"text": "紙があれば自作できる簡単なおもちゃだ。", "target_word": "自作", "complexity_tier": "T3", "furigana": "紙[かみ]があれば自作[じさく]できる簡単[かんたん]なおもちゃだ。", "sentence_source": "generated"}, {"text": "自作は時間がかかるが、好きな大きさにできる。", "target_word": "自作", "complexity_tier": "T3", "furigana": "自作[じさく]は時間[じかん]がかかるが、好[す]きな大[おお]きさにできる。", "sentence_source": "generated"}, {"text": "料理を習ったので、ケーキの型も自作してみた。", "target_word": "自作", "complexity_tier": "T3", "furigana": "料理[りょうり]を習[なら]ったので、ケーキの型[かた]も自作[じさく]してみた。", "sentence_source": "generated"}, {"text": "買うお金がなかったので、小鳥の巣箱を自作した。", "target_word": "自作", "complexity_tier": "T3", "furigana": "買[か]うお金[かね]がなかったので、小鳥[ことり]の巣箱[すばこ]を自作[じさく]した。", "sentence_source": "generated"}, {"text": "自作のかばんを持って、友達に見せに行った。", "target_word": "自作", "complexity_tier": "T3", "furigana": "自作[じさく]のかばんを持[も]って、友達[ともだち]に見[み]せに行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自作", "label": "基本形"}, {"form": "自作する", "label": "動詞形（する）"}, {"form": "自作した", "label": "過去形"}, {"form": "自作できる", "label": "可能形"}, {"form": "自作の", "label": "連体形（の）"}], "register": "neutral (plain form)", "sense_fingerprint": "自作 as DIY: making an object yourself instead of buying it ready-made", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6a65927-b447-4fa1-9765-03dbf2c9836d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38784, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自作", "is_correct": true, "explanation": "自分で作ったという意味で、父が庭の棚を作ったという文に合う。"}, {"text": "談笑", "is_correct": false, "explanation": "笑いながら話し合うことで、棚を対象にはできない。"}, {"text": "散歩", "is_correct": false, "explanation": "ぶらぶら歩くことで、棚を作る動作とは合わない。"}, {"text": "点滅", "is_correct": false, "explanation": "明かりがついたり消えたりすることで、棚に対する動作としては成立しない。"}], "explanations": {"自作": "自分で作ったという意味で、父が庭の棚を作ったという文に合う。", "談笑": "笑いながら話し合うことで、棚を対象にはできない。", "散歩": "ぶらぶら歩くことで、棚を作る動作とは合わない。", "点滅": "明かりがついたり消えたりすることで、棚に対する動作としては成立しない。"}, "sentence_index": 0, "correct_answer": "自作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は私を自作の娘だと話していた。", "explanation": "ここは〈自慢〉の意味。自作は自分で物を作ることで、人を誇る意味にはならない。"}, {"text": "彼は自作で英語を覚えた。", "explanation": "ここは〈独学〉の意味。自作は自分で作った物を指すので、学んで身につける意味では使えない。"}, {"text": "彼は怒りを自作して、無言で部屋を出た。", "explanation": "ここは〈自制〉の意味。自作は作ることで、感情を抑える意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38784, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自作", "is_correct": true, "explanation": "自分で作るには時間がかかるが大きさを選べるという文に合う。"}, {"text": "嘆息", "is_correct": false, "explanation": "ため息をつくことで、作る行為や大きさの話とつながらない。"}, {"text": "会釈", "is_correct": false, "explanation": "軽く頭を下げることで、大きさの話とは関係がない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかけることで、作る行為とも大きさの話とも合わない。"}], "explanations": {"自作": "自分で作るには時間がかかるが大きさを選べるという文に合う。", "嘆息": "ため息をつくことで、作る行為や大きさの話とつながらない。", "会釈": "軽く頭を下げることで、大きさの話とは関係がない。", "施錠": "鍵をかけることで、作る行為とも大きさの話とも合わない。"}, "sentence_index": 6, "correct_answer": "自作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は高校を出て自作した。", "explanation": "ここは〈自立〉の意味。自作は自分で物を作ることで、親から独立して暮らす意味にはならない。"}, {"text": "彼は失敗を自作した。", "explanation": "ここは〈自省〉の意味。自作は物を作ることで、反省する意味は表せない。"}, {"text": "週末は自作で過ごすことが多い。", "explanation": "ここは〈自宅〉の意味。自作は物を作ることなので、場所で過ごす意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38784, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は自作な棚をキッチンに置いている。", "corrected_sentence": "兄は自作の棚をキッチンに置いている。", "error_description": "正しくは「自作の棚」。自作は名詞なので、名詞を修飾するには「の」を使う。「な」は形容動詞用なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38784, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は木の机が自作した。", "corrected_sentence": "私は木の机を自作した。", "error_description": "正しくは「木の机を自作した」。自作する対象は「を」で示す。「が」にすると机が主語になり、机が自分で作ったという不自然な意味になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38785, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「兄の自作」で、兄が作ったという作者を示す連体修飾の助詞。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「兄を自作」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「兄へ自作」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "相手や対象を示す助詞だが、「兄に自作」は文が通らない。"}], "correct_answer": "の", "explanations": {"の": "「兄の自作」で、兄が作ったという作者を示す連体修飾の助詞。", "を": "目的語を示す助詞で、「兄を自作」では意味が通らない。", "へ": "方向を示す助詞で、「兄へ自作」は不自然。", "に": "相手や対象を示す助詞だが、「兄に自作」は文が通らない。"}, "error_tags": {"を": "object marker", "へ": "direction", "に": "dative"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
