INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38785, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分で考えて作り出すこと。また、自分で作った物。", "primary_collocate": null, "pronunciation": "じさく", "ipa": "dʑisakɯ", "syllable_count": 3, "sentences": [{"text": "彼女は自作の詩をみんなの前で読んだ。", "target_word": "自作", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自作[じさく]の詩[し]をみんなの前[まえ]で読[よ]んだ。", "sentence_source": "generated"}, {"text": "この曲は兄の自作で、まだ誰にも聞かせていない。", "target_word": "自作", "complexity_tier": "T3", "furigana": "この曲[きょく]は兄[あに]の自作[じさく]で、まだ誰[だれ]にも聞[き]かせていない。", "sentence_source": "generated"}, {"text": "発表会では、自作の歌を三曲歌った。", "target_word": "自作", "complexity_tier": "T3", "furigana": "発表会[はっぴょうかい]では、自作[じさく]の歌[うた]を三曲[さんきょく]歌[うた]った。", "sentence_source": "generated"}, {"text": "自作の物語を絵本にして、弟にプレゼントした。", "target_word": "自作", "complexity_tier": "T3", "furigana": "自作[じさく]の物語[ものがたり]を絵本[えほん]にして、弟[おとうと]にプレゼントした。", "sentence_source": "generated"}, {"text": "先生は生徒の自作の俳句を、教室の壁にはった。", "target_word": "自作", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の自作[じさく]の俳句[はいく]を、教室[きょうしつ]の壁[かべ]にはった。", "sentence_source": "generated"}, {"text": "彼は自作の曲をネットで公開している。", "target_word": "自作", "complexity_tier": "T3", "furigana": "彼[かれ]は自作[じさく]の曲[きょく]をネットで公開[こうかい]している。", "sentence_source": "generated"}, {"text": "自作ではなく人の作品を使うときは、名前を書く決まりだ。", "target_word": "自作", "complexity_tier": "T3", "furigana": "自作[じさく]ではなく人[ひと]の作品[さくひん]を使[つか]うときは、名前[なまえ]を書[か]く決[き]まりだ。", "sentence_source": "generated"}, {"text": "自作の漫画を出版社に送ったが、返事は来なかった。", "target_word": "自作", "complexity_tier": "T3", "furigana": "自作[じさく]の漫画[まんが]を出版社[しゅっぱんしゃ]に送[おく]ったが、返事[へんじ]は来[こ]なかった。", "sentence_source": "generated"}, {"text": "このゲームの音楽は全部自作だと聞いて驚いた。", "target_word": "自作", "complexity_tier": "T3", "furigana": "このゲームの音楽[おんがく]は全部[ぜんぶ]自作[じさく]だと聞[き]いて驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "自作の短歌を、手紙の最後に一首書いた。", "target_word": "自作", "complexity_tier": "T3", "furigana": "自作[じさく]の短歌[たんか]を、手紙[てがみ]の最後[さいご]に一首[いっしゅ]書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自作", "label": "基本形"}, {"form": "自作の", "label": "連体形（の）"}, {"form": "自作だ", "label": "断定形"}, {"form": "自作する", "label": "動詞形（する）"}, {"form": "自作した", "label": "過去形"}], "register": "neutral (plain form)", "sense_fingerprint": "自作 as one''s own original creation: a song, poem or story you thought up and made yourself", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6a65927-b447-4fa1-9765-03dbf2c9836d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38785, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自作", "is_correct": true, "explanation": "自分で作った詩を読んだという文に合う。"}, {"text": "絵画", "is_correct": false, "explanation": "絵の作品を指すので、詩を読むという文には合わない。"}, {"text": "作曲", "is_correct": false, "explanation": "曲を作ることを指すので、詩を表すことはできない。"}, {"text": "彫刻", "is_correct": false, "explanation": "彫って作る美術品のことで、読むものではない。"}], "explanations": {"自作": "自分で作った詩を読んだという文に合う。", "絵画": "絵の作品を指すので、詩を読むという文には合わない。", "作曲": "曲を作ることを指すので、詩を表すことはできない。", "彫刻": "彫って作る美術品のことで、読むものではない。"}, "sentence_index": 0, "correct_answer": "自作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は自作の気持ちで、堂々と発表に臨んだ。", "explanation": "「自作の気持ち」は不自然。自作は作品や作ることを指し、気持ちを修飾しない。"}, {"text": "彼は自作でピアノを覚えた。", "explanation": "「自作で」は学ぶ手段にならず不自然。自作は作ることであり、独学の意味はない。"}, {"text": "会社から自作して店を開いた。", "explanation": "ここは〈独立〉の意味。自作は作ることで、組織から離れる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38785, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自作", "is_correct": true, "explanation": "人の作品と対比する「自分が作った作品」の意味で、名前を書く決まりの文に合う。"}, {"text": "買い物", "is_correct": false, "explanation": "品物を買うことで、作品との対比にならず、文が通らない。"}, {"text": "掃除", "is_correct": false, "explanation": "部屋を綺麗にすることで、作品を使う話とは関係がない。"}, {"text": "休憩", "is_correct": false, "explanation": "一時的に休むことで、作品の対比にはならない。"}], "explanations": {"自作": "人の作品と対比する「自分が作った作品」の意味で、名前を書く決まりの文に合う。", "買い物": "品物を買うことで、作品との対比にならず、文が通らない。", "掃除": "部屋を綺麗にすることで、作品を使う話とは関係がない。", "休憩": "一時的に休むことで、作品の対比にはならない。"}, "sentence_index": 6, "correct_answer": "自作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎晩、寝る前に自作の習慣がある。", "explanation": "「自作の習慣」は作品を指す語として習慣の話にならず、不自然。"}, {"text": "週末は自作で過ごすことが多い。", "explanation": "「自作で過ごす」は場所や時間の意味にならず不自然。自作は作ることであり、自宅の意味はない。"}, {"text": "会社は大きな自作を得た。", "explanation": "「大きな自作を得た」は得る対象として不自然。自作に利益の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38785, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は自作な歌を、発表会で初めて披露した。", "corrected_sentence": "彼は自作の歌を、発表会で初めて披露した。", "error_description": "「自作」は名詞なので「な」は付かない。正しくは「自作の歌」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38785, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は自作だ短歌を三首、雑誌に載せた。", "corrected_sentence": "彼は自作の短歌を三首、雑誌に載せた。", "error_description": "正しくは「自作の短歌」。自作は名詞なので、名詞を修飾するには「の」が必要。「だ」は断定の形で、名詞の前には置けない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38786, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「住民は百人です」と、主題を示す。"}, {"text": "を", "is_correct": false, "explanation": "「住民を百人です」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「住民へ百人です」では方向の意味が合わず文にならない。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は否定を伴うので「です」とは合わない。"}], "correct_answer": "は", "explanations": {"は": "「住民は百人です」と、主題を示す。", "を": "「住民を百人です」では文が成り立たない。", "へ": "「住民へ百人です」では方向の意味が合わず文にならない。", "しか": "「しか」は否定を伴うので「です」とは合わない。"}, "error_tags": {"を": "object_marker_misuse", "へ": "direction", "しか": "requires_negation"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
