INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38786, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある場所に住んでいる人。", "primary_collocate": null, "pronunciation": "じゅうみん", "ipa": "dʑɯːmiɴ", "syllable_count": 4, "sentences": [{"text": "住民が増えた。", "target_word": "住民", "complexity_tier": "T1", "furigana": "住民[じゅうみん]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "この村の住民は百人です。", "target_word": "住民", "complexity_tier": "T2", "furigana": "この村[むら]の住民[じゅうみん]は百人[ひゃくにん]です。", "sentence_source": "generated"}, {"text": "住民に道を聞きました。", "target_word": "住民", "complexity_tier": "T2", "furigana": "住民[じゅうみん]に道[みち]を聞[き]きました。", "sentence_source": "generated"}, {"text": "町の住民が、広場でお祭りを開いた。", "target_word": "住民", "complexity_tier": "T3", "furigana": "町[まち]の住民[じゅうみん]が、広場[ひろば]でお祭[まつ]りを開[ひら]いた。", "sentence_source": "generated"}, {"text": "このビルの住民は、ほとんどが学生だ。", "target_word": "住民", "complexity_tier": "T3", "furigana": "このビルの住民[じゅうみん]は、ほとんどが学生[がくせい]だ。", "sentence_source": "generated"}, {"text": "住民に聞けば、おいしい店がわかる。", "target_word": "住民", "complexity_tier": "T4", "furigana": "住民[じゅうみん]に聞[き]けば、おいしい店[みせ]がわかる。", "sentence_source": "generated"}, {"text": "住民でなければ、このプールは使えない。", "target_word": "住民", "complexity_tier": "T4", "furigana": "住民[じゅうみん]でなければ、このプールは使[つか]えない。", "sentence_source": "generated"}, {"text": "住民のために、新しい図書館が建てられた。", "target_word": "住民", "complexity_tier": "T4", "furigana": "住民[じゅうみん]のために、新[あたら]しい図書館[としょかん]が建[た]てられた。", "sentence_source": "generated"}, {"text": "島の住民は、毎朝海で魚をとっている。", "target_word": "住民", "complexity_tier": "T3", "furigana": "島[しま]の住民[じゅうみん]は、毎朝[まいあさ]海[うみ]で魚[さかな]をとっている。", "sentence_source": "generated"}, {"text": "住民の一人として、私は町の未来を心配している。", "target_word": "住民", "complexity_tier": "T4", "furigana": "住民[じゅうみん]の一人[ひとり]として、私[わたし]は町[まち]の未来[みらい]を心配[しんぱい]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "住民票", "label": "派生"}, {"form": "住民税", "label": "派生"}, {"form": "住民登録", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ある場所に住んでいる人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a39150a-21a7-47ec-ad3d-64f57f18784e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38786, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "住民", "is_correct": true, "explanation": "見出し語「じゅうみん」そのもの。"}, {"text": "重心", "is_correct": false, "explanation": "「じゅうしん」で、「み」が「し」に変わる別の語。"}, {"text": "重点", "is_correct": false, "explanation": "「じゅうてん」で、「み」が「て」に変わる別の語。"}, {"text": "十万", "is_correct": false, "explanation": "「じゅうまん」で、「み」が「ま」に変わる別の語。"}], "explanations": {"住民": "見出し語「じゅうみん」そのもの。", "重心": "「じゅうしん」で、「み」が「し」に変わる別の語。", "重点": "「じゅうてん」で、「み」が「て」に変わる別の語。", "十万": "「じゅうまん」で、「み」が「ま」に変わる別の語。"}, "sentence_index": null, "correct_answer": "住民"}, "level_3": {"options": [{"text": "住民", "is_correct": true, "explanation": "人の数が増えたという意味に合う。"}, {"text": "天井", "is_correct": false, "explanation": "形は合うが意味が合わない。天井が増えるとは言えない。"}, {"text": "空", "is_correct": false, "explanation": "形は合うが意味が合わない。空が増えるとは言えない。"}, {"text": "隣", "is_correct": false, "explanation": "形は合うが意味が合わない。隣が増えるとは言えない。"}], "explanations": {"住民": "人の数が増えたという意味に合う。", "天井": "形は合うが意味が合わない。天井が増えるとは言えない。", "空": "形は合うが意味が合わない。空が増えるとは言えない。", "隣": "形は合うが意味が合わない。隣が増えるとは言えない。"}, "sentence_index": 0, "correct_answer": "住民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "住民が空から降ってきて、屋根をぬらした。", "explanation": "「住民」を雨のように「降ってくる」ものとして使っており、人の意味に合わない。"}, {"text": "この村の住民は、三階まである高い建物だ。", "explanation": "「住民」を建物の意味で使っており、住んでいる人の意味に反する。"}, {"text": "朝ごはんに住民を焼いて食べた。", "explanation": "「住民」を食材のように焼いて食べており、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38786, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "住民", "is_correct": true, "explanation": "見出し語「じゅうみん」そのもの。"}, {"text": "充電", "is_correct": false, "explanation": "「じゅうでん」で、「み」が「で」に変わる別の語。"}, {"text": "銃弾", "is_correct": false, "explanation": "「じゅうだん」で、「み」が「だ」に変わる別の語。"}, {"text": "十分", "is_correct": false, "explanation": "「じゅうぶん」で、「み」が「ぶ」に変わる別の語。"}], "explanations": {"住民": "見出し語「じゅうみん」そのもの。", "充電": "「じゅうでん」で、「み」が「で」に変わる別の語。", "銃弾": "「じゅうだん」で、「み」が「だ」に変わる別の語。", "十分": "「じゅうぶん」で、「み」が「ぶ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "住民"}, "level_3": {"options": [{"text": "住民", "is_correct": true, "explanation": "「住民でなければ使えない」と、利用条件として意味が合う。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが意味が合わない。プールの利用条件にならない。"}, {"text": "建物", "is_correct": false, "explanation": "形は合うが意味が合わない。利用者の資格として成り立たない。"}, {"text": "道路", "is_correct": false, "explanation": "形は合うが意味が合わない。プールを使う条件にならない。"}], "explanations": {"住民": "「住民でなければ使えない」と、利用条件として意味が合う。", "野菜": "形は合うが意味が合わない。プールの利用条件にならない。", "建物": "形は合うが意味が合わない。利用者の資格として成り立たない。", "道路": "形は合うが意味が合わない。プールを使う条件にならない。"}, "sentence_index": 6, "correct_answer": "住民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日、住民をはいて、足が温かくなった。", "explanation": "「住民」を靴下のように「はく」ものとして使っており、人の意味に合わない。"}, {"text": "この住民は水が冷たくて、泳ぐと気持ちいい。", "explanation": "「住民」を泳げる場所のように使っており、住んでいる人の意味に反する。"}, {"text": "住民を飲んだら、のどがかわかなくなった。", "explanation": "「住民」を飲み物として使っており、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38786, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この島の住民に八十人です。", "corrected_sentence": "この島の住民は八十人です。", "error_description": "「住民」の後ろは主題を表す「は」が正しく、「に」は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
