INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38787, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「住民の参加」と、参加する主体を表す。"}, {"text": "を", "is_correct": false, "explanation": "「住民を主体的な参加」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、この「住民」と「参加」の関係に合わない。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は否定と一緒に使うので、この文では不自然。"}], "correct_answer": "の", "explanations": {"の": "「住民の参加」と、参加する主体を表す。", "を": "「住民を主体的な参加」では文が成り立たない。", "へ": "方向を表す「へ」は、この「住民」と「参加」の関係に合わない。", "しか": "「しか」は否定と一緒に使うので、この文では不自然。"}, "error_tags": {"を": "object_marker_misuse", "へ": "direction", "しか": "requires_negation"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38787, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「住民の生活」と、生活の持ち主を表す。"}, {"text": "を", "is_correct": false, "explanation": "「住民を生活が」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「住民へ生活が」では方向の意味が合わず文にならない。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は否定と使うので、「便利になった」とは合わない。"}], "correct_answer": "の", "explanations": {"の": "「住民の生活」と、生活の持ち主を表す。", "を": "「住民を生活が」では文が成り立たない。", "へ": "「住民へ生活が」では方向の意味が合わず文にならない。", "しか": "「しか」は否定と使うので、「便利になった」とは合わない。"}, "error_tags": {"を": "object_marker_misuse", "へ": "direction", "しか": "requires_negation"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38787, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "特定の地域や国に住んでいる人のこと。", "primary_collocate": null, "pronunciation": "じゅうみん", "ipa": "dʑɯːmiɴ", "syllable_count": 4, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "住民", "complexity_tier": "T6", "furigana": "特[とく]に、住民[じゅうみん]の主体的[しゅたいてき]な参加[さんか]により創出[そうしゅつ]されるガーデンは、生物[せいぶつ]多様性[たようせい]の回復[かいふく]のみならず、微気候[びきこう]の改善[かいぜん]といった側面[そくめん]においても近隣[きんりん]緑地[りょくち]に好影響[こうえいきょう]を及[およ]ぼしている。", "sentence_source": "mined"}, {"text": "住民が集まった。", "target_word": "住民", "complexity_tier": "T1", "furigana": "住民[じゅうみん]が集[あつ]まった。", "sentence_source": "generated"}, {"text": "この町の住民は親切です。", "target_word": "住民", "complexity_tier": "T2", "furigana": "この町[まち]の住民[じゅうみん]は親切[しんせつ]です。", "sentence_source": "generated"}, {"text": "住民に話を聞きました。", "target_word": "住民", "complexity_tier": "T2", "furigana": "住民[じゅうみん]に話[はなし]を聞[き]きました。", "sentence_source": "generated"}, {"text": "住民の多くは、お年寄りです。", "target_word": "住民", "complexity_tier": "T2", "furigana": "住民[じゅうみん]の多[おお]くは、お年寄[としよ]りです。", "sentence_source": "generated"}, {"text": "市は住民にごみの出し方を説明した。", "target_word": "住民", "complexity_tier": "T3", "furigana": "市[し]は住民[じゅうみん]にごみの出[だ]し方[かた]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "住民が協力して、公園をきれいにしている。", "target_word": "住民", "complexity_tier": "T3", "furigana": "住民[じゅうみん]が協力[きょうりょく]して、公園[こうえん]をきれいにしている。", "sentence_source": "generated"}, {"text": "新しい駅ができて、住民の生活が便利になった。", "target_word": "住民", "complexity_tier": "T3", "furigana": "新[あたら]しい駅[えき]ができて、住民[じゅうみん]の生活[せいかつ]が便利[べんり]になった。", "sentence_source": "generated"}, {"text": "住民の反対があれば、工事は進められないだろう。", "target_word": "住民", "complexity_tier": "T4", "furigana": "住民[じゅうみん]の反対[はんたい]があれば、工事[こうじ]は進[すす]められないだろう。", "sentence_source": "generated"}, {"text": "住民は市から、避難するように言われた。", "target_word": "住民", "complexity_tier": "T4", "furigana": "住民[じゅうみん]は市[し]から、避難[ひなん]するように言[い]われた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "住民票", "label": "派生"}, {"form": "住民税", "label": "派生"}, {"form": "住民登録", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 特定の地域や国に住む人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 好影響 (Zipf 2.16)']::text[], '7a39150a-21a7-47ec-ad3d-64f57f18784e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38787, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "住民", "is_correct": true, "explanation": "見出し語「じゅうみん」そのもの。"}, {"text": "重心", "is_correct": false, "explanation": "「じゅうしん」で、「み」が「し」に変わる別の語。"}, {"text": "重点", "is_correct": false, "explanation": "「じゅうてん」で、「み」が「て」に変わる別の語。"}, {"text": "十万", "is_correct": false, "explanation": "「じゅうまん」で、「み」が「ま」に変わる別の語。"}, {"text": "絨毯", "is_correct": false, "explanation": "「じゅうたん」で、「み」が「た」に変わる別の語。"}], "explanations": {"住民": "見出し語「じゅうみん」そのもの。", "重心": "「じゅうしん」で、「み」が「し」に変わる別の語。", "重点": "「じゅうてん」で、「み」が「て」に変わる別の語。", "十万": "「じゅうまん」で、「み」が「ま」に変わる別の語。", "絨毯": "「じゅうたん」で、「み」が「た」に変わる別の語。"}, "sentence_index": null, "correct_answer": "住民"}, "level_3": {"options": [{"text": "住民", "is_correct": true, "explanation": "地域の人が主体的に参加する、という意味に合う。"}, {"text": "天候", "is_correct": false, "explanation": "形は合うが意味が合わない。天候は「主体的に参加」できない。"}, {"text": "価格", "is_correct": false, "explanation": "形は合うが意味が合わない。価格は参加の主体にならない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。季節が主体的に参加することはない。"}], "explanations": {"住民": "地域の人が主体的に参加する、という意味に合う。", "天候": "形は合うが意味が合わない。天候は「主体的に参加」できない。", "価格": "形は合うが意味が合わない。価格は参加の主体にならない。", "季節": "形は合うが意味が合わない。季節が主体的に参加することはない。"}, "sentence_index": 0, "correct_answer": "住民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夜、住民が大きく降って、傘をさした。", "explanation": "「住民」を雨のように「降る」ものとして使っており、人を表す意味に合わない。"}, {"text": "この町の住民は、とても甘くておいしいです。", "explanation": "「住民」を食べ物のように味で評価しており、住んでいる人の意味に反する。"}, {"text": "私は住民を五枚買って、友達に送った。", "explanation": "「住民」を紙のように「枚」で数えて買うものにしており、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38787, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "住民", "is_correct": true, "explanation": "見出し語「じゅうみん」そのもの。"}, {"text": "充電", "is_correct": false, "explanation": "「じゅうでん」で、「み」が「で」に変わる別の語。"}, {"text": "銃弾", "is_correct": false, "explanation": "「じゅうだん」で、「み」が「だ」に変わる別の語。"}, {"text": "十分", "is_correct": false, "explanation": "「じゅうぶん」で、「み」が「ぶ」に変わる別の語。"}, {"text": "重鎮", "is_correct": false, "explanation": "「じゅうちん」で、「み」が「ち」に変わる別の語。"}], "explanations": {"住民": "見出し語「じゅうみん」そのもの。", "充電": "「じゅうでん」で、「み」が「で」に変わる別の語。", "銃弾": "「じゅうだん」で、「み」が「だ」に変わる別の語。", "十分": "「じゅうぶん」で、「み」が「ぶ」に変わる別の語。", "重鎮": "「じゅうちん」で、「み」が「ち」に変わる別の語。"}, "sentence_index": null, "correct_answer": "住民"}, "level_3": {"options": [{"text": "住民", "is_correct": true, "explanation": "協力して公園をきれいにする主体として意味が合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は協力して掃除できない。"}, {"text": "建物", "is_correct": false, "explanation": "形は合うが意味が合わない。建物が協力することはない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。季節は協力する主体にならない。"}], "explanations": {"住民": "協力して公園をきれいにする主体として意味が合う。", "天気": "形は合うが意味が合わない。天気は協力して掃除できない。", "建物": "形は合うが意味が合わない。建物が協力することはない。", "季節": "形は合うが意味が合わない。季節は協力する主体にならない。"}, "sentence_index": 6, "correct_answer": "住民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "住民は駅の前に建っていて、とても高い。", "explanation": "「住民」を建物のように「建つ」「高い」ものとして使っており、人の意味に合わない。"}, {"text": "朝ごはんに住民を焼いて、お茶と一緒に食べた。", "explanation": "「住民」を焼いて食べる食材として使っており、意味が合わない。"}, {"text": "雨がやんだので、住民をたたんでかばんに入れた。", "explanation": "「住民」を傘のように「たたむ」ものにしており、住んでいる人の意味に反する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version,