INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38787, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町の住民を親切な人ばかりです。", "corrected_sentence": "この町の住民は親切な人ばかりです。", "error_description": "「住民」の後ろの助詞が「を」では文が成り立たない。主題を表す「は」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38787, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅の近くの住民を多くが学生だ。", "corrected_sentence": "駅の近くの住民の多くが学生だ。", "error_description": "「住民」と「多く」をつなぐ助詞は「を」ではなく「の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38788, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。ムーブメントが「生まれる」の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「生まれる」は目的語を取らない自動詞なので「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「ムーブメントに生まれる」は不自然。「に」は生まれる場所や相手を表す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表し、ここで生まれる主体を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。ムーブメントが「生まれる」の主語になる。", "を": "「生まれる」は目的語を取らない自動詞なので「を」は合わない。", "に": "「ムーブメントに生まれる」は不自然。「に」は生まれる場所や相手を表す。", "と": "「と」は並列や引用を表し、ここで生まれる主体を示せない。"}, "error_tags": {"を": "目的語（主語ではない）", "に": "位置・相手", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
