INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38788, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が集まって、何かを変えようとする動きのことです。", "primary_collocate": null, "pronunciation": "むーぶめんと", "ipa": "mɯːbɯmeɴto", "syllable_count": 6, "sentences": [{"text": "町の人たちが集まって、ごみを減らすムーブメントを始めました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]たちが集[あつ]まって、ごみを減[へ]らすムーブメントを始[はじ]めました。", "sentence_source": "generated"}, {"text": "若者の署名から、大きなムーブメントが生まれました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "若者[わかもの]の署名[しょめい]から、大[おお]きなムーブメントが生[う]まれました。", "sentence_source": "generated"}, {"text": "このムーブメントには、全国から千人が参加しました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "このムーブメントには、全国[ぜんこく]から千人[せんにん]が参加[さんか]しました。", "sentence_source": "generated"}, {"text": "彼女は女性の権利を守るムーブメントの中心です。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は女性[じょせい]の権利[けんり]を守[まも]るムーブメントの中心[ちゅうしん]です。", "sentence_source": "generated"}, {"text": "小さな集まりが、やがて社会を変えるムーブメントになりました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "小[ちい]さな集[あつ]まりが、やがて社会[しゃかい]を変[か]えるムーブメントになりました。", "sentence_source": "generated"}, {"text": "学校で、いじめをなくそうというムーブメントが起きました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "学校[がっこう]で、いじめをなくそうというムーブメントが起[お]きました。", "sentence_source": "generated"}, {"text": "みんなで駅前を掃除するムーブメントに、私も加わりました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "みんなで駅前[えきまえ]を掃除[そうじ]するムーブメントに、私[わたし]も加[くわ]わりました。", "sentence_source": "generated"}, {"text": "そのムーブメントは、市長が考えを変えるまで続きました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "そのムーブメントは、市長[しちょう]が考[かんが]えを変[か]えるまで続[つづ]きました。", "sentence_source": "generated"}, {"text": "川をきれいにするムーブメントのおかげで、魚が戻ってきました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "川[かわ]をきれいにするムーブメントのおかげで、魚[さかな]が戻[もど]ってきました。", "sentence_source": "generated"}, {"text": "先生は「ムーブメントは一人の行動から始まる」と話しました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "先生[せんせい]は「ムーブメントは一人[ひとり]の行動[こうどう]から始[はじ]まる」と話[はな]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ムーブメント", "label": "基本形"}], "register": "polite", "sense_fingerprint": "人々が集まって社会や状況を変えようとする運動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35216ce1-5f8f-42d2-939c-3c153ea82559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38788, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ムーブメント", "is_correct": true, "explanation": "正解。人々が集まって社会を変えようとする動きを指し、「始めました」に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は「始めました」の対象にならず、ごみを減らす活動を表さない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は人が「始める」ものではなく、文として成り立たない。"}, {"text": "階段", "is_correct": false, "explanation": "階段は建物の一部で、人々が始める取り組みを表さない。"}], "explanations": {"ムーブメント": "正解。人々が集まって社会を変えようとする動きを指し、「始めました」に合う。", "手紙": "手紙は「始めました」の対象にならず、ごみを減らす活動を表さない。", "天気": "天気は人が「始める」ものではなく、文として成り立たない。", "階段": "階段は建物の一部で、人々が始める取り組みを表さない。"}, "sentence_index": 0, "correct_answer": "ムーブメント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末は、友だちとのムーブメントで映画を見に行きました。", "explanation": "ここは一緒に過ごす時間という意味。ムーブメントは社会を変えようとする人々の動きで、友人との外出は指さない。"}, {"text": "その店は、ムーブメントの割引で安く売っています。", "explanation": "ここは値引き（値段を下げること）の意味。ムーブメントは社会的な動きで、値段の割引は表さない。"}, {"text": "この時計のムーブメントで、合格者が増えました。", "explanation": "ここは時計の内部の機械部分の意味。社会的な動きの意味では、合格者の増加とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38788, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ムーブメント", "is_correct": true, "explanation": "正解。みんなで掃除する社会的な動きを指し、「加わりました」に合う。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は学習課題で、人々の掃除の動きに「加わる」ものではない。"}, {"text": "名刺", "is_correct": false, "explanation": "名刺は持ち物で、人の集まりに「加わる」対象にならない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は建物の部分で、人々の取り組みに「加わる」対象にならない。"}], "explanations": {"ムーブメント": "正解。みんなで掃除する社会的な動きを指し、「加わりました」に合う。", "宿題": "宿題は学習課題で、人々の掃除の動きに「加わる」ものではない。", "名刺": "名刺は持ち物で、人の集まりに「加わる」対象にならない。", "天井": "天井は建物の部分で、人々の取り組みに「加わる」対象にならない。"}, "sentence_index": 6, "correct_answer": "ムーブメント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新居へのムーブメントは、来週の日曜に行います。", "explanation": "ここは引っ越し（住む場所を移すこと）の意味。ムーブメントは社会的な流れで、住まいの移動は表さない。"}, {"text": "毎朝、牛乳をムーブメントに混ぜています。", "explanation": "ここは材料（食べ物の原料）の意味。ムーブメントは社会的な流れで、牛乳に混ぜる材料にはならない。"}, {"text": "彼女は駅前で、ムーブメントを売り歩きました。", "explanation": "ここは商品（売る品物）の意味。ムーブメントは社会の流れで、物として売ることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38788, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "若者の間で、新しいムーブメントを広がりました。", "corrected_sentence": "若者の間で、新しいムーブメントが広がりました。", "error_description": "「広がる」は自動詞なので、動きの主語は「が」で示す。「を」は他動詞の目的語につくので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38788, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "清掃のムーブメントを、大勢が加わりました。", "corrected_sentence": "清掃のムーブメントに、大勢が加わりました。", "error_description": "「加わる」は「に」で参加先を示す。「を」は目的語につくので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38789, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。ムーブメントが「生まれる」の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「生まれる」は目的語を取らない自動詞なので「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「ムーブメントに生まれる」は不自然。「に」は生まれる場所や相手を表す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表し、ここで生まれる主体を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。ムーブメントが「生まれる」の主語になる。", "を": "「生まれる」は目的語を取らない自動詞なので「を」は合わない。", "に": "「ムーブメントに生まれる」は不自然。「に」は生まれる場所や相手を表す。", "と": "「と」は並列や引用を表し、ここで生まれる主体を示せない。"}, "error_tags": {"を": "目的語（主語ではない）", "に": "位置・相手", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38789, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38789, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人々の間に広がる新しい考えや社会的な動きのこと。", "primary_collocate": null, "pronunciation": "むーぶめんと", "ipa": "mɯːbɯmeɴto", "syllable_count": 6, "sentences": [{"text": "新しい働き方を求めるムーブメントが、世界に広がっています。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "新[あたら]しい働[はたら]き方[かた]を求[もと]めるムーブメントが、世界[せかい]に広[ひろ]がっています。", "sentence_source": "generated"}, {"text": "十九世紀、芸術の新しいムーブメントがパリで生まれました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "十九世紀[じゅうきゅうせいき]、芸術[げいじゅつ]の新[あたら]しいムーブメントがパリで生[う]まれました。", "sentence_source": "generated"}, {"text": "健康を大切にするムーブメントが、若い人の間で人気です。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "健康[けんこう]を大切[たいせつ]にするムーブメントが、若[わか]い人[ひと]の間[あいだ]で人気[にんき]です。", "sentence_source": "generated"}, {"text": "インターネットのおかげで、そのムーブメントは国を越えて広がりました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "インターネットのおかげで、そのムーブメントは国[くに]を越[こ]えて広[ひろ]がりました。", "sentence_source": "generated"}, {"text": "手作りの物を見直すムーブメントが、今静かに続いています。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "手作[てづく]りの物[もの]を見直[みなお]すムーブメントが、今[いま]静[しず]かに続[つづ]いています。", "sentence_source": "generated"}, {"text": "古い考えを疑うムーブメントが、大学から始まりました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "古[ふる]い考[かんが]えを疑[うたが]うムーブメントが、大学[だいがく]から始[はじ]まりました。", "sentence_source": "generated"}, {"text": "食べ物を無駄にしないムーブメントは、家庭にも広がりました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]を無駄[むだ]にしないムーブメントは、家庭[かてい]にも広[ひろ]がりました。", "sentence_source": "generated"}, {"text": "そのムーブメントは、社会の見方を大きく変えました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "そのムーブメントは、社会[しゃかい]の見方[みかた]を大[おお]きく変[か]えました。", "sentence_source": "generated"}, {"text": "本を読む時間を増やそうというムーブメントが、国中で話題です。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "本[ほん]を読[よ]む時間[じかん]を増[ふ]やそうというムーブメントが、国中[くにじゅう]で話題[わだい]です。", "sentence_source": "generated"}, {"text": "ムーブメントが広がるにつれて、賛成する人も増えました。", "target_word": "ムーブメント", "complexity_tier": "T3", "furigana": "ムーブメントが広[ひろ]がるにつれて、賛成[さんせい]する人[ひと]も増[ふ]えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ムーブメント", "label": "基本形"}], "register": "polite", "sense_fingerprint": "新しい考え方や流行が社会に広がっていく動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35216ce1-5f8f-42d2-939c-3c153ea82559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38789, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ムーブメント", "is_correct": true, "explanation": "正解。新しい働き方が世界に広がる社会的な流れを指し、「広がっています」に合う。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は物で、考え方や働き方が「世界に広がる」ことはない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は建物の部分で、世界に広がる対象にならない。"}, {"text": "名刺", "is_correct": false, "explanation": "名刺は持ち物で、新しい働き方が広がる流れを表さない。"}], "explanations": {"ムーブメント": "正解。新しい働き方が世界に広がる社会的な流れを指し、「広がっています」に合う。", "石鹸": "石鹸は物で、考え方や働き方が「世界に広がる」ことはない。", "天井": "天井は建物の部分で、世界に広がる対象にならない。", "名刺": "名刺は持ち物で、新しい働き方が広がる流れを表さない。"}, "sentence_index": 0, "correct_answer": "ムーブメント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この時計はムーブメントが古いので、修理に出しました。", "explanation": "ここは時計の内部の機械部分の意味。ムーブメントは社会的な動きで、機械は指さない。"}, {"text": "この時計のムーブメントは、とても正確です。", "explanation": "ここも時計の機械部分の意味。社会的な動きの意味では使わない。"}, {"text": "新しい商品のムーブメントを店頭に貼りました。", "explanation": "ここは広告（宣伝の紙や看板）の意味。ムーブメントは人々の間から自然に広がる流れで、貼り出す物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38789, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ムーブメント", "is_correct": true, "explanation": "正解。食べ物の無駄をなくす社会的な動きを指し、「広がりました」に合う。"}, {"text": "財布", "is_correct": false, "explanation": "財布は持ち物で、考えや動きが「家庭にも広がる」対象にならない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は物で、取り組みの動きが家庭に広がるという文に合わない。"}, {"text": "傘", "is_correct": false, "explanation": "傘は持ち物で、社会的な流れが家庭に広がる文脈に合わない。"}], "explanations": {"ムーブメント": "正解。食べ物の無駄をなくす社会的な動きを指し、「広がりました」に合う。", "財布": "財布は持ち物で、考えや動きが「家庭にも広がる」対象にならない。", "手紙": "手紙は物で、取り組みの動きが家庭に広がるという文に合わない。", "傘": "傘は持ち物で、社会的な流れが家庭に広がる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "ムーブメント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料理は、ムーブメントの味が強いです。", "explanation": "ここは味（食べ物の風味）の意味。ムーブメントは社会に広がる流れで、料理の味は指さない。"}, {"text": "町の人にムーブメントをしました。", "explanation": "ここは調査（情報を集めること）の意味。ムーブメントは社会的な流れで、情報を集める行為には使わない。"}, {"text": "この時計のムーブメントを、修理に出しました。", "explanation": "ここは時計の機械部分の意味。社会的な動きの意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38789, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "環境を守るムーブメントを、学校でも始まりました。", "corrected_sentence": "環境を守るムーブメントが、学校でも始まりました。", "error_description": "「始まる」は自動詞なので、主語は「が」で示す。「を」は他動詞の目的語につくので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38789, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい食べ方を広めるムーブメントに、若者の間に広まりました。", "corrected_sentence": "新しい食べ方を広めるムーブメントが、若者の間に広まりました。", "error_description": "「広まる」の主語は「が」で示す。「に」では主語にならないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38790, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「話の核心」と名詞をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「話を核心は」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「話へ核心は」は名詞をつなげない。"}, {"text": "まで", "is_correct": false, "explanation": "「話まで核心は」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「話の核心」と名詞をつなぐ。", "を": "「話を核心は」は文法的に成り立たない。", "へ": "「話へ核心は」は名詞をつなげない。", "まで": "「話まで核心は」は意味が通らない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "まで": "limit"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "枝葉", "is_correct": true, "explanation": "枝葉は大事でない部分で、核心の反対。"}, {"text": "中心", "is_correct": false, "explanation": "中心は核心に近い類義語で、反対ではない。"}, {"text": "要点", "is_correct": false, "explanation": "要点も大事なところを指す類義語。"}, {"text": "本質", "is_correct": false, "explanation": "本質も中心的な性質を指し、反対ではない。"}], "correct_answer": "枝葉", "explanations": {"枝葉": "枝葉は大事でない部分で、核心の反対。", "中心": "中心は核心に近い類義語で、反対ではない。", "要点": "要点も大事なところを指す類義語。", "本質": "本質も中心的な性質を指し、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38790, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「知りたい」の対象を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「核心に知りたい」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「核心へ知りたい」は方向を表し、対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「核心で知りたい」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「知りたい」の対象を示す「を」。", "に": "「核心に知りたい」は文法的に成り立たない。", "へ": "「核心へ知りたい」は方向を表し、対象にならない。", "で": "「核心で知りたい」は意味が通らない。"}, "error_tags": {"に": "target", "へ": "direction", "で": "location"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "末節", "is_correct": true, "explanation": "末節は些細な部分で、核心の反対。"}, {"text": "根本", "is_correct": false, "explanation": "根本は物事の土台で、核心に近い意味。"}, {"text": "主題", "is_correct": false, "explanation": "主題は中心となる題目で、反対ではない。"}, {"text": "中枢", "is_correct": false, "explanation": "中枢も中心を指す類義語。"}], "correct_answer": "末節", "explanations": {"末節": "末節は些細な部分で、核心の反対。", "根本": "根本は物事の土台で、核心に近い意味。", "主題": "主題は中心となる題目で、反対ではない。", "中枢": "中枢も中心を指す類義語。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38790, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事のいちばん大事なところ。", "primary_collocate": null, "pronunciation": "かくしん", "ipa": "kakɯɕiɴ", "syllable_count": 4, "sentences": [{"text": "話の核心は何ですか。", "target_word": "核心", "complexity_tier": "T2", "furigana": "話[はなし]の核心[かくしん]は何[なん]ですか。", "sentence_source": "generated"}, {"text": "核心をつく。", "target_word": "核心", "complexity_tier": "T1", "furigana": "核心[かくしん]をつく。", "sentence_source": "generated"}, {"text": "先生は核心を教えてくれた。", "target_word": "核心", "complexity_tier": "T3", "furigana": "先生[せんせい]は核心[かくしん]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "これが問題の核心です。", "target_word": "核心", "complexity_tier": "T2", "furigana": "これが問題[もんだい]の核心[かくしん]です。", "sentence_source": "generated"}, {"text": "核心がまだ分かりません。", "target_word": "核心", "complexity_tier": "T2", "furigana": "核心[かくしん]がまだ分[わ]かりません。", "sentence_source": "generated"}, {"text": "核心に近い話を聞いた。", "target_word": "核心", "complexity_tier": "T3", "furigana": "核心[かくしん]に近[ちか]い話[はなし]を聞[き]いた。", "sentence_source": "generated"}, {"text": "彼の言葉は核心をついていた。", "target_word": "核心", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]は核心[かくしん]をついていた。", "sentence_source": "generated"}, {"text": "本当の核心を知りたいです。", "target_word": "核心", "complexity_tier": "T2", "furigana": "本当[ほんとう]の核心[かくしん]を知[し]りたいです。", "sentence_source": "generated"}, {"text": "話の核心だけを短く書いてください。", "target_word": "核心", "complexity_tier": "T3", "furigana": "話[はなし]の核心[かくしん]だけを短[みじか]く書[か]いてください。", "sentence_source": "generated"}, {"text": "核心から話すと、みんなが分かりやすい。", "target_word": "核心", "complexity_tier": "T4", "furigana": "核心[かくしん]から話[はな]すと、みんなが分[わ]かりやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "核心的", "label": "派生"}, {"form": "核心部", "label": "派生"}, {"form": "核心的な", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 物事のいちばん大事なところ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a6e59f-ea65-43a2-8a55-7ec9fc7d85ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38790, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "核心", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "格式", "is_correct": false, "explanation": "かくしき。最後の「ん」が「き」に変わる。"}, {"text": "確執", "is_correct": false, "explanation": "かくしつ。最後の「ん」が「つ」に変わる。"}, {"text": "各人", "is_correct": false, "explanation": "かくじん。「し」が「じ」に変わる。"}], "explanations": {"核心": "見出し語そのもの。", "格式": "かくしき。最後の「ん」が「き」に変わる。", "確執": "かくしつ。最後の「ん」が「つ」に変わる。", "各人": "かくじん。「し」が「じ」に変わる。"}, "sentence_index": null, "correct_answer": "核心"}, "level_3": {"options": [{"text": "核心", "is_correct": true, "explanation": "話のいちばん大事なところを尋ねる意味で合う。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、話の靴は何かという意味が合わない。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、話の野菜は何かという意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、話の季節は何かという意味が合わない。"}], "explanations": {"核心": "話のいちばん大事なところを尋ねる意味で合う。", "靴": "形は合うが、話の靴は何かという意味が合わない。", "野菜": "形は合うが、話の野菜は何かという意味が合わない。", "季節": "形は合うが、話の季節は何かという意味が合わない。"}, "sentence_index": 0, "correct_answer": "核心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、核心を飲んでから学校に行った。", "explanation": "核心は飲むものではなく、動詞との組み合わせが誤り。"}, {"text": "核心は私の妹で、小学生です。", "explanation": "核心は人ではないので、妹として使うのは誤り。"}, {"text": "公園で核心と遊んで、楽しかった。", "explanation": "核心は一緒に遊べる相手ではなく、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38790, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "核心", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "拡散", "is_correct": false, "explanation": "かくさん。「し」が「さ」に変わる。"}, {"text": "北進", "is_correct": false, "explanation": "ほくしん。最初の「か」が「ほ」に変わる。"}, {"text": "特進", "is_correct": false, "explanation": "とくしん。最初の「か」が「と」に変わる。"}], "explanations": {"核心": "見出し語そのもの。", "拡散": "かくさん。「し」が「さ」に変わる。", "北進": "ほくしん。最初の「か」が「ほ」に変わる。", "特進": "とくしん。最初の「か」が「と」に変わる。"}, "sentence_index": null, "correct_answer": "核心"}, "level_3": {"options": [{"text": "核心", "is_correct": true, "explanation": "「核心をつく」で、いちばん大事な点を言い当てる意味。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、言葉が靴をつくという意味が合わない。"}, {"text": "窓", "is_correct": false, "explanation": "形は合うが、言葉が窓をつくという意味が合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "形は合うが、言葉が砂糖をつくという意味が合わない。"}], "explanations": {"核心": "「核心をつく」で、いちばん大事な点を言い当てる意味。", "靴": "形は合うが、言葉が靴をつくという意味が合わない。", "窓": "形は合うが、言葉が窓をつくという意味が合わない。", "砂糖": "形は合うが、言葉が砂糖をつくという意味が合わない。"}, "sentence_index": 6, "correct_answer": "核心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "核心を二枚買って、かばんに入れた。", "explanation": "核心は物事の大事な部分で、買って数える物ではない。"}, {"text": "彼の核心は毎朝七時に起きて走っている。", "explanation": "核心は人ではなく、走るなどの動作主にならない。"}, {"text": "雨が降ったので、核心を着て出かけた。", "explanation": "核心は着るものではなく、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
