INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38791, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「核心に触れる」で、触れる対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「核心が触れなかった」では核心が触れる主体になり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「核心で触れなかった」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「核心と触れなかった」は文法的に成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「核心に触れる」で、触れる対象を示す。", "が": "「核心が触れなかった」では核心が触れる主体になり、文が成り立たない。", "で": "「核心で触れなかった」は意味が通らない。", "と": "「核心と触れなかった」は文法的に成り立たない。"}, "error_tags": {"が": "subject_marker", "で": "location", "と": "comitative"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "枝葉", "is_correct": true, "explanation": "枝葉は重要でない部分で、核心の反対。"}, {"text": "中心", "is_correct": false, "explanation": "中心は核心に近い類義語で、反対ではない。"}, {"text": "要点", "is_correct": false, "explanation": "要点も重要な部分を指す類義語。"}, {"text": "本質", "is_correct": false, "explanation": "本質も中心的な性質を指し、反対ではない。"}], "correct_answer": "枝葉", "explanations": {"枝葉": "枝葉は重要でない部分で、核心の反対。", "中心": "中心は核心に近い類義語で、反対ではない。", "要点": "要点も重要な部分を指す類義語。", "本質": "本質も中心的な性質を指し、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38791, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「核心から外れる」で、離れる起点を表す。"}, {"text": "に", "is_correct": false, "explanation": "「核心に外れている」は文法的に不自然。"}, {"text": "で", "is_correct": false, "explanation": "「核心で外れている」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「核心と外れている」は文法的に成り立たない。"}], "correct_answer": "から", "explanations": {"から": "「核心から外れる」で、離れる起点を表す。", "に": "「核心に外れている」は文法的に不自然。", "で": "「核心で外れている」は意味が通らない。", "と": "「核心と外れている」は文法的に成り立たない。"}, "error_tags": {"に": "target", "で": "location", "と": "comitative"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "末節", "is_correct": true, "explanation": "末節は些細な部分で、核心の反対。"}, {"text": "根本", "is_correct": false, "explanation": "根本は物事の土台で、核心に近い意味。"}, {"text": "主題", "is_correct": false, "explanation": "主題は中心となる題目で、反対ではない。"}, {"text": "中枢", "is_correct": false, "explanation": "中枢も中心を指す類義語。"}], "correct_answer": "末節", "explanations": {"末節": "末節は些細な部分で、核心の反対。", "根本": "根本は物事の土台で、核心に近い意味。", "主題": "主題は中心となる題目で、反対ではない。", "中枢": "中枢も中心を指す類義語。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38791, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の中心となる、最も重要な部分。", "primary_collocate": null, "pronunciation": "かくしん", "ipa": "kakɯɕiɴ", "syllable_count": 4, "sentences": [{"text": "建築を単なる機能の集合体ではなく、記号が織りなすテキストとして読み解く態度が、ポスト構造主義に基づく批評の核心です。", "target_word": "核心", "complexity_tier": "T6", "furigana": "建築[けんちく]を単[たん]なる機能[きのう]の集合体[しゅうごうたい]ではなく、記号[きごう]が織[お]りなすテキストとして読[よ]み解[と]く態度[たいど]が、ポスト構造主義[こうぞうしゅぎ]に基[もと]づく批評[ひひょう]の核心[かくしん]です。", "sentence_source": "mined"}, {"text": "彼は話の核心に触れなかった。", "target_word": "核心", "complexity_tier": "T3", "furigana": "彼[かれ]は話[はなし]の核心[かくしん]に触[ふ]れなかった。", "sentence_source": "generated"}, {"text": "問題の核心は、お金ではなく時間だ。", "target_word": "核心", "complexity_tier": "T3", "furigana": "問題[もんだい]の核心[かくしん]は、お金[かね]ではなく時間[じかん]だ。", "sentence_source": "generated"}, {"text": "質問は核心を突いていた。", "target_word": "核心", "complexity_tier": "T3", "furigana": "質問[しつもん]は核心[かくしん]を突[つ]いていた。", "sentence_source": "generated"}, {"text": "核心を話してください。", "target_word": "核心", "complexity_tier": "T3", "furigana": "核心[かくしん]を話[はな]してください。", "sentence_source": "generated"}, {"text": "調査で事件の核心が明らかになった。", "target_word": "核心", "complexity_tier": "T3", "furigana": "調査[ちょうさ]で事件[じけん]の核心[かくしん]が明[あき]らかになった。", "sentence_source": "generated"}, {"text": "核心に近づくほど、話は難しくなる。", "target_word": "核心", "complexity_tier": "T3", "furigana": "核心[かくしん]に近[ちか]づくほど、話[はなし]は難[むずか]しくなる。", "sentence_source": "generated"}, {"text": "彼の説明は核心から外れている。", "target_word": "核心", "complexity_tier": "T3", "furigana": "彼[かれ]の説明[せつめい]は核心[かくしん]から外[はず]れている。", "sentence_source": "generated"}, {"text": "大切なのは、計画の核心を理解することです。", "target_word": "核心", "complexity_tier": "T3", "furigana": "大切[たいせつ]なのは、計画[けいかく]の核心[かくしん]を理解[りかい]することです。", "sentence_source": "generated"}, {"text": "核心に迫る質問が出された。", "target_word": "核心", "complexity_tier": "T4", "furigana": "核心[かくしん]に迫[せま]る質問[しつもん]が出[だ]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "核心的", "label": "派生"}, {"form": "核心部", "label": "派生"}, {"form": "核心的な", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 物事の中心となる最も重要な部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a6e59f-ea65-43a2-8a55-7ec9fc7d85ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38791, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "核心", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "格式", "is_correct": false, "explanation": "かくしき。最後の「ん」が「き」に変わる。"}, {"text": "確執", "is_correct": false, "explanation": "かくしつ。最後の「ん」が「つ」に変わる。"}, {"text": "各人", "is_correct": false, "explanation": "かくじん。「し」が「じ」に変わる。"}], "explanations": {"核心": "見出し語そのもの。", "格式": "かくしき。最後の「ん」が「き」に変わる。", "確執": "かくしつ。最後の「ん」が「つ」に変わる。", "各人": "かくじん。「し」が「じ」に変わる。"}, "sentence_index": null, "correct_answer": "核心"}, "level_3": {"options": [{"text": "核心", "is_correct": true, "explanation": "批評の最も重要な部分という意味で合う。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、批評の野菜という意味が合わない。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、批評の靴という意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、態度が批評の季節だという意味が合わない。"}], "explanations": {"核心": "批評の最も重要な部分という意味で合う。", "野菜": "形は合うが、批評の野菜という意味が合わない。", "靴": "形は合うが、批評の靴という意味が合わない。", "季節": "形は合うが、態度が批評の季節だという意味が合わない。"}, "sentence_index": 0, "correct_answer": "核心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、核心を二つ食べました。", "explanation": "核心は物事の中心部分で、数えて食べるものではない。"}, {"text": "核心は私の友だちで、毎日一緒に帰る。", "explanation": "核心は人ではないので、友だちとして使うのは誤り。"}, {"text": "雨で核心が濡れてしまったから、傘をさそう。", "explanation": "核心は抽象的な部分で、雨に濡れる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38791, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "核心", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "拡散", "is_correct": false, "explanation": "かくさん。「し」が「さ」に変わる。"}, {"text": "北進", "is_correct": false, "explanation": "ほくしん。最初の「か」が「ほ」に変わる。"}, {"text": "特進", "is_correct": false, "explanation": "とくしん。最初の「か」が「と」に変わる。"}], "explanations": {"核心": "見出し語そのもの。", "拡散": "かくさん。「し」が「さ」に変わる。", "北進": "ほくしん。最初の「か」が「ほ」に変わる。", "特進": "とくしん。最初の「か」が「と」に変わる。"}, "sentence_index": null, "correct_answer": "核心"}, "level_3": {"options": [{"text": "核心", "is_correct": true, "explanation": "中心に近づくほど話が難しくなる意味で合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "形は合うが、砂糖に近づくほど話が難しくなる意味が合わない。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、財布に近づくほど話が難しくなる意味が合わない。"}, {"text": "背中", "is_correct": false, "explanation": "形は合うが、背中に近づくほど話が難しくなる意味が合わない。"}], "explanations": {"核心": "中心に近づくほど話が難しくなる意味で合う。", "砂糖": "形は合うが、砂糖に近づくほど話が難しくなる意味が合わない。", "財布": "形は合うが、財布に近づくほど話が難しくなる意味が合わない。", "背中": "形は合うが、背中に近づくほど話が難しくなる意味が合わない。"}, "sentence_index": 6, "correct_answer": "核心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "核心を歌いながら、公園を散歩した。", "explanation": "核心は歌うものではなく、動詞との組み合わせが誤り。"}, {"text": "彼は核心にバスで乗って、駅へ行った。", "explanation": "核心は乗り物ではなく、意味が合わない。"}, {"text": "朝ごはんに核心を焼いて食べた。", "explanation": "核心は抽象的な部分で、焼いて食べるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
