INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38792, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「密閉すると」の形で、〜したら必ず〜になるという条件を表す。"}, {"text": "を", "is_correct": false, "explanation": "「密閉する」に「を」が続くと目的語を示す形になり、ここでは文がつながらない。"}, {"text": "で", "is_correct": false, "explanation": "「密閉する」に「で」は続かず、手段や場所を表す形にならない。"}, {"text": "に", "is_correct": false, "explanation": "「密閉する」に「に」は続かず、方向や相手を表す形にならない。"}], "correct_answer": "と", "explanations": {"と": "「密閉すると」の形で、〜したら必ず〜になるという条件を表す。", "を": "「密閉する」に「を」が続くと目的語を示す形になり、ここでは文がつながらない。", "で": "「密閉する」に「で」は続かず、手段や場所を表す形にならない。", "に": "「密閉する」に「に」は続かず、方向や相手を表す形にならない。"}, "error_tags": {"を": "目的語（対象）", "で": "手段・場所", "に": "方向・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "開放", "is_correct": true, "explanation": "密閉の反対で、外から空気が入るように開けておく意味。対義語にあたる。"}, {"text": "保存", "is_correct": false, "explanation": "物を長く保つ意味で、閉じる・開けるの対になる語ではない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分を取り除く意味で、密閉の対義語ではない。"}, {"text": "解体", "is_correct": false, "explanation": "組み立てたものをばらす意味で、密閉の対義語ではない。"}], "correct_answer": "開放", "explanations": {"開放": "密閉の反対で、外から空気が入るように開けておく意味。対義語にあたる。", "保存": "物を長く保つ意味で、閉じる・開けるの対になる語ではない。", "乾燥": "水分を取り除く意味で、密閉の対義語ではない。", "解体": "組み立てたものをばらす意味で、密閉の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38792, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "開放", "is_correct": true, "explanation": "密閉の反対で、外から空気が入るように開けておく意味。対義語にあたる。"}, {"text": "収納", "is_correct": false, "explanation": "しまって置く意味で、閉じる状態の対義語ではない。"}, {"text": "注入", "is_correct": false, "explanation": "中に流し入れる意味で、密閉の対義語ではない。"}, {"text": "解凍", "is_correct": false, "explanation": "凍ったものを溶かす意味で、密閉の対義語ではない。"}], "correct_answer": "開放", "explanations": {"開放": "密閉の反対で、外から空気が入るように開けておく意味。対義語にあたる。", "収納": "しまって置く意味で、閉じる状態の対義語ではない。", "注入": "中に流し入れる意味で、密閉の対義語ではない。", "解凍": "凍ったものを溶かす意味で、密閉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38792, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを、中に空気が入らないように、しっかりと閉じること。", "primary_collocate": null, "pronunciation": "みっぺい", "ipa": "mippeː", "syllable_count": 4, "sentences": [{"text": "袋の口を密閉して、冷蔵庫に入れた。", "target_word": "密閉", "complexity_tier": "T3", "furigana": "袋[ふくろ]の口[くち]を密閉[みっぺい]して、冷蔵庫[れいぞうこ]に入[い]れた。", "sentence_source": "generated"}, {"text": "部屋を密閉すると、空気が入れ替わらず息苦しくなる。", "target_word": "密閉", "complexity_tier": "T3", "furigana": "部屋[へや]を密閉[みっぺい]すると、空気[くうき]が入[い]れ替[か]わらず息苦[いきぐる]しくなる。", "sentence_source": "generated"}, {"text": "密閉した部屋で火を使うのは危険だ。", "target_word": "密閉", "complexity_tier": "T3", "furigana": "密閉[みっぺい]した部屋[へや]で火[ひ]を使[つか]うのは危険[きけん]だ。", "sentence_source": "generated"}, {"text": "箱のすき間をテープで密閉した。", "target_word": "密閉", "complexity_tier": "T3", "furigana": "箱[はこ]のすき間[ま]をテープで密閉[みっぺい]した。", "sentence_source": "generated"}, {"text": "海苔は湿りやすいので、密閉して保存する。", "target_word": "密閉", "complexity_tier": "T3", "furigana": "海苔[のり]は湿[しめ]りやすいので、密閉[みっぺい]して保存[ほぞん]する。", "sentence_source": "generated"}, {"text": "密閉された箱の中は、音もほとんど聞こえなかった。", "target_word": "密閉", "complexity_tier": "T3", "furigana": "密閉[みっぺい]された箱[はこ]の中[なか]は、音[おと]もほとんど聞[き]こえなかった。", "sentence_source": "generated"}, {"text": "湿気が入らないよう、荷物を密閉してから船で運んだ。", "target_word": "密閉", "complexity_tier": "T3", "furigana": "湿気[しっけ]が入[はい]らないよう、荷物[にもつ]を密閉[みっぺい]してから船[ふね]で運[はこ]んだ。", "sentence_source": "generated"}, {"text": "古い建物は、冬に冷たい風が入るほど密閉されていない。", "target_word": "密閉", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]は、冬[ふゆ]に冷[つめ]たい風[かぜ]が入[はい]るほど密閉[みっぺい]されていない。", "sentence_source": "generated"}, {"text": "袋を密閉しなかったので、中のクッキーが湿ってしまった。", "target_word": "密閉", "complexity_tier": "T3", "furigana": "袋[ふくろ]を密閉[みっぺい]しなかったので、中[なか]のクッキーが湿[しめ]ってしまった。", "sentence_source": "generated"}, {"text": "密閉は、食べ物を長く保つための基本だ。", "target_word": "密閉", "complexity_tier": "T3", "furigana": "密閉[みっぺい]は、食[た]べ物[もの]を長[なが]く保[たも]つための基本[きほん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "密閉", "label": "基本形"}, {"form": "密閉する", "label": "動詞形（する）"}, {"form": "密閉した", "label": "過去形"}, {"form": "密閉される", "label": "受身形"}, {"form": "密閉して", "label": "て形"}], "register": "neutral (plain form)", "sense_fingerprint": "密閉 as tightly closing a thing (bag, room, box) so that no air gets in", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6a65927-b447-4fa1-9765-03dbf2c9836d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38792, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密閉", "is_correct": true, "explanation": "空気が入らないように閉じるという意味で、「袋の口を〜して、冷蔵庫に入れた」に合う。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味で、袋の口を閉じる動作には使えない。"}, {"text": "解凍", "is_correct": false, "explanation": "凍ったものを溶かす意味で、袋の口には使わない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分を取り除く意味で、袋の口を閉じる動作とは合わない。"}], "explanations": {"密閉": "空気が入らないように閉じるという意味で、「袋の口を〜して、冷蔵庫に入れた」に合う。", "点火": "火をつける意味で、袋の口を閉じる動作には使えない。", "解凍": "凍ったものを溶かす意味で、袋の口には使わない。", "乾燥": "水分を取り除く意味で、袋の口を閉じる動作とは合わない。"}, "sentence_index": 0, "correct_answer": "密閉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の海岸は、人を密閉するほど混んでいて歩けなかった。", "explanation": "ここは〈密集〉の意味。人が詰まって並ぶ様子は密集と言い、密閉は容器などを空気が入らないように閉じる場合にしか使わない。"}, {"text": "大雨で川沿いの道を密閉したため、車が通れなくなった。", "explanation": "ここは〈封鎖〉の意味。道を通れなくすることは封鎖と言い、密閉は空気が入らないように閉じるときに使う。"}, {"text": "両国は、経済面で関係を密閉している。", "explanation": "ここは〈密接〉の意味。国どうしの関係の近さは密接と言い、密閉は物を空気から遮断する閉じ方にしか使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38792, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密閉", "is_correct": true, "explanation": "荷物を空気が入らないように閉じる意味で、「荷物を〜してから船で運んだ」に合う。"}, {"text": "脱水", "is_correct": false, "explanation": "水分を抜く意味で、荷物を閉じる動作ではない。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつける意味で、荷物には使わない。"}, {"text": "解剖", "is_correct": false, "explanation": "生き物の体を切り開いて調べる意味で、荷物には使わない。"}], "explanations": {"密閉": "荷物を空気が入らないように閉じる意味で、「荷物を〜してから船で運んだ」に合う。", "脱水": "水分を抜く意味で、荷物を閉じる動作ではない。", "点灯": "明かりをつける意味で、荷物には使わない。", "解剖": "生き物の体を切り開いて調べる意味で、荷物には使わない。"}, "sentence_index": 6, "correct_answer": "密閉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きな写真データを密閉して、メールに添付した。", "explanation": "ここは〈圧縮〉の意味。データの容量を小さくすることは圧縮と言い、密閉は空気を入れない閉じ方に使う。"}, {"text": "感染の疑いがある人を、別の部屋に密閉した。", "explanation": "ここは〈隔離〉の意味。人を他から離して置くことは隔離と言い、密閉は容器を空気が入らないように閉じるときに使う。"}, {"text": "両国は、極秘の取り決めを密閉して結んだ。", "explanation": "ここは〈密約〉の意味。秘密の取り決めは密約と言い、密閉は物を空気が入らないように閉じるときに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38792, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ふたを密閉たので、中身が漏れなかった。", "corrected_sentence": "ふたを密閉したので、中身が漏れなかった。", "error_description": "「密閉た」は誤り。「密閉する」の過去形は「密閉した」で、「する」を落とすと動詞として成り立たない。正しくは「密閉した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38792, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "箱を密閉に、中身がこぼれなかった。", "corrected_sentence": "箱を密閉して、中身がこぼれなかった。", "error_description": "「密閉に」は誤り。動作をつなぐ「密閉して」の形にする必要があり、「に」は続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
