INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38796, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「市販のシャンプー」の「の」。「市販」を「シャンプー」に続けて名詞句にする。"}, {"text": "が", "is_correct": false, "explanation": "「市販が」は主語の形だが、後ろの「シャンプーで」とつながらず文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「市販を」は目的語の形だが、後ろの「シャンプー」とつながらず意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「市販へ」は方向を表すが、後ろの「シャンプー」にはつながらない。"}], "correct_answer": "の", "explanations": {"の": "「市販のシャンプー」の「の」。「市販」を「シャンプー」に続けて名詞句にする。", "が": "「市販が」は主語の形だが、後ろの「シャンプーで」とつながらず文が成り立たない。", "を": "「市販を」は目的語の形だが、後ろの「シャンプー」とつながらず意味が通らない。", "へ": "「市販へ」は方向を表すが、後ろの「シャンプー」にはつながらない。"}, "error_tags": {"が": "主語（後続と成り立たない）", "を": "目的語（後続と成り立たない）", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38796, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お店で売っていること。", "primary_collocate": null, "pronunciation": "しはん", "ipa": "ɕihaɴ", "syllable_count": 3, "sentences": [{"text": "市販の風邪薬を飲んだら、少し楽になりました。", "target_word": "市販", "complexity_tier": "T3", "furigana": "市販[しはん]の風邪薬[かぜぐすり]を飲[の]んだら、少[すこ]し楽[らく]になりました。", "sentence_source": "generated"}, {"text": "このお菓子は市販されていないので、店では買えません。", "target_word": "市販", "complexity_tier": "T3", "furigana": "このお菓子[かし]は市販[しはん]されていないので、店[みせ]では買[か]えません。", "sentence_source": "generated"}, {"text": "市販のカレールーを使えば、簡単に作れます。", "target_word": "市販", "complexity_tier": "T3", "furigana": "市販[しはん]のカレールーを使[つか]えば、簡単[かんたん]に作[つく]れます。", "sentence_source": "generated"}, {"text": "母は市販のソースではなく、自分で作ったソースを使います。", "target_word": "市販", "complexity_tier": "T3", "furigana": "母[はは]は市販[しはん]のソースではなく、自分[じぶん]で作[つく]ったソースを使[つか]います。", "sentence_source": "generated"}, {"text": "この機械は来月から市販される予定です。", "target_word": "市販", "complexity_tier": "T3", "furigana": "この機械[きかい]は来月[らいげつ]から市販[しはん]される予定[よてい]です。", "sentence_source": "generated"}, {"text": "市販の地図には、この小さな道は載っていませんでした。", "target_word": "市販", "complexity_tier": "T3", "furigana": "市販[しはん]の地図[ちず]には、この小[ちい]さな道[みち]は載[の]っていませんでした。", "sentence_source": "generated"}, {"text": "試作品はよかったのですが、市販までには時間がかかるそうです。", "target_word": "市販", "complexity_tier": "T3", "furigana": "試作品[しさくひん]はよかったのですが、市販[しはん]までには時間[じかん]がかかるそうです。", "sentence_source": "generated"}, {"text": "市販のシャンプーで髪が荒れたので、別の物に変えました。", "target_word": "市販", "complexity_tier": "T3", "furigana": "市販[しはん]のシャンプーで髪[かみ]が荒[あ]れたので、別[べつ]の物[もの]に変[か]えました。", "sentence_source": "generated"}, {"text": "薬局に行かなくても、市販の薬ならスーパーで買えます。", "target_word": "市販", "complexity_tier": "T3", "furigana": "薬局[やっきょく]に行[い]かなくても、市販[しはん]の薬[くすり]ならスーパーで買[か]えます。", "sentence_source": "generated"}, {"text": "市販のパンより、手作りのパンのほうが私は好きです。", "target_word": "市販", "complexity_tier": "T3", "furigana": "市販[しはん]のパンより、手作[てづく]りのパンのほうが私[わたし]は好[す]きです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "市販", "label": "基本形"}, {"form": "市販の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "お店で一般に売られている状態。市販の薬・市販される", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67562c68-4c35-496f-99ad-14c6fca363a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38796, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市販", "is_correct": true, "explanation": "「市販の風邪薬」は店で売られている風邪薬の意味で、自然に入る。"}, {"text": "音楽", "is_correct": false, "explanation": "「音楽の風邪薬」とは言えず、薬の説明として意味が通らない。"}, {"text": "地下", "is_correct": false, "explanation": "「地下の風邪薬」は意味をなさず、薬の種類を表せない。"}, {"text": "夕方", "is_correct": false, "explanation": "「夕方の風邪薬」とは言えず、薬の種類や性質を表せない。"}], "explanations": {"市販": "「市販の風邪薬」は店で売られている風邪薬の意味で、自然に入る。", "音楽": "「音楽の風邪薬」とは言えず、薬の説明として意味が通らない。", "地下": "「地下の風邪薬」は意味をなさず、薬の種類を表せない。", "夕方": "「夕方の風邪薬」とは言えず、薬の種類や性質を表せない。"}, "sentence_index": 0, "correct_answer": "市販"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町は、新しい道路の計画を市販した。", "explanation": "ここは「公表」の意味（広く知らせること）。「市販」は店で売る商品を指し、計画の発表には使わないので合わない。"}, {"text": "この研究の成果は、学会で市販される予定だ。", "explanation": "ここは「公開」の意味（人に見せる、知らせる）。「市販」は商品を店で売ることで、研究の成果には使わないので合わない。"}, {"text": "町内会が、無料でチラシを市販する。", "explanation": "ここは「配布」の意味（無料で配ること）。「市販」は代金を払って店で買える状態を指すので、無料で配る話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38796, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市販", "is_correct": true, "explanation": "「市販までには時間がかかる」は店で売り出すまでの時間の意味で、自然に入る。"}, {"text": "体重", "is_correct": false, "explanation": "「体重までには時間がかかる」とは言えず、意味が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩までには時間がかかる」は試作品の話に合わず不自然。"}, {"text": "湯気", "is_correct": false, "explanation": "「湯気までには時間がかかる」とは言えず、意味が通らない。"}], "explanations": {"市販": "「市販までには時間がかかる」は店で売り出すまでの時間の意味で、自然に入る。", "体重": "「体重までには時間がかかる」とは言えず、意味が通らない。", "散歩": "「散歩までには時間がかかる」は試作品の話に合わず不自然。", "湯気": "「湯気までには時間がかかる」とは言えず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "市販"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この機械は工場で一台ずつ市販されている。", "explanation": "ここは「製造」の意味（作ること）。「市販」は店で売られている状態を指し、工場での製造には使わないので合わない。"}, {"text": "古い教科書を学校に市販した。", "explanation": "ここは「寄贈」の意味（無償で贈ること）。「市販」は店で売ることで、無償で贈る行為には合わない。"}, {"text": "試供品を、お客さんに市販する。", "explanation": "ここは「提供」の意味（相手に渡すこと）。「市販」は店で売ることを指し、相手に渡す内容には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38796, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この菓子は、今月から市販さている。", "corrected_sentence": "この菓子は、今月から市販されている。", "error_description": "「市販されている」の「れ」が抜けている。「市販される」の活用は「される」「されている」と続け、「さている」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38796, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市販を目薬で、目の疲れが和らいだ。", "corrected_sentence": "市販の目薬で、目の疲れが和らいだ。", "error_description": "「市販の目薬」の「の」が「を」になっている。「市販」は「の」で「目薬」に続けるので、「市販を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38797, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「安い市販のペン」の「の」。「市販」と「ペン」を結んで一つの名詞句にする。"}, {"text": "に", "is_correct": false, "explanation": "「市販に」は方向や対象を表すが、「安い市販にペンで」は文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「市販で」は手段や場所を表すが、「安い市販でペンで」は文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。「安い市販からペンで」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「安い市販のペン」の「の」。「市販」と「ペン」を結んで一つの名詞句にする。", "に": "「市販に」は方向や対象を表すが、「安い市販にペンで」は文が成り立たない。", "で": "「市販で」は手段や場所を表すが、「安い市販でペンで」は文が成り立たない。", "から": "「から」は起点を表す。「安い市販からペンで」は意味が通らない。"}, "error_tags": {"に": "方向・対象", "で": "手段・場所", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38797, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「市販が決まり」の「が」。「市販」が主語として「決まる」につながる。"}, {"text": "を", "is_correct": false, "explanation": "「市販を決まり」は目的語の形だが、「決まる」は目的語を取らず意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「市販へ決まり」は方向を表すが、「決まる」とつながらず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「市販より決まり」は比較で、比べる対象がなく意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「市販が決まり」の「が」。「市販」が主語として「決まる」につながる。", "を": "「市販を決まり」は目的語の形だが、「決まる」は目的語を取らず意味が通らない。", "へ": "「市販へ決まり」は方向を表すが、「決まる」とつながらず不自然。", "より": "「市販より決まり」は比較で、比べる対象がなく意味が通らない。"}, "error_tags": {"を": "目的語（後続と成り立たない）", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38797, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一般の店で売られていること。また、その商品。", "primary_collocate": null, "pronunciation": "しはん", "ipa": "ɕihaɴ", "syllable_count": 3, "sentences": [{"text": "市販のものでも、十分きれいに洗えます。", "target_word": "市販", "complexity_tier": "T3", "furigana": "市販[しはん]のものでも、十分[じゅうぶん]きれいに洗[あら]えます。", "sentence_source": "generated"}, {"text": "安い市販のペンで、書類にサインしました。", "target_word": "市販", "complexity_tier": "T3", "furigana": "安[やす]い市販[しはん]のペンで、書類[しょるい]にサインしました。", "sentence_source": "generated"}, {"text": "手作りと市販を比べると、味はほとんど同じでした。", "target_word": "市販", "complexity_tier": "T3", "furigana": "手作[てづく]りと市販[しはん]を比[くら]べると、味[あじ]はほとんど同[おな]じでした。", "sentence_source": "generated"}, {"text": "市販の弁当は便利ですが、野菜が少ないです。", "target_word": "市販", "complexity_tier": "T3", "furigana": "市販[しはん]の弁当[べんとう]は便利[べんり]ですが、野菜[やさい]が少[すく]ないです。", "sentence_source": "generated"}, {"text": "この道具は工場用で、市販はしていません。", "target_word": "市販", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は工場用[こうじょうよう]で、市販[しはん]はしていません。", "sentence_source": "generated"}, {"text": "市販の肥料を庭の花にまきました。", "target_word": "市販", "complexity_tier": "T3", "furigana": "市販[しはん]の肥料[ひりょう]を庭[にわ]の花[はな]にまきました。", "sentence_source": "generated"}, {"text": "市販の薬が効かなかったので、病院へ行きました。", "target_word": "市販", "complexity_tier": "T3", "furigana": "市販[しはん]の薬[くすり]が効[き]かなかったので、病院[びょういん]へ行[い]きました。", "sentence_source": "generated"}, {"text": "新しいゲーム機の市販が決まり、店の前に人が並びました。", "target_word": "市販", "complexity_tier": "T3", "furigana": "新[あたら]しいゲーム機[き]の市販[しはん]が決[き]まり、店[みせ]の前[まえ]に人[ひと]が並[なら]びました。", "sentence_source": "generated"}, {"text": "高い市販のかばんより、職人が作った物がほしいです。", "target_word": "市販", "complexity_tier": "T3", "furigana": "高[たか]い市販[しはん]のかばんより、職人[しょくにん]が作[つく]った物[もの]がほしいです。", "sentence_source": "generated"}, {"text": "市販の絵の具でも、工夫すればいい色が出せます。", "target_word": "市販", "complexity_tier": "T3", "furigana": "市販[しはん]の絵[え]の具[ぐ]でも、工夫[くふう]すればいい色[いろ]が出[だ]せます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "市販", "label": "基本形"}, {"form": "市販の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "一般の店で売られていること、またその商品。手作り・専門用と対比される", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67562c68-4c35-496f-99ad-14c6fca363a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38797, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市販", "is_correct": true, "explanation": "「市販のものでも」は店で売られている品物の意味で、自然に入る。"}, {"text": "夜間", "is_correct": false, "explanation": "「夜間のもの」は不自然で、洗える物の説明にならない。"}, {"text": "午前", "is_correct": false, "explanation": "「午前のもの」は不自然で、洗える物の説明にならない。"}, {"text": "氷山", "is_correct": false, "explanation": "「氷山のもの」は洗える物として成り立たず、文が通らない。"}], "explanations": {"市販": "「市販のものでも」は店で売られている品物の意味で、自然に入る。", "夜間": "「夜間のもの」は不自然で、洗える物の説明にならない。", "午前": "「午前のもの」は不自然で、洗える物の説明にならない。", "氷山": "「氷山のもの」は洗える物として成り立たず、文が通らない。"}, "sentence_index": 0, "correct_answer": "市販"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このケーキは祖母の市販だ。", "explanation": "ここは「手作り」の意味（家で作ったもの）。「市販」は店で売られている商品を指し、人が作った物には使わないので合わない。"}, {"text": "この冊子は市販で、来店したお客さんに無料で配っている。", "explanation": "ここは「非売品」の意味（売らない品）。「市販」は一般の店で売られている商品を指し、無料で配る品には使わないので合わない。"}, {"text": "この靴は市販で、足の形に合わせて作られた。", "explanation": "ここは「特注」の意味（注文に合わせて作ること）。「市販」は不特定多数に売る商品を指し、個人の注文に合わせた物には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38797, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市販", "is_correct": true, "explanation": "「市販の薬」は店で売られている薬の意味で、自然に入る。"}, {"text": "線香", "is_correct": false, "explanation": "「線香の薬」とは言えず、薬の説明として意味が通らない。"}, {"text": "布団", "is_correct": false, "explanation": "「布団の薬」は成り立たず、薬の種類を表せない。"}, {"text": "竹林", "is_correct": false, "explanation": "「竹林の薬」は意味をなさず、文が通らない。"}], "explanations": {"市販": "「市販の薬」は店で売られている薬の意味で、自然に入る。", "線香": "「線香の薬」とは言えず、薬の説明として意味が通らない。", "布団": "「布団の薬」は成り立たず、薬の種類を表せない。", "竹林": "「竹林の薬」は意味をなさず、文が通らない。"}, "sentence_index": 6, "correct_answer": "市販"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このジャムは市販で、家族で作った。", "explanation": "ここは「自家製」の意味（家で作ったもの）。「市販」は店で売っている品を指し、家族で作ったという内容とは矛盾するので合わない。"}, {"text": "この茶碗は職人の市販で作られている。", "explanation": "ここは「手仕事」の意味（手で作ること）。「市販」は店で売られる商品を指し、作り方は表さないので合わない。"}, {"text": "この包丁は、開発中の試作品の市販だ。", "explanation": "ここは「試作品」の意味（試しに作った製品）。「市販」は店で売られている商品を指し、開発中の試作品には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38797, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市販が洗剤で、服の汚れが落ちた。", "corrected_sentence": "市販の洗剤で、服の汚れが落ちた。", "error_description": "「市販の洗剤」の「の」が「が」になっている。「市販」は「の」で「洗剤」に続けるので、「市販が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38797, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この洗剤は、来年から市販された予定だ。", "corrected_sentence": "この洗剤は、来年から市販される予定だ。", "error_description": "「予定」は未来の計画を表すので、「市販される予定」が正しい。「市販された」は過去の形で、時制が合わず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38798, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "薄手", "is_correct": true, "explanation": "厚手の対義語で、厚さが小さい布や紙を指す。この文の厚いカーテンと反対の意味になる。"}, {"text": "大型", "is_correct": false, "explanation": "大型は大きさの対義語で、厚さの反対語ではないので合わない。"}, {"text": "小型", "is_correct": false, "explanation": "小型は大型の対義語で、厚さとは関係しないので不適切。"}, {"text": "軽量", "is_correct": false, "explanation": "軽量は重さが少ないことを表し、厚さの反対語ではない。"}], "correct_answer": "薄手", "explanations": {"薄手": "厚手の対義語で、厚さが小さい布や紙を指す。この文の厚いカーテンと反対の意味になる。", "大型": "大型は大きさの対義語で、厚さの反対語ではないので合わない。", "小型": "小型は大型の対義語で、厚さとは関係しないので不適切。", "軽量": "軽量は重さが少ないことを表し、厚さの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38798, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "薄手", "is_correct": true, "explanation": "厚手の対義語で、物の厚さが小さいことを表す。この文の厚い手帳と反対の意味になる。"}, {"text": "重量", "is_correct": false, "explanation": "重量は重さの量を表し、厚さの反対語ではない。"}, {"text": "大判", "is_correct": false, "explanation": "大判は判型が大きいことを指し、厚さとは関係ない。"}, {"text": "厚紙", "is_correct": false, "explanation": "厚紙は厚い紙の一種で、厚手の反対語ではない。"}], "correct_answer": "薄手", "explanations": {"薄手": "厚手の対義語で、物の厚さが小さいことを表す。この文の厚い手帳と反対の意味になる。", "重量": "重量は重さの量を表し、厚さの反対語ではない。", "大判": "大判は判型が大きいことを指し、厚さとは関係ない。", "厚紙": "厚紙は厚い紙の一種で、厚手の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38798, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ものが、ふつうよりあついこと。", "primary_collocate": null, "pronunciation": "あつで", "ipa": "atsɯde", "syllable_count": 3, "sentences": [{"text": "冬は厚手のコートがないと、外に出られません。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "冬[ふゆ]は厚手[あつで]のコートがないと、外[そと]に出[で]られません。", "sentence_source": "generated"}, {"text": "厚手の紙なので、インクが裏にうつりません。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]の紙[かみ]なので、インクが裏[うら]にうつりません。", "sentence_source": "generated"}, {"text": "この靴下は厚手で、足が温かいです。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "この靴下[くつした]は厚手[あつで]で、足[あし]が温[あたた]かいです。", "sentence_source": "generated"}, {"text": "厚手のカーテンを閉めたら、部屋が暗くなりました。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]のカーテンを閉[し]めたら、部屋[へや]が暗[くら]くなりました。", "sentence_source": "generated"}, {"text": "夏に厚手の服を着ると、汗をかいてしまいます。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "夏[なつ]に厚手[あつで]の服[ふく]を着[き]ると、汗[あせ]をかいてしまいます。", "sentence_source": "generated"}, {"text": "厚手のタオルは、水をよく吸います。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]のタオルは、水[みず]をよく吸[す]います。", "sentence_source": "generated"}, {"text": "薄手のシャツでは寒いので、厚手のセーターを選びました。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "薄手[うすで]のシャツでは寒[さむ]いので、厚手[あつで]のセーターを選[えら]びました。", "sentence_source": "generated"}, {"text": "厚手のビニール袋は、重い荷物を入れても破れません。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]のビニール袋[ぶくろ]は、重[おも]い荷物[にもつ]を入[い]れても破[やぶ]れません。", "sentence_source": "generated"}, {"text": "厚手の生地は、ミシンで縫うのが大変です。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]の生地[きじ]は、ミシンで縫[ぬ]うのが大変[たいへん]です。", "sentence_source": "generated"}, {"text": "厚手の手帳は、持ち歩くと少し重いです。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]の手帳[てちょう]は、持[も]ち歩[ある]くと少[すこ]し重[おも]いです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "厚手", "label": "基本形"}, {"form": "厚手の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "布・紙などが普通より厚いこと。薄手の対", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67562c68-4c35-496f-99ad-14c6fca363a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38798, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厚手", "is_correct": true, "explanation": "生地が厚く保温性の高い服を指すので、冬の外出に必要なコートとして文に合う。"}, {"text": "大手", "is_correct": false, "explanation": "大手は大企業を指す名詞で、コートの厚さや種類を表せない。"}, {"text": "上手", "is_correct": false, "explanation": "上手は技量が優れていることを表し、服の厚みは表せない。"}, {"text": "白紙", "is_correct": false, "explanation": "白紙は何も書かれていない紙の状態を指し、コートには合わない。"}], "explanations": {"厚手": "生地が厚く保温性の高い服を指すので、冬の外出に必要なコートとして文に合う。", "大手": "大手は大企業を指す名詞で、コートの厚さや種類を表せない。", "上手": "上手は技量が優れていることを表し、服の厚みは表せない。", "白紙": "白紙は何も書かれていない紙の状態を指し、コートには合わない。"}, "sentence_index": 0, "correct_answer": "厚手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は上司から厚手の信頼を寄せられ、重要な案件を任された。", "explanation": "ここは信頼や気持ちが深いことを表す〈厚い〉が合う。厚手は物の厚さを表すので、信頼の深さには使わない。"}, {"text": "彼女は厚手の性格で、誰にでも穏やかに接する。", "explanation": "ここは人柄が穏やかな〈温厚〉の意味。厚手は物の厚さを言うので、人の性格には使わない。"}, {"text": "彼女は厚手の支援を受けて、研究を続けることができた。", "explanation": "ここは手厚く助けるの〈手厚い〉が合う。厚手は物の厚さを表すので、支援には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38798, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厚手", "is_correct": true, "explanation": "寒さをしのぐため保温性のある厚い服を指すので、薄手のシャツと対比して厚手のセーターに合う。"}, {"text": "名物", "is_correct": false, "explanation": "名物は地域で有名な産物を指し、セーターの厚さを表せない。"}, {"text": "老舗", "is_correct": false, "explanation": "老舗は長く続く店のことで、服の厚みとは無関係。"}, {"text": "大物", "is_correct": false, "explanation": "大物は有力者や大きな物を指し、服の厚さには合わない。"}], "explanations": {"厚手": "寒さをしのぐため保温性のある厚い服を指すので、薄手のシャツと対比して厚手のセーターに合う。", "名物": "名物は地域で有名な産物を指し、セーターの厚さを表せない。", "老舗": "老舗は長く続く店のことで、服の厚みとは無関係。", "大物": "大物は有力者や大きな物を指し、服の厚さには合わない。"}, "sentence_index": 6, "correct_answer": "厚手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は厚手の看護を受けて、すぐに回復した。", "explanation": "ここは丁寧で行き届いた〈手厚い〉の意味。厚手は素材の厚さを表すので、看護の丁寧さには使わない。"}, {"text": "新しい会社では厚手の待遇を受けて、給料も上がった。", "explanation": "ここは手厚くもてなされる〈厚遇〉が合う。厚手は物の厚みに使うので、待遇には使わない。"}, {"text": "彼の厚手のお心づかいに、ずっと感謝している。", "explanation": "ここは親切な心づかいの〈厚意〉の意味。厚手は物の厚さに使う語で、気持ちには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38798, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この毛布は厚手に、冬の夜も暖かいです。", "corrected_sentence": "この毛布は厚手で、冬の夜も暖かいです。", "error_description": "『厚手』は状態を表すとき『で』で続ける。『に』は誤り。正しくは『厚手で』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38798, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この手袋は厚手く、雪の日も指が冷えない。", "corrected_sentence": "この手袋は厚手で、雪の日も指が冷えない。", "error_description": "『厚手』は名詞扱いなので『く』で活用させるのは誤り。状態を述べるときは『で』を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38799, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "薄手", "is_correct": true, "explanation": "厚手の対義語で、厚さが小さい物を指す。この文の厚いクッションと反対の意味になる。"}, {"text": "大判", "is_correct": false, "explanation": "大判は判型が大きいことを指し、厚さの反対語ではない。"}, {"text": "重量", "is_correct": false, "explanation": "重量は重さの量を表し、厚さの対義語にはならない。"}, {"text": "大型", "is_correct": false, "explanation": "大型は大きさの対義語である小型と組むので、厚さの反対語ではない。"}], "correct_answer": "薄手", "explanations": {"薄手": "厚手の対義語で、厚さが小さい物を指す。この文の厚いクッションと反対の意味になる。", "大判": "大判は判型が大きいことを指し、厚さの反対語ではない。", "重量": "重量は重さの量を表し、厚さの対義語にはならない。", "大型": "大型は大きさの対義語である小型と組むので、厚さの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
