INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38799, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物の厚さが標準よりも大きいさま。", "primary_collocate": null, "pronunciation": "あつで", "ipa": "atsɯde", "syllable_count": 3, "sentences": [{"text": "厚手の生地を選んだので、丈夫なバッグができました。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]の生地[きじ]を選[えら]んだので、丈夫[じょうぶ]なバッグができました。", "sentence_source": "generated"}, {"text": "この封筒は厚手で、中の写真が折れません。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "この封筒[ふうとう]は厚手[あつで]で、中[なか]の写真[しゃしん]が折[お]れません。", "sentence_source": "generated"}, {"text": "厚手のジーンズは、冬にちょうどいいです。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]のジーンズは、冬[ふゆ]にちょうどいいです。", "sentence_source": "generated"}, {"text": "厚手の布団を重ねて、寒い夜を過ごしました。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]の布団[ふとん]を重[かさ]ねて、寒[さむ]い夜[よる]を過[す]ごしました。", "sentence_source": "generated"}, {"text": "厚手のフライパンは、熱が均等に伝わります。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]のフライパンは、熱[ねつ]が均等[きんとう]に伝[つた]わります。", "sentence_source": "generated"}, {"text": "厚手のエプロンなので、油がはねても大丈夫です。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]のエプロンなので、油[あぶら]がはねても大丈夫[だいじょうぶ]です。", "sentence_source": "generated"}, {"text": "厚手のゴム手袋をはめて、庭の草を抜きました。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]のゴム手袋[てぶくろ]をはめて、庭[にわ]の草[くさ]を抜[ぬ]きました。", "sentence_source": "generated"}, {"text": "薄い紙は破れやすいので、厚手のものに変えました。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "薄[うす]い紙[かみ]は破[やぶ]れやすいので、厚手[あつで]のものに変[か]えました。", "sentence_source": "generated"}, {"text": "厚手のマットを敷くと、床に座っても痛くありません。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]のマットを敷[し]くと、床[ゆか]に座[すわ]っても痛[いた]くありません。", "sentence_source": "generated"}, {"text": "厚手のフェルトは、切るときに力が要ります。", "target_word": "厚手", "complexity_tier": "T3", "furigana": "厚手[あつで]のフェルトは、切[き]るときに力[ちから]が要[い]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "厚手", "label": "基本形"}, {"form": "厚手の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "素材の厚みが標準より大きい様子。丈夫さ・保温性と結びつく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67562c68-4c35-496f-99ad-14c6fca363a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38799, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厚手", "is_correct": true, "explanation": "厚い布地を指し、丈夫なバッグの素材として文に合う。"}, {"text": "大勢", "is_correct": false, "explanation": "大勢は人数の多さを表すので、布地の厚みには使えない。"}, {"text": "目玉", "is_correct": false, "explanation": "目玉は注目の品や目の玉を指し、生地には合わない。"}, {"text": "上手", "is_correct": false, "explanation": "上手は腕前の高さを指すので、生地の厚さは表せない。"}], "explanations": {"厚手": "厚い布地を指し、丈夫なバッグの素材として文に合う。", "大勢": "大勢は人数の多さを表すので、布地の厚みには使えない。", "目玉": "目玉は注目の品や目の玉を指し、生地には合わない。", "上手": "上手は腕前の高さを指すので、生地の厚さは表せない。"}, "sentence_index": 0, "correct_answer": "厚手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は初対面の相手にも厚手の図々しさで話しかけ、周りを驚かせた。", "explanation": "ここは遠慮がない〈厚かましい〉の意味。厚手は物の厚さを表すので、図々しさには使わない。"}, {"text": "彼は厚手の人柄で、誰とも穏やかに付き合う。", "explanation": "ここは人柄が温かく穏やかな〈温厚〉の意味。厚手は物の厚さを表し、人柄には使わない。"}, {"text": "転職先では厚手の待遇を受けて、給料も上がった。", "explanation": "ここは手厚い扱いの〈厚遇〉が合う。厚手は物の厚みに使うので、待遇には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38799, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厚手", "is_correct": true, "explanation": "手を守るための厚い素材のゴム手袋を指し、草を抜く文に合う。"}, {"text": "名産", "is_correct": false, "explanation": "名産は地域の特産品を指し、手袋の厚さを表せない。"}, {"text": "老舗", "is_correct": false, "explanation": "老舗は長く続く店のことで、手袋の素材とは無関係。"}, {"text": "大物", "is_correct": false, "explanation": "大物は有力者や大きな物を指し、手袋の厚みには合わない。"}], "explanations": {"厚手": "手を守るための厚い素材のゴム手袋を指し、草を抜く文に合う。", "名産": "名産は地域の特産品を指し、手袋の厚さを表せない。", "老舗": "老舗は長く続く店のことで、手袋の素材とは無関係。", "大物": "大物は有力者や大きな物を指し、手袋の厚みには合わない。"}, "sentence_index": 6, "correct_answer": "厚手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は厚手の指導で、一人ひとりを丁寧に見てくれた。", "explanation": "ここは丁寧で行き届いた〈手厚い〉の意味。厚手は物の厚さに使うので、指導の丁寧さには使わない。"}, {"text": "お客さまの厚手のお心づかいに、店長は深く感謝した。", "explanation": "ここは親切な心づかいの〈厚意〉が合う。厚手は素材の厚みを表し、気持ちには使わない。"}, {"text": "彼女は厚手の化粧で、ふだんと印象が違って見えた。", "explanation": "ここは濃く施した化粧を指す〈厚化粧〉の意味。厚手は素材の厚さを表すので、化粧には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38799, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このファイルは厚手に、書類が折れません。", "corrected_sentence": "このファイルは厚手で、書類が折れません。", "error_description": "『厚手』に続けて状態を表すなら『で』が正しい。『に』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38799, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この寝袋は厚手く、冬の山でも暖かく眠れる。", "corrected_sentence": "この寝袋は厚手で、冬の山でも暖かく眠れる。", "error_description": "『厚手』は名詞扱いなので『く』は付かない。状態は『で』で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38800, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "場所を示す『に』で、道が続く位置を表す。『湖の周縁に』で文が自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示すので、道が続くという文では合わない。"}, {"text": "が", "is_correct": false, "explanation": "『が』で主語にすると周縁が続く主体になり、文の意味が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐだけで、場所を示す役割にならない。『のは』では文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "場所を示す『に』で、道が続く位置を表す。『湖の周縁に』で文が自然につながる。", "を": "『を』は目的語を示すので、道が続くという文では合わない。", "が": "『が』で主語にすると周縁が続く主体になり、文の意味が崩れる。", "の": "『の』は名詞をつなぐだけで、場所を示す役割にならない。『のは』では文が成り立たない。"}, "error_tags": {"を": "目的語の誤用", "が": "主語の誤用", "の": "連体修飾の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38800, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "場所を示す『に』で、木を植える位置を表す。『畑の周縁に木を植えて』で自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "『を』が二つになり、『畑の周縁を木を』と二重の目的語になって不自然。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較の基準を示すため、植える場所を表せない。"}, {"text": "が", "is_correct": false, "explanation": "『が』で主語にすると、周縁が木を植える主体になり文の意味が崩れる。"}], "correct_answer": "に", "explanations": {"に": "場所を示す『に』で、木を植える位置を表す。『畑の周縁に木を植えて』で自然に続く。", "を": "『を』が二つになり、『畑の周縁を木を』と二重の目的語になって不自然。", "より": "『より』は比較の基準を示すため、植える場所を表せない。", "が": "『が』で主語にすると、周縁が木を植える主体になり文の意味が崩れる。"}, "error_tags": {"を": "目的語の二重使用", "より": "比較の誤用", "が": "主語の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38800, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "もののふちの部分。", "primary_collocate": null, "pronunciation": "しゅうえん", "ipa": "ɕɯːeɴ", "syllable_count": 4, "sentences": [{"text": "円の周縁に沿って、小さな点を並べました。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "円[えん]の周縁[しゅうえん]に沿[そ]って、小[ちい]さな点[てん]を並[なら]べました。", "sentence_source": "generated"}, {"text": "湖の周縁には、細い道が続いています。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "湖[みずうみ]の周縁[しゅうえん]には、細[ほそ]い道[みち]が続[つづ]いています。", "sentence_source": "generated"}, {"text": "皿の周縁に模様があって、とてもきれいです。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "皿[さら]の周縁[しゅうえん]に模様[もよう]があって、とてもきれいです。", "sentence_source": "generated"}, {"text": "細胞の周縁を顕微鏡で調べました。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "細胞[さいぼう]の周縁[しゅうえん]を顕微鏡[けんびきょう]で調[しら]べました。", "sentence_source": "generated"}, {"text": "台風の周縁では、まだ雨が降っています。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "台風[たいふう]の周縁[しゅうえん]では、まだ雨[あめ]が降[ふ]っています。", "sentence_source": "generated"}, {"text": "都市の周縁に、新しい住宅が増えています。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "都市[とし]の周縁[しゅうえん]に、新[あたら]しい住宅[じゅうたく]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "地図の周縁が破れて、文字が読めません。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "地図[ちず]の周縁[しゅうえん]が破[やぶ]れて、文字[もじ]が読[よ]めません。", "sentence_source": "generated"}, {"text": "畑の周縁に木を植えて、風を防ぎました。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "畑[はたけ]の周縁[しゅうえん]に木[き]を植[う]えて、風[かぜ]を防[ふせ]ぎました。", "sentence_source": "generated"}, {"text": "月の周縁が少し赤く見えました。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "月[つき]の周縁[しゅうえん]が少[すこ]し赤[あか]く見[み]えました。", "sentence_source": "generated"}, {"text": "板の周縁を紙やすりでけずって、なめらかにしました。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "板[いた]の周縁[しゅうえん]を紙[かみ]やすりでけずって、なめらかにしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "周縁", "label": "基本形"}, {"form": "周縁の", "label": "連体形"}], "register": "formal", "sense_fingerprint": "ものの中心に対する、ふちの部分。円・湖・都市などの外側", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67562c68-4c35-496f-99ad-14c6fca363a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38800, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周縁", "is_correct": true, "explanation": "円のふちを指し、『〜に沿って』と自然に続く。"}, {"text": "地平", "is_correct": false, "explanation": "地平は地面と空の境目を指し、円の縁を表せない。"}, {"text": "夕暮れ", "is_correct": false, "explanation": "夕暮れは時間帯のことで、図形の部分には当たらない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時期を表し、円の一部を指すことはできない。"}], "explanations": {"周縁": "円のふちを指し、『〜に沿って』と自然に続く。", "地平": "地平は地面と空の境目を指し、円の縁を表せない。", "夕暮れ": "夕暮れは時間帯のことで、図形の部分には当たらない。", "季節": "季節は時期を表し、円の一部を指すことはできない。"}, "sentence_index": 0, "correct_answer": "周縁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は議論の周縁を突いて、みんなを納得させた。", "explanation": "ここは要点を突く〈核心〉の意味。周縁は物のふちを指すので、話の要点には使わない。"}, {"text": "景気は周縁に達し、その後は少しずつ下がった。", "explanation": "ここは最も高い状態の〈頂点〉が合う。周縁は物の端を指すので、勢いの最高点は表せない。"}, {"text": "問題の周縁を見抜けば、解決の道が見える。", "explanation": "ここは物事の核となる〈本質〉の意味。周縁は外側のふちなので、本質の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38800, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "周縁", "is_correct": true, "explanation": "地図のふちを指し、そこが破れて文字が読めなくなる文に合う。"}, {"text": "恋心", "is_correct": false, "explanation": "恋心は恋愛の気持ちを表し、地図の縁には当たらない。"}, {"text": "旅路", "is_correct": false, "explanation": "旅路は旅の道のりを指し、紙の部分は表せない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は人や物の年数を表し、地図の破れた部分には使えない。"}], "explanations": {"周縁": "地図のふちを指し、そこが破れて文字が読めなくなる文に合う。", "恋心": "恋心は恋愛の気持ちを表し、地図の縁には当たらない。", "旅路": "旅路は旅の道のりを指し、紙の部分は表せない。", "年齢": "年齢は人や物の年数を表し、地図の破れた部分には使えない。"}, "sentence_index": 6, "correct_answer": "周縁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この町は江戸時代に周縁を迎え、多くの人が集まった。", "explanation": "ここは一番栄えた時期の〈最盛期〉が合う。周縁は物のふちを指すので、時期の意味にはならない。"}, {"text": "この小説の周縁は、家族の絆を描くことだ。", "explanation": "ここは作品の中心となる題材の〈主題〉が合う。周縁は外側のふちなので、テーマの意味には使わない。"}, {"text": "会社の周縁は、経営の判断をすべて担っている。", "explanation": "ここは中心となる重要部分の〈中枢〉が合う。周縁は外側を指すので、役割の中心は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38800, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池の周縁を浅いので、子どもも安心して遊べます。", "corrected_sentence": "池の周縁は浅いので、子どもも安心して遊べます。", "error_description": "『池の周縁』は主題を示す『は』で続ける。『を』は目的語を示すため、ここでは文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38800, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "テーブルの周縁が欠けるで、指を切りやすい。", "corrected_sentence": "テーブルの周縁が欠けていて、指を切りやすい。", "error_description": "『欠ける』は『欠けていて』と活用させる。『欠けるで』は活用が誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38801, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を示す『で』で、見た場所を表す。『森の周縁で見ました』で自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "『が』で主語にすると、見る主体が崩れて文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "『を』を重ねると目的語が二つになり、『森の周縁を、シカを』と不自然になる。"}, {"text": "や", "is_correct": false, "explanation": "『や』は並列の途中で終わるため、続く語がなく文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "場所を示す『で』で、見た場所を表す。『森の周縁で見ました』で自然に続く。", "が": "『が』で主語にすると、見る主体が崩れて文が成り立たない。", "を": "『を』を重ねると目的語が二つになり、『森の周縁を、シカを』と不自然になる。", "や": "『や』は並列の途中で終わるため、続く語がなく文が成り立たない。"}, "error_tags": {"が": "主語の誤用", "を": "目的語の二重使用", "や": "並列の不完全"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38801, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "動作の対象を示す『を』で、周縁を折るという文に合う。"}, {"text": "が", "is_correct": false, "explanation": "『が』で主語にすると、周縁が折る主体になり文の意味が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並べる相手が要るが、ここでは並列の相手がなく文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較の基準を示すので、ここでは使えない。"}], "correct_answer": "を", "explanations": {"を": "動作の対象を示す『を』で、周縁を折るという文に合う。", "が": "『が』で主語にすると、周縁が折る主体になり文の意味が崩れる。", "と": "『と』は並べる相手が要るが、ここでは並列の相手がなく文が成り立たない。", "より": "『より』は比較の基準を示すので、ここでは使えない。"}, "error_tags": {"が": "主語の誤用", "と": "並列の不完全", "より": "比較の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38801, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の端やふちの部分。周囲の縁（へり）。", "primary_collocate": null, "pronunciation": "しゅうえん", "ipa": "ɕɯːeɴ", "syllable_count": 4, "sentences": [{"text": "テーブルの周縁にコップを置くと、落ちそうで危ないです。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "テーブルの周縁[しゅうえん]にコップを置[お]くと、落[お]ちそうで危[あぶ]ないです。", "sentence_source": "generated"}, {"text": "森の周縁で、小さなシカを見ました。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "森[もり]の周縁[しゅうえん]で、小[ちい]さなシカを見[み]ました。", "sentence_source": "generated"}, {"text": "池の周縁は浅いので、子どもでも安全に遊べます。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "池[いけ]の周縁[しゅうえん]は浅[あさ]いので、子[こ]どもでも安全[あんぜん]に遊[あそ]べます。", "sentence_source": "generated"}, {"text": "鏡の周縁に金色の飾りがついています。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "鏡[かがみ]の周縁[しゅうえん]に金色[きんいろ]の飾[かざ]りがついています。", "sentence_source": "generated"}, {"text": "画面の周縁が黒くなり、写真が見にくいです。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "画面[がめん]の周縁[しゅうえん]が黒[くろ]くなり、写真[しゃしん]が見[み]にくいです。", "sentence_source": "generated"}, {"text": "町の周縁には、古い田んぼがまだ残っています。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "町[まち]の周縁[しゅうえん]には、古[ふる]い田[た]んぼがまだ残[のこ]っています。", "sentence_source": "generated"}, {"text": "葉の周縁がぎざぎざしているのが、この木の特徴です。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "葉[は]の周縁[しゅうえん]がぎざぎざしているのが、この木[き]の特徴[とくちょう]です。", "sentence_source": "generated"}, {"text": "紙の周縁を折って、箱の形にしました。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "紙[かみ]の周縁[しゅうえん]を折[お]って、箱[はこ]の形[かたち]にしました。", "sentence_source": "generated"}, {"text": "帽子の周縁に、赤いリボンを縫いつけました。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "帽子[ぼうし]の周縁[しゅうえん]に、赤[あか]いリボンを縫[ぬ]いつけました。", "sentence_source": "generated"}, {"text": "島の周縁を船でぐるりと一周しました。", "target_word": "周縁", "complexity_tier": "T3", "furigana": "島[しま]の周縁[しゅうえん]を船[ふね]でぐるりと一周[いっしゅう]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "周縁", "label": "基本形"}, {"form": "周縁の", "label": "連体形"}], "register": "formal", "sense_fingerprint": "物や場所の端・へりにあたる部分。周囲の縁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67562c68-4c35-496f-99ad-14c6fca363a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38801, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周縁", "is_correct": true, "explanation": "テーブルのふちを指し、コップを置く場所として文に合う。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは日の入りの空の色を指し、テーブルの部分にはならない。"}, {"text": "昼寝", "is_correct": false, "explanation": "昼寝は眠ることを表し、物を置く場所を表せない。"}, {"text": "名言", "is_correct": false, "explanation": "名言は心に残る言葉を指し、物の場所には当たらない。"}], "explanations": {"周縁": "テーブルのふちを指し、コップを置く場所として文に合う。", "夕焼け": "夕焼けは日の入りの空の色を指し、テーブルの部分にはならない。", "昼寝": "昼寝は眠ることを表し、物を置く場所を表せない。", "名言": "名言は心に残る言葉を指し、物の場所には当たらない。"}, "sentence_index": 0, "correct_answer": "周縁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議では問題の周縁をつかみ、結論を出した。", "explanation": "ここは要点の〈核心〉が合う。周縁は物のふちを指すので、話の要点は表せない。"}, {"text": "彼女は周縁を言わず、いつも遠回しに話す。", "explanation": "ここは本当の気持ちの〈本音〉が合う。周縁は物のふちなので、気持ちを表す語には使えない。"}, {"text": "この作品は周縁が高く、評価も高い。", "explanation": "ここは仕上がりの程度を表す〈完成度〉が合う。周縁は物の端なので、作品の出来は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38801, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "周縁", "is_correct": true, "explanation": "葉のふちを指し、ぎざぎざした縁が特徴だという文に合う。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は人や木の年数を表し、葉のぎざぎざは表せない。"}, {"text": "恋心", "is_correct": false, "explanation": "恋心は恋愛の気持ちを指し、葉の形には当たらない。"}, {"text": "旅路", "is_correct": false, "explanation": "旅路は旅の道のりを指し、葉の部分を表せない。"}], "explanations": {"周縁": "葉のふちを指し、ぎざぎざした縁が特徴だという文に合う。", "年齢": "年齢は人や木の年数を表し、葉のぎざぎざは表せない。", "恋心": "恋心は恋愛の気持ちを指し、葉の形には当たらない。", "旅路": "旅路は旅の道のりを指し、葉の部分を表せない。"}, "sentence_index": 6, "correct_answer": "周縁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この組織の周縁が、すべての決定を下している。", "explanation": "ここは中心となる重要部分の〈中枢〉が合う。周縁は外側のふちなので、決定の中心は表せない。"}, {"text": "試合は終盤に周縁を迎え、会場が盛り上がった。", "explanation": "ここは一番盛り上がる場面の〈頂点〉が合う。周縁は物の端を指すので、場面の盛り上がりは表せない。"}, {"text": "この寺は江戸時代に周縁の時期を迎えた。", "explanation": "ここは一番栄えた時期の〈最盛期〉が合う。周縁は物のふちを指すので、時期の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38801, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ふたの周縁な部分が欠けている。", "corrected_sentence": "ふたの周縁の部分が欠けている。", "error_description": "『周縁』は名詞なので、後ろの名詞を修飾するときは『の』を使う。『な』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38801, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓の周縁が割れるて、風が入る。", "corrected_sentence": "窓の周縁が割れていて、風が入る。", "error_description": "『割れる』は『割れていて』と活用させる。『割れるて』は活用が誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
