INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38802, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「わかる」の主語を示す格助詞で、「直径が」として文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「わかる」は「が」で主語を取るので、「直径を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「直径へわかれば」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、「直径とわかれば」では文が続かない。"}], "correct_answer": "が", "explanations": {"が": "「わかる」の主語を示す格助詞で、「直径が」として文が成り立つ。", "を": "「わかる」は「が」で主語を取るので、「直径を」は合わない。", "へ": "方向を示すが、「直径へわかれば」では文が成り立たない。", "と": "並列を示すが、「直径とわかれば」では文が続かない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38802, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "丸い形の真ん中を通る、まっすぐな線の長さのことです。", "primary_collocate": null, "pronunciation": "ちょっけい", "ipa": "tɕokkeː", "syllable_count": 4, "sentences": [{"text": "このコップの口の直径は七センチだ。", "target_word": "直径", "complexity_tier": "T2", "furigana": "このコップの口[くち]の直径[ちょっけい]は七[なな]センチだ。", "sentence_source": "generated"}, {"text": "円の半径を二倍にした長さが、直径だ。", "target_word": "直径", "complexity_tier": "T3", "furigana": "円[えん]の半径[はんけい]を二倍[にばい]にした長[なが]さが、直径[ちょっけい]だ。", "sentence_source": "generated"}, {"text": "ピザの直径が三十センチもあって、一人では食べきれなかった。", "target_word": "直径", "complexity_tier": "T3", "furigana": "ピザの直径[ちょっけい]が三十[さんじゅう]センチもあって、一人[ひとり]では食[た]べきれなかった。", "sentence_source": "generated"}, {"text": "この箱は小さいので、直径が十センチを超えるボールは入らない。", "target_word": "直径", "complexity_tier": "T3", "furigana": "この箱[はこ]は小[ちい]さいので、直径[ちょっけい]が十[じゅっ]センチを超[こ]えるボールは入[はい]らない。", "sentence_source": "generated"}, {"text": "丸いテーブルの直径を測って、ちょうどいいクロスを買った。", "target_word": "直径", "complexity_tier": "T3", "furigana": "丸[まる]いテーブルの直径[ちょっけい]を測[はか]って、ちょうどいいクロスを買[か]った。", "sentence_source": "generated"}, {"text": "半径が五センチの円なら、直径は十センチだ。", "target_word": "直径", "complexity_tier": "T2", "furigana": "半径[はんけい]が五[ご]センチの円[えん]なら、直径[ちょっけい]は十[じゅっ]センチだ。", "sentence_source": "generated"}, {"text": "この木は、幹の直径が一メートルもある。", "target_word": "直径", "complexity_tier": "T3", "furigana": "この木[き]は、幹[みき]の直径[ちょっけい]が一[いち]メートルもある。", "sentence_source": "generated"}, {"text": "円の直径がわかれば、その半分の半径もすぐにわかる。", "target_word": "直径", "complexity_tier": "T3", "furigana": "円[えん]の直径[ちょっけい]がわかれば、その半分[はんぶん]の半径[はんけい]もすぐにわかる。", "sentence_source": "generated"}, {"text": "丸い池の直径を歩数で測ったら、約四十歩だった。", "target_word": "直径", "complexity_tier": "T4", "furigana": "丸[まる]い池[いけ]の直径[ちょっけい]を歩数[ほすう]で測[はか]ったら、約[やく]四十歩[よんじゅっぽ]だった。", "sentence_source": "generated"}, {"text": "新しい皿は、古い皿より直径が二センチ大きい。", "target_word": "直径", "complexity_tier": "T3", "furigana": "新[あたら]しい皿[さら]は、古[ふる]い皿より直径[ちょっけい]が二[に]センチ大[おお]きい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直径", "label": "基本形"}], "register": "中立", "sense_fingerprint": "丸い物の真ん中を通る線の長さ(日常の大きさの説明)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20a93d0-c34a-4826-8ae3-e5c131706219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38802, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直径", "is_correct": true, "explanation": "コップの口の大きさを円の中心を通る線の長さで表す語で、「七センチ」と合う。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは質量を表す語で、センチという長さの単位とは合わない。"}, {"text": "硬さ", "is_correct": false, "explanation": "硬さは押したときに変形しにくい度合いを表す語で、長さの数値には続かない。"}, {"text": "明るさ", "is_correct": false, "explanation": "明るさは光の強さを表す語で、「七センチ」とは合わない。"}], "explanations": {"直径": "コップの口の大きさを円の中心を通る線の長さで表す語で、「七センチ」と合う。", "重さ": "重さは質量を表す語で、センチという長さの単位とは合わない。", "硬さ": "硬さは押したときに変形しにくい度合いを表す語で、長さの数値には続かない。", "明るさ": "明るさは光の強さを表す語で、「七センチ」とは合わない。"}, "sentence_index": 0, "correct_answer": "直径"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "円の直径は、中心から円周までの長さだ。", "explanation": "ここは〈半径〉の意味。直径は円の端から端までを結ぶ線全体で、中心から円周までは半径なので合わない。"}, {"text": "円の直径は、円の周りを一周した長さだ。", "explanation": "ここは〈円周〉の意味。直径は中心を通る線の長さで、一周した長さは円周を指すので合わない。"}, {"text": "円の直径は、円の内側の広さを表す。", "explanation": "ここは〈面積〉の意味。直径は長さを表し、内側の広さは面積なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38802, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直径", "is_correct": true, "explanation": "幹の太さを円の中心を通る線の長さで表す語で、「一メートルもある」と合う。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は生まれてからの年数を表す語で、幹の長さ一メートルとは合わない。"}, {"text": "密度", "is_correct": false, "explanation": "密度は単位体積あたりの質量を表す語で、長さの一メートルとは合わない。"}, {"text": "強さ", "is_correct": false, "explanation": "強さは力の大きさを表す語で、長さの説明とは合わない。"}], "explanations": {"直径": "幹の太さを円の中心を通る線の長さで表す語で、「一メートルもある」と合う。", "年齢": "年齢は生まれてからの年数を表す語で、幹の長さ一メートルとは合わない。", "密度": "密度は単位体積あたりの質量を表す語で、長さの一メートルとは合わない。", "強さ": "強さは力の大きさを表す語で、長さの説明とは合わない。"}, "sentence_index": 6, "correct_answer": "直径"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この本棚は、奥行きより直径が二センチ長い。", "explanation": "ここは〈幅〉の意味。本棚の横の長さは幅で、直径は円や球の中心を通る線の長さなので合わない。"}, {"text": "このタワーは、地面から頂上までの直径が百メートルある。", "explanation": "ここは〈高さ〉の意味。地面から頂上までの縦の長さは高さで、直径は円や球の中心を通る線なので合わない。"}, {"text": "この水槽の直径は、縦と横と高さをかけた大きさだ。", "explanation": "ここは〈体積〉の意味。三つの長さをかけた立体の大きさは体積で、直径は線の長さなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38802, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいフライパンの直径に二十八センチあって、料理がしやすい。", "corrected_sentence": "新しいフライパンの直径が二十八センチあって、料理がしやすい。", "error_description": "「直径」は「ある」の主語になるので「が」が正しい。「に」は場所や対象を示す助詞で、「二十八センチある」の主語にはならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38802, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "丸いお盆の直径を歩数で数えたら、約二十歩だった。", "corrected_sentence": "丸いお盆の直径を歩数で測ったら、約二十歩だった。", "error_description": "直径は長さなので「測る」が正しい。「数える」は個数を数えるときの動詞で、長さである直径には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38803, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38803, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「直径」を主語にして「大きい」を述語とする格助詞で、「直径が大きい」となる。"}, {"text": "を", "is_correct": false, "explanation": "「大きい」は目的語を取らないので、「直径を大きい」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "位置や帰着を示すが、「直径に大きい」では述語が続かない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「直径から大きい」では文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「直径」を主語にして「大きい」を述語とする格助詞で、「直径が大きい」となる。", "を": "「大きい」は目的語を取らないので、「直径を大きい」は不自然。", "に": "位置や帰着を示すが、「直径に大きい」では述語が続かない。", "から": "起点を示すが、「直径から大きい」では文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "位置・結果", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38803, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "円や球の中心を通り、両端が周囲に接する直線の長さ。", "primary_collocate": null, "pronunciation": "ちょっけい", "ipa": "tɕokkeː", "syllable_count": 4, "sentences": [{"text": "地球の直径は、約一万二千七百キロメートルだ。", "target_word": "直径", "complexity_tier": "T4", "furigana": "地球[ちきゅう]の直径[ちょっけい]は、約[やく]一万二千七百[いちまんにせんななひゃく]キロメートルだ。", "sentence_source": "generated"}, {"text": "球の直径は、中心を通る線で測る。", "target_word": "直径", "complexity_tier": "T3", "furigana": "球[きゅう]の直径[ちょっけい]は、中心[ちゅうしん]を通[とお]る線[せん]で測[はか]る。", "sentence_source": "generated"}, {"text": "直径が十センチもあるパイプは、この小さな穴には通らない。", "target_word": "直径", "complexity_tier": "T3", "furigana": "直径[ちょっけい]が十[じゅっ]センチもあるパイプは、この小[ちい]さな穴[あな]には通[とお]らない。", "sentence_source": "generated"}, {"text": "月の直径は、地球の約四分の一だ。", "target_word": "直径", "complexity_tier": "T3", "furigana": "月[つき]の直径[ちょっけい]は、地球[ちきゅう]の約[やく]四分[よんぶん]の一[いち]だ。", "sentence_source": "generated"}, {"text": "円の中心を通り、両端が円周に接する線の長さが、直径だ。", "target_word": "直径", "complexity_tier": "T4", "furigana": "円[えん]の中心[ちゅうしん]を通[とお]り、両端[りょうたん]が円周[えんしゅう]に接[せっ]する線[せん]の長[なが]さが、直径[ちょっけい]だ。", "sentence_source": "generated"}, {"text": "直径二メートルの丸い鏡が、天井からつるされている。", "target_word": "直径", "complexity_tier": "T3", "furigana": "直径[ちょっけい]二[に]メートルの丸[まる]い鏡[かがみ]が、天井[てんじょう]からつるされている。", "sentence_source": "generated"}, {"text": "顕微鏡で見ると、この細胞の直径は百分の一ミリほどだった。", "target_word": "直径", "complexity_tier": "T4", "furigana": "顕微鏡[けんびきょう]で見[み]ると、この細胞[さいぼう]の直径[ちょっけい]は百分[ひゃくぶん]の一[いち]ミリほどだった。", "sentence_source": "generated"}, {"text": "木星は、太陽系で最も直径が大きい惑星だ。", "target_word": "直径", "complexity_tier": "T4", "furigana": "木星[もくせい]は、太陽系[たいようけい]で最[もっと]も直径[ちょっけい]が大[おお]きい惑星[わくせい]だ。", "sentence_source": "generated"}, {"text": "タイヤは直径が大きいほど、一回転で進む距離が長くなる。", "target_word": "直径", "complexity_tier": "T4", "furigana": "タイヤは直径[ちょっけい]が大[おお]きいほど、一回転[いっかいてん]で進[すす]む距離[きょり]が長[なが]くなる。", "sentence_source": "generated"}, {"text": "二つの球の直径を測って、大きいほうを選んだ。", "target_word": "直径", "complexity_tier": "T3", "furigana": "二[ふた]つの球[たま]の直径[ちょっけい]を測[はか]って、大[おお]きいほうを選[えら]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直径", "label": "基本形"}], "register": "中立", "sense_fingerprint": "円や球の中心を通り両端が周囲に接する直線の長さ(幾何・天体・物の大きさ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20a93d0-c34a-4826-8ae3-e5c131706219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38803, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直径", "is_correct": true, "explanation": "地球の大きさを両端の長さで表す語で、キロメートルの数値と合う。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは質量を表す語で、キロメートルという長さとは合わない。"}, {"text": "密度", "is_correct": false, "explanation": "密度は単位体積あたりの質量を表す語で、長さの数値とは合わない。"}, {"text": "温度", "is_correct": false, "explanation": "温度は熱の度合いを表す語で、キロメートルの長さとは合わない。"}], "explanations": {"直径": "地球の大きさを両端の長さで表す語で、キロメートルの数値と合う。", "重さ": "重さは質量を表す語で、キロメートルという長さとは合わない。", "密度": "密度は単位体積あたりの質量を表す語で、長さの数値とは合わない。", "温度": "温度は熱の度合いを表す語で、キロメートルの長さとは合わない。"}, "sentence_index": 0, "correct_answer": "直径"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "球の直径は、中心から表面までの長さだ。", "explanation": "ここは〈半径〉の意味。直径は中心を通り両端が表面に接する線全体の長さで、中心から表面までは半径なので合わない。"}, {"text": "球の直径は、球の外側を覆う面の広さだ。", "explanation": "ここは〈表面積〉の意味。直径は長さで、外側の広さは表面積を指すので合わない。"}, {"text": "球の直径は、球の中に入る空間の大きさだ。", "explanation": "ここは〈体積〉の意味。中に入る空間の大きさは体積で、直径は線の長さなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38803, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直径", "is_correct": true, "explanation": "細胞の大きさを円や球の中心を通る線の長さで表し、百分の一ミリと合う。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は生まれてからの年数を表す語で、細胞の長さには使わない。"}, {"text": "硬さ", "is_correct": false, "explanation": "硬さは押したときの強さを表す語で、ミリの長さとは合わない。"}, {"text": "明るさ", "is_correct": false, "explanation": "明るさは光の強さを表す語で、ミリの長さとは合わない。"}], "explanations": {"直径": "細胞の大きさを円や球の中心を通る線の長さで表し、百分の一ミリと合う。", "年齢": "年齢は生まれてからの年数を表す語で、細胞の長さには使わない。", "硬さ": "硬さは押したときの強さを表す語で、ミリの長さとは合わない。", "明るさ": "明るさは光の強さを表す語で、ミリの長さとは合わない。"}, "sentence_index": 6, "correct_answer": "直径"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この通路の直径は、人がすれ違えるほど広い。", "explanation": "ここは〈幅〉の意味。通路の横の広さは幅で、直径は円や球の中心を通る線の長さなので合わない。"}, {"text": "このビルの直径は、地面から屋上までの長さだ。", "explanation": "ここは〈高さ〉の意味。地面から屋上までの縦の長さは高さで、直径は円や球の中心を通る線なので合わない。"}, {"text": "この板の直径は、表と裏の間の長さだ。", "explanation": "ここは〈厚さ〉の意味。表と裏の間の長さは厚さで、直径は円や球の中心を通る線の長さなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38803, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この小惑星の直径を、約三百キロメートルだ。", "corrected_sentence": "この小惑星の直径は、約三百キロメートルだ。", "error_description": "「〜は〜だ」の文の主題は「直径は」で示す。「直径を」は動作の目的語を示すので、この文の形には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38803, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二つの鉄球の直径を測るて、重いほうを選んだ。", "corrected_sentence": "二つの鉄球の直径を測って、重いほうを選んだ。", "error_description": "「測る」のて形は「測って」。「測るて」は活用の誤りで、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38806, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「掘る」の目的語を示す格助詞で、「穴を掘って」となる。"}, {"text": "に", "is_correct": false, "explanation": "場所を示すが、「穴に掘って」では目的語として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「穴へ掘って」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「穴より掘って」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「掘る」の目的語を示す格助詞で、「穴を掘って」となる。", "に": "場所を示すが、「穴に掘って」では目的語として成り立たない。", "へ": "方向を示すが、「穴へ掘って」は不自然。", "より": "比較を示すが、「穴より掘って」では文が成り立たない。"}, "error_tags": {"に": "場所（目的語にならない）", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38806, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「穴に」で場所を示し、水がたまる場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "「たまる」は目的語を取らないので、「穴を水がたまる」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、主語が二つになり「穴が水がたまる」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、「穴と水がたまる」では述語が続かない。"}], "correct_answer": "に", "explanations": {"に": "「穴に」で場所を示し、水がたまる場所を表す。", "を": "「たまる」は目的語を取らないので、「穴を水がたまる」は成り立たない。", "が": "主語を示すが、主語が二つになり「穴が水がたまる」は不自然。", "と": "並列を示すが、「穴と水がたまる」では述語が続かない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38806, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の表面にあいた、小さなくぼみや、向こうまで通じる口のこと。", "primary_collocate": null, "pronunciation": "あな", "ipa": "ana", "syllable_count": 2, "sentences": [{"text": "靴下に穴があいて、親指が出てしまった。", "target_word": "穴", "complexity_tier": "T2", "furigana": "靴下[くつした]に穴[あな]があいて、親指[おやゆび]が出[で]てしまった。", "sentence_source": "generated"}, {"text": "地面に穴を掘って、木の苗を植えた。", "target_word": "穴", "complexity_tier": "T3", "furigana": "地面[じめん]に穴[あな]を掘[ほ]って、木[き]の苗[なえ]を植[う]えた。", "sentence_source": "generated"}, {"text": "犬が庭に大きな穴を掘ったので、母は怒った。", "target_word": "穴", "complexity_tier": "T3", "furigana": "犬[いぬ]が庭[にわ]に大[おお]きな穴[あな]を掘[ほ]ったので、母[はは]は怒[おこ]った。", "sentence_source": "generated"}, {"text": "壁の穴をふさぐために、パテを買ってきた。", "target_word": "穴", "complexity_tier": "T3", "furigana": "壁[かべ]の穴[あな]をふさぐために、パテを買[か]ってきた。", "sentence_source": "generated"}, {"text": "古いかばんの底に穴があって、中の物が落ちてしまった。", "target_word": "穴", "complexity_tier": "T3", "furigana": "古[ふる]いかばんの底[そこ]に穴[あな]があって、中[なか]の物[もの]が落[お]ちてしまった。", "sentence_source": "generated"}, {"text": "紙に小さな穴を二つあけて、ひもを通した。", "target_word": "穴", "complexity_tier": "T3", "furigana": "紙[かみ]に小[ちい]さな穴[あな]を二[ふた]つあけて、ひもを通[とお]した。", "sentence_source": "generated"}, {"text": "ドーナツの真ん中には、丸い穴がある。", "target_word": "穴", "complexity_tier": "T2", "furigana": "ドーナツの真[ま]ん中[なか]には、丸[まる]い穴[あな]がある。", "sentence_source": "generated"}, {"text": "雨が降ると、道路の穴に水がたまる。", "target_word": "穴", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ると、道路[どうろ]の穴[あな]に水[みず]がたまる。", "sentence_source": "generated"}, {"text": "氷に穴をあけて、そこから魚を釣る。", "target_word": "穴", "complexity_tier": "T3", "furigana": "氷[こおり]に穴[あな]をあけて、そこから魚[さかな]を釣[つ]る。", "sentence_source": "generated"}, {"text": "セーターに虫食いの穴を見つけて、がっかりした。", "target_word": "穴", "complexity_tier": "T4", "furigana": "セーターに虫食[むしく]いの穴[あな]を見[み]つけて、がっかりした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "穴", "label": "基本形"}], "register": "中立", "sense_fingerprint": "物の表面のくぼみや、向こうへ通じる口(日常の穴)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20a93d0-c34a-4826-8ae3-e5c131706219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38806, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穴", "is_correct": true, "explanation": "靴下にあいた、向こうまで通じる口を指し、「あいて」と親指が出る文脈と合う。"}, {"text": "色", "is_correct": false, "explanation": "色は表面の見た目を表す語で、「あいて」とは続かない。"}, {"text": "模様", "is_correct": false, "explanation": "模様は表面の柄を表す語で、「あいて」とは続かない。"}, {"text": "糸", "is_correct": false, "explanation": "糸は材料の一つで、靴下に「あいて」とは続かない。"}], "explanations": {"穴": "靴下にあいた、向こうまで通じる口を指し、「あいて」と親指が出る文脈と合う。", "色": "色は表面の見た目を表す語で、「あいて」とは続かない。", "模様": "模様は表面の柄を表す語で、「あいて」とは続かない。", "糸": "糸は材料の一つで、靴下に「あいて」とは続かない。"}, "sentence_index": 0, "correct_answer": "穴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震で、ダムの壁に細かい穴が入った。", "explanation": "ここは〈亀裂〉の意味。壁に走った細い割れ目は亀裂で、くぼみや貫通した口を指す穴とは違い、「入る」とも合わないので使えない。"}, {"text": "予定に穴があいたので、旅行を入れた。", "explanation": "ここは〈空き〉の意味。予定の空白は空きで、物にあいた穴とは違うので合わない。"}, {"text": "会議で、計画の穴を指摘されて、直した。", "explanation": "ここは〈欠陥〉の意味。計画の不備は欠陥で、物にあいた穴とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38806, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穴", "is_correct": true, "explanation": "ドーナツの真ん中にある、向こうまで通じる丸い口を指し、「丸い穴がある」と合う。"}, {"text": "油", "is_correct": false, "explanation": "油は液体の食材で、「丸い」ものがあるという文脈に合わない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは匂いを表す語で、「丸い」ものとしては続かない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは質量を表す語で、「丸い」物の位置を示す文とは合わない。"}], "explanations": {"穴": "ドーナツの真ん中にある、向こうまで通じる丸い口を指し、「丸い穴がある」と合う。", "油": "油は液体の食材で、「丸い」ものがあるという文脈に合わない。", "香り": "香りは匂いを表す語で、「丸い」ものとしては続かない。", "重さ": "重さは質量を表す語で、「丸い」物の位置を示す文とは合わない。"}, "sentence_index": 6, "correct_answer": "穴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "申込書の穴に、名前を書いた。", "explanation": "ここは〈空欄〉の意味。書き込むために空けてある部分は空欄で、物にあいたくぼみや貫通部分の穴とは違い、名前を書く場所としては合わない。"}, {"text": "車の穴を磨いて消した。", "explanation": "ここは〈傷〉の意味。表面のすり跡は磨いて消せるが、穴は磨いても消えないので合わない。"}, {"text": "押し入れの穴を有効に使う。", "explanation": "ここは〈空間〉の意味。押し入れの中の広さは空間で、くぼみや貫通部分の穴とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38806, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ズボンの穴が見つけて、すぐに縫った。", "corrected_sentence": "ズボンの穴を見つけて、すぐに縫った。", "error_description": "「見つける」の目的語は「を」で示す。「が」は誤りで、「穴を見つける」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38806, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭に穴を編んで、古い手紙を埋めた。", "corrected_sentence": "庭に穴を掘って、古い手紙を埋めた。", "error_description": "穴は「掘る」もので、「編む」は糸などを扱う動詞。動詞の選択が誤りで、「穴を掘って」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38807, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「穴に」で通す先を示し、「針の穴に糸を通す」となる。"}, {"text": "を", "is_correct": false, "explanation": "「通す」の目的語はすでに「糸を」なので、「穴を糸を」は二重になり不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「穴が糸を通す」は文の主語として不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、「穴と糸を通す」では文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「穴に」で通す先を示し、「針の穴に糸を通す」となる。", "を": "「通す」の目的語はすでに「糸を」なので、「穴を糸を」は二重になり不自然。", "が": "主語を示すが、「穴が糸を通す」は文の主語として不自然。", "と": "並列を示すが、「穴と糸を通す」では文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38807, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「あける」の目的語を示す格助詞で、「耳に穴をあける」となる。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「耳に穴であける」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「耳に穴へあける」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「穴よりあける」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「あける」の目的語を示す格助詞で、「耳に穴をあける」となる。", "で": "手段や場所を示すが、「耳に穴であける」では意味が通らない。", "へ": "方向を示すが、「耳に穴へあける」は不自然。", "より": "比較を示すが、「穴よりあける」では文が成り立たない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38807, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物体の表面や内部にできる、くぼんだ部分や貫通した部分。", "primary_collocate": null, "pronunciation": "あな", "ipa": "ana", "syllable_count": 2, "sentences": [{"text": "木の幹に穴があって、リスが巣にしているようだ。", "target_word": "穴", "complexity_tier": "T3", "furigana": "木[き]の幹[みき]に穴[あな]があって、リスが巣[す]にしているようだ。", "sentence_source": "generated"}, {"text": "針の穴に糸を通すのは、目が悪いと難しい。", "target_word": "穴", "complexity_tier": "T3", "furigana": "針[はり]の穴[あな]に糸[いと]を通[とお]すのは、目[め]が悪[わる]いと難[むずか]しい。", "sentence_source": "generated"}, {"text": "チーズの中には、たくさんの小さな穴がある。", "target_word": "穴", "complexity_tier": "T2", "furigana": "チーズの中[なか]には、たくさんの小[ちい]さな穴[あな]がある。", "sentence_source": "generated"}, {"text": "岩の穴の奥から、冷たい風が吹いてくる。", "target_word": "穴", "complexity_tier": "T3", "furigana": "岩[いわ]の穴[あな]の奥[おく]から、冷[つめ]たい風[かぜ]が吹[ふ]いてくる。", "sentence_source": "generated"}, {"text": "タイヤに小さな穴があいていて、空気が少しずつ抜ける。", "target_word": "穴", "complexity_tier": "T3", "furigana": "タイヤに小[ちい]さな穴[あな]があいていて、空気[くうき]が少[すこ]しずつ抜[ぬ]ける。", "sentence_source": "generated"}, {"text": "工事の人が、道路に深い穴を掘っている。", "target_word": "穴", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が、道路[どうろ]に深[ふか]い穴[あな]を掘[ほ]っている。", "sentence_source": "generated"}, {"text": "ボールに穴があいたので、もう弾まない。", "target_word": "穴", "complexity_tier": "T2", "furigana": "ボールに穴[あな]があいたので、もう弾[はず]まない。", "sentence_source": "generated"}, {"text": "耳に穴をあけて、ピアスをつける人もいる。", "target_word": "穴", "complexity_tier": "T3", "furigana": "耳[みみ]に穴[あな]をあけて、ピアスをつける人[ひと]もいる。", "sentence_source": "generated"}, {"text": "床の穴から、ネズミが出入りしているらしい。", "target_word": "穴", "complexity_tier": "T4", "furigana": "床[ゆか]の穴[あな]から、ネズミが出入[でい]りしているらしい。", "sentence_source": "generated"}, {"text": "ベルトの穴が足りなくて、これ以上きつく締められない。", "target_word": "穴", "complexity_tier": "T4", "furigana": "ベルトの穴[あな]が足[た]りなくて、これ以上[いじょう]きつく締[し]められない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "穴", "label": "基本形"}], "register": "中立", "sense_fingerprint": "物体の表面や内部のくぼみ、または貫通した部分(物の状態としての穴)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20a93d0-c34a-4826-8ae3-e5c131706219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38807, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穴", "is_correct": true, "explanation": "木の幹にある、リスが巣にできるほどの空洞を指し、文の内容と合う。"}, {"text": "苔", "is_correct": false, "explanation": "苔は表面に生える植物で、リスの巣と結びつかない。"}, {"text": "樹皮", "is_correct": false, "explanation": "樹皮は幹の外側の皮で、巣にできる空洞とは合わない。"}, {"text": "年輪", "is_correct": false, "explanation": "年輪は幹の断面にある輪の模様で、巣とは結びつかない。"}], "explanations": {"穴": "木の幹にある、リスが巣にできるほどの空洞を指し、文の内容と合う。", "苔": "苔は表面に生える植物で、リスの巣と結びつかない。", "樹皮": "樹皮は幹の外側の皮で、巣にできる空洞とは合わない。", "年輪": "年輪は幹の断面にある輪の模様で、巣とは結びつかない。"}, "sentence_index": 0, "correct_answer": "穴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震で、岩盤に細かい穴が入った。", "explanation": "ここは〈亀裂〉の意味。岩に走った細い割れ目は亀裂で、くぼみや貫通部分の穴とは違い、「入る」とも合わないので使えない。"}, {"text": "ガラスの穴は、磨けば消える。", "explanation": "ここは〈傷〉の意味。表面のすり跡は磨けば消えるが、くぼみや貫通部分の穴は磨いても消えないので合わない。"}, {"text": "壁の穴が、ゆっくり動く。", "explanation": "ここは〈影〉の意味。光がさえぎられてできる暗い部分は影で、物にあいた穴が動くことはないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38807, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穴", "is_correct": true, "explanation": "ボールにあいた口で、弾まなくなる原因として文脈と合う。"}, {"text": "色", "is_correct": false, "explanation": "色は表面の見た目で、弾まないことの理由にはならない。"}, {"text": "油", "is_correct": false, "explanation": "油は液体で、ボールに「あいた」とは続かない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは質量を表す語で、ボールに「あいた」とは続かない。"}], "explanations": {"穴": "ボールにあいた口で、弾まなくなる原因として文脈と合う。", "色": "色は表面の見た目で、弾まないことの理由にはならない。", "油": "油は液体で、ボールに「あいた」とは続かない。", "重さ": "重さは質量を表す語で、ボールに「あいた」とは続かない。"}, "sentence_index": 6, "correct_answer": "穴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "紙の穴に、先生がコメントを書いてくれた。", "explanation": "ここは〈余白〉の意味。文字や絵のない部分は余白で、物にあいたくぼみや貫通部分の穴とは違い、コメントを書く場所としては合わない。"}, {"text": "時計の穴を数えると、十二個あった。", "explanation": "ここは〈目盛り〉の意味。文字盤に刻まれた線は目盛りで、くぼみや貫通部分の穴とは違うので合わない。"}, {"text": "山道は穴が激しく、車がよく揺れた。", "explanation": "ここは〈凹凸〉の意味。表面がでこぼこしている状態は凹凸で、一か所のくぼみを指す穴とは違い、「激しい」と様子を表す使い方にも合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38807, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古いタンスの底に穴をあって、ネズミが入ったようだ。", "corrected_sentence": "古いタンスの底に穴があって、ネズミが入ったようだ。", "error_description": "「ある」は存在を表す動詞で、主語には「が」を使う。「穴を」は他動詞の目的語を示すので、この文には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38807, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "革のベルトに穴をあげて、新しい長さに合わせた。", "corrected_sentence": "革のベルトに穴をあけて、新しい長さに合わせた。", "error_description": "穴を作る動詞は「あける」。「あげる」は別の動詞で、穴には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38808, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「穴を空ける」の目的語を示す。他動詞〈空ける〉は作る穴を「を」で受ける。"}, {"text": "に", "is_correct": false, "explanation": "場所の「に」。「紙に」が既に場所を示しているので、穴に続けると不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は移動の先を示す。穴を作る動作の対象には使わない。"}, {"text": "と", "is_correct": false, "explanation": "相手・並列の「と」。穴を作る動作の対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「穴を空ける」の目的語を示す。他動詞〈空ける〉は作る穴を「を」で受ける。", "に": "場所の「に」。「紙に」が既に場所を示しているので、穴に続けると不自然。", "へ": "方向の「へ」は移動の先を示す。穴を作る動作の対象には使わない。", "と": "相手・並列の「と」。穴を作る動作の対象には合わない。"}, "error_tags": {"に": "場所", "へ": "方向", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38808, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「穴を空ける」の目的語を示す。他動詞〈空ける〉は作る穴を「を」で受ける。"}, {"text": "が", "is_correct": false, "explanation": "「穴が空ける」は誤り。「が」の〈空く〉は自動詞の主語形で、他動詞の〈空ける〉には使えない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」。穴を作る対象を示す位置には使えない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点の「より」。穴を作る動作の対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「穴を空ける」の目的語を示す。他動詞〈空ける〉は作る穴を「を」で受ける。", "が": "「穴が空ける」は誤り。「が」の〈空く〉は自動詞の主語形で、他動詞の〈空ける〉には使えない。", "で": "手段・場所の「で」。穴を作る対象を示す位置には使えない。", "より": "比較・起点の「より」。穴を作る動作の対象には合わない。"}, "error_tags": {"が": "主語", "で": "手段", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38808, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あなをあける。", "primary_collocate": null, "pronunciation": "あける", "ipa": "akeɾɯ", "syllable_count": 3, "sentences": [{"text": "壁にドリルで穴を空ける。", "target_word": "空ける", "complexity_tier": "T2", "furigana": "壁[かべ]にドリルで穴[あな]を空[あ]ける。", "sentence_source": "generated"}, {"text": "紙に二つ穴を空けて、ファイルにとじた。", "target_word": "空けて", "complexity_tier": "T3", "furigana": "紙[かみ]に二[ふた]つ穴[あな]を空[あ]けて、ファイルにとじた。", "sentence_source": "generated"}, {"text": "父は板に釘で小さな穴を空けた。", "target_word": "空けた", "complexity_tier": "T3", "furigana": "父[ちち]は板[いた]に釘[くぎ]で小[ちい]さな穴[あな]を空[あ]けた。", "sentence_source": "generated"}, {"text": "ベルトに新しい穴を空けると、ちょうどよくなった。", "target_word": "空けると", "complexity_tier": "T3", "furigana": "ベルトに新[あたら]しい穴[あな]を空[あ]けると、ちょうどよくなった。", "sentence_source": "generated"}, {"text": "氷に穴を空けて、ワカサギ釣りを始めた。", "target_word": "空けて", "complexity_tier": "T3", "furigana": "氷[こおり]に穴[あな]を空[あ]けて、ワカサギ釣[づ]りを始[はじ]めた。", "sentence_source": "generated"}, {"text": "ピアスをつけるために、耳に穴を空けた。", "target_word": "空けた", "complexity_tier": "T3", "furigana": "ピアスをつけるために、耳[みみ]に穴[あな]を空[あ]けた。", "sentence_source": "generated"}, {"text": "缶のふたに穴を空けて、貯金箱を作った。", "target_word": "空けて", "complexity_tier": "T3", "furigana": "缶[かん]のふたに穴[あな]を空[あ]けて、貯金箱[ちょきんばこ]を作[つく]った。", "sentence_source": "generated"}, {"text": "木に穴を空けるときは、先に印をつけておくと失敗しない。", "target_word": "空ける", "complexity_tier": "T4", "furigana": "木[き]に穴[あな]を空[あ]けるときは、先[さき]に印[しるし]をつけておくと失敗[しっぱい]しない。", "sentence_source": "generated"}, {"text": "靴に穴を空けないように、とがった石をよけて歩いた。", "target_word": "空けない", "complexity_tier": "T4", "furigana": "靴[くつ]に穴[あな]を空[あ]けないように、とがった石[いし]をよけて歩[ある]いた。", "sentence_source": "generated"}, {"text": "工事の人が、床に配管用の穴を空けている。", "target_word": "空けている", "complexity_tier": "T4", "furigana": "工事[こうじ]の人[ひと]が、床[ゆか]に配管用[はいかんよう]の穴[あな]を空[あ]けている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "空ける", "label": "辞書形"}, {"form": "空けます", "label": "丁寧形"}, {"form": "空けて", "label": "て形"}, {"form": "空けた", "label": "た形"}, {"form": "空けない", "label": "否定形"}, {"form": "空ければ", "label": "仮定形"}, {"form": "空けられる", "label": "受身・可能形"}], "register": "中立", "sense_fingerprint": "道具などで物にあなを作る(穴を空ける)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20a93d0-c34a-4826-8ae3-e5c131706219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38808, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空ける", "is_correct": true, "explanation": "「穴を空ける」の基本形。ドリルで穴を作る動作を表し、文末に合う。"}, {"text": "飲む", "is_correct": false, "explanation": "「穴を飲む」は成り立たない。穴は飲むものではない。"}, {"text": "開く", "is_correct": false, "explanation": "自動詞で目的語に「を」を取れないため、「穴を開く」は文として成り立たない。"}, {"text": "締める", "is_correct": false, "explanation": "穴は締めるものではない。締めるはねじや帯など、ものを固く絞る動作に使う。"}], "explanations": {"空ける": "「穴を空ける」の基本形。ドリルで穴を作る動作を表し、文末に合う。", "飲む": "「穴を飲む」は成り立たない。穴は飲むものではない。", "開く": "自動詞で目的語に「を」を取れないため、「穴を開く」は文として成り立たない。", "締める": "穴は締めるものではない。締めるはねじや帯など、ものを固く絞る動作に使う。"}, "sentence_index": 0, "correct_answer": "空ける"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアを空けて、部屋に入った。", "explanation": "ここは〈開ける〉の意味。ドアは開けるもので、穴を作る〈空ける〉とは言わないので、この文には合わない。"}, {"text": "水道管を通すため、地面を空けた。", "explanation": "ここは〈掘る〉の意味。地面は掘るもので、〈空ける〉は穴や空間を作る語として地面を対象にしない。"}, {"text": "ボタンを空けて、シャツを脱いだ。", "explanation": "ここは〈外す〉の意味。ボタンは外すもので、穴を作る〈空ける〉とは言わないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38808, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空けて", "is_correct": true, "explanation": "「缶のふたに穴を空けて」の形。て形で後ろの〈貯金箱を作った〉につながる。"}, {"text": "眺めて", "is_correct": false, "explanation": "「穴を眺める」は成り立たない。眺めるは景色などを見る動作で、穴には使えない。"}, {"text": "乗せて", "is_correct": false, "explanation": "「穴に乗せる」は意味が通らない。乗せるは物を載せる動作の語。"}, {"text": "叫んで", "is_correct": false, "explanation": "「穴を叫ぶ」は成り立たない。叫ぶは声を出す動作で、穴には使えない。"}], "explanations": {"空けて": "「缶のふたに穴を空けて」の形。て形で後ろの〈貯金箱を作った〉につながる。", "眺めて": "「穴を眺める」は成り立たない。眺めるは景色などを見る動作で、穴には使えない。", "乗せて": "「穴に乗せる」は意味が通らない。乗せるは物を載せる動作の語。", "叫んで": "「穴を叫ぶ」は成り立たない。叫ぶは声を出す動作で、穴には使えない。"}, "sentence_index": 6, "correct_answer": "空けて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "職人が木の床に名前を空けている。", "explanation": "ここは〈彫る〉の意味。名前は彫るもので、〈空ける〉（穴や空間を作る）とは言わない。"}, {"text": "ナイフで床に傷を空けた。", "explanation": "ここは〈つける〉の意味。傷はつけるもので、穴を作る〈空ける〉とは言わないので、この文には合わない。"}, {"text": "絡まった糸を空けて、針に通した。", "explanation": "ここは〈ほどく〉の意味。絡まった糸は解くもので、〈空ける〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38808, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドリルで壁に穴が空けた。", "corrected_sentence": "ドリルで壁に穴を空けた。", "error_description": "「穴が」は誤り。〈空ける〉は他動詞なので、作る穴は「穴を」で受ける。正しくは「穴を空けた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "空けて", "is_correct": true, "explanation": "て形。後ろの〈ファイルにとじた〉と文をつなぐ形として正しい。"}, {"text": "空けた", "is_correct": false, "explanation": "た形で文が終わってしまい、後ろの〈とじた〉に続けられない。"}, {"text": "空けよう", "is_correct": false, "explanation": "意志形。後ろの〈ファイルにとじた〉に続かず、文として成り立たない。"}, {"text": "空けろ", "is_correct": false, "explanation": "命令形。〈空けろ、ファイルにとじた〉のように文が続かず、文脈に合わない。"}], "correct_form": "空けて", "base_form": "空ける", "form_label": "て形", "sentence_index": 1, "explanations": {"空けて": "て形。後ろの〈ファイルにとじた〉と文をつなぐ形として正しい。", "空けた": "た形で文が終わってしまい、後ろの〈とじた〉に続けられない。", "空けよう": "意志形。後ろの〈ファイルにとじた〉に続かず、文として成り立たない。", "空けろ": "命令形。〈空けろ、ファイルにとじた〉のように文が続かず、文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38808, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "缶に三つ穴を空いて、ランプを作った。", "corrected_sentence": "缶に三つ穴を空けて、ランプを作った。", "error_description": "「空いて」は自動詞で、穴を作る動作は表せない。他動詞の「空けて」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "空ける", "is_correct": true, "explanation": "辞書形。後ろの〈とき〉に続けて、一般的な場面を述べる形。"}, {"text": "空けます", "is_correct": false, "explanation": "丁寧形。〈空けるとき〉という普通体の文の流れに合わない。"}, {"text": "空けなさい", "is_correct": false, "explanation": "命令形の丁寧な言い方。〈〜ときは〉の前には置けず、文として成り立たない。"}, {"text": "空けたら", "is_correct": false, "explanation": "仮定形。〈〜ときは〉と条件を重ねることになり、文として成り立たない。"}], "correct_form": "空ける", "base_form": "空ける", "form_label": "辞書形", "sentence_index": 7, "explanations": {"空ける": "辞書形。後ろの〈とき〉に続けて、一般的な場面を述べる形。", "空けます": "丁寧形。〈空けるとき〉という普通体の文の流れに合わない。", "空けなさい": "命令形の丁寧な言い方。〈〜ときは〉の前には置けず、文として成り立たない。", "空けたら": "仮定形。〈〜ときは〉と条件を重ねることになり、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38809, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「穴を空ける」の目的語を示す。〈空ける〉は作る穴を「を」で受ける。"}, {"text": "に", "is_correct": false, "explanation": "場所の「に」。「風船に」が既に場所を示しているので、穴に続けると不自然。"}, {"text": "と", "is_correct": false, "explanation": "相手・並列の「と」。穴を作る動作の対象には合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」。穴を作る対象を示す位置には使えない。"}], "correct_answer": "を", "explanations": {"を": "「穴を空ける」の目的語を示す。〈空ける〉は作る穴を「を」で受ける。", "に": "場所の「に」。「風船に」が既に場所を示しているので、穴に続けると不自然。", "と": "相手・並列の「と」。穴を作る動作の対象には合わない。", "で": "手段の「で」。穴を作る対象を示す位置には使えない。"}, "error_tags": {"に": "場所", "と": "相手・並列", "で": "手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "詰める", "is_correct": true, "explanation": "〈間を詰める〉は間隔をせばめる意味で、〈間を空ける〉の対義にあたる。"}, {"text": "運ぶ", "is_correct": false, "explanation": "〈運ぶ〉は物を移動させる動詞で、間の広さを表す対義語ではない。"}, {"text": "洗う", "is_correct": false, "explanation": "〈洗う〉は汚れを落とす動作で、間の広さとは無関係。"}, {"text": "眠る", "is_correct": false, "explanation": "〈眠る〉は寝る動作で、間の広さを示す語とは関係がない。"}], "correct_answer": "詰める", "explanations": {"詰める": "〈間を詰める〉は間隔をせばめる意味で、〈間を空ける〉の対義にあたる。", "運ぶ": "〈運ぶ〉は物を移動させる動詞で、間の広さを表す対義語ではない。", "洗う": "〈洗う〉は汚れを落とす動作で、間の広さとは無関係。", "眠る": "〈眠る〉は寝る動作で、間の広さを示す語とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38809, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「間を空ける」の目的語を示す。〈空ける〉は間を「を」で受ける。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。間を空ける動作の対象には使えない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点の「より」。間を作る対象を示す位置には合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。間の対象を示す位置には使えない。"}], "correct_answer": "を", "explanations": {"を": "「間を空ける」の目的語を示す。〈空ける〉は間を「を」で受ける。", "へ": "方向の「へ」。間を空ける動作の対象には使えない。", "より": "比較・起点の「より」。間を作る対象を示す位置には合わない。", "から": "起点の「から」。間の対象を示す位置には使えない。"}, "error_tags": {"へ": "方向", "より": "比較・起点", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38809, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物に穴や空間を作る。", "primary_collocate": null, "pronunciation": "あける", "ipa": "akeɾɯ", "syllable_count": 3, "sentences": [{"text": "本棚の板を、五センチずつ間を空けて並べた。", "target_word": "空けて", "complexity_tier": "T3", "furigana": "本棚[ほんだな]の板[いた]を、五[ご]センチずつ間[あいだ]を空[あ]けて並[なら]べた。", "sentence_source": "generated"}, {"text": "風船に針で穴を空けると、大きな音がして割れた。", "target_word": "空けると", "complexity_tier": "T3", "furigana": "風船[ふうせん]に針[はり]で穴[あな]を空[あ]けると、大[おお]きな音[おと]がして割[わ]れた。", "sentence_source": "generated"}, {"text": "壁に絵をかけるために、くぎで小さな穴を空ける。", "target_word": "空ける", "complexity_tier": "T3", "furigana": "壁[かべ]に絵[え]をかけるために、くぎで小[ちい]さな穴[あな]を空[あ]ける。", "sentence_source": "generated"}, {"text": "机と壁の間を少し空けておくと、掃除がしやすい。", "target_word": "空けて", "complexity_tier": "T3", "furigana": "机[つくえ]と壁[かべ]の間[あいだ]を少[すこ]し空[あ]けておくと、掃除[そうじ]がしやすい。", "sentence_source": "generated"}, {"text": "植木鉢の底に水が抜ける穴を空けて、土を入れた。", "target_word": "空けて", "complexity_tier": "T4", "furigana": "植木鉢[うえきばち]の底[そこ]に水[みず]が抜[ぬ]ける穴[あな]を空[あ]けて、土[つち]を入[い]れた。", "sentence_source": "generated"}, {"text": "前の車との間を十分に空けて、ゆっくり走った。", "target_word": "空けて", "complexity_tier": "T3", "furigana": "前[まえ]の車[くるま]との間[あいだ]を十分[じゅうぶん]に空[あ]けて、ゆっくり走[はし]った。", "sentence_source": "generated"}, {"text": "革のバッグに金具をつけるため、先に穴を空けておいた。", "target_word": "空けて", "complexity_tier": "T4", "furigana": "革[かわ]のバッグに金具[かなぐ]をつけるため、先[さき]に穴[あな]を空[あ]けておいた。", "sentence_source": "generated"}, {"text": "苗は三十センチずつ間を空けて植える。", "target_word": "空けて", "complexity_tier": "T3", "furigana": "苗[なえ]は三十[さんじゅっ]センチずつ間[あいだ]を空[あ]けて植[う]える。", "sentence_source": "generated"}, {"text": "子どもがいたずらで、障子に指で穴を空けてしまった。", "target_word": "空けて", "complexity_tier": "T4", "furigana": "子[こ]どもがいたずらで、障子[しょうじ]に指[ゆび]で穴[あな]を空[あ]けてしまった。", "sentence_source": "generated"}, {"text": "板を重ねる前に、真ん中に棒を通す穴を空けた。", "target_word": "空けた", "complexity_tier": "T4", "furigana": "板[いた]を重[かさ]ねる前[まえ]に、真[ま]ん中[なか]に棒[ぼう]を通[とお]す穴[あな]を空[あ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "空ける", "label": "辞書形"}, {"form": "空けます", "label": "丁寧形"}, {"form": "空けて", "label": "て形"}, {"form": "空けた", "label": "た形"}, {"form": "空けない", "label": "否定形"}, {"form": "空ければ", "label": "仮定形"}, {"form": "空けられる", "label": "受身・可能形"}], "register": "中立", "sense_fingerprint": "物に穴やすき間などの空間を作る(穴を空ける、間を空ける)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20a93d0-c34a-4826-8ae3-e5c131706219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38809, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空けて", "is_correct": true, "explanation": "「間を空けて」の形。五センチずつ間を作って並べたという意味になる。"}, {"text": "歌って", "is_correct": false, "explanation": "「間を歌う」は成り立たない。歌うは声を出す動作で、間の文脈には合わない。"}, {"text": "眺めて", "is_correct": false, "explanation": "「間を眺める」は不自然で、板を並べる文脈では意味が通らない。"}, {"text": "叩いて", "is_correct": false, "explanation": "「間を叩く」は成り立たない。叩く動作は間を作る意味にならない。"}], "explanations": {"空けて": "「間を空けて」の形。五センチずつ間を作って並べたという意味になる。", "歌って": "「間を歌う」は成り立たない。歌うは声を出す動作で、間の文脈には合わない。", "眺めて": "「間を眺める」は不自然で、板を並べる文脈では意味が通らない。", "叩いて": "「間を叩く」は成り立たない。叩く動作は間を作る意味にならない。"}, "sentence_index": 0, "correct_answer": "空けて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝る前に、ボタンを空けてシャツを脱いだ。", "explanation": "ここは〈外す〉の意味。ボタンは外すもので、間や穴を作る〈空ける〉とは言わないので、この文には合わない。"}, {"text": "寝る前に髪を空けた。", "explanation": "ここは〈洗う〉の意味。髪は洗うもので、〈空ける〉（間をあける）とは言わない。"}, {"text": "玄関のドアを空けて、部屋に入った。", "explanation": "ここは〈開ける〉の意味。ドアは開けるもので、間や穴を作る〈空ける〉とは言わないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38809, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空けて", "is_correct": true, "explanation": "「先に穴を空けておいた」の形。先に穴を作っておいたという意味になる。"}, {"text": "叫んで", "is_correct": false, "explanation": "「穴を叫ぶ」は成り立たない。叫ぶは声を出す動作で、穴には使えない。"}, {"text": "乗せて", "is_correct": false, "explanation": "「穴を乗せる」は意味が通らない。乗せるは物を載せる動作の語。"}, {"text": "飲んで", "is_correct": false, "explanation": "「穴を飲む」は成り立たない。穴は飲むものではない。"}], "explanations": {"空けて": "「先に穴を空けておいた」の形。先に穴を作っておいたという意味になる。", "叫んで": "「穴を叫ぶ」は成り立たない。叫ぶは声を出す動作で、穴には使えない。", "乗せて": "「穴を乗せる」は意味が通らない。乗せるは物を載せる動作の語。", "飲んで": "「穴を飲む」は成り立たない。穴は飲むものではない。"}, "sentence_index": 6, "correct_answer": "空けて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机の表面に傷を空けた。", "explanation": "ここは〈つける〉の意味。傷はつけるもので、間や穴を作る〈空ける〉とは言わないので、この文には合わない。"}, {"text": "木の看板に店名を空けた。", "explanation": "ここは〈彫る〉の意味。店名は彫るもので、〈空ける〉（穴や間をあける）とは言わない。"}, {"text": "絡まった糸を空けた。", "explanation": "ここは〈ほどく〉の意味。糸は解くもので、〈空ける〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38809, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓と柱の間に五センチ空けて、テープを貼った。", "corrected_sentence": "窓と柱の間を五センチ空けて、テープを貼った。", "error_description": "「間に」は誤り。〈空ける〉の目的語は「間を」で受ける。正しくは「間を五センチ空けて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "空けると", "is_correct": true, "explanation": "と形（条件）。〜すると〜した、という因果の流れを表す。"}, {"text": "空けろ", "is_correct": false, "explanation": "命令形。〈大きな音がして割れた〉と続かず、文として成り立たない。"}, {"text": "空けた", "is_correct": false, "explanation": "た形で文の流れが切れ、〈割れた〉との因果関係が表せない。"}, {"text": "空けない", "is_correct": false, "explanation": "否定形。穴を空けないという反対の意味になる。"}], "correct_form": "空けると", "base_form": "空ける", "form_label": "と形（条件）", "sentence_index": 1, "explanations": {"空けると": "と形（条件）。〜すると〜した、という因果の流れを表す。", "空けろ": "命令形。〈大きな音がして割れた〉と続かず、文として成り立たない。", "空けた": "た形で文の流れが切れ、〈割れた〉との因果関係が表せない。", "空けない": "否定形。穴を空けないという反対の意味になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38809, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "箱の底に水抜きの穴が空けて、植木を植えた。", "corrected_sentence": "箱の底に水抜きの穴を空けて、植木を植えた。", "error_description": "「穴が」は誤り。〈空ける〉は他動詞なので、作る穴は「穴を」で受ける。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "空けて", "is_correct": true, "explanation": "て形。後ろの〈植える〉に続けて、間を空けてから植える流れを作る形。"}, {"text": "空けます", "is_correct": false, "explanation": "丁寧形で文体が合わず、〈植える〉に続く て形の流れにならない。"}, {"text": "空けられる", "is_correct": false, "explanation": "可能形。間を空けることができるという意味になり、単なる動作の連続とは合わない。"}, {"text": "空けている", "is_correct": false, "explanation": "〜ている形。間を空けた状態の継続を表し、〈植える〉との流れが合わない。"}], "correct_form": "空けて", "base_form": "空ける", "form_label": "て形", "sentence_index": 7, "explanations": {"空けて": "て形。後ろの〈植える〉に続けて、間を空けてから植える流れを作る形。", "空けます": "丁寧形で文体が合わず、〈植える〉に続く て形の流れにならない。", "空けられる": "可能形。間を空けることができるという意味になり、単なる動作の連続とは合わない。", "空けている": "〜ている形。間を空けた状態の継続を表し、〈植える〉との流れが合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
