INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38810, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いやなにおいのことです。", "primary_collocate": null, "pronunciation": "あくしゅう", "ipa": "akɯɕɯː", "syllable_count": 4, "sentences": [{"text": "ごみ置き場から悪臭がして、近くを通るのがいやだった。", "target_word": "悪臭", "complexity_tier": "T3", "furigana": "ごみ置[お]き場[ば]から悪臭[あくしゅう]がして、近[ちか]くを通[とお]るのがいやだった。", "sentence_source": "generated"}, {"text": "魚が腐って、台所に悪臭が広がった。", "target_word": "悪臭", "complexity_tier": "T3", "furigana": "魚[さかな]が腐[くさ]って、台所[だいどころ]に悪臭[あくしゅう]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "悪臭がひどいので、窓を開けて空気を入れ替えた。", "target_word": "悪臭", "complexity_tier": "T3", "furigana": "悪臭[あくしゅう]がひどいので、窓[まど]を開[あ]けて空気[くうき]を入[い]れ替[か]えた。", "sentence_source": "generated"}, {"text": "川から悪臭がするという苦情が市役所に届いた。", "target_word": "悪臭", "complexity_tier": "T3", "furigana": "川[かわ]から悪臭[あくしゅう]がするという苦情[くじょう]が市役所[しやくしょ]に届[とど]いた。", "sentence_source": "generated"}, {"text": "古い靴下の悪臭に、思わず顔をしかめた。", "target_word": "悪臭", "complexity_tier": "T3", "furigana": "古[ふる]い靴下[くつした]の悪臭[あくしゅう]に、思[おも]わず顔[かお]をしかめた。", "sentence_source": "generated"}, {"text": "悪臭を消すために、部屋に消臭剤を置いた。", "target_word": "悪臭", "complexity_tier": "T3", "furigana": "悪臭[あくしゅう]を消[け]すために、部屋[へや]に消臭剤[しょうしゅうざい]を置[お]いた。", "sentence_source": "generated"}, {"text": "工場のそばを通ると、鼻をつく悪臭がした。", "target_word": "悪臭", "complexity_tier": "T3", "furigana": "工場[こうじょう]のそばを通[とお]ると、鼻[はな]をつく悪臭[あくしゅう]がした。", "sentence_source": "generated"}, {"text": "冷蔵庫の中の悪臭の原因は、忘れていた肉だった。", "target_word": "悪臭", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の中[なか]の悪臭[あくしゅう]の原因[げんいん]は、忘[わす]れていた肉[にく]だった。", "sentence_source": "generated"}, {"text": "トイレの悪臭が気になって、毎日掃除している。", "target_word": "悪臭", "complexity_tier": "T3", "furigana": "トイレの悪臭[あくしゅう]が気[き]になって、毎日[まいにち]掃除[そうじ]している。", "sentence_source": "generated"}, {"text": "排水溝から悪臭が上がってきたので、業者を呼んだ。", "target_word": "悪臭", "complexity_tier": "T3", "furigana": "排水溝[はいすいこう]から悪臭[あくしゅう]が上[あ]がってきたので、業者[ぎょうしゃ]を呼[よ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "悪臭", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "いやなにおい全般（ごみ・腐敗・排水などのにおい）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20a93d0-c34a-4826-8ae3-e5c131706219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38810, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悪臭", "is_correct": true, "explanation": "いやなにおいを表す名詞。ごみ置き場から漂うにおいとして自然。"}, {"text": "悪夢", "is_correct": false, "explanation": "〈悪夢〉は怖い夢の意味で、ごみ置き場のにおいの文脈には合わない。"}, {"text": "悪口", "is_correct": false, "explanation": "〈悪口〉は人を非難する言葉で、においがするという文には合わない。"}, {"text": "悪役", "is_correct": false, "explanation": "〈悪役〉は物語の役割の意味で、においの文脈には合わない。"}], "explanations": {"悪臭": "いやなにおいを表す名詞。ごみ置き場から漂うにおいとして自然。", "悪夢": "〈悪夢〉は怖い夢の意味で、ごみ置き場のにおいの文脈には合わない。", "悪口": "〈悪口〉は人を非難する言葉で、においがするという文には合わない。", "悪役": "〈悪役〉は物語の役割の意味で、においの文脈には合わない。"}, "sentence_index": 0, "correct_answer": "悪臭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨夜は悪臭を見て、夜中に目が覚めた。", "explanation": "ここは〈悪夢〉の意味。〈悪臭〉は見るものではなく、夢の内容には使わない。"}, {"text": "パンを焼くと、香ばしい悪臭が広がった。", "explanation": "ここは〈匂い〉の意味。〈悪臭〉は不快なにおいなので、香ばしいとは合わない。"}, {"text": "彼は悪臭を言い広めて、友人を困らせた。", "explanation": "ここは〈悪口〉の意味。〈悪臭〉は言い広めるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38810, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悪臭", "is_correct": true, "explanation": "鼻をつくような不快なにおいを表す名詞。工場のそばの文脈に合う。"}, {"text": "悪知恵", "is_correct": false, "explanation": "〈悪知恵〉は人が考える悪い計略の意味で、においの文脈には合わない。"}, {"text": "悪天候", "is_correct": false, "explanation": "〈悪天候〉は天気の意味で、においを表す文脈には合わない。"}, {"text": "悪筆", "is_correct": false, "explanation": "〈悪筆〉は字が下手なことで、においの文脈には合わない。"}], "explanations": {"悪臭": "鼻をつくような不快なにおいを表す名詞。工場のそばの文脈に合う。", "悪知恵": "〈悪知恵〉は人が考える悪い計略の意味で、においの文脈には合わない。", "悪天候": "〈悪天候〉は天気の意味で、においを表す文脈には合わない。", "悪筆": "〈悪筆〉は字が下手なことで、においの文脈には合わない。"}, "sentence_index": 6, "correct_answer": "悪臭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は悪臭をついて、部屋を出ていった。", "explanation": "ここは〈悪態をつく〉の意味。〈悪臭〉は人がつくものではないので、この文には合わない。"}, {"text": "お香を焚くと、上品な悪臭が部屋に広がった。", "explanation": "ここは〈香り〉の意味。上品な香りに対して、〈悪臭〉は不快なにおいなので合わない。"}, {"text": "相手に悪臭を抱くことはなかった。", "explanation": "ここは〈悪意〉の意味。〈悪臭〉は抱くものではないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38810, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を開けると、部屋の悪臭を消えた。", "corrected_sentence": "窓を開けると、部屋の悪臭が消えた。", "error_description": "「悪臭を」は誤り。〈消える〉は自動詞で、主語の「が」を取る。正しくは「悪臭が消えた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38810, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冷蔵庫から鼻をつく悪臭に漂ってきた。", "corrected_sentence": "冷蔵庫から鼻をつく悪臭が漂ってきた。", "error_description": "「悪臭に」は誤り。〈漂う〉は主語の「が」を取るので、悪臭が主語になる「悪臭が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38812, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「色が拡散していく」の「が」で、色が主語として自分で広がる動きを表す。"}, {"text": "を", "is_correct": false, "explanation": "「色を拡散していく」は色が他の物を広げる他動詞の形になり、色自身が広がる文と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「色で拡散していく」は手段の意味になり、色を使って広げるという文になって合わない。"}, {"text": "の", "is_correct": false, "explanation": "「色の拡散していく」は名詞句として続かず、動詞「拡散していく」を支えられない。"}], "correct_answer": "が", "explanations": {"が": "正解。「色が拡散していく」の「が」で、色が主語として自分で広がる動きを表す。", "を": "「色を拡散していく」は色が他の物を広げる他動詞の形になり、色自身が広がる文と合わない。", "で": "「色で拡散していく」は手段の意味になり、色を使って広げるという文になって合わない。", "の": "「色の拡散していく」は名詞句として続かず、動詞「拡散していく」を支えられない。"}, "error_tags": {"を": "目的語", "で": "手段", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38812, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「細かいちりで拡散する」の「で」で、ちりを原因・手段として光が広がることを表す。"}, {"text": "と", "is_correct": false, "explanation": "「ちりと拡散する」は共同の相手を表し、ちりが一緒に広がる意味になって文と合わない。"}, {"text": "を", "is_correct": false, "explanation": "「ちりを拡散する」は、ちりを他のものへ広げる他動詞の形になり、光が広がる文と合わない。"}, {"text": "より", "is_correct": false, "explanation": "「ちりより拡散する」は比較の基準を示すが、ここでは原因を述べる文と合わない。"}], "correct_answer": "で", "explanations": {"で": "正解。「細かいちりで拡散する」の「で」で、ちりを原因・手段として光が広がることを表す。", "と": "「ちりと拡散する」は共同の相手を表し、ちりが一緒に広がる意味になって文と合わない。", "を": "「ちりを拡散する」は、ちりを他のものへ広げる他動詞の形になり、光が広がる文と合わない。", "より": "「ちりより拡散する」は比較の基準を示すが、ここでは原因を述べる文と合わない。"}, "error_tags": {"と": "共同・相手", "を": "目的語", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38812, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものが広く広がること。", "primary_collocate": null, "pronunciation": "かくさん", "ipa": "kakɯsaɴ", "syllable_count": 4, "sentences": [{"text": "煙の拡散を防ぐために、工場は高い煙突を使っている。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "煙[けむり]の拡散[かくさん]を防[ふせ]ぐために、工場[こうじょう]は高[たか]い煙突[えんとつ]を使[つか]っている。", "sentence_source": "generated"}, {"text": "インクを水に落とすと、色が拡散していく様子が見える。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "インクを水[みず]に落[お]とすと、色[いろ]が拡散[かくさん]していく様子[ようす]が見[み]える。", "sentence_source": "generated"}, {"text": "火山の灰が風に乗って拡散した。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "火山[かざん]の灰[はい]が風[かぜ]に乗[の]って拡散[かくさん]した。", "sentence_source": "generated"}, {"text": "ガスの拡散は、風が強い日ほど速い。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "ガスの拡散[かくさん]は、風[かぜ]が強[つよ]い日[ひ]ほど速[はや]い。", "sentence_source": "generated"}, {"text": "花粉の拡散がひどい日は、マスクをして出かける。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "花粉[かふん]の拡散[かくさん]がひどい日[ひ]は、マスクをして出[で]かける。", "sentence_source": "generated"}, {"text": "においの拡散を調べるために、教室の前と後ろで実験した。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "においの拡散[かくさん]を調[しら]べるために、教室[きょうしつ]の前[まえ]と後[うし]ろで実験[じっけん]した。", "sentence_source": "generated"}, {"text": "薬品が拡散しないように、容器のふたをしっかり閉めた。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "薬品[やくひん]が拡散[かくさん]しないように、容器[ようき]のふたをしっかり閉[し]めた。", "sentence_source": "generated"}, {"text": "光は空気中の細かいちりで拡散するので、空が明るく見える。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "光[ひかり]は空気中[くうきちゅう]の細[こま]かいちりで拡散[かくさん]するので、空[そら]が明[あか]るく見[み]える。", "sentence_source": "generated"}, {"text": "油が海に流れ出て、拡散を止めるのが難しかった。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "油[あぶら]が海[うみ]に流[なが]れ出[で]て、拡散[かくさん]を止[と]めるのが難[むずか]しかった。", "sentence_source": "generated"}, {"text": "水の中の汚れが拡散して、池全体が濁ってしまった。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "水[みず]の中[なか]の汚[よご]れが拡散[かくさん]して、池全体[いけぜんたい]が濁[にご]ってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拡散", "label": "基本形"}, {"form": "拡散する", "label": "サ変動詞形"}], "register": "標準（やや書き言葉）", "sense_fingerprint": "煙・ガス・光・インクなど物質や現象が空間に広く散らばること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20a93d0-c34a-4826-8ae3-e5c131706219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38812, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拡散", "is_correct": true, "explanation": "正解。「煙の拡散を防ぐ」は、煙が広がること自体を防ぐという意味に合う。"}, {"text": "注文", "is_correct": false, "explanation": "「煙の注文」は名詞として成り立たず、防ぐ対象にならない。"}, {"text": "遠慮", "is_correct": false, "explanation": "「煙の遠慮」は意味が通らず、防ぐ対象として文に合わない。"}, {"text": "反省", "is_correct": false, "explanation": "「煙の反省」は煙を対象にした意味にならず、防ぐ文に合わない。"}], "explanations": {"拡散": "正解。「煙の拡散を防ぐ」は、煙が広がること自体を防ぐという意味に合う。", "注文": "「煙の注文」は名詞として成り立たず、防ぐ対象にならない。", "遠慮": "「煙の遠慮」は意味が通らず、防ぐ対象として文に合わない。", "反省": "「煙の反省」は煙を対象にした意味にならず、防ぐ文に合わない。"}, "sentence_index": 0, "correct_answer": "拡散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会社は店舗網を拡散して、全国に三十店を増やした。", "explanation": "ここは〈拡大〉の意味。拡散は物質や現象が広がって散らばることなので、店舗網のような規模には使わない。"}, {"text": "三人で仕事の負担を拡散して、一人の残業を減らした。", "explanation": "ここは〈分散〉の意味。拡散は物が広がることで、負担を分けて持つ意味では使わない。"}, {"text": "駐車場を拡散して、車を二十台停められるようにした。", "explanation": "ここは〈拡張〉の意味。設備を広げて増やす工事を指し、物が散らばる拡散とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38812, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拡散", "is_correct": true, "explanation": "正解。「薬品が拡散しないように」は、薬品が広がるのを防ぐ意味に合う。"}, {"text": "相談", "is_correct": false, "explanation": "「薬品が相談しない」は人の行為で、薬品を主語にすると成り立たない。"}, {"text": "挨拶", "is_correct": false, "explanation": "「薬品が挨拶しない」は意味が通らず、防ぐ対象として文に合わない。"}, {"text": "承諾", "is_correct": false, "explanation": "「薬品が承諾しない」は意味が成り立たず、文の空所に合わない。"}], "explanations": {"拡散": "正解。「薬品が拡散しないように」は、薬品が広がるのを防ぐ意味に合う。", "相談": "「薬品が相談しない」は人の行為で、薬品を主語にすると成り立たない。", "挨拶": "「薬品が挨拶しない」は意味が通らず、防ぐ対象として文に合わない。", "承諾": "「薬品が承諾しない」は意味が成り立たず、文の空所に合わない。"}, "sentence_index": 6, "correct_answer": "拡散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この大学は図書館の施設を拡散して、学生が増えても困らないようにした。", "explanation": "ここは〈拡充〉の意味。拡散は物が広がって散ることで、設備を増やして充実させる意味では使わない。"}, {"text": "試験の前日は、勉強だけに拡散して、ほかのことは何もしなかった。", "explanation": "ここは〈集中〉の意味。拡散は広がって散らばることで、一つのことに注意を向け続ける意味では使わない。"}, {"text": "会社は荷物を各店舗に拡散して送った。", "explanation": "ここは〈分配〉の意味。拡散は広がって散ることで、物を振り分けて配る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38812, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "香りが部屋に拡散ないように、窓を閉めた。", "corrected_sentence": "香りが部屋に拡散しないように、窓を閉めた。", "error_description": "「拡散」はサ変動詞なので、否定は「拡散しない」になる。「拡散ない」は「し」が抜けた誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38812, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汚れが池全体に拡散れたので、水が濁った。", "corrected_sentence": "汚れが池全体に拡散したので、水が濁った。", "error_description": "「拡散」はサ変動詞なので、過去形は「拡散した」になる。「拡散れた」は「し」を「れ」に変えた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38813, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「拡散を防ぐ」の「を」で、防ぐ対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「拡散に防ぐ」は防ぐ対象を表せず、目的語には「を」が必要。"}, {"text": "の", "is_correct": false, "explanation": "「拡散の防ぐ」は名詞に動詞が直接続かず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「拡散で防ぐ」は手段の意味になるが、広がりそのものを手段にして防ぐという文は通じない。"}], "correct_answer": "を", "explanations": {"を": "正解。「拡散を防ぐ」の「を」で、防ぐ対象を示す。", "に": "「拡散に防ぐ」は防ぐ対象を表せず、目的語には「を」が必要。", "の": "「拡散の防ぐ」は名詞に動詞が直接続かず、文が成り立たない。", "で": "「拡散で防ぐ」は手段の意味になるが、広がりそのものを手段にして防ぐという文は通じない。"}, "error_tags": {"に": "方向・相手", "の": "連体修飾", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38813, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「拡散を止める」の「を」で、止める対象を示す。"}, {"text": "と", "is_correct": false, "explanation": "「拡散と止める」は相手や共同を表し、止める対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「拡散へ止める」は方向を表すが、止める対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「拡散から止める」は起点の意味になり、止める対象として文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「拡散を止める」の「を」で、止める対象を示す。", "と": "「拡散と止める」は相手や共同を表し、止める対象にならない。", "へ": "「拡散へ止める」は方向を表すが、止める対象を示せない。", "から": "「拡散から止める」は起点の意味になり、止める対象として文が成り立たない。"}, "error_tags": {"と": "共同・相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38813, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事や情報が、周りに広がっていくこと。", "primary_collocate": null, "pronunciation": "かくさん", "ipa": "kakɯsaɴ", "syllable_count": 4, "sentences": [{"text": "そのうわさはSNSで拡散して、町中の人が知るようになった。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "そのうわさはSNSで拡散[かくさん]して、町中[まちじゅう]の人[ひと]が知[し]るようになった。", "sentence_source": "generated"}, {"text": "ウイルスの拡散を防ぐため、学校は一週間休みになった。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "ウイルスの拡散[かくさん]を防[ふせ]ぐため、学校[がっこう]は一週間[いっしゅうかん]休[やす]みになった。", "sentence_source": "generated"}, {"text": "間違った情報の拡散には、十分気をつけてください。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "間違[まちが]った情報[じょうほう]の拡散[かくさん]には、十分[じゅうぶん]気[き]をつけてください。", "sentence_source": "generated"}, {"text": "動画が拡散したおかげで、小さな店に客が増えた。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "動画[どうが]が拡散[かくさん]したおかげで、小[ちい]さな店[みせ]に客[きゃく]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "ニュースの拡散が速すぎて、訂正が追いつかなかった。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "ニュースの拡散[かくさん]が速[はや]すぎて、訂正[ていせい]が追[お]いつかなかった。", "sentence_source": "generated"}, {"text": "この写真を拡散してほしいと、友だちに頼まれた。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "この写真[しゃしん]を拡散[かくさん]してほしいと、友[とも]だちに頼[たの]まれた。", "sentence_source": "generated"}, {"text": "災害のとき、正しい情報を拡散することが大切だ。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、正[ただ]しい情報[じょうほう]を拡散[かくさん]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "デマの拡散を止めようと、市は公式サイトで説明した。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "デマの拡散[かくさん]を止[と]めようと、市[し]は公式[こうしき]サイトで説明[せつめい]した。", "sentence_source": "generated"}, {"text": "病気の拡散を心配して、旅行を取りやめた。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "病気[びょうき]の拡散[かくさん]を心配[しんぱい]して、旅行[りょこう]を取[と]りやめた。", "sentence_source": "generated"}, {"text": "彼の発言が拡散し、思わぬ議論になった。", "target_word": "拡散", "complexity_tier": "T3", "furigana": "彼[かれ]の発言[はつげん]が拡散[かくさん]し、思[おも]わぬ議論[ぎろん]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拡散", "label": "基本形"}, {"form": "拡散する", "label": "サ変動詞形"}], "register": "標準（やや書き言葉）", "sense_fingerprint": "うわさ・情報・病気などの物事が人々の間に広まっていくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20a93d0-c34a-4826-8ae3-e5c131706219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38813, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拡散", "is_correct": true, "explanation": "正解。「SNSで拡散して」は、うわさが多くの人に広がるという意味に合う。"}, {"text": "解体", "is_correct": false, "explanation": "「SNSで解体して」は意味が通らず、うわさを壊す意味にもならない。"}, {"text": "反省", "is_correct": false, "explanation": "「SNSで反省して」は人の心の動きで、うわさを主語にすると成り立たない。"}, {"text": "承諾", "is_correct": false, "explanation": "「SNSで承諾して」はうわさが同意するという意味になり、広がる内容と合わない。"}], "explanations": {"拡散": "正解。「SNSで拡散して」は、うわさが多くの人に広がるという意味に合う。", "解体": "「SNSで解体して」は意味が通らず、うわさを壊す意味にもならない。", "反省": "「SNSで反省して」は人の心の動きで、うわさを主語にすると成り立たない。", "承諾": "「SNSで承諾して」はうわさが同意するという意味になり、広がる内容と合わない。"}, "sentence_index": 0, "correct_answer": "拡散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町は観光客を拡散するため、新しい駐車場を作った。", "explanation": "ここは〈誘致〉の意味。拡散は情報や物事が広まることで、人を呼び寄せる意味では使わない。"}, {"text": "会議中は外からの連絡を拡散して、誰も邪魔しなかった。", "explanation": "ここは〈遮断〉の意味。拡散は広がることで、外との連絡を断つ意味では使わない。"}, {"text": "選手は練習の力を拡散して、試合の最後まで走った。", "explanation": "ここは〈発揮〉の意味。拡散は広まることで、力を十分に表に出す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38813, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拡散", "is_correct": true, "explanation": "正解。「正しい情報を拡散することが大切だ」は、情報を広めることの大切さを述べる文に合う。"}, {"text": "遠慮", "is_correct": false, "explanation": "「正しい情報を遠慮する」は意味が通らず、空所に入らない。"}, {"text": "挨拶", "is_correct": false, "explanation": "「正しい情報を挨拶する」は意味が成り立たず、文に合わない。"}, {"text": "辞退", "is_correct": false, "explanation": "「正しい情報を辞退する」は情報を断るという意味になり、文の内容と合わない。"}], "explanations": {"拡散": "正解。「正しい情報を拡散することが大切だ」は、情報を広めることの大切さを述べる文に合う。", "遠慮": "「正しい情報を遠慮する」は意味が通らず、空所に入らない。", "挨拶": "「正しい情報を挨拶する」は意味が成り立たず、文に合わない。", "辞退": "「正しい情報を辞退する」は情報を断るという意味になり、文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "拡散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市は道路の交通量を拡散するため、一時的に車を止めた。", "explanation": "ここは〈制限〉の意味。拡散は広がる意味で、交通量を抑える意味では使わない。"}, {"text": "会社は取引先の申し出を拡散して、契約を結んだ。", "explanation": "ここは〈承認〉の意味。拡散は広まる意味で、申し出を認める意味では使わない。"}, {"text": "先生は答案を拡散して、点数をつけた。", "explanation": "ここは〈採点〉の意味。拡散は広がる意味で、答案に点数をつける意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38813, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その動画は拡散ず、友だちだけに見られた。", "corrected_sentence": "その動画は拡散せず、友だちだけに見られた。", "error_description": "「拡散」はサ変動詞なので、否定の「ず」は「せず」と結ぶ。「拡散ず」は「せ」が抜けた誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38813, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "デマが拡散れたので、市が説明した。", "corrected_sentence": "デマが拡散したので、市が説明した。", "error_description": "「拡散」の過去形は「拡散した」になる。「拡散れた」は「し」を「れ」に変えた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
