INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38814, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "はさみなどで切ること。", "primary_collocate": null, "pronunciation": "せんだん", "ipa": "seɲdaɴ", "syllable_count": 4, "sentences": [{"text": "作業台の大型はさみで、厚い段ボールを剪断した。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "作業台[さぎょうだい]の大型[おおがた]はさみで、厚[あつ]い段ボールを剪断[せんだん]した。", "sentence_source": "generated"}, {"text": "この機械は、薄い紙を一度に剪断できる。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "このきかいは、うすいかみをいちどにせんだんできる。", "sentence_source": "generated"}, {"text": "薄いアルミ板を、まっすぐな線に沿って剪断する。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "薄[うす]いアルミ板[いた]を、まっすぐな線[せん]に沿[そ]って剪断[せんだん]する。", "sentence_source": "generated"}, {"text": "針金は固いので、普通のはさみでは剪断できない。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "はりがねはかたいので、ふつうのはさみではせんだんできない。", "sentence_source": "generated"}, {"text": "工場では、長い鉄の板を決まった長さに剪断している。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "こうじょうでは、ながいてつのいたをきまったながさにせんだんしている。", "sentence_source": "generated"}, {"text": "剪断のあと、切り口はきれいに整えられた。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "せんだんのあと、きりくちはきれいにととのえられた。", "sentence_source": "generated"}, {"text": "太いケーブルを剪断するときは、専用の刃物を使う。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "太[ふと]いケーブルを剪断[せんだん]するときは、専用[せんよう]の刃物[はもの]を使[つか]う。", "sentence_source": "generated"}, {"text": "古い防水シートを剪断して、応急の覆いを作った。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "古[ふる]い防水[ぼうすい]シートを剪断[せんだん]して、応急[おうきゅう]の覆[おお]いを作[つく]った。", "sentence_source": "generated"}, {"text": "刃がにぶいと、紙の剪断がうまくいかない。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "はがにぶいと、かみのせんだんがうまくいかない。", "sentence_source": "generated"}, {"text": "通路にはみ出していた鉄板の端を、剪断することにした。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "通路[つうろ]にはみ出[だ]していた鉄板[てっぱん]の端[はし]を、剪断[せんだん]することにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "剪断する", "label": "終止形"}, {"form": "剪断した", "label": "過去形"}, {"form": "剪断して", "label": "て形"}, {"form": "剪断できる", "label": "可能形"}, {"form": "剪断しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "はさみや刃で枝・紙・布などを切ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2bc8fb-5cad-4828-a8e5-f8d473bc523b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38814, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剪断", "is_correct": true, "explanation": "はさみで厚い段ボールを切る行為を表し、文の意味に合う。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつける行為で、段ボールには使えない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかける行為で、段ボールを対象にしないので合わない。"}, {"text": "湿布", "is_correct": false, "explanation": "患部に貼る薬で、段ボールには使わないので合わない。"}], "explanations": {"剪断": "はさみで厚い段ボールを切る行為を表し、文の意味に合う。", "点灯": "明かりをつける行為で、段ボールには使えない。", "施錠": "鍵をかける行為で、段ボールを対象にしないので合わない。", "湿布": "患部に貼る薬で、段ボールには使わないので合わない。"}, "sentence_index": 0, "correct_answer": "剪断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冷めたスープを、剪断して温めた。", "explanation": "ここは〈温める〉の意味。剪断は刃物で切ることで、液体を温める意味には合わない。"}, {"text": "包丁を剪断して、刃を整えた。", "explanation": "ここは〈研ぐ〉の意味。刃を磨く作業で、切ることではないので剪断は使わない。"}, {"text": "食器を剪断して、汚れを落とした。", "explanation": "ここは〈洗う〉の意味。汚れを落とす作業で、切る行為ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38814, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剪断", "is_correct": true, "explanation": "太いケーブルを刃で切る行為として、文の意味に合う。"}, {"text": "解凍", "is_correct": false, "explanation": "凍ったものを溶かす行為で、ケーブルを切る文脈には合わない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分を飛ばす行為で、刃物を使う文脈には合わない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける行為で、ケーブルには使えず刃物と結びつかない。"}], "explanations": {"剪断": "太いケーブルを刃で切る行為として、文の意味に合う。", "解凍": "凍ったものを溶かす行為で、ケーブルを切る文脈には合わない。", "乾燥": "水分を飛ばす行為で、刃物を使う文脈には合わない。", "点火": "火をつける行為で、ケーブルには使えず刃物と結びつかない。"}, "sentence_index": 6, "correct_answer": "剪断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二枚の鉄板を、剪断でつなぐことにした。", "explanation": "ここは〈溶接〉の意味。二つの材料をつなぐ作業で、切る剪断ではつながらない。"}, {"text": "洗濯物を、剪断することにした。", "explanation": "ここは〈干す〉の意味。洗った布を乾かす作業で、切ることではない。"}, {"text": "プレゼントを、丁寧に剪断することにした。", "explanation": "ここは〈包む〉の意味。贈り物を紙で覆う作業で、切る行為ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38814, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "金属板の剪断を後、端を整えた。", "corrected_sentence": "金属板の剪断の後、端を整えた。", "error_description": "誤りは「剪断を後」の「を」。正しくは「剪断の後」（「の」で名詞をつなぐ）。「剪断を」は後に続く名詞として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38814, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厚いゴムシートを剪断しるには、専用の刃が必要だ。", "corrected_sentence": "厚いゴムシートを剪断するには、専用の刃が必要だ。", "error_description": "誤りは「剪断しる」の「しる」。正しくは「剪断する」。「しる」は「知る」の語形で、「剪断」と組み合わせられない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
