INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38815, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物をはさみや刃物で切断すること。", "primary_collocate": null, "pronunciation": "せんだん", "ipa": "seɲdaɴ", "syllable_count": 4, "sentences": [{"text": "職人は刃物でロープを剪断した。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "しょくにんははものでロープをせんだんした。", "sentence_source": "generated"}, {"text": "大きな刃物を使って、ゴムの管を剪断した。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "おおきなはものをつかって、ゴムのくだをせんだんした。", "sentence_source": "generated"}, {"text": "この道具は、金属のパイプも簡単に剪断できる。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "このどうぐは、きんぞくのパイプもかんたんにせんだんできる。", "sentence_source": "generated"}, {"text": "危ないので、子どもは刃物による剪断をしてはいけない。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "あぶないので、こどもははものによるせんだんをしてはいけない。", "sentence_source": "generated"}, {"text": "紙の束を剪断する機械の音が、部屋に響いた。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "かみのたばをせんだんするきかいのおとが、へやにひびいた。", "sentence_source": "generated"}, {"text": "彼は針金をはさみで剪断し、箱のふたを開けた。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "かれははりがねをはさみでせんだんし、はこのふたをあけた。", "sentence_source": "generated"}, {"text": "テープを剪断したら、中から古い手紙が出てきた。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "テープをせんだんしたら、なかからふるいてがみがでてきた。", "sentence_source": "generated"}, {"text": "刃が欠けていて、厚いステンレス板を剪断するのに時間がかかった。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "刃[は]が欠[か]けていて、厚[あつ]いステンレス板[ばん]を剪断[せんだん]するのに時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "工事の人が太い鉄の棒を剪断する様子を見た。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "こうじのひとがふといてつのぼうをせんだんするようすをみた。", "sentence_source": "generated"}, {"text": "手で切れないひもは、刃物で剪断するしかない。", "target_word": "剪断", "complexity_tier": "T3", "furigana": "てできれないひもは、はものでせんだんするしかない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "剪断する", "label": "終止形"}, {"form": "剪断した", "label": "過去形"}, {"form": "剪断して", "label": "て形"}, {"form": "剪断できる", "label": "可能形"}, {"form": "剪断しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "ひも・針金・パイプなどの物を刃物で切り離すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2bc8fb-5cad-4828-a8e5-f8d473bc523b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38815, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剪断", "is_correct": true, "explanation": "刃物でロープを切り離す行為を表し、文の意味に合う。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分を飛ばす作業で、刃物で切る文脈には合わない。"}, {"text": "貼付", "is_correct": false, "explanation": "貼りつける行為で、刃物で切り離す文脈には合わない。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつける行為で、ロープには使えないので合わない。"}], "explanations": {"剪断": "刃物でロープを切り離す行為を表し、文の意味に合う。", "乾燥": "水分を飛ばす作業で、刃物で切る文脈には合わない。", "貼付": "貼りつける行為で、刃物で切り離す文脈には合わない。", "点灯": "明かりをつける行為で、ロープには使えないので合わない。"}, "sentence_index": 0, "correct_answer": "剪断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "金属のパイプを、溶接ではなく剪断でつないだ。", "explanation": "ここは〈溶接〉の意味。二つの材料をつなぐ作業で、切り離す剪断では合わない。"}, {"text": "洗った服を、剪断することにした。", "explanation": "ここは〈乾かす〉の意味。水気を飛ばす作業で、刃物で切り離す意味には合わない。"}, {"text": "音楽を、剪断して聞いた。", "explanation": "ここは〈聴く〉の意味。音楽は刃物で切り離せないので、剪断は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38815, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剪断", "is_correct": true, "explanation": "テープを刃物で切る行為を表し、中の手紙が出てくる文脈に合う。"}, {"text": "解凍", "is_correct": false, "explanation": "凍ったものを溶かす行為で、テープを切る文脈には合わない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける行為で、テープには使えず刃物とも結びつかない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかける行為で、テープを対象にしないので合わない。"}], "explanations": {"剪断": "テープを刃物で切る行為を表し、中の手紙が出てくる文脈に合う。", "解凍": "凍ったものを溶かす行為で、テープを切る文脈には合わない。", "点火": "火をつける行為で、テープには使えず刃物とも結びつかない。", "施錠": "鍵をかける行為で、テープを対象にしないので合わない。"}, "sentence_index": 6, "correct_answer": "剪断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "切れ味の落ちた包丁を、剪断することにした。", "explanation": "ここは〈研ぐ〉の意味。切れ味を戻す作業で、切り離す意味ではないので合わない。"}, {"text": "プレゼントを、剪断して包んだ。", "explanation": "ここは〈包む〉の意味。贈り物を紙で覆う作業で、切り離す行為ではない。"}, {"text": "食器を、剪断することにした。", "explanation": "ここは〈洗う〉の意味。汚れを落とす作業で、切り離す行為ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38815, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古いテープの剪断を後、中身を取り出した。", "corrected_sentence": "古いテープの剪断の後、中身を取り出した。", "error_description": "誤りは「剪断を後」の「を」。正しくは「剪断の後」（「の」で名詞をつなぐ）。「剪断を」は後に続く名詞として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38815, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "刃が鈍いと、剪断きない。", "corrected_sentence": "刃が鈍いと、剪断できない。", "error_description": "誤りは「剪断きない」。正しくは「剪断できない」。「でき」が抜けており、可能の形が崩れている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38816, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「ぶつかるときの緩衝」の「の」で、緩衝がどの場面のものかを示す。"}, {"text": "を", "is_correct": false, "explanation": "「ぶつかるときを緩衝として」は「とき」を目的語にすることになり、名詞修飾の形に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「ぶつかるときで緩衝として」は手段の意味にならず、文が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「ぶつかるときへ緩衝」は方向を表すが、場面を示す名詞修飾にはならない。"}], "correct_answer": "の", "explanations": {"の": "正解。「ぶつかるときの緩衝」の「の」で、緩衝がどの場面のものかを示す。", "を": "「ぶつかるときを緩衝として」は「とき」を目的語にすることになり、名詞修飾の形に合わない。", "で": "「ぶつかるときで緩衝として」は手段の意味にならず、文が通らない。", "へ": "「ぶつかるときへ緩衝」は方向を表すが、場面を示す名詞修飾にはならない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38816, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「緩衝が入っている」の「が」で、緩衝を主語にして入っている状態を表す。"}, {"text": "と", "is_correct": false, "explanation": "「緩衝と入っている」は相手や共同を表し、物が入っている文と合わない。"}, {"text": "より", "is_correct": false, "explanation": "「緩衝より入っている」は比較の基準になり、入っている状態の文と合わない。"}, {"text": "から", "is_correct": false, "explanation": "「緩衝から入っている」は起点の意味になり、中に入っている状態を表せない。"}], "correct_answer": "が", "explanations": {"が": "正解。「緩衝が入っている」の「が」で、緩衝を主語にして入っている状態を表す。", "と": "「緩衝と入っている」は相手や共同を表し、物が入っている文と合わない。", "より": "「緩衝より入っている」は比較の基準になり、入っている状態の文と合わない。", "から": "「緩衝から入っている」は起点の意味になり、中に入っている状態を表せない。"}, "error_tags": {"と": "共同・相手", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38816, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ぶつかったときの力をやわらげるもの。", "primary_collocate": null, "pronunciation": "かんしょう", "ipa": "kaɴɕoː", "syllable_count": 4, "sentences": [{"text": "このゴムは、ぶつかったときの緩衝になる。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "このゴムは、ぶつかったときの緩衝[かんしょう]になる。", "sentence_source": "generated"}, {"text": "ボールが壁にぶつかるときの緩衝として、壁にスポンジを貼った。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "ボールが壁にぶつかるときの緩衝[かんしょう]として、壁にスポンジを貼った。", "sentence_source": "generated"}, {"text": "バンパーは車の緩衝として、衝突の力を弱めている。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "バンパーは車[くるま]の緩衝[かんしょう]として、衝突[しょうとつ]の力[ちから]を弱[よわ]めている。", "sentence_source": "generated"}, {"text": "厚い雪が緩衝になって、子どもは落ちてもけがをしなかった。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "厚[あつ]い雪[ゆき]が緩衝[かんしょう]になって、子[こ]どもは落[お]ちてもけがをしなかった。", "sentence_source": "generated"}, {"text": "柔らかい砂が緩衝の働きをして、ジャンプの着地が楽だった。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "柔[やわ]らかい砂[すな]が緩衝[かんしょう]の働[はたら]きをして、ジャンプの着地[ちゃくち]が楽[らく]だった。", "sentence_source": "generated"}, {"text": "机の角に緩衝をつけたので、小さな子どもも安心だ。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "机[つくえ]の角[かど]に緩衝[かんしょう]をつけたので、小[ちい]さな子[こ]どもも安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "草むらが緩衝となり、倒れても痛くなかった。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "草[くさ]むらが緩衝[かんしょう]となり、倒[たお]れても痛[いた]くなかった。", "sentence_source": "generated"}, {"text": "靴の底には、足への衝撃を弱める緩衝が入っている。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "靴[くつ]の底[そこ]には、足[あし]への衝撃[しょうげき]を弱[よわ]める緩衝[かんしょう]が入[はい]っている。", "sentence_source": "generated"}, {"text": "箱の中に紙を丸めて入れ、緩衝の代わりにした。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "箱[はこ]の中[なか]に紙[かみ]を丸[まる]めて入[い]れ、緩衝[かんしょう]の代[か]わりにした。", "sentence_source": "generated"}, {"text": "ドアに緩衝がないと、閉めるたびに大きな音がする。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "ドアに緩衝[かんしょう]がないと、閉[し]めるたびに大[おお]きな音[おと]がする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緩衝", "label": "基本形"}], "register": "標準（やや書き言葉）", "sense_fingerprint": "ぶつかる力を受けてやわらげる物や部分（ゴム・雪・砂など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20a93d0-c34a-4826-8ae3-e5c131706219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38816, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "緩衝", "is_correct": true, "explanation": "正解。「ぶつかったときの緩衝になる」は、衝撃をやわらげるものという意味に合う。"}, {"text": "照明", "is_correct": false, "explanation": "「ぶつかったときの照明」は意味が通らず、衝撃とは関係ない。"}, {"text": "会計", "is_correct": false, "explanation": "「ぶつかったときの会計」は成り立たず、衝撃をやわらげる役にならない。"}, {"text": "辞書", "is_correct": false, "explanation": "「ぶつかったときの辞書」は衝撃をやわらげるものにならず、文に合わない。"}], "explanations": {"緩衝": "正解。「ぶつかったときの緩衝になる」は、衝撃をやわらげるものという意味に合う。", "照明": "「ぶつかったときの照明」は意味が通らず、衝撃とは関係ない。", "会計": "「ぶつかったときの会計」は成り立たず、衝撃をやわらげる役にならない。", "辞書": "「ぶつかったときの辞書」は衝撃をやわらげるものにならず、文に合わない。"}, "sentence_index": 0, "correct_answer": "緩衝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強い痛みを和らげるために、薬の緩衝を使った。", "explanation": "ここは〈緩和〉の意味。緩衝は物がぶつかる力をやわらげるもので、痛みを和らげる場合には使わない。"}, {"text": "壁に緩衝を貼って、隣の音を防いだ。", "explanation": "ここは〈防音〉の意味。緩衝は衝撃をやわらげるもので、音を遮る意味では使わない。"}, {"text": "屋根に緩衝を施して、雨漏りを防いだ。", "explanation": "ここは〈防水〉の意味。緩衝は衝撃をやわらげるもので、水を通さない意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38816, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "緩衝", "is_correct": true, "explanation": "正解。「草むらが緩衝となり」は、倒れたときの衝撃をやわらげる役になるという意味に合う。"}, {"text": "拍手", "is_correct": false, "explanation": "「草むらが拍手となり」は意味が通らず、衝撃をやわらげる役にならない。"}, {"text": "販売", "is_correct": false, "explanation": "「草むらが販売となり」は草むらが商品になるという意味で、文に合わない。"}, {"text": "朝食", "is_correct": false, "explanation": "「草むらが朝食となり」は意味が成り立たず、文に合わない。"}], "explanations": {"緩衝": "正解。「草むらが緩衝となり」は、倒れたときの衝撃をやわらげる役になるという意味に合う。", "拍手": "「草むらが拍手となり」は意味が通らず、衝撃をやわらげる役にならない。", "販売": "「草むらが販売となり」は草むらが商品になるという意味で、文に合わない。", "朝食": "「草むらが朝食となり」は意味が成り立たず、文に合わない。"}, "sentence_index": 6, "correct_answer": "緩衝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い橋の緩衝のため、鉄の柱を追加した。", "explanation": "ここは〈補強〉の意味。緩衝は衝撃をやわらげるもので、構造を強くする意味では使わない。"}, {"text": "夏のエンジンに緩衝をつけて、熱くならないようにした。", "explanation": "ここは〈冷却〉の意味。緩衝は衝撃をやわらげるもので、熱を下げる意味では使わない。"}, {"text": "昼間は窓から緩衝を取り入れて、部屋を明るくした。", "explanation": "ここは〈採光〉の意味。緩衝は衝撃をやわらげるもので、光を取り入れる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38816, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この布は、ガラスを守る緩衝をなる。", "corrected_sentence": "この布は、ガラスを守る緩衝になる。", "error_description": "「なる」は「～になる」の形で、「緩衝」には「に」を続ける。「緩衝をなる」は助詞の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38816, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "卵を運ぶには、箱の中に緩衝に必要だ。", "corrected_sentence": "卵を運ぶには、箱の中に緩衝が必要だ。", "error_description": "「必要だ」は「が必要だ」と結ぶ。「緩衝に必要」は「が」を「に」にした誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38817, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「緩衝を敷いた」の「を」で、敷く対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「緩衝が敷いた」は緩衝が自分で敷く主語になり、文の意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「緩衝から敷いた」は起点の意味になり、敷く対象を示せず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「緩衝へ敷いた」は方向を表し、敷く対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「緩衝を敷いた」の「を」で、敷く対象を示す。", "が": "「緩衝が敷いた」は緩衝が自分で敷く主語になり、文の意味が通らない。", "から": "「緩衝から敷いた」は起点の意味になり、敷く対象を示せず文が成り立たない。", "へ": "「緩衝へ敷いた」は方向を表し、敷く対象を示せない。"}, "error_tags": {"が": "主語", "から": "起点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38817, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「緩衝を敷けば」の「を」で、敷く対象を示す。"}, {"text": "と", "is_correct": false, "explanation": "「緩衝と敷けば」は相手や共同を表し、敷く対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「緩衝より敷けば」は比較の基準になり、敷く動作と結びつかない。"}, {"text": "から", "is_correct": false, "explanation": "「緩衝から敷けば」は起点の意味になり、敷く対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「緩衝を敷けば」の「を」で、敷く対象を示す。", "と": "「緩衝と敷けば」は相手や共同を表し、敷く対象にならない。", "より": "「緩衝より敷けば」は比較の基準になり、敷く動作と結びつかない。", "から": "「緩衝から敷けば」は起点の意味になり、敷く対象を示せない。"}, "error_tags": {"と": "共同・相手", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38817, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "衝撃を和らげるために使うもの。", "primary_collocate": null, "pronunciation": "かんしょう", "ipa": "kaɴɕoː", "syllable_count": 4, "sentences": [{"text": "割れ物を送るときは、緩衝として新聞紙を使う。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "割[わ]れ物[もの]を送[おく]るときは、緩衝[かんしょう]として新聞紙[しんぶんし]を使[つか]う。", "sentence_source": "generated"}, {"text": "荷物が壊れないように、箱の底に緩衝を敷いた。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "荷物[にもつ]が壊[こわ]れないように、箱[はこ]の底[そこ]に緩衝[かんしょう]を敷[し]いた。", "sentence_source": "generated"}, {"text": "ヘルメットの内側には、頭への衝撃を弱める緩衝が入っている。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "ヘルメットの内側[うちがわ]には、頭[あたま]への衝撃[しょうげき]を弱[よわ]める緩衝[かんしょう]が入[はい]っている。", "sentence_source": "generated"}, {"text": "運動靴の緩衝がすり減って、走ると足が痛くなった。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "運動靴[うんどうぐつ]の緩衝[かんしょう]がすり減[へ]って、走[はし]ると足[あし]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "この機械は、振動を吸収する緩衝をつけて静かに動く。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "この機械[きかい]は、振動[しんどう]を吸収[きゅうしゅう]する緩衝[かんしょう]をつけて静[しず]かに動[うご]く。", "sentence_source": "generated"}, {"text": "エレベーターの底には、落ちたときのための緩衝がある。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "エレベーターの底[そこ]には、落[お]ちたときのための緩衝[かんしょう]がある。", "sentence_source": "generated"}, {"text": "ガラスのコップは、布を緩衝にして包んだ。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "ガラスのコップは、布[ぬの]を緩衝[かんしょう]にして包[つつ]んだ。", "sentence_source": "generated"}, {"text": "床に緩衝を敷けば、物を落としても割れにくい。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "床[ゆか]に緩衝[かんしょう]を敷[し]けば、物[もの]を落[お]としても割[わ]れにくい。", "sentence_source": "generated"}, {"text": "自転車のサドルには、ばねの緩衝がついている。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]のサドルには、ばねの緩衝[かんしょう]がついている。", "sentence_source": "generated"}, {"text": "卵を運ぶ容器の緩衝が、衝撃から卵を守る。", "target_word": "緩衝", "complexity_tier": "T3", "furigana": "卵[たまご]を運[はこ]ぶ容器[ようき]の緩衝[かんしょう]が、衝撃[しょうげき]から卵[たまご]を守[まも]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緩衝", "label": "基本形"}], "register": "標準（やや書き言葉）", "sense_fingerprint": "衝撃や振動を和らげる目的で使う道具・詰め物・装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20a93d0-c34a-4826-8ae3-e5c131706219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38817, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "緩衝", "is_correct": true, "explanation": "正解。「割れ物を送るときは、緩衝として新聞紙を使う」は、衝撃から守る材料という意味に合う。"}, {"text": "注文", "is_correct": false, "explanation": "「注文として新聞紙を使う」は意味が通らず、送るときの用途にならない。"}, {"text": "鑑賞", "is_correct": false, "explanation": "「鑑賞として新聞紙を使う」は意味が成り立たず、梱包の役目にならない。"}, {"text": "遠慮", "is_correct": false, "explanation": "「遠慮として新聞紙を使う」は意味が通らず、文に合わない。"}], "explanations": {"緩衝": "正解。「割れ物を送るときは、緩衝として新聞紙を使う」は、衝撃から守る材料という意味に合う。", "注文": "「注文として新聞紙を使う」は意味が通らず、送るときの用途にならない。", "鑑賞": "「鑑賞として新聞紙を使う」は意味が成り立たず、梱包の役目にならない。", "遠慮": "「遠慮として新聞紙を使う」は意味が通らず、文に合わない。"}, "sentence_index": 0, "correct_answer": "緩衝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ベルトを荷物の緩衝にして、動かないようにした。", "explanation": "ここは〈固定〉の意味。緩衝は衝撃をやわらげるもので、物を動かないように止める意味では使わない。"}, {"text": "寒い日は、コートを体の緩衝にして、暖かく過ごした。", "explanation": "ここは〈保温〉の意味。緩衝は衝撃をやわらげるもので、温度を保つ意味では使わない。"}, {"text": "引き出しの緩衝で、小物を分けて入れた。", "explanation": "ここは〈仕切り〉の意味。緩衝は衝撃をやわらげるもので、区切って分ける意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38817, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "緩衝", "is_correct": true, "explanation": "正解。「布を緩衝にして包んだ」は、布で衝撃から守るという意味に合う。"}, {"text": "洗濯", "is_correct": false, "explanation": "「布を洗濯にして包んだ」は意味が通らず、包む材料にならない。"}, {"text": "採点", "is_correct": false, "explanation": "「布を採点にして包んだ」は意味が成り立たず、文に合わない。"}, {"text": "注意", "is_correct": false, "explanation": "「布を注意にして包んだ」は布が注意になるという意味で、包む材料として合わない。"}], "explanations": {"緩衝": "正解。「布を緩衝にして包んだ」は、布で衝撃から守るという意味に合う。", "洗濯": "「布を洗濯にして包んだ」は意味が通らず、包む材料にならない。", "採点": "「布を採点にして包んだ」は意味が成り立たず、文に合わない。", "注意": "「布を注意にして包んだ」は布が注意になるという意味で、包む材料として合わない。"}, "sentence_index": 6, "correct_answer": "緩衝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カーテンは部屋の光の緩衝として、昼も暗く保つ。", "explanation": "ここは〈遮光〉の意味。緩衝は衝撃をやわらげるもので、光をさえぎる意味では使わない。"}, {"text": "ひびの入った壁を緩衝にして、きれいにした。", "explanation": "ここは〈補修〉の意味。緩衝は衝撃をやわらげるもので、傷んだものを直す意味では使わない。"}, {"text": "夏の暑さを防ぐため、窓に緩衝を取りつけた。", "explanation": "ここは〈遮熱〉の意味。緩衝は衝撃をやわらげるもので、日差しや熱を防ぐ意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38817, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "割れやすい皿には、緩衝が入れておく。", "corrected_sentence": "割れやすい皿には、緩衝を入れておく。", "error_description": "「入れる」は目的語に「を」をとる。「緩衝が入れておく」は「が」が誤りで、「を」に直す必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38817, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "割れ物には、緩衝を必要だ。", "corrected_sentence": "割れ物には、緩衝が必要だ。", "error_description": "「必要だ」は「が必要だ」と結ぶ。「緩衝を必要だ」は「を」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d1a52f9-ed6d-494d-9a2b-c2127414e950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38818, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「底面は」で底面を話題として示す。「円柱の底面は丸い形をしている」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「形をしている」の「を」と紛らわしいが、底面を対象にすると文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。底面が丸い形をしているという文の主題にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示す。底面と丸い形を並べても、底面の性質を述べる文にならない。"}], "correct_answer": "は", "explanations": {"は": "「底面は」で底面を話題として示す。「円柱の底面は丸い形をしている」と自然に続く。", "を": "「形をしている」の「を」と紛らわしいが、底面を対象にすると文が成り立たない。", "で": "「で」は場所や手段を示す。底面が丸い形をしているという文の主題にはならない。", "と": "「と」は並列を示す。底面と丸い形を並べても、底面の性質を述べる文にならない。"}, "error_tags": {"を": "対象の誤用", "で": "場所・手段の誤用", "と": "並列の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38818, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「底面に」で、ゴムをつける場所を示す。「家具の底面にゴムをつけて」と自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。底面が主語になってゴムをつける文は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。底面より、と続けても文の意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "ゴムが「を」で目的語になっており、底面にもう一つ「を」を置くと文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「底面に」で、ゴムをつける場所を示す。「家具の底面にゴムをつけて」と自然に続く。", "が": "「が」は主語を示す。底面が主語になってゴムをつける文は成り立たない。", "より": "「より」は比較を示す。底面より、と続けても文の意味が通らない。", "を": "ゴムが「を」で目的語になっており、底面にもう一つ「を」を置くと文が成り立たない。"}, "error_tags": {"が": "主語の誤用", "より": "比較の誤用", "を": "目的語の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38818, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物のいちばん下の部分。", "primary_collocate": null, "pronunciation": "ていめん", "ipa": "teimeɴ", "syllable_count": 4, "sentences": [{"text": "箱の底面に小さな穴があいていて、水がもれてしまった。", "target_word": "底面", "complexity_tier": "T3", "furigana": "箱[はこ]の底面[ていめん]に小[ちい]さな穴[あな]があいていて、水[みず]がもれてしまった。", "sentence_source": "generated"}, {"text": "円柱の底面は丸い形をしている。", "target_word": "底面", "complexity_tier": "T3", "furigana": "円柱[えんちゅう]の底面[ていめん]は丸[まる]い形[かたち]をしている。", "sentence_source": "generated"}, {"text": "このコップは底面が広いので、倒れにくい。", "target_word": "底面", "complexity_tier": "T3", "furigana": "このコップは底面[ていめん]が広[ひろ]いので、倒[たお]れにくい。", "sentence_source": "generated"}, {"text": "机の底面に、作った人の名前が書いてあった。", "target_word": "底面", "complexity_tier": "T3", "furigana": "机[つくえ]の底面[ていめん]に、作[つく]った人[ひと]の名前[なまえ]が書[か]いてあった。", "sentence_source": "generated"}, {"text": "荷物を置く前に、箱の底面をきれいにふいた。", "target_word": "底面", "complexity_tier": "T3", "furigana": "荷物[にもつ]を置[お]く前[まえ]に、箱[はこ]の底面[ていめん]をきれいにふいた。", "sentence_source": "generated"}, {"text": "ピラミッドの底面は正方形になっている。", "target_word": "底面", "complexity_tier": "T3", "furigana": "ピラミッドの底面[ていめん]は正方形[せいほうけい]になっている。", "sentence_source": "generated"}, {"text": "靴の底面がすり減って、雨の日にすべりやすい。", "target_word": "底面", "complexity_tier": "T3", "furigana": "靴[くつ]の底面[ていめん]がすり減[へ]って、雨[あめ]の日[ひ]にすべりやすい。", "sentence_source": "generated"}, {"text": "家具の底面にゴムをつけて、床に傷がつかないようにした。", "target_word": "底面", "complexity_tier": "T3", "furigana": "家具[かぐ]の底面[ていめん]にゴムをつけて、床[ゆか]に傷[きず]がつかないようにした。", "sentence_source": "generated"}, {"text": "石を持ち上げると、底面に虫がいた。", "target_word": "底面", "complexity_tier": "T3", "furigana": "石[いし]を持[も]ち上[あ]げると、底面[ていめん]に虫[むし]がいた。", "sentence_source": "generated"}, {"text": "この箱は底面が弱いから、重い物は入れられない。", "target_word": "底面", "complexity_tier": "T3", "furigana": "この箱[はこ]は底面[ていめん]が弱[よわ]いから、重[おも]い物[もの]は入[い]れられない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "底面", "label": "基本形"}], "register": "標準語（常体）", "sense_fingerprint": "物の一番下にあたる部分。箱・立体・道具などの下側。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0568bb4e-9a35-4f81-9107-29aa110f32d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38818, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "底面", "is_correct": true, "explanation": "箱の下側の面を指し、穴があく場所として自然に入る。"}, {"text": "値段", "is_correct": false, "explanation": "値段は箱にあく穴の場所にならず、文の意味が成り立たない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは穴の場所を表せず、ここでは文が意味をなさない。"}, {"text": "中身", "is_correct": false, "explanation": "中身は箱の内側の物で、穴があいた場所としては文脈に合わない。"}], "explanations": {"底面": "箱の下側の面を指し、穴があく場所として自然に入る。", "値段": "値段は箱にあく穴の場所にならず、文の意味が成り立たない。", "香り": "香りは穴の場所を表せず、ここでは文が意味をなさない。", "中身": "中身は箱の内側の物で、穴があいた場所としては文脈に合わない。"}, "sentence_index": 0, "correct_answer": "底面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三角形の底面の長さを測って、面積を求めた。", "explanation": "ここは〈底辺〉の意味。底面は立体の下の面を指し、三角形のような平面図形には使わない。"}, {"text": "貯金がとうとう底面をついて、来月の家賃が払えない。", "explanation": "ここは〈底をつく〉（なくなる）の表現。底面は物の下の面で、なくなる意味では使わない。"}, {"text": "この店は今日だけ底面で野菜を売っている。", "explanation": "ここは〈底値〉（いちばん安い値段）の意味。底面は物の下の面で、値段の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38818, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "底面", "is_correct": true, "explanation": "靴の下側の部分を指し、すり減る場所として自然。"}, {"text": "重さ", "is_correct": false, "explanation": "重さはすり減る対象にならず、文の意味が成り立たない。"}, {"text": "音", "is_correct": false, "explanation": "音は靴がすり減る対象ではなく、ここでは文が合わない。"}, {"text": "匂い", "is_correct": false, "explanation": "匂いは靴の部位ではなく、すり減るという文脈に合わない。"}], "explanations": {"底面": "靴の下側の部分を指し、すり減る場所として自然。", "重さ": "重さはすり減る対象にならず、文の意味が成り立たない。", "音": "音は靴がすり減る対象ではなく、ここでは文が合わない。", "匂い": "匂いは靴の部位ではなく、すり減るという文脈に合わない。"}, "sentence_index": 6, "correct_answer": "底面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの選手は底面が強くて、最後まで走り抜けた。", "explanation": "ここは〈底力〉（粘り強い力）の意味。底面は物の下の面で、体力や粘りの意味では使わない。"}, {"text": "この部屋は底面がひどくて、夜は足元から冷える。", "explanation": "ここは〈底冷え〉（床から伝わる寒さ）の意味。底面は物の下の面で、寒さの意味では使わない。"}, {"text": "この人は底面が浅いので、すぐ考えが変わってしまう。", "explanation": "ここは〈底の浅い〉（考えが浅い）の意味。底面は物の下の面で、人の考えには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38818, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "テーブルの底面に、ぞうきんできれいにふいた。", "corrected_sentence": "テーブルの底面を、ぞうきんできれいにふいた。", "error_description": "「ふく」の対象は「を」で示す。「底面に」は誤りで、正しくは「底面を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38818, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この棚は底面が弱さなので、重い物は置けない。", "corrected_sentence": "この棚は底面が弱いので、重い物は置けない。", "error_description": "「弱い」は形容詞。名詞形の「弱さ」を述語には使えない。正しくは「弱い」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38819, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「底面が」で、底面が焦げるという主語を示す。「鍋の底面が焦げて」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示す。底面を焦げるとは言えず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、動詞「焦げて」に直接続けると文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示す。底面と焦げるという組み合わせは意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「底面が」で、底面が焦げるという主語を示す。「鍋の底面が焦げて」と自然に続く。", "を": "「を」は対象を示す。底面を焦げるとは言えず、文が成り立たない。", "の": "「の」は名詞をつなぐ助詞で、動詞「焦げて」に直接続けると文が成り立たない。", "と": "「と」は並列を示す。底面と焦げるという組み合わせは意味が通らない。"}, "error_tags": {"を": "対象の誤用", "と": "並列の誤用", "の": "名詞修飾の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38819, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「底面に」で、古い手紙が落ちた場所を示す。「引き出しの底面に、古い手紙が一枚落ちていた」と自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。底面が主語になって手紙が落ちる文は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。底面より、と続けても文の意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「落ちる」は自動詞で目的語をとれず、「を」を置くと文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「底面に」で、古い手紙が落ちた場所を示す。「引き出しの底面に、古い手紙が一枚落ちていた」と自然に続く。", "が": "「が」は主語を示す。底面が主語になって手紙が落ちる文は成り立たない。", "より": "「より」は比較を示す。底面より、と続けても文の意味が通らない。", "を": "「落ちる」は自動詞で目的語をとれず、「を」を置くと文が成り立たない。"}, "error_tags": {"が": "主語の誤用", "より": "比較の誤用", "を": "自動詞の目的語の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38819, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の下の面。底の面。入れ物などの、一番下になる平らな部分。", "primary_collocate": null, "pronunciation": "ていめん", "ipa": "teimeɴ", "syllable_count": 4, "sentences": [{"text": "紙コップの底面に、ジュースが少し残っていた。", "target_word": "底面", "complexity_tier": "T3", "furigana": "紙[かみ]コップの底面[ていめん]に、ジュースが少[すこ]し残[のこ]っていた。", "sentence_source": "generated"}, {"text": "鍋の底面が焦げて、洗うのに時間がかかった。", "target_word": "底面", "complexity_tier": "T3", "furigana": "鍋[なべ]の底面[ていめん]が焦[こ]げて、洗[あら]うのに時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "水槽の底面に砂を敷いて、魚を入れた。", "target_word": "底面", "complexity_tier": "T3", "furigana": "水槽[すいそう]の底面[ていめん]に砂[すな]を敷[し]いて、魚[さかな]を入[い]れた。", "sentence_source": "generated"}, {"text": "この弁当箱は底面が平らなので、重ねやすい。", "target_word": "底面", "complexity_tier": "T3", "furigana": "この弁当箱[べんとうばこ]は底面[ていめん]が平[たい]らなので、重[かさ]ねやすい。", "sentence_source": "generated"}, {"text": "花びんの底面がぬれていたので、机に水のあとがついた。", "target_word": "底面", "complexity_tier": "T3", "furigana": "花[はな]びんの底面[ていめん]がぬれていたので、机[つくえ]に水[みず]のあとがついた。", "sentence_source": "generated"}, {"text": "バケツの底面に穴があき、水がどんどんもれた。", "target_word": "底面", "complexity_tier": "T3", "furigana": "バケツの底面[ていめん]に穴[あな]があき、水[みず]がどんどんもれた。", "sentence_source": "generated"}, {"text": "皿の底面にまで、きれいな絵がかかれている。", "target_word": "底面", "complexity_tier": "T3", "furigana": "皿[さら]の底面[ていめん]にまで、きれいな絵[え]がかかれている。", "sentence_source": "generated"}, {"text": "引き出しの底面に、古い手紙が一枚落ちていた。", "target_word": "底面", "complexity_tier": "T3", "furigana": "引[ひ]き出[だ]しの底面[ていめん]に、古[ふる]い手紙[てがみ]が一枚[いちまい]落[お]ちていた。", "sentence_source": "generated"}, {"text": "かごの底面に紙をしくと、小さな物が落ちない。", "target_word": "底面", "complexity_tier": "T3", "furigana": "かごの底面[ていめん]に紙[かみ]をしくと、小[ちい]さな物[もの]が落[お]ちない。", "sentence_source": "generated"}, {"text": "ビンを逆さにして、底面をたたいて中身を出した。", "target_word": "底面", "complexity_tier": "T3", "furigana": "ビンを逆[さか]さにして、底面[ていめん]をたたいて中身[なかみ]を出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "底面", "label": "基本形"}], "register": "標準語（常体）", "sense_fingerprint": "入れ物の一番下にある平らな面。コップ・鍋・水槽などの底。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0568bb4e-9a35-4f81-9107-29aa110f32d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38819, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "底面", "is_correct": true, "explanation": "紙コップの下側の面を指し、ジュースが残る場所として自然。"}, {"text": "色", "is_correct": false, "explanation": "色はジュースが残る場所にならず、文が成り立たない。"}, {"text": "味", "is_correct": false, "explanation": "味は場所を表せず、ここでは文が意味をなさない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は紙コップの部位ではなく、残る場所として合わない。"}], "explanations": {"底面": "紙コップの下側の面を指し、ジュースが残る場所として自然。", "色": "色はジュースが残る場所にならず、文が成り立たない。", "味": "味は場所を表せず、ここでは文が意味をなさない。", "値段": "値段は紙コップの部位ではなく、残る場所として合わない。"}, "sentence_index": 0, "correct_answer": "底面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この三角形は底面の長さが長いので、面積が大きい。", "explanation": "ここは〈底辺〉の意味。底面は立体の下の面で、三角形の辺には使わない。"}, {"text": "この店は底面で卵を売り出した。", "explanation": "ここは〈底値〉（いちばん安い値段）の意味。底面は物の下の面で、値段の意味では使わない。"}, {"text": "この地下室は底面がひどくて、夏でも足元が冷える。", "explanation": "ここは〈底冷え〉（床から伝わる寒さ）の意味。底面は物の下の面で、寒さの意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38819, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "底面", "is_correct": true, "explanation": "皿の下側の面を指し、絵がかかれる場所として自然。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは絵がかかれる場所にならず、文が成り立たない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは絵の場所にならず、文の意味が通らない。"}, {"text": "音", "is_correct": false, "explanation": "音は皿に絵をかく場所を表さず、意味が通らない。"}], "explanations": {"底面": "皿の下側の面を指し、絵がかかれる場所として自然。", "重さ": "重さは絵がかかれる場所にならず、文が成り立たない。", "香り": "香りは絵の場所にならず、文の意味が通らない。", "音": "音は皿に絵をかく場所を表さず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "底面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あのチームは底面が強くて、終盤に逆転した。", "explanation": "ここは〈底力〉（粘り強い力）の意味。底面は物の下の面で、チームの粘りの意味では使わない。"}, {"text": "彼の底面の知れない実力に、みんなが驚いた。", "explanation": "ここは〈底知れない〉（どこまであるか分からない）の意味。底面は物の下の面で、実力の計り知れなさには使わない。"}, {"text": "株価がついに底面を割って、下がり続けた。", "explanation": "ここは〈底を割る〉（最安値を下回る）の意味。底面は物の下の面で、相場の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38819, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鍋の底面で焦げが残っていた。", "corrected_sentence": "鍋の底面に焦げが残っていた。", "error_description": "「残る」の場所は「に」で示す。「で」は手段や場所の意味になり、誤り。正しくは「底面に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38819, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "底面が平らの弁当箱を買った。", "corrected_sentence": "底面が平らな弁当箱を買った。", "error_description": "「平ら」は形容動詞で、名詞を修飾するときは「な」を使う。「の」は誤り。正しくは「平らな」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38820, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「シートを敷く」の目的語を示す格助詞で、敷く対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、シートは敷かれる対象なので「シートが敷いて」は文として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、敷く対象を表す場面には使えない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す助詞で、「シートと敷いて」は意味が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「シートを敷く」の目的語を示す格助詞で、敷く対象を表す。", "が": "主語を示す助詞で、シートは敷かれる対象なので「シートが敷いて」は文として合わない。", "へ": "方向を示す助詞で、敷く対象を表す場面には使えない。", "と": "並列や相手を示す助詞で、「シートと敷いて」は意味が成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38820, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「大きなビニールを敷く」の目的語を示す格助詞で、敷く対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「ビニールが敷きましょう」は主語と勧誘形が合わず成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、敷く対象を表す場面では使えない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す助詞で、「ビニールより敷く」は意味が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「大きなビニールを敷く」の目的語を示す格助詞で、敷く対象を表す。", "が": "主語を示す助詞で、「ビニールが敷きましょう」は主語と勧誘形が合わず成り立たない。", "から": "起点を示す助詞で、敷く対象を表す場面では使えない。", "より": "比較を示す助詞で、「ビニールより敷く」は意味が成り立たない。"}, "error_tags": {"が": "主語", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38820, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを、下に平らに置くこと。", "primary_collocate": null, "pronunciation": "しく", "ipa": "ɕikɯ", "syllable_count": 2, "sentences": [{"text": "夜になったので、和室に布団を敷きます。", "target_word": "敷きます", "complexity_tier": "T3", "furigana": "夜[よる]になったので、和室[わしつ]に布団[ふとん]を敷[し]きます。", "sentence_source": "generated"}, {"text": "公園の芝生にシートを敷いて、お弁当を食べました。", "target_word": "敷いて", "complexity_tier": "T3", "furigana": "公園[こうえん]の芝生[しばふ]にシートを敷[し]いて、お弁当[べんとう]を食[た]べました。", "sentence_source": "generated"}, {"text": "床が冷たいので、その上にカーペットを敷いてください。", "target_word": "敷いて", "complexity_tier": "T3", "furigana": "床[ゆか]が冷[つめ]たいので、その上[うえ]にカーペットを敷[し]いてください。", "sentence_source": "generated"}, {"text": "母は座る前に、いすに座布団を敷きました。", "target_word": "敷きました", "complexity_tier": "T3", "furigana": "母[はは]は座[すわ]る前[まえ]に、いすに座布団[ざぶとん]を敷[し]きました。", "sentence_source": "generated"}, {"text": "机が汚れないように、新聞紙を敷いて絵を描きます。", "target_word": "敷いて", "complexity_tier": "T3", "furigana": "机[つくえ]が汚[よご]れないように、新聞紙[しんぶんし]を敷[し]いて絵[え]を描[か]きます。", "sentence_source": "generated"}, {"text": "海辺で砂の上にタオルを敷いて、横になりました。", "target_word": "敷いて", "complexity_tier": "T3", "furigana": "海辺[うみべ]で砂[すな]の上[うえ]にタオルを敷[し]いて、横[よこ]になりました。", "sentence_source": "generated"}, {"text": "旅行先の宿では、女の人が部屋に布団を敷いてくれた。", "target_word": "敷いて", "complexity_tier": "T3", "furigana": "旅行先[りょこうさき]の宿[やど]では、女[おんな]の人[ひと]が部屋[へや]に布団[ふとん]を敷[し]いてくれた。", "sentence_source": "generated"}, {"text": "地面がぬれているので、まず大きなビニールを敷きましょう。", "target_word": "敷きましょう", "complexity_tier": "T3", "furigana": "地面[じめん]がぬれているので、まず大[おお]きなビニールを敷[し]きましょう。", "sentence_source": "generated"}, {"text": "子どもは自分の部屋で、マットを敷いて体操をしています。", "target_word": "敷いて", "complexity_tier": "T3", "furigana": "子[こ]どもは自分[じぶん]の部屋[へや]で、マットを敷[し]いて体操[たいそう]をしています。", "sentence_source": "generated"}, {"text": "机の上に白い布を敷くと、写真がきれいに撮れます。", "target_word": "敷く", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に白[しろ]い布[ぬの]を敷[し]くと、写真[しゃしん]がきれいに撮[と]れます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "敷く", "label": "辞書形"}, {"form": "敷きます", "label": "丁寧形"}, {"form": "敷いて", "label": "て形"}, {"form": "敷いた", "label": "た形"}, {"form": "敷かない", "label": "ない形"}, {"form": "敷けば", "label": "仮定形"}, {"form": "敷こう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "布団やシートなどを下に平らに広げて置く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c11be19-e1cc-49c2-a822-0ba302475d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38820, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "敷きます", "is_correct": true, "explanation": "正解。布団を下に平らに広げるという意味で、和室に布団を置く文脈に合う。"}, {"text": "掃きます", "is_correct": false, "explanation": "ほうきで床のごみを払う動作で、布団には使わない。"}, {"text": "磨きます", "is_correct": false, "explanation": "表面をこすって光らせる動作で、布団を置く文脈には合わない。"}, {"text": "食べます", "is_correct": false, "explanation": "口に入れて噛む動作で、布団とは結びつかない。"}], "explanations": {"敷きます": "正解。布団を下に平らに広げるという意味で、和室に布団を置く文脈に合う。", "掃きます": "ほうきで床のごみを払う動作で、布団には使わない。", "磨きます": "表面をこすって光らせる動作で、布団を置く文脈には合わない。", "食べます": "口に入れて噛む動作で、布団とは結びつかない。"}, "sentence_index": 0, "correct_answer": "敷きます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テーブルに花瓶を敷いて、花を飾った。", "explanation": "ここは〈置く〉の意味。敷くは布などを下に広げることで、花瓶のように物を置く意味では使わない。"}, {"text": "新しい法律を敷いて、国民を縛った。", "explanation": "ここは〈施行する〉の意味。敷くは物の下に平らに置く意味で、法律を行き渡らせる意味では使わない。"}, {"text": "カーテンを敷いて、部屋を暗くした。", "explanation": "ここは〈閉める〉の意味。敷くは物を下に平らに置くことで、カーテンを閉じる動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38820, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "敷いて", "is_correct": true, "explanation": "正解。「部屋に布団を敷いてくれた」の動作を表し、宿での世話の文脈に合う。"}, {"text": "噛んで", "is_correct": false, "explanation": "口で噛む動作で、布団を部屋に用意する文脈には合わない。"}, {"text": "笑って", "is_correct": false, "explanation": "表情や声の動作で、布団を置く行為とは結びつかない。"}, {"text": "叫んで", "is_correct": false, "explanation": "大声を出す動作で、布団を部屋に用意する文脈には合わない。"}], "explanations": {"敷いて": "正解。「部屋に布団を敷いてくれた」の動作を表し、宿での世話の文脈に合う。", "噛んで": "口で噛む動作で、布団を部屋に用意する文脈には合わない。", "笑って": "表情や声の動作で、布団を置く行為とは結びつかない。", "叫んで": "大声を出す動作で、布団を部屋に用意する文脈には合わない。"}, "sentence_index": 6, "correct_answer": "敷いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厳しい規則を敷いて、社員を管理した。", "explanation": "ここは〈施行する〉の意味。敷くは物の下に平らに置く意味で、規則を行き渡らせる意味では使わない。"}, {"text": "お皿を敷いてから、食器棚にしまった。", "explanation": "ここは〈洗う〉の意味。敷くは物を下に置く動作で、汚れを落とす意味では使わない。"}, {"text": "本を棚に敷いてから、ラベルを貼った。", "explanation": "ここは〈並べる〉の意味。敷くは一面に広げて下に置くことで、物を順に並べる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38820, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "マットを敷きて、その上に座った。", "corrected_sentence": "マットを敷いて、その上に座った。", "error_description": "「敷く」のて形は「敷いて」（五段活用）。「敷きて」は一段動詞の形と混同した誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "敷いて", "is_correct": true, "explanation": "正解。て形で「〜て、お弁当を食べました」と動作を順につなぐ形。"}, {"text": "敷きます", "is_correct": false, "explanation": "丁寧形は文を終わらせるので、後ろに続くお弁当の文とつながらない。"}, {"text": "敷かない", "is_correct": false, "explanation": "否定形で、シートを敷く動作が起きていないことになり文の意味に合わない。"}, {"text": "敷くて", "is_correct": false, "explanation": "形容詞の活用を当てはめた誤りで、「敷くて」は文法的に成り立たない。"}], "correct_form": "敷いて", "base_form": "敷く", "form_label": "て形", "sentence_index": 1, "explanations": {"敷いて": "正解。て形で「〜て、お弁当を食べました」と動作を順につなぐ形。", "敷きます": "丁寧形は文を終わらせるので、後ろに続くお弁当の文とつながらない。", "敷かない": "否定形で、シートを敷く動作が起きていないことになり文の意味に合わない。", "敷くて": "形容詞の活用を当てはめた誤りで、「敷くて」は文法的に成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38820, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒いので、まずマットを敷きよう。", "corrected_sentence": "寒いので、まずマットを敷こう。", "error_description": "「敷く」の意志形は「敷こう」（五段活用）。「敷きよう」は一段動詞の形と混同した誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "敷きましょう", "is_correct": true, "explanation": "正解。「〜ましょう」の勧誘形で、「まず大きなビニールを敷きましょう」と提案する文に合う。"}, {"text": "敷き", "is_correct": false, "explanation": "連用形で、文を終わらせる勧誘の形にならない。"}, {"text": "敷かれ", "is_correct": false, "explanation": "受身の連用形で、文末に置くと「敷かれ」で文が切れてしまい提案の意味にならない。"}, {"text": "敷いたり", "is_correct": false, "explanation": "「〜たり」の並列形で、提案を述べる文として完結しない。"}], "correct_form": "敷きましょう", "base_form": "敷く", "form_label": "勧誘形", "sentence_index": 7, "explanations": {"敷きましょう": "正解。「〜ましょう」の勧誘形で、「まず大きなビニールを敷きましょう」と提案する文に合う。", "敷き": "連用形で、文を終わらせる勧誘の形にならない。", "敷かれ": "受身の連用形で、文末に置くと「敷かれ」で文が切れてしまい提案の意味にならない。", "敷いたり": "「〜たり」の並列形で、提案を述べる文として完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38821, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「ランチョンマットを敷く」の目的語を示す格助詞で、敷く対象を表す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、敷く対象を表す場面には使えない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す助詞で、「ランチョンマットと敷く」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、「ランチョンマットから敷く」は敷く対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「ランチョンマットを敷く」の目的語を示す格助詞で、敷く対象を表す。", "へ": "方向を示す助詞で、敷く対象を表す場面には使えない。", "と": "並列を示す助詞で、「ランチョンマットと敷く」は成り立たない。", "から": "起点を示す助詞で、「ランチョンマットから敷く」は敷く対象を示せない。"}, "error_tags": {"へ": "方向", "と": "並列", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38821, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「平らな石を敷く」の目的語を示す格助詞で、敷く対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、石が敷く動作の主体になってしまい文の意味に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す助詞で、「平らな石より敷く」は意味が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す助詞で、「平らな石の敷く」は動詞の目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「平らな石を敷く」の目的語を示す格助詞で、敷く対象を表す。", "が": "主語を示す助詞で、石が敷く動作の主体になってしまい文の意味に合わない。", "より": "比較を示す助詞で、「平らな石より敷く」は意味が成り立たない。", "の": "連体修飾を示す助詞で、「平らな石の敷く」は動詞の目的語を示せない。"}, "error_tags": {"が": "主語", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38821, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物の下に別の物を置いて、その上に重ねたり、広げたりすること。", "primary_collocate": null, "pronunciation": "しく", "ipa": "ɕikɯ", "syllable_count": 2, "sentences": [{"text": "猫がねむれるように、箱の底にタオルを敷きました。", "target_word": "敷きました", "complexity_tier": "T3", "furigana": "猫[ねこ]がねむれるように、箱[はこ]の底[そこ]にタオルを敷[し]きました。", "sentence_source": "generated"}, {"text": "皿の下にランチョンマットを敷くと、食卓がきれいに見えます。", "target_word": "敷く", "complexity_tier": "T3", "furigana": "皿[さら]の下[した]にランチョンマットを敷[し]くと、食卓[しょくたく]がきれいに見[み]えます。", "sentence_source": "generated"}, {"text": "道に砂利を敷くと、雨の日も歩きやすくなります。", "target_word": "敷く", "complexity_tier": "T3", "furigana": "道[みち]に砂利[じゃり]を敷[し]くと、雨[あめ]の日[ひ]も歩[ある]きやすくなります。", "sentence_source": "generated"}, {"text": "オーブンで焼く前に、天板にクッキングシートを敷いてください。", "target_word": "敷いて", "complexity_tier": "T3", "furigana": "オーブンで焼[や]く前[まえ]に、天板[てんばん]にクッキングシートを敷[し]いてください。", "sentence_source": "generated"}, {"text": "子どもが寝ているソファーの上に、バスタオルを敷いておいた。", "target_word": "敷いて", "complexity_tier": "T3", "furigana": "子[こ]どもが寝[ね]ているソファーの上[うえ]に、バスタオルを敷[し]いておいた。", "sentence_source": "generated"}, {"text": "犬の小屋には、わらを敷いて暖かくしてあります。", "target_word": "敷いて", "complexity_tier": "T3", "furigana": "犬[いぬ]の小屋[こや]には、わらを敷[し]いて暖[あたた]かくしてあります。", "sentence_source": "generated"}, {"text": "ご飯の下にのりを敷いて、その上に具をのせました。", "target_word": "敷いて", "complexity_tier": "T3", "furigana": "ご飯[はん]の下[した]にのりを敷[し]いて、その上[うえ]に具[ぐ]をのせました。", "sentence_source": "generated"}, {"text": "庭に平らな石を敷くと、雨の日でも靴が汚れません。", "target_word": "敷く", "complexity_tier": "T3", "furigana": "庭[にわ]に平[たい]らな石[いし]を敷[し]くと、雨[あめ]の日[ひ]でも靴[くつ]が汚[よご]れません。", "sentence_source": "generated"}, {"text": "遠足では、大きなシートを敷いて、みんなで輪になって座りました。", "target_word": "敷いて", "complexity_tier": "T3", "furigana": "遠足[えんそく]では、大[おお]きなシートを敷[し]いて、みんなで輪[わ]になって座[すわ]りました。", "sentence_source": "generated"}, {"text": "引っ越しの日は、床に新聞紙を敷いてから荷物を運びます。", "target_word": "敷いて", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの日[ひ]は、床[ゆか]に新聞紙[しんぶんし]を敷[し]いてから荷物[にもつ]を運[はこ]びます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "敷く", "label": "辞書形"}, {"form": "敷きます", "label": "丁寧形"}, {"form": "敷いて", "label": "て形"}, {"form": "敷いた", "label": "た形"}, {"form": "敷かない", "label": "ない形"}, {"form": "敷けば", "label": "仮定形"}, {"form": "敷こう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "物の下に別の物を置き、その上に重ねたり広げたりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c11be19-e1cc-49c2-a822-0ba302475d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38821, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "敷きました", "is_correct": true, "explanation": "正解。箱の底に布を下から重ねて広げるという意味で、猫のための準備の文脈に合う。"}, {"text": "叫びました", "is_correct": false, "explanation": "大声を出す動作で、タオルを箱に置く文脈には合わない。"}, {"text": "笑いました", "is_correct": false, "explanation": "表情や声の動作で、物を箱の底に置く行為とは結びつかない。"}, {"text": "掃きました", "is_correct": false, "explanation": "ほうきで払う動作で、タオルを箱の底に重ねる文脈には合わない。"}], "explanations": {"敷きました": "正解。箱の底に布を下から重ねて広げるという意味で、猫のための準備の文脈に合う。", "叫びました": "大声を出す動作で、タオルを箱に置く文脈には合わない。", "笑いました": "表情や声の動作で、物を箱の底に置く行為とは結びつかない。", "掃きました": "ほうきで払う動作で、タオルを箱の底に重ねる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "敷きました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁にポスターを敷いて、ピンでとめた。", "explanation": "ここは〈貼る〉の意味。敷くは物の下に別の物を重ねることで、表面に張り付ける意味では使わない。"}, {"text": "ベランダに洗濯物を敷いて、乾かした。", "explanation": "ここは〈干す〉の意味。敷くは物の下に別の物を置く意味で、洗濯物を広げて掛ける意味では使わない。"}, {"text": "コップに水を敷いて、ゆっくり飲んだ。", "explanation": "ここは〈注ぐ〉の意味。敷くは物を重ねる動作で、液体を容器に入れる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38821, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "敷いて", "is_correct": true, "explanation": "正解。ご飯の下にのりを重ねて広げるという意味で、「その上に具をのせました」と続く文に合う。"}, {"text": "噛んで", "is_correct": false, "explanation": "口で噛む動作で、のりを下に重ねる文脈には合わない。"}, {"text": "歌って", "is_correct": false, "explanation": "声を出す動作で、のりを置く行為とは結びつかない。"}, {"text": "飲んで", "is_correct": false, "explanation": "口に入れて飲み込む動作で、のりを下に重ねる文脈には合わない。"}], "explanations": {"敷いて": "正解。ご飯の下にのりを重ねて広げるという意味で、「その上に具をのせました」と続く文に合う。", "噛んで": "口で噛む動作で、のりを下に重ねる文脈には合わない。", "歌って": "声を出す動作で、のりを置く行為とは結びつかない。", "飲んで": "口に入れて飲み込む動作で、のりを下に重ねる文脈には合わない。"}, "sentence_index": 6, "correct_answer": "敷いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壁にペンキを敷いてから、乾くのを待った。", "explanation": "ここは〈塗る〉の意味。敷くは物を下に重ねることで、表面に液体を塗る意味では使わない。"}, {"text": "窓ガラスを布で敷いてから、きれいにした。", "explanation": "ここは〈拭く〉の意味。敷くは物を下に広げる動作で、汚れを取る意味では使わない。"}, {"text": "町に新しい制度を敷いて、住民を管理した。", "explanation": "ここは〈施行する〉の意味。敷くは物の下に別の物を置く意味で、制度を行き渡らせる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38821, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "棚の下に新聞紙を敷きた。", "corrected_sentence": "棚の下に新聞紙を敷いた。", "error_description": "「敷く」の過去形は「敷いた」（五段活用）。「敷きた」は活用を誤った形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "敷く", "is_correct": true, "explanation": "正解。辞書形で「敷くと、食卓がきれいに見えます」の条件節を作る形。"}, {"text": "敷いて", "is_correct": false, "explanation": "て形で、「〜と」に続けると文法的に成り立たず「敷いてと」は不自然。"}, {"text": "敷け", "is_correct": false, "explanation": "命令形で、「敷けと」は文として不自然で条件節にならない。"}, {"text": "敷こう", "is_correct": false, "explanation": "意志形で、「敷こうと」は意図の表現になり、一般的な結果を述べる文に合わない。"}], "correct_form": "敷く", "base_form": "敷く", "form_label": "辞書形", "sentence_index": 1, "explanations": {"敷く": "正解。辞書形で「敷くと、食卓がきれいに見えます」の条件節を作る形。", "敷いて": "て形で、「〜と」に続けると文法的に成り立たず「敷いてと」は不自然。", "敷け": "命令形で、「敷けと」は文として不自然で条件節にならない。", "敷こう": "意志形で、「敷こうと」は意図の表現になり、一般的な結果を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38821, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "床には白い布が敷いられている。", "corrected_sentence": "床には白い布が敷かれている。", "error_description": "「敷く」の受身は「敷かれる」（五段活用）。「敷いられる」は一段動詞の形と混同した誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "敷く", "is_correct": true, "explanation": "正解。辞書形で「庭に平らな石を敷くと、靴が汚れません」の条件節を作る形。"}, {"text": "敷かれ", "is_correct": false, "explanation": "受身の連用形で、「敷かれ」で文が切れて条件節にならない。"}, {"text": "敷かせ", "is_correct": false, "explanation": "使役の連用形で、文の動作主が変わり、文の意味に合わない。"}, {"text": "敷き", "is_correct": false, "explanation": "連用形で、「〜と」の条件節を作れず、文の構造に合わない。"}], "correct_form": "敷く", "base_form": "敷く", "form_label": "辞書形", "sentence_index": 7, "explanations": {"敷く": "正解。辞書形で「庭に平らな石を敷くと、靴が汚れません」の条件節を作る形。", "敷かれ": "受身の連用形で、「敷かれ」で文が切れて条件節にならない。", "敷かせ": "使役の連用形で、文の動作主が変わり、文の意味に合わない。", "敷き": "連用形で、「〜と」の条件節を作れず、文の構造に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
