INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38822, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "abstract", "definition": "毎日", "primary_collocate": null, "pronunciation": "ひび", "ipa": "çibi", "syllable_count": 2, "sentences": [{"text": "彼は日々、ランニングを欠かさない。", "target_word": "日々", "complexity_tier": "T3", "furigana": "彼[かれ]は日々[ひび]、ランニングを欠[か]かさない。", "sentence_source": "generated"}, {"text": "日々練習を重ねたので、発表会は成功した。", "target_word": "日々", "complexity_tier": "T3", "furigana": "日々[ひび]練習[れんしゅう]を重[かさ]ねたので、発表会[はっぴょうかい]は成功[せいこう]した。", "sentence_source": "generated"}, {"text": "この店では、日々新しいパンを焼いている。", "target_word": "日々", "complexity_tier": "T3", "furigana": "この店[みせ]では、日々[ひび]新[あたら]しいパンを焼[や]いている。", "sentence_source": "generated"}, {"text": "医師たちは日々患者のために働いている。", "target_word": "日々", "complexity_tier": "T3", "furigana": "医師[いし]たちは日々[ひび]患者[かんじゃ]のために働[はたら]いている。", "sentence_source": "generated"}, {"text": "日々勉強しているのに、なかなか上手にならない。", "target_word": "日々", "complexity_tier": "T3", "furigana": "日々[ひび]勉強[べんきょう]しているのに、なかなか上手[じょうず]にならない。", "sentence_source": "generated"}, {"text": "物価が日々上がっていて、買い物が大変だ。", "target_word": "日々", "complexity_tier": "T3", "furigana": "物価[ぶっか]が日々[ひび]上[あ]がっていて、買[か]い物[もの]が大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "母は日々天気を確かめてから、洗濯の予定を決める。", "target_word": "日々", "complexity_tier": "T3", "furigana": "母[はは]は日々[ひび]天気[てんき]を確[たし]かめてから、洗濯[せんたく]の予定[よてい]を決[き]める。", "sentence_source": "generated"}, {"text": "彼女は日々感謝の気持ちを忘れないようにしている。", "target_word": "日々", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は日々[ひび]感謝[かんしゃ]の気持[きも]ちを忘[わす]れないようにしている。", "sentence_source": "generated"}, {"text": "日々読書を続けたおかげで、語彙が増えた。", "target_word": "日々", "complexity_tier": "T3", "furigana": "日々[ひび]読書[どくしょ]を続[つづ]けたおかげで、語彙[ごい]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "町の様子は日々変わり、去年とは別の場所のようだ。", "target_word": "日々", "complexity_tier": "T3", "furigana": "町[まち]の様子[ようす]は日々[ひび]変[か]わり、去年[きょねん]とは別[べつ]の場所[ばしょ]のようだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "日々", "label": "基本形"}, {"form": "日々の", "label": "連体形(の)"}], "register": "neutral", "sense_fingerprint": "毎日そうすること、日ごとにそうなることを表す副詞的用法(日々練習する・日々変わる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f522c88-2b37-4463-ae1e-fd98b63d1180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38822, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日々", "is_correct": true, "explanation": "「日々」は「毎日」の意味で、毎日ランニングを続ける様子に合う。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "「ぐっすり」は眠り込む様子を表すので、ランニングの文には合わない。"}, {"text": "ぐったり", "is_correct": false, "explanation": "「ぐったり」は疲れて力が抜けた様子を表すので、ここでは意味が通らない。"}, {"text": "とぼとぼ", "is_correct": false, "explanation": "「とぼとぼ」は元気なく歩く様子を表すので、ランニングの習慣の文には合わない。"}], "explanations": {"日々": "「日々」は「毎日」の意味で、毎日ランニングを続ける様子に合う。", "ぐっすり": "「ぐっすり」は眠り込む様子を表すので、ランニングの文には合わない。", "ぐったり": "「ぐったり」は疲れて力が抜けた様子を表すので、ここでは意味が通らない。", "とぼとぼ": "「とぼとぼ」は元気なく歩く様子を表すので、ランニングの習慣の文には合わない。"}, "sentence_index": 0, "correct_answer": "日々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この大会は三年に一度、日々開かれる。", "explanation": "「日々」は〈毎日〉の意味。大会は三年に一度なので、毎日開かれるという文は合わない。"}, {"text": "友人は、結婚式を日々挙げた。", "explanation": "「日々」は〈毎日〉の意味。結婚式を毎日挙げるのは不自然なので、この文は合わない。"}, {"text": "彼は、一度きりの海外旅行に日々出かけた。", "explanation": "「日々」は〈毎日〉の意味。一度きりの旅行を毎日出かけることはできないので、この文は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38822, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日々", "is_correct": true, "explanation": "「日々」は毎日天気を確かめる習慣を表し、ここに合う。"}, {"text": "一向に", "is_correct": false, "explanation": "「一向に」は否定の文で使うので、肯定の「確かめてから」には続かない。"}, {"text": "滅多に", "is_correct": false, "explanation": "「滅多に」は否定と組む副詞なので、肯定の文では使えない。"}, {"text": "一度も", "is_correct": false, "explanation": "「一度も」は否定の表現とともに使うので、「確かめてから」とは続かない。"}], "explanations": {"日々": "「日々」は毎日天気を確かめる習慣を表し、ここに合う。", "一向に": "「一向に」は否定の文で使うので、肯定の「確かめてから」には続かない。", "滅多に": "「滅多に」は否定と組む副詞なので、肯定の文では使えない。", "一度も": "「一度も」は否定の表現とともに使うので、「確かめてから」とは続かない。"}, "sentence_index": 6, "correct_answer": "日々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この家は十年に一度、日々塗り直される。", "explanation": "「日々」は〈毎日〉の意味。塗り直しは十年に一度なので、毎日行う文と矛盾する。"}, {"text": "彼は一度きりの留学を、日々続けた。", "explanation": "「日々」は〈毎日〉の意味。留学は一度きりなので、毎日続ける文とは合わない。"}, {"text": "この店は年に一度の大売り出しを、日々行っている。", "explanation": "「日々」は〈毎日〉の意味。大売り出しは年一回なので、毎日行う文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38822, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は日々なギターを練習している。", "corrected_sentence": "兄は日々、ギターを練習している。", "error_description": "「日々」に「な」は付かない。副詞として「日々、」と置き、「練習している」にかける。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38822, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は日々で、ピアノの練習を続けている。", "corrected_sentence": "妹は日々、ピアノの練習を続けている。", "error_description": "「日々」に「で」は付かない。副詞として「日々、」と置き、「続けている」にかける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38826, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「箱に」は投入先を示し、「箱に投入する」で自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「箱を投入」では箱が入れられるものになり、投入先の意味が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「箱で投入する」は手段や場所の意味になり、投入先を示す文として合わない。"}, {"text": "や", "is_correct": false, "explanation": "並列の「や」は動詞に直接続かず、「箱や投入する」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「箱に」は投入先を示し、「箱に投入する」で自然に続く。", "を": "「箱を投入」では箱が入れられるものになり、投入先の意味が成り立たない。", "で": "「箱で投入する」は手段や場所の意味になり、投入先を示す文として合わない。", "や": "並列の「や」は動詞に直接続かず、「箱や投入する」は成り立たない。"}, "error_tags": {"を": "対象", "で": "手段・場所", "や": "列挙"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38826, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「肥料を投入した」で、入れられる物を示す。"}, {"text": "に", "is_correct": false, "explanation": "「肥料に投入」では肥料が入れる先になり、文の意味が通らない。"}, {"text": "や", "is_correct": false, "explanation": "並列の「や」は動詞に直接続かず、「肥料や投入した」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比べる基準を示すので、ここで投入の対象を示す用法には合わない。"}], "correct_answer": "を", "explanations": {"を": "「肥料を投入した」で、入れられる物を示す。", "に": "「肥料に投入」では肥料が入れる先になり、文の意味が通らない。", "や": "並列の「や」は動詞に直接続かず、「肥料や投入した」は成り立たない。", "より": "比べる基準を示すので、ここで投入の対象を示す用法には合わない。"}, "error_tags": {"に": "先・対象の取り違え", "より": "比較", "や": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38826, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "なかに いれること。", "primary_collocate": null, "pronunciation": "とうにゅう", "ipa": "toːɲɯː", "syllable_count": 4, "sentences": [{"text": "自動販売機にお金を投入すると、ボタンのランプがつく。", "target_word": "投入", "complexity_tier": "T3", "furigana": "自動販売機[じどうはんばいき]にお金[かね]を投入[とうにゅう]すると、ボタンのランプがつく。", "sentence_source": "generated"}, {"text": "ごみを分別して、それぞれの箱に投入する決まりだ。", "target_word": "投入", "complexity_tier": "T3", "furigana": "ごみを分別[ぶんべつ]して、それぞれの箱[はこ]に投入[とうにゅう]する決[き]まりだ。", "sentence_source": "generated"}, {"text": "粉と水をミキサーに投入して、スイッチを入れた。", "target_word": "投入", "complexity_tier": "T3", "furigana": "粉[こな]と水[みず]をミキサーに投入[とうにゅう]して、スイッチを入[い]れた。", "sentence_source": "generated"}, {"text": "コインを投入してもジュースが出ないので、お店の人を呼んだ。", "target_word": "投入", "complexity_tier": "T3", "furigana": "コインを投入[とうにゅう]してもジュースが出[で]ないので、お店[みせ]の人[ひと]を呼[よ]んだ。", "sentence_source": "generated"}, {"text": "薪をストーブに投入すると、部屋がだんだん暖かくなった。", "target_word": "投入", "complexity_tier": "T3", "furigana": "薪[まき]をストーブに投入[とうにゅう]すると、部屋[へや]がだんだん暖[あたた]かくなった。", "sentence_source": "generated"}, {"text": "湯が沸いたら、麺を鍋に投入して三分待つ。", "target_word": "投入", "complexity_tier": "T3", "furigana": "湯[ゆ]が沸[わ]いたら、麺[めん]を鍋[なべ]に投入[とうにゅう]して三分[さんぷん]待[ま]つ。", "sentence_source": "generated"}, {"text": "ごみ処理場では、集めたごみを大きな炉に投入している。", "target_word": "投入", "complexity_tier": "T3", "furigana": "ごみ処理場[しょりじょう]では、集[あつ]めたごみを大[おお]きな炉[ろ]に投入[とうにゅう]している。", "sentence_source": "generated"}, {"text": "土に肥料を投入したので、野菜が大きく育った。", "target_word": "投入", "complexity_tier": "T3", "furigana": "土[つち]に肥料[ひりょう]を投入[とうにゅう]したので、野菜[やさい]が大[おお]きく育[そだ]った。", "sentence_source": "generated"}, {"text": "実験では、容器に氷を投入した直後に水温を測る。", "target_word": "投入", "complexity_tier": "T3", "furigana": "実験[じっけん]では、容器[ようき]に氷[こおり]を投入[とうにゅう]した直後[ちょくご]に水温[すいおん]を測[はか]る。", "sentence_source": "generated"}, {"text": "給食の残りを大きな容器に投入する当番を、今日は私がやった。", "target_word": "投入", "complexity_tier": "T3", "furigana": "給食[きゅうしょく]の残[のこ]りを大[おお]きな容器[ようき]に投入[とうにゅう]する当番[とうばん]を、今日[きょう]は私[わたし]がやった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "投入", "label": "名詞形"}, {"form": "投入する", "label": "動詞形"}, {"form": "投入した", "label": "過去形"}, {"form": "投入される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "物やお金を機械・容器・炉などの中に入れる動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0a981c-3ffd-4367-ac70-36156b437484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38826, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投入", "is_correct": true, "explanation": "お金を機械に入れる動作を表し、「お金を投入すると」の空欄に合う。"}, {"text": "返却", "is_correct": false, "explanation": "借りた物や預かった物を返す意味で、機械にお金を入れる文脈とは合わない。"}, {"text": "回収", "is_correct": false, "explanation": "機械や箱からものを集め取る意味で、お金を入れるとランプがつくという文と合わない。"}, {"text": "放出", "is_correct": false, "explanation": "勢いよく外へ出す意味で、お金を機械に入れる場面には合わない。"}], "explanations": {"投入": "お金を機械に入れる動作を表し、「お金を投入すると」の空欄に合う。", "返却": "借りた物や預かった物を返す意味で、機械にお金を入れる文脈とは合わない。", "回収": "機械や箱からものを集め取る意味で、お金を入れるとランプがつくという文と合わない。", "放出": "勢いよく外へ出す意味で、お金を機械に入れる場面には合わない。"}, "sentence_index": 0, "correct_answer": "投入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雑誌に写真を投入した。", "explanation": "ここは〈投稿〉の意味。作品を雑誌に送って載せてもらうのは〈投稿〉で、〈投入〉は物を容器や機械に入れる語なので合わない。"}, {"text": "原稿の二行目に、大事な一文を投入した。", "explanation": "ここは〈挿入〉の意味。文章の途中に一文を加えるのは〈挿入〉で、〈投入〉は容器や機械に物を入れる場合に使うので合わない。"}, {"text": "傷口に絆創膏を投入した。", "explanation": "ここは〈貼る〉の意味。絆創膏を傷口に当てることは〈貼る〉で、〈投入〉は物を中に入れる語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38826, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投入", "is_correct": true, "explanation": "大量の材料を炉の中に入れる動作を表し、「炉に投入している」に合う。"}, {"text": "分別", "is_correct": false, "explanation": "種類ごとに分ける意味で、炉に入れる動作とは合わない。"}, {"text": "放棄", "is_correct": false, "explanation": "権利や責任を捨てる意味で、ごみを炉に入れる文とは合わない。"}, {"text": "保管", "is_correct": false, "explanation": "大切に預かって置いておく意味で、炉に入れて処理する文脈と合わない。"}], "explanations": {"投入": "大量の材料を炉の中に入れる動作を表し、「炉に投入している」に合う。", "分別": "種類ごとに分ける意味で、炉に入れる動作とは合わない。", "放棄": "権利や責任を捨てる意味で、ごみを炉に入れる文とは合わない。", "保管": "大切に預かって置いておく意味で、炉に入れて処理する文脈と合わない。"}, "sentence_index": 6, "correct_answer": "投入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コードをコンセントに投入して、電源を入れた。", "explanation": "ここは〈差し込む〉の意味。細い差し口へ差し込むことには〈差し込む〉を使い、〈投入〉は合わない。"}, {"text": "花瓶に花を投入して、窓辺に置いた。", "explanation": "ここは〈挿す〉の意味。花を花瓶に差して飾ることは〈挿す〉で、〈投入〉は容器や機械に物を入れる語なので合わない。"}, {"text": "来年、子どもを幼稚園に投入する。", "explanation": "ここは〈入園させる〉の意味。人を施設に通わせるのは〈入園させる〉で、〈投入〉は物を入れる語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38826, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洗濯機に洗剤を投入でから、スイッチを入れる。", "corrected_sentence": "洗濯機に洗剤を投入してから、スイッチを入れる。", "error_description": "「投入」に続く接続は「して」が正しく、「で」は誤り。「投入してから」の形にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38826, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "券売機に硬貨に投入して、切符を買う。", "corrected_sentence": "券売機に硬貨を投入して、切符を買う。", "error_description": "「投入」の対象は「を」で示す。「硬貨に投入」の「に」は誤りで、「硬貨を投入」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38827, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "『投入する』の後に続けて条件を示す。機械に入れると部品ができる、という意味になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、動詞の後に続けると文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、動詞の後に続けると条件の意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、動詞の後に続けると文が成り立たない。"}], "correct_answer": "と", "explanations": {"と": "『投入する』の後に続けて条件を示す。機械に入れると部品ができる、という意味になる。", "を": "目的語を示すが、動詞の後に続けると文が成り立たない。", "で": "手段や場所を示すが、動詞の後に続けると条件の意味にならない。", "へ": "方向を示すが、動詞の後に続けると文が成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38827, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『投入する』の目的語『野菜』を示す。投入されるものを表す。"}, {"text": "に", "is_correct": false, "explanation": "場所を示すが、『鍋に』が既にあるので重なって不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示し、投入されるものを表すことはできない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、『野菜が投入する』では野菜が動作主になってしまい不自然。"}], "correct_answer": "を", "explanations": {"を": "『投入する』の目的語『野菜』を示す。投入されるものを表す。", "に": "場所を示すが、『鍋に』が既にあるので重なって不自然。", "より": "比較を示し、投入されるものを表すことはできない。", "が": "主語を示すが、『野菜が投入する』では野菜が動作主になってしまい不自然。"}, "error_tags": {"に": "場所", "より": "比較", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38827, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物を中に入れること。また、金銭や労力などをある目的のために注ぎ込むこと。", "primary_collocate": null, "pronunciation": "とうにゅう", "ipa": "toːɲɯː", "syllable_count": 4, "sentences": [{"text": "高温のオーブンへ投入された瞬間、生地は熱エネルギーによって急激に膨張します。", "target_word": "投入", "complexity_tier": "T3", "furigana": "高温[こうおん]のオーブンへ投入[とうにゅう]された瞬間[しゅんかん]、生地[きじ]は熱[ねつ]エネルギーによって急激[きゅうげき]に膨張[ぼうちょう]します。", "sentence_source": "mined"}, {"text": "機械に材料を投入すると、数分で部品が自動的に作られます。", "target_word": "投入", "complexity_tier": "T3", "furigana": "機械[きかい]に材料[ざいりょう]を投入[とうにゅう]すると、数分[すうふん]で部品[ぶひん]が自動的[じどうてき]に作[つく]られます。", "sentence_source": "generated"}, {"text": "会社は新しい商品の開発に、多くの資金を投入することにした。", "target_word": "投入", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新[あたら]しい商品[しょうひん]の開発[かいはつ]に、多[おお]くの資金[しきん]を投入[とうにゅう]することにした。", "sentence_source": "generated"}, {"text": "工事を急ぐために、百人もの作業員が現場に投入された。", "target_word": "投入", "complexity_tier": "T3", "furigana": "工事[こうじ]を急[いそ]ぐために、百人[ひゃくにん]もの作業員[さぎょういん]が現場[げんば]に投入[とうにゅう]された。", "sentence_source": "generated"}, {"text": "洗濯機に洗剤を投入してから、スタートのボタンを押した。", "target_word": "投入", "complexity_tier": "T3", "furigana": "洗濯機[せんたくき]に洗剤[せんざい]を投入[とうにゅう]してから、スタートのボタンを押[お]した。", "sentence_source": "generated"}, {"text": "試合の終わりに、監督は若い選手を投入して流れを変えようとした。", "target_word": "投入", "complexity_tier": "T3", "furigana": "試合[しあい]の終[お]わりに、監督[かんとく]は若[わか]い選手[せんしゅ]を投入[とうにゅう]して流[なが]れを変[か]えようとした。", "sentence_source": "generated"}, {"text": "この計画には時間も労力も大量に投入したのに、結果は出なかった。", "target_word": "投入", "complexity_tier": "T3", "furigana": "この計画[けいかく]には時間[じかん]も労力[ろうりょく]も大量[たいりょう]に投入[とうにゅう]したのに、結果[けっか]は出[で]なかった。", "sentence_source": "generated"}, {"text": "鍋に野菜を投入する順番を間違えると、味がかなり変わってしまう。", "target_word": "投入", "complexity_tier": "T3", "furigana": "鍋[なべ]に野菜[やさい]を投入[とうにゅう]する順番[じゅんばん]を間違[まちが]えると、味[あじ]がかなり変[か]わってしまう。", "sentence_source": "generated"}, {"text": "政府は災害の被害を減らすため、新たな予算を投入すると発表した。", "target_word": "投入", "complexity_tier": "T3", "furigana": "政府[せいふ]は災害[さいがい]の被害[ひがい]を減[へ]らすため、新[あら]たな予算[よさん]を投入[とうにゅう]すると発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "川の水をきれいにする装置に薬品を投入して、水質を調べた。", "target_word": "投入", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]をきれいにする装置[そうち]に薬品[やくひん]を投入[とうにゅう]して、水質[すいしつ]を調[しら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "投入", "label": "名詞形"}, {"form": "投入する", "label": "動詞形"}, {"form": "投入した", "label": "過去形"}, {"form": "投入される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "物を容器や機械の中に入れる意味と、資金・人員・労力を注ぎ込む意味を持つする動詞の名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0a981c-3ffd-4367-ac70-36156b437484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38827, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投入", "is_correct": true, "explanation": "オーブンの中に生地を入れること。「投入された瞬間」の文脈に合う。"}, {"text": "解凍", "is_correct": false, "explanation": "凍ったものを溶かす意味で、オーブンへ入れる動作とは合わない。"}, {"text": "冷却", "is_correct": false, "explanation": "冷やす意味で、高温のオーブンへ入れる文脈とは逆になる。"}, {"text": "洗浄", "is_correct": false, "explanation": "汚れを洗い落とす意味で、オーブンへ入れることにはならない。"}], "explanations": {"投入": "オーブンの中に生地を入れること。「投入された瞬間」の文脈に合う。", "解凍": "凍ったものを溶かす意味で、オーブンへ入れる動作とは合わない。", "冷却": "冷やす意味で、高温のオーブンへ入れる文脈とは逆になる。", "洗浄": "汚れを洗い落とす意味で、オーブンへ入れることにはならない。"}, "sentence_index": 0, "correct_answer": "投入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は大学に投入して、三年間学んだ。", "explanation": "ここは〈入学〉の意味。投入は物・資金・人員を注ぎ込む意味で、人が学校に入る文脈では使えない。"}, {"text": "父は新しい健康保険に投入した。", "explanation": "ここは〈加入〉の意味。投入は物や資金を注ぎ込むことで、保険に入る意味にはならない。"}, {"text": "箱から投入した。", "explanation": "ここは〈取り出す〉の意味。投入は中へ入れることで、箱から出す動作には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38827, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投入", "is_correct": true, "explanation": "時間や労力を注ぎ込む意味で、「大量に」と結果の文脈に合う。"}, {"text": "撤回", "is_correct": false, "explanation": "取り消す意味で、注ぎ込んだという文脈と合わない。"}, {"text": "撤去", "is_correct": false, "explanation": "建物や設備を取り除く意味で、時間や労力には使えず文と合わない。"}, {"text": "停止", "is_correct": false, "explanation": "途中でやめる意味で、「大量に」と合わない。"}], "explanations": {"投入": "時間や労力を注ぎ込む意味で、「大量に」と結果の文脈に合う。", "撤回": "取り消す意味で、注ぎ込んだという文脈と合わない。", "撤去": "建物や設備を取り除く意味で、時間や労力には使えず文と合わない。", "停止": "途中でやめる意味で、「大量に」と合わない。"}, "sentence_index": 6, "correct_answer": "投入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スクリーンに映像を投入した。", "explanation": "ここは〈映す〉の意味。投入は中へ入れる意味で、映像を映す場面には使えない。"}, {"text": "取引先に部品を投入する。", "explanation": "ここは〈納入〉の意味。部品を取引先へ届けるのは納入で、投入は中へ入れる意味なので、届ける文脈には合わない。"}, {"text": "彼女は、花の写真を投入した。", "explanation": "ここは〈投稿〉の意味。写真を応募や掲載のために送ることは〈投稿〉で、〈投入〉は物を中に入れる語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38827, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洗剤を投入しなくと、汚れが落ちない。", "corrected_sentence": "洗剤を投入しないと、汚れが落ちない。", "error_description": "『投入しない』の条件形は『しないと』。『しなくと』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38827, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "予算を投入を後、効果を調べる。", "corrected_sentence": "予算を投入した後、効果を調べる。", "error_description": "『投入した後』の過去形『した』が必要。『を』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
