INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38828, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "合うこと。ぴったりであること。", "primary_collocate": null, "pronunciation": "てきする", "ipa": "tekisɯɾɯ", "syllable_count": 4, "sentences": [{"text": "この鍵は、ドアの鍵穴に適している。", "target_word": "適している", "complexity_tier": "T3", "furigana": "この鍵[かぎ]は、ドアの鍵穴[かぎあな]に適[てき]している。", "sentence_source": "generated"}, {"text": "寒い土地に適した服を選んで旅行に行った。", "target_word": "適した", "complexity_tier": "T3", "furigana": "寒[さむ]い土地[とち]に適[てき]した服[ふく]を選[えら]んで旅行[りょこう]に行[い]った。", "sentence_source": "generated"}, {"text": "この植物は、日当たりのよい場所に適している。", "target_word": "適して", "complexity_tier": "T3", "furigana": "この植物[しょくぶつ]は、日当[ひあ]たりのよい場所[ばしょ]に適[てき]している。", "sentence_source": "generated"}, {"text": "彼は体が小さいので、バスケットボールには適さない。", "target_word": "適さない", "complexity_tier": "T3", "furigana": "彼[かれ]は体[からだ]が小[ちい]さいので、バスケットボールには適[てき]さない。", "sentence_source": "generated"}, {"text": "赤ちゃんの肌に適したせっけんを探している。", "target_word": "適した", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの肌[はだ]に適[てき]したせっけんを探[さが]している。", "sentence_source": "generated"}, {"text": "夏の暑さに適した、すずしい着物を買った。", "target_word": "適した", "complexity_tier": "T3", "furigana": "夏[なつ]の暑[あつ]さに適[てき]した、すずしい着物[きもの]を買[か]った。", "sentence_source": "generated"}, {"text": "彼の明るい性格は、接客の仕事に適している。", "target_word": "適して", "complexity_tier": "T3", "furigana": "彼[かれ]の明[あか]るい性格[せいかく]は、接客[せっきゃく]の仕事[しごと]に適[てき]している。", "sentence_source": "generated"}, {"text": "この靴は足の形に適していて、長く歩いても疲れない。", "target_word": "適して", "complexity_tier": "T3", "furigana": "この靴[くつ]は足[あし]の形[かたち]に適[てき]していて、長[なが]く歩[ある]いても疲[つか]れない。", "sentence_source": "generated"}, {"text": "山の気候に適した作物を、父は毎年育てている。", "target_word": "適した", "complexity_tier": "T3", "furigana": "山[やま]の気候[きこう]に適[てき]した作物[さくもつ]を、父[ちち]は毎年[まいとし]育[そだ]てている。", "sentence_source": "generated"}, {"text": "私は朝型なので、夜の仕事には適さない。", "target_word": "適さない", "complexity_tier": "T3", "furigana": "私[わたし]は朝型[あさがた]なので、夜[よる]の仕事[しごと]には適[てき]さない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "適する", "label": "辞書形"}, {"form": "適します", "label": "丁寧形"}, {"form": "適さない", "label": "否定形"}, {"form": "適して", "label": "て形"}, {"form": "適した", "label": "た形"}, {"form": "適すれば", "label": "仮定形"}], "register": "標準語（常体）", "sense_fingerprint": "人や物の性質・体質・気候などにぴったり合う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0568bb4e-9a35-4f81-9107-29aa110f32d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38828, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "適している", "is_correct": true, "explanation": "鍵が鍵穴にぴったり合うという意味で、ここでは自然に入る。"}, {"text": "逆らっている", "is_correct": false, "explanation": "逆らうは反対する意味で、鍵穴に合う意味にはならない。"}, {"text": "反映している", "is_correct": false, "explanation": "反映は影響が表れる意味で、鍵穴の文脈に合わない。"}, {"text": "驚いている", "is_correct": false, "explanation": "驚くは感情を表す語で、鍵穴との関係を述べる文には入らない。"}], "explanations": {"適している": "鍵が鍵穴にぴったり合うという意味で、ここでは自然に入る。", "逆らっている": "逆らうは反対する意味で、鍵穴に合う意味にはならない。", "反映している": "反映は影響が表れる意味で、鍵穴の文脈に合わない。", "驚いている": "驚くは感情を表す語で、鍵穴との関係を述べる文には入らない。"}, "sentence_index": 0, "correct_answer": "適している"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は箱のふたを適して、中身を取り出した。", "explanation": "ここは〈開ける〉の意味。適するは条件に合う意味で、ふたを開ける動作には使わない。"}, {"text": "彼女はワンピースを適して出かけた。", "explanation": "ここは〈着る〉の意味。適するは条件に合う意味で、服を身につける動作には使わない。"}, {"text": "企画が会議で適して、そのまま実行された。", "explanation": "ここは〈通る〉（承認される）の意味。適するは条件に合う意味で、承認の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38828, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "適して", "is_correct": true, "explanation": "接客の仕事に合うという意味の「て形」で、文脈に自然に入る。"}, {"text": "反論して", "is_correct": false, "explanation": "反論は意見を述べて争う意味で、仕事への適合を表せない。"}, {"text": "嘆いて", "is_correct": false, "explanation": "嘆くは悲しむ意味で、仕事が合うという文脈に結びつかない。"}, {"text": "笑って", "is_correct": false, "explanation": "笑うは感情の動作で、仕事への適合を表す文にならない。"}], "explanations": {"適して": "接客の仕事に合うという意味の「て形」で、文脈に自然に入る。", "反論して": "反論は意見を述べて争う意味で、仕事への適合を表せない。", "嘆いて": "嘆くは悲しむ意味で、仕事が合うという文脈に結びつかない。", "笑って": "笑うは感情の動作で、仕事への適合を表す文にならない。"}, "sentence_index": 6, "correct_answer": "適して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は選挙で多くの票を集めて、適していた。", "explanation": "ここは〈当選〉（選ばれる）の意味。適するは条件に合う意味で、選挙で選ばれる意味では使わない。"}, {"text": "彼は試合の最後まで粘って、適していた。", "explanation": "ここは〈勝つ〉の意味。適するは条件に合う意味で、試合の勝敗には使わない。"}, {"text": "彼は新しい計画に最後まで反対し、適していた。", "explanation": "ここは〈反対する〉の意味。適するは条件に合う意味で、反対の立場は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38828, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このクリームは、乾いた肌で適している。", "corrected_sentence": "このクリームは、乾いた肌に適している。", "error_description": "「適する」の対象は「に」で示す。「で」では場所や手段の意味になり、誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "適した", "is_correct": true, "explanation": "た形。名詞「服」を修飾し、寒い土地に合う服を表す。"}, {"text": "適します", "is_correct": false, "explanation": "丁寧形。文末で使う形で、名詞を修飾する位置には入らない。"}, {"text": "適すれば", "is_correct": false, "explanation": "仮定形。条件を述べる形で、名詞を修飾する位置には入らない。"}, {"text": "適して", "is_correct": false, "explanation": "て形。名詞を修飾できず、「服」の前に置くと文が成り立たない。"}], "correct_form": "適した", "base_form": "適する", "form_label": "た形", "sentence_index": 1, "explanations": {"適した": "た形。名詞「服」を修飾し、寒い土地に合う服を表す。", "適します": "丁寧形。文末で使う形で、名詞を修飾する位置には入らない。", "適すれば": "仮定形。条件を述べる形で、名詞を修飾する位置には入らない。", "適して": "て形。名詞を修飾できず、「服」の前に置くと文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38828, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この鍵は、ドアの鍵穴に適すていて、よく回る。", "corrected_sentence": "この鍵は、ドアの鍵穴に適していて、よく回る。", "error_description": "「適する」の活用を誤っている。「す」を「し」にした「適していて」が正しい。「適すて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "適して", "is_correct": true, "explanation": "て形。「適していて」の一部で、後ろに続く文をつなぐ。"}, {"text": "適さない", "is_correct": false, "explanation": "否定形。合わないという逆の意味になり、疲れないという文脈に合わない。"}, {"text": "適した", "is_correct": false, "explanation": "た形。名詞を修飾するか過去を表す形で、ここでは続けて述べる形が必要。"}, {"text": "適さなかった", "is_correct": false, "explanation": "否定過去。過去に合わなかったという意味で、今の状態を述べる文に合わない。"}], "correct_form": "適して", "base_form": "適する", "form_label": "て形", "sentence_index": 7, "explanations": {"適して": "て形。「適していて」の一部で、後ろに続く文をつなぐ。", "適さない": "否定形。合わないという逆の意味になり、疲れないという文脈に合わない。", "適した": "た形。名詞を修飾するか過去を表す形で、ここでは続けて述べる形が必要。", "適さなかった": "否定過去。過去に合わなかったという意味で、今の状態を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
