INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38829, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "条件や目的に合っていること。ふさわしい。", "primary_collocate": null, "pronunciation": "てきする", "ipa": "tekisɯɾɯ", "syllable_count": 4, "sentences": [{"text": "この道具は、細かい作業に適している。", "target_word": "適して", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は、細[こま]かい作業[さぎょう]に適[てき]している。", "sentence_source": "generated"}, {"text": "会議の場に適した服装で行くべきだ。", "target_word": "適した", "complexity_tier": "T3", "furigana": "会議[かいぎ]の場[ば]に適[てき]した服装[ふくそう]で行[い]くべきだ。", "sentence_source": "generated"}, {"text": "この池は水がきれいで、泳ぐのに適している。", "target_word": "適して", "complexity_tier": "T3", "furigana": "この池[いけ]は水[みず]がきれいで、泳[およ]ぐのに適[てき]している。", "sentence_source": "generated"}, {"text": "子どもが読むのに適した本を図書館で借りた。", "target_word": "適した", "complexity_tier": "T3", "furigana": "子[こ]どもが読[よ]むのに適[てき]した本[ほん]を図書館[としょかん]で借[か]りた。", "sentence_source": "generated"}, {"text": "運動会を開くには、広い校庭が適している。", "target_word": "適して", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]を開[ひら]くには、広[ひろ]い校庭[こうてい]が適[てき]している。", "sentence_source": "generated"}, {"text": "このお米はカレーより、おすしに適している。", "target_word": "適して", "complexity_tier": "T3", "furigana": "このお米[こめ]はカレーより、おすしに適[てき]している。", "sentence_source": "generated"}, {"text": "初心者に適した山を、先生が教えてくれた。", "target_word": "適した", "complexity_tier": "T3", "furigana": "初心者[しょしんしゃ]に適[てき]した山[やま]を、先生[せんせい]が教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "結婚式のスピーチに適した言葉を、一晩考えた。", "target_word": "適した", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]のスピーチに適[てき]した言葉[ことば]を、一晩[ひとばん]考[かんが]えた。", "sentence_source": "generated"}, {"text": "室内で育てるのに適した花を、店員に聞いた。", "target_word": "適した", "complexity_tier": "T3", "furigana": "室内[しつない]で育[そだ]てるのに適[てき]した花[はな]を、店員[てんいん]に聞[き]いた。", "sentence_source": "generated"}, {"text": "大きな声で話すのは、図書館という場所に適さない。", "target_word": "適さない", "complexity_tier": "T3", "furigana": "大[おお]きな声[こえ]で話[はな]すのは、図書館[としょかん]という場所[ばしょ]に適[てき]さない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "適する", "label": "辞書形"}, {"form": "適します", "label": "丁寧形"}, {"form": "適さない", "label": "否定形"}, {"form": "適して", "label": "て形"}, {"form": "適した", "label": "た形"}, {"form": "適すれば", "label": "仮定形"}], "register": "標準語（常体）", "sense_fingerprint": "用途・目的・場面などの条件にふさわしい。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0568bb4e-9a35-4f81-9107-29aa110f32d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38829, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "適して", "is_correct": true, "explanation": "作業に合うという意味の「て形」で、「適している」の一部として自然に入る。"}, {"text": "驚いて", "is_correct": false, "explanation": "驚くは感情の動作で、作業への適合を表せない。"}, {"text": "反論して", "is_correct": false, "explanation": "反論は意見を争う意味で、道具と作業の文脈に合わない。"}, {"text": "笑って", "is_correct": false, "explanation": "笑うは感情の動作で、作業に合う意味にはならない。"}], "explanations": {"適して": "作業に合うという意味の「て形」で、「適している」の一部として自然に入る。", "驚いて": "驚くは感情の動作で、作業への適合を表せない。", "反論して": "反論は意見を争う意味で、道具と作業の文脈に合わない。", "笑って": "笑うは感情の動作で、作業に合う意味にはならない。"}, "sentence_index": 0, "correct_answer": "適して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は選挙に当選して、適していた。", "explanation": "ここは〈当選〉（選ばれる）の意味。適するは条件に合う意味で、選挙で選ばれる意味では使わない。"}, {"text": "チームは最後の試合で勝って、適していた。", "explanation": "ここは〈勝つ〉の意味。適するは条件に合う意味で、試合の勝敗には使わない。"}, {"text": "母は新しい計画に最後まで反対し、適していた。", "explanation": "ここは〈反対する〉の意味。適するは条件に合う意味で、反対の立場は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38829, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "適した", "is_correct": true, "explanation": "初心者に合うという意味のた形で、名詞「山」を修飾して自然。"}, {"text": "嘆いた", "is_correct": false, "explanation": "嘆くは悲しむ意味で、初心者に合う山という文脈に合わない。"}, {"text": "逆らった", "is_correct": false, "explanation": "逆らうは反抗する意味で、初心者に合う意味にはならない。"}, {"text": "怒った", "is_correct": false, "explanation": "怒るは感情を表す語で、山を修飾して合うという意味にならない。"}], "explanations": {"適した": "初心者に合うという意味のた形で、名詞「山」を修飾して自然。", "嘆いた": "嘆くは悲しむ意味で、初心者に合う山という文脈に合わない。", "逆らった": "逆らうは反抗する意味で、初心者に合う意味にはならない。", "怒った": "怒るは感情を表す語で、山を修飾して合うという意味にならない。"}, "sentence_index": 6, "correct_answer": "適した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は試験に合格して、適していた。", "explanation": "ここは〈合格〉（試験に通る）の意味。適するは条件に合う意味で、試験の合否には使わない。"}, {"text": "船は検問を通過して、適していた。", "explanation": "ここは〈通過〉（通り抜ける）の意味。適するは条件に合う意味で、通過の意味では使わない。"}, {"text": "問題は話し合いで解決して、適していた。", "explanation": "ここは〈解決〉（問題が片づく）の意味。適するは条件に合う意味で、問題の解決には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38829, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このインクは、古い紙で適している。", "corrected_sentence": "このインクは、古い紙に適している。", "error_description": "「適する」の対象は「に」で示す。「で」では場所や手段の意味になり、誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "適した", "is_correct": true, "explanation": "た形。名詞「服装」を修飾し、会議の場に合う服装を表す。"}, {"text": "適して", "is_correct": false, "explanation": "て形。名詞を修飾できず、ここでは文の形が合わない。"}, {"text": "適すれば", "is_correct": false, "explanation": "仮定形。条件を述べる形で、名詞を修飾する位置には入らない。"}, {"text": "適します", "is_correct": false, "explanation": "丁寧形。文末で使う形で、名詞を修飾する位置には入らない。"}], "correct_form": "適した", "base_form": "適する", "form_label": "た形", "sentence_index": 1, "explanations": {"適した": "た形。名詞「服装」を修飾し、会議の場に合う服装を表す。", "適して": "て形。名詞を修飾できず、ここでは文の形が合わない。", "適すれば": "仮定形。条件を述べる形で、名詞を修飾する位置には入らない。", "適します": "丁寧形。文末で使う形で、名詞を修飾する位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38829, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道具は子どもの手に適すた大きさだ。", "corrected_sentence": "この道具は子どもの手に適した大きさだ。", "error_description": "「適する」の過去形（た形）は「適した」。「適すた」は活用を誤っており、誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "適した", "is_correct": true, "explanation": "た形。名詞「言葉」を修飾し、結婚式に合う言葉を表す。"}, {"text": "適さず", "is_correct": false, "explanation": "連用形の否定。名詞「言葉」を直接修飾できず、ここでは文が成り立たない。"}, {"text": "適すると", "is_correct": false, "explanation": "条件を述べる形で、名詞を修飾する位置には入らない。"}, {"text": "適しない", "is_correct": false, "explanation": "否定の誤った活用。正しい否定形は「適さない」で、名詞の前には自然に入らない。"}], "correct_form": "適した", "base_form": "適する", "form_label": "た形", "sentence_index": 7, "explanations": {"適した": "た形。名詞「言葉」を修飾し、結婚式に合う言葉を表す。", "適さず": "連用形の否定。名詞「言葉」を直接修飾できず、ここでは文が成り立たない。", "適すると": "条件を述べる形で、名詞を修飾する位置には入らない。", "適しない": "否定の誤った活用。正しい否定形は「適さない」で、名詞の前には自然に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38831, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『含まれる』に対応する『に』で、「肉類には」の形で文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す『を』になるが、『含まれる』は『に』か『が』を取るので成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する『の』になり、『肉類のはたんぱく質』と続いて文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す『へ』になり、「肉類へ含まれている」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "『含まれる』に対応する『に』で、「肉類には」の形で文が成り立つ。", "を": "目的語を表す『を』になるが、『含まれる』は『に』か『が』を取るので成り立たない。", "の": "名詞を修飾する『の』になり、『肉類のはたんぱく質』と続いて文が成り立たない。", "へ": "方向を表す『へ』になり、「肉類へ含まれている」は成り立たない。"}, "error_tags": {"を": "目的語の誤り", "の": "修飾の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38831, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "並列を表す『と』で、「肉類と野菜」の形で文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す『が』になり、「肉類が一緒に食べる」は主体が合わない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を表す『に』になり、「肉類に野菜を一緒に食べる」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す『から』になり、「肉類から野菜を一緒に食べる」は意味が通らない。"}], "correct_answer": "と", "explanations": {"と": "並列を表す『と』で、「肉類と野菜」の形で文が成り立つ。", "が": "主語を表す『が』になり、「肉類が一緒に食べる」は主体が合わない。", "に": "方向や相手を表す『に』になり、「肉類に野菜を一緒に食べる」は成り立たない。", "から": "起点を表す『から』になり、「肉類から野菜を一緒に食べる」は意味が通らない。"}, "error_tags": {"が": "主語の誤り", "に": "方向・相手の誤り", "から": "起点の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38831, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "動物の肉を主な材料とする食品の総称。牛肉、豚肉、鶏肉などが含まれる。", "primary_collocate": null, "pronunciation": "にくるい", "ipa": "nikɯɾɯi", "syllable_count": 4, "sentences": [{"text": "この店では、牛肉や豚肉などの肉類を冷凍で売っている。", "target_word": "肉類", "complexity_tier": "T3", "furigana": "この店[みせ]では、牛肉[ぎゅうにく]や豚肉[ぶたにく]などの肉類[にくるい]を冷凍[れいとう]で売[う]っている。", "sentence_source": "generated"}, {"text": "肉類にはたんぱく質が多く含まれている。", "target_word": "肉類", "complexity_tier": "T3", "furigana": "肉類[にくるい]にはたんぱく質[しつ]が多[おお]く含[ふく]まれている。", "sentence_source": "generated"}, {"text": "肉類を調理するときは、中までしっかり火を通す。", "target_word": "肉類", "complexity_tier": "T3", "furigana": "肉類[にくるい]を調理[ちょうり]するときは、中[なか]までしっかり火[ひ]を通[とお]す。", "sentence_source": "generated"}, {"text": "牛肉、豚肉、鶏肉などをまとめて肉類と呼ぶ。", "target_word": "肉類", "complexity_tier": "T3", "furigana": "牛肉[ぎゅうにく]、豚肉[ぶたにく]、鶏肉[とりにく]などをまとめて肉類[にくるい]と呼[よ]ぶ。", "sentence_source": "generated"}, {"text": "肉類の輸入量が増えて、値段が少し下がった。", "target_word": "肉類", "complexity_tier": "T3", "furigana": "肉類[にくるい]の輸入量[ゆにゅうりょう]が増[ふ]えて、値段[ねだん]が少[すこ]し下[さ]がった。", "sentence_source": "generated"}, {"text": "この工場では、肉類を使った冷凍食品を作っている。", "target_word": "肉類", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、肉類[にくるい]を使[つか]った冷凍食品[れいとうしょくひん]を作[つく]っている。", "sentence_source": "generated"}, {"text": "肉類は冷蔵庫の下の段に入れて保存する。", "target_word": "肉類", "complexity_tier": "T3", "furigana": "肉類[にくるい]は冷蔵庫[れいぞうこ]の下[した]の段[だん]に入[い]れて保存[ほぞん]する。", "sentence_source": "generated"}, {"text": "栄養のバランスのために、肉類と野菜を一緒に食べる。", "target_word": "肉類", "complexity_tier": "T3", "furigana": "栄養[えいよう]のバランスのために、肉類[にくるい]と野菜[やさい]を一緒[いっしょ]に食[た]べる。", "sentence_source": "generated"}, {"text": "病院では、肉類を少なくした食事が出された。", "target_word": "肉類", "complexity_tier": "T3", "furigana": "病院[びょういん]では、肉類[にくるい]を少[すく]なくした食事[しょくじ]が出[で]された。", "sentence_source": "generated"}, {"text": "肉類の売り上げは、冬の鍋の季節にいちばん伸びる。", "target_word": "肉類", "complexity_tier": "T3", "furigana": "肉類[にくるい]の売[う]り上[あ]げは、冬[ふゆ]の鍋[なべ]の季節[きせつ]にいちばん伸[の]びる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "肉類", "label": "基本形"}], "register": "標準語（常体）", "sense_fingerprint": "牛肉・豚肉・鶏肉など、動物の肉を材料とする食品の分類名。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0568bb4e-9a35-4f81-9107-29aa110f32d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38831, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肉類", "is_correct": true, "explanation": "牛肉や豚肉をまとめた食品の総称で、「などの」の後に入って文が通る。"}, {"text": "黒板", "is_correct": false, "explanation": "黒板は食品ではないので、冷凍で売る種類にならない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は文房具で、冷凍で売る食品ではない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は配達のサービスで、食品の種類を表さない。"}], "explanations": {"肉類": "牛肉や豚肉をまとめた食品の総称で、「などの」の後に入って文が通る。", "黒板": "黒板は食品ではないので、冷凍で売る種類にならない。", "鉛筆": "鉛筆は文房具で、冷凍で売る食品ではない。", "郵便": "郵便は配達のサービスで、食品の種類を表さない。"}, "sentence_index": 0, "correct_answer": "肉類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎朝、肉類を鍛えている。", "explanation": "ここは〈肉体〉（体）の意味。肉類は食品の総称なので、鍛える対象にはならない。"}, {"text": "農家では肉類を十羽飼っている。", "explanation": "ここは〈鶏〉（生きた鳥）の意味。肉類は食品の総称なので、生き物を羽の数で数えられない。"}, {"text": "ステーキを切ると肉類があふれた。", "explanation": "ここは〈肉汁〉（肉から出る汁）の意味。肉類は食品の種類なので、あふれる液体には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38831, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肉類", "is_correct": true, "explanation": "冷蔵庫で保存する食品の総称で、「は」の前に入って文が通る。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は保存する食品ではないので、冷蔵庫に入れる文脈に合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は食品ではないので、冷蔵庫に入れて保存しない。"}, {"text": "太陽", "is_correct": false, "explanation": "太陽は冷蔵庫に入れて保存するものではない。"}], "explanations": {"肉類": "冷蔵庫で保存する食品の総称で、「は」の前に入って文が通る。", "教科書": "教科書は保存する食品ではないので、冷蔵庫に入れる文脈に合わない。", "座布団": "座布団は食品ではないので、冷蔵庫に入れて保存しない。", "太陽": "太陽は冷蔵庫に入れて保存するものではない。"}, "sentence_index": 6, "correct_answer": "肉類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この牛は肉類がよくて、高値で取引される。", "explanation": "ここは〈肉質〉（肉の質）の意味。肉類は食品の総称なので、牛の品質には使えない。"}, {"text": "夜空の星は、肉類でもよく見える。", "explanation": "ここは〈肉眼〉（裸眼）の意味。肉類は食品の総称なので、目で見る方法は表せない。"}, {"text": "近所の肉類で働いている。", "explanation": "ここは〈肉屋〉（店）の意味。肉類は店ではないので、働く場所にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38831, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ハムやソーセージは、肉類で一種だ。", "corrected_sentence": "ハムやソーセージは、肉類の一種だ。", "error_description": "『〜の一種』は『の』で名詞を続ける形。『肉類で』の『で』が誤りで、『肉類の一種』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38831, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "肉類は中まで火を通してから飲む。", "corrected_sentence": "肉類は中まで火を通してから食べる。", "error_description": "『飲む』は液体などに使う動詞で、肉類には合わない。『食べる』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38834, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「雑菌が食べ物につく」の主語を示す助詞。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すが、「雑菌に食べ物につく」では主語が立たず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、雑菌は手段ではないので「雑菌で食べ物につく」は通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「雑菌へ食べ物につく」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「雑菌が食べ物につく」の主語を示す助詞。", "に": "「に」は場所や相手を示すが、「雑菌に食べ物につく」では主語が立たず文が成り立たない。", "で": "「で」は手段や場所を示すが、雑菌は手段ではないので「雑菌で食べ物につく」は通らない。", "へ": "「へ」は方向を示すが、「雑菌へ食べ物につく」は意味が通らない。"}, "error_tags": {"に": "位置・相手の誤り", "で": "手段の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38834, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「雑菌を防ぐ」の目的語を示す助詞。防ぐ対象は雑菌なので「を」が正しい。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「雑菌と防ぐ」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「雑菌の防ぐ」は動詞に続かず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、「雑菌より防ぐ」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「雑菌を防ぐ」の目的語を示す助詞。防ぐ対象は雑菌なので「を」が正しい。", "と": "「と」は相手や並列を示すが、「雑菌と防ぐ」は成り立たない。", "の": "「の」は名詞をつなぐ助詞で、「雑菌の防ぐ」は動詞に続かず不自然。", "より": "「より」は比較を示すが、「雑菌より防ぐ」は意味が通らない。"}, "error_tags": {"と": "相手・並列の誤り", "の": "連体修飾の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38834, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "目に見えない小さな生き物で、食べ物を腐らせるものもある。", "primary_collocate": null, "pronunciation": "ざっきん", "ipa": "dzakkiɴ", "syllable_count": 4, "sentences": [{"text": "夏は雑菌が増えやすいので、お弁当は早めに食べてください。", "target_word": "雑菌", "complexity_tier": "T3", "furigana": "夏(なつ)は雑菌(ざっきん)が増(ふ)えやすいので、お弁当(べんとう)は早(はや)めに食(た)べてください。", "sentence_source": "generated"}, {"text": "手を洗わずに料理をすると、雑菌が食べ物につきます。", "target_word": "雑菌", "complexity_tier": "T3", "furigana": "手(て)を洗(あら)わずに料理(りょうり)をすると、雑菌(ざっきん)が食(た)べ物(もの)につきます。", "sentence_source": "generated"}, {"text": "まな板の雑菌を減らすために、熱いお湯をかけます。", "target_word": "雑菌", "complexity_tier": "T3", "furigana": "まな板(いた)の雑菌(ざっきん)を減(へ)らすために、熱(あつ)いお湯(ゆ)をかけます。", "sentence_source": "generated"}, {"text": "雑菌のせいで、冷蔵庫の中のお肉が腐ってしまいました。", "target_word": "雑菌", "complexity_tier": "T3", "furigana": "雑菌(ざっきん)のせいで、冷蔵庫(れいぞうこ)の中(なか)のお肉(にく)が腐(くさ)ってしまいました。", "sentence_source": "generated"}, {"text": "傷口に雑菌が入らないように、きれいな水で洗いました。", "target_word": "雑菌", "complexity_tier": "T3", "furigana": "傷口(きずぐち)に雑菌(ざっきん)が入(はい)らないように、きれいな水(みず)で洗(あら)いました。", "sentence_source": "generated"}, {"text": "このふきんは雑菌が多いので、新しいものに替えましょう。", "target_word": "雑菌", "complexity_tier": "T3", "furigana": "このふきんは雑菌(ざっきん)が多(おお)いので、新(あたら)しいものに替(か)えましょう。", "sentence_source": "generated"}, {"text": "目には見えませんが、台所には雑菌がたくさんいます。", "target_word": "雑菌", "complexity_tier": "T3", "furigana": "目(め)には見(み)えませんが、台所(だいどころ)には雑菌(ざっきん)がたくさんいます。", "sentence_source": "generated"}, {"text": "雑菌を防ぐために、お茶の入った水筒はよく洗います。", "target_word": "雑菌", "complexity_tier": "T3", "furigana": "雑菌(ざっきん)を防(ふせ)ぐために、お茶(ちゃ)の入(はい)った水筒(すいとう)はよく洗(あら)います。", "sentence_source": "generated"}, {"text": "雑菌がつかないよう、ご飯をラップで包んで冷凍します。", "target_word": "雑菌", "complexity_tier": "T3", "furigana": "雑菌(ざっきん)がつかないよう、ご飯(はん)をラップで包(つつ)んで冷凍(れいとう)します。", "sentence_source": "generated"}, {"text": "石けんを使うと、手についた雑菌をしっかり落とせます。", "target_word": "雑菌", "complexity_tier": "T3", "furigana": "石(せっ)けんを使(つか)うと、手(て)についた雑菌(ざっきん)をしっかり落(お)とせます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雑菌", "label": "基本形"}], "register": "丁寧(です・ます体)", "sense_fingerprint": "目に見えない小さな生き物。食べ物を腐らせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0568bb4e-9a35-4f81-9107-29aa110f32d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38834, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雑菌", "is_correct": true, "explanation": "「夏は〜が増えやすい」に入るのは、夏に増えて食べ物を傷ませる目に見えない微生物の雑菌だけ。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は道具で、夏に増えていくものではないので「増えやすい」と続かない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、「夏は冷蔵庫が増えやすい」は文として成り立たない。"}, {"text": "調理台", "is_correct": false, "explanation": "調理台は台所の設備で、数が増えていく対象として文に入らない。"}], "explanations": {"雑菌": "「夏は〜が増えやすい」に入るのは、夏に増えて食べ物を傷ませる目に見えない微生物の雑菌だけ。", "包丁": "包丁は道具で、夏に増えていくものではないので「増えやすい」と続かない。", "冷蔵庫": "冷蔵庫は家電で、「夏は冷蔵庫が増えやすい」は文として成り立たない。", "調理台": "調理台は台所の設備で、数が増えていく対象として文に入らない。"}, "sentence_index": 0, "correct_answer": "雑菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このパソコンは雑菌に感染して、画面が勝手に切り替わる。", "explanation": "ここは〈ウイルス〉の意味。コンピューターに感染するのはウイルスで、食べ物を腐らせる雑菌は機械の感染には使わない。"}, {"text": "キッチンに雑菌が出たので、殺虫剤をまいた。", "explanation": "ここは〈害虫〉の意味。殺虫剤で退治する虫は目に見える生き物で、目に見えない雑菌を殺虫剤で退治する対象にはしない。"}, {"text": "この山では、食べられる雑菌がたくさん採れる。", "explanation": "ここは〈食用のきのこ〉の意味。雑菌は食べ物を腐らせる有害なものを指すので、食べられるきのこには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38834, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雑菌", "is_correct": true, "explanation": "「台所にはいる」と続けられる、目に見えない生き物の雑菌。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は物なので「台所には鍋がたくさんいる」と「いる」では続かない。"}, {"text": "調味料", "is_correct": false, "explanation": "調味料は「ある」で言う物で、「いる」とは続かない。"}, {"text": "食器", "is_correct": false, "explanation": "食器は「ある」で言う物で、「たくさんいる」は不自然で文が成り立たない。"}], "explanations": {"雑菌": "「台所にはいる」と続けられる、目に見えない生き物の雑菌。", "鍋": "鍋は物なので「台所には鍋がたくさんいる」と「いる」では続かない。", "調味料": "調味料は「ある」で言う物で、「いる」とは続かない。", "食器": "食器は「ある」で言う物で、「たくさんいる」は不自然で文が成り立たない。"}, "sentence_index": 6, "correct_answer": "雑菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "腸によい雑菌を増やすために、ヨーグルトを毎日食べる。", "explanation": "ここは〈善玉菌〉の意味。雑菌は食べ物を腐らせたり病気の原因になる有害なものを指すので、腸によい働きをする菌には使わない。"}, {"text": "パンがふくらむのは、雑菌が出す炭酸ガスのおかげだ。", "explanation": "ここは〈酵母〉の意味。パンをふくらませるのは人が発酵に使う酵母で、衛生上問題になる雑菌を発酵に使うとは言わない。"}, {"text": "お腹の雑菌を、駆虫薬で追い出した。", "explanation": "ここは〈寄生虫〉の意味。駆虫薬で追い出すのは腸にいる寄生虫で、目に見えない小さな生き物の雑菌は駆虫の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38834, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "調理台の雑菌が、熱湯で消毒した。", "corrected_sentence": "調理台の雑菌を、熱湯で消毒した。", "error_description": "「消毒した」の目的語は「雑菌」なので「を」が正しい。「が」は主語を表すため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38834, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "まな板の雑菌は、熱湯をかけると減らす。", "corrected_sentence": "まな板の雑菌は、熱湯をかけると減る。", "error_description": "「減る」は自動詞で、雑菌が自然に減ることを表す。「減らす」は他動詞で目的語が必要なので、主語が雑菌のこの文では誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38838, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「原則として」の「と」。「原則として」で副詞的に使う定型の形になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「原則をして」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「原則へして」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すが、「原則でして」は文として成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「原則として」の「と」。「原則として」で副詞的に使う定型の形になる。", "を": "「を」は目的語を示すが、「原則をして」は成り立たない。", "へ": "「へ」は方向を示すが、「原則へして」は意味が通らない。", "で": "「で」は手段を示すが、「原則でして」は文として成り立たない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "で": "手段の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "例外", "is_correct": true, "explanation": "原則（ふつうはこうするという決まり）の対義語。原則には例外があるという関係にある。"}, {"text": "目的", "is_correct": false, "explanation": "目的は行動のねらいで、原則の反対の意味にはならない。"}, {"text": "結果", "is_correct": false, "explanation": "結果は出来事の終わりの状態で、原則の対義語ではない。"}, {"text": "手順", "is_correct": false, "explanation": "手順は作業の順序で、原則の対義語ではない。"}], "correct_answer": "例外", "explanations": {"例外": "原則（ふつうはこうするという決まり）の対義語。原則には例外があるという関係にある。", "目的": "目的は行動のねらいで、原則の反対の意味にはならない。", "結果": "結果は出来事の終わりの状態で、原則の対義語ではない。", "手順": "手順は作業の順序で、原則の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38838, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「原則として」の「と」。「原則として」で副詞的に使う定型の形になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「原則がして」は文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、「原則よりして」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「原則のして」は文として成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「原則として」の「と」。「原則として」で副詞的に使う定型の形になる。", "が": "「が」は主語を示すが、「原則がして」は文として成り立たない。", "より": "「より」は比較を示すが、「原則よりして」は意味が通らない。", "の": "「の」は名詞をつなぐ助詞で、「原則のして」は文として成り立たない。"}, "error_tags": {"が": "主語の誤り", "より": "比較の誤り", "の": "連体修飾の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "例外", "is_correct": true, "explanation": "原則（ふつうはこうするという決まり）の対義語。原則として不可という文の例外を表す関係にある。"}, {"text": "日程", "is_correct": false, "explanation": "日程は予定の時間割で、原則の対義語ではない。"}, {"text": "材料", "is_correct": false, "explanation": "材料は物を作るもとになる物で、原則の対義語ではない。"}, {"text": "資格", "is_correct": false, "explanation": "資格は認められた地位や条件で、原則の対義語ではない。"}], "correct_answer": "例外", "explanations": {"例外": "原則（ふつうはこうするという決まり）の対義語。原則として不可という文の例外を表す関係にある。", "日程": "日程は予定の時間割で、原則の対義語ではない。", "材料": "材料は物を作るもとになる物で、原則の対義語ではない。", "資格": "資格は認められた地位や条件で、原則の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38838, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「原則」は、だいたいのきまりや、ふつうはこうするという意味です。", "primary_collocate": null, "pronunciation": "げんそく", "ipa": "ɡensokɯ", "syllable_count": 4, "sentences": [{"text": "当店の休みは、原則として毎週水曜日です。", "target_word": "原則", "complexity_tier": "T3", "furigana": "当店(とうてん)の休(やす)みは、原則(げんそく)として毎週(まいしゅう)水曜日(すいようび)です。", "sentence_source": "generated"}, {"text": "学校では原則として、携帯電話の使用が禁止されています。", "target_word": "原則", "complexity_tier": "T3", "furigana": "学校(がっこう)では原則(げんそく)として、携帯電話(けいたいでんわ)の使用(しよう)が禁止(きんし)されています。", "sentence_source": "generated"}, {"text": "返品は原則できませんが、壊れていた場合は交換します。", "target_word": "原則", "complexity_tier": "T3", "furigana": "返品(へんぴん)は原則(げんそく)できませんが、壊(こわ)れていた場合(ばあい)は交換(こうかん)します。", "sentence_source": "generated"}, {"text": "この時期は原則として、予約なしでは入れません。", "target_word": "原則", "complexity_tier": "T3", "furigana": "この時期(じき)は原則(げんそく)として、予約(よやく)なしでは入(い)れません。", "sentence_source": "generated"}, {"text": "原則はそうですが、今回は特別に許可します。", "target_word": "原則", "complexity_tier": "T3", "furigana": "原則(げんそく)はそうですが、今回(こんかい)は特別(とくべつ)に許可(きょか)します。", "sentence_source": "generated"}, {"text": "試験は原則、教室で受けますが、病気の人は家でも受けられます。", "target_word": "原則", "complexity_tier": "T3", "furigana": "試験(しけん)は原則(げんそく)、教室(きょうしつ)で受(う)けますが、病気(びょうき)の人(ひと)は家(いえ)でも受(う)けられます。", "sentence_source": "generated"}, {"text": "うちでは原則、夜十時以降はゲームをしない決まりです。", "target_word": "原則", "complexity_tier": "T3", "furigana": "うちでは原則(げんそく)、夜(よる)十時(じゅうじ)以降(いこう)はゲームをしない決(き)まりです。", "sentence_source": "generated"}, {"text": "雨の日は原則として、屋外での練習は中止です。", "target_word": "原則", "complexity_tier": "T3", "furigana": "雨(あめ)の日(ひ)は原則(げんそく)として、屋外(おくがい)での練習(れんしゅう)は中止(ちゅうし)です。", "sentence_source": "generated"}, {"text": "料金は原則前払いですが、例外もあります。", "target_word": "原則", "complexity_tier": "T3", "furigana": "料金(りょうきん)は原則(げんそく)前払(まえばら)いですが、例外(れいがい)もあります。", "sentence_source": "generated"}, {"text": "原則として、ペットを連れて入ることはできません。", "target_word": "原則", "complexity_tier": "T3", "furigana": "原則(げんそく)として、ペットを連(つ)れて入(はい)ることはできません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原則", "label": "基本形"}, {"form": "原則として", "label": "副詞的用法"}], "register": "丁寧(です・ます体)", "sense_fingerprint": "だいたいのきまり。ふつうはこうするという決まり(例外あり)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0568bb4e-9a35-4f81-9107-29aa110f32d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38838, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原則", "is_correct": true, "explanation": "「〜として毎週水曜日です」に入るのは、ふつうはこうするという決まりを表す原則だけ。"}, {"text": "予算", "is_correct": false, "explanation": "予算は使うお金の額で、「〜として毎週水曜日です」には続かない。"}, {"text": "期限", "is_correct": false, "explanation": "期限は締め切りの時期で、「〜として毎週水曜日です」の空所には入らない。"}, {"text": "手順", "is_correct": false, "explanation": "手順は作業の順序で、休みの曜日を示す文脈には合わない。"}], "explanations": {"原則": "「〜として毎週水曜日です」に入るのは、ふつうはこうするという決まりを表す原則だけ。", "予算": "予算は使うお金の額で、「〜として毎週水曜日です」には続かない。", "期限": "期限は締め切りの時期で、「〜として毎週水曜日です」の空所には入らない。", "手順": "手順は作業の順序で、休みの曜日を示す文脈には合わない。"}, "sentence_index": 0, "correct_answer": "原則"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "役所に、この契約書の原則を提出した。", "explanation": "ここは〈原本〉の意味。役所に提出するのは契約書の原本で、だいたいのきまりを表す原則は提出するものではないので合わない。"}, {"text": "銀行に、預金の原則を預けた。", "explanation": "ここは〈元本〉（預けたお金の元の額）の意味。銀行に預けるのは元本で、きまりを表す原則は預けられないので合わない。"}, {"text": "作家は、書き上げた原則を出版社に渡した。", "explanation": "ここは〈原稿〉の意味。出版社に渡すのは書き上げた文章の原稿で、きまりを表す原則は渡すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38838, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原則", "is_correct": true, "explanation": "「うちでは原則、夜十時以降は〜」の形で、ふつうはこうするという意味になる原則だけが入る。"}, {"text": "食事", "is_correct": false, "explanation": "食事は食べることなので、「うちでは食事、夜十時以降は」と続けても決まりの文にならない。"}, {"text": "洗濯", "is_correct": false, "explanation": "洗濯は家事の行為で、「うちでは洗濯、夜十時以降は」では決まりの文にならない。"}, {"text": "予定", "is_correct": false, "explanation": "予定は行う事柄の計画で、「うちでは予定、夜十時以降は」では意味が通らない。"}], "explanations": {"原則": "「うちでは原則、夜十時以降は〜」の形で、ふつうはこうするという意味になる原則だけが入る。", "食事": "食事は食べることなので、「うちでは食事、夜十時以降は」と続けても決まりの文にならない。", "洗濯": "洗濯は家事の行為で、「うちでは洗濯、夜十時以降は」では決まりの文にならない。", "予定": "予定は行う事柄の計画で、「うちでは予定、夜十時以降は」では意味が通らない。"}, "sentence_index": 6, "correct_answer": "原則"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この食品の原則は、国産の大豆だ。", "explanation": "ここは〈原料〉の意味。食品を作る材料は原料で、だいたいのきまりを表す原則は食品の材料を指さないので合わない。"}, {"text": "この宝石は、磨く前の原則だ。", "explanation": "ここは〈原石〉（磨く前の石）の意味。原則は決まりを表す語で、石の状態を指す言葉ではない。"}, {"text": "北海道の原則を、一日中歩いた。", "explanation": "ここは〈原野〉（人の手の入っていない広い土地）の意味。歩くのは広い土地の原野で、きまりを表す原則は歩けるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38838, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社では原則で、在宅勤務は週二日までです。", "corrected_sentence": "会社では原則として、在宅勤務は週二日までです。", "error_description": "「原則」は副詞的に「原則として」の形で使うのが自然。「原則で」は助詞の使い方が誤りで、正しくは「原則として」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
