INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38839, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「原則に従う」の「に」。従う相手は原則なので「に」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「原則が従って」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「原則へ従って」は自然な言い方にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すが、「原則で従って」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「原則に従う」の「に」。従う相手は原則なので「に」が正しい。", "が": "「が」は主語を示すが、「原則が従って」は文として成り立たない。", "へ": "「へ」は方向を示すが、「原則へ従って」は自然な言い方にならない。", "で": "「で」は手段を示すが、「原則で従って」は意味が通らない。"}, "error_tags": {"が": "主語の誤り", "へ": "方向の誤り", "で": "手段の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "例外", "is_correct": true, "explanation": "基本的なきまりとしての原則の対義語。原則を決めても例外が生じるという関係にある。"}, {"text": "目標", "is_correct": false, "explanation": "目標は目指す到達点で、原則の対義語ではない。"}, {"text": "結果", "is_correct": false, "explanation": "結果は出来事の終わりの状態で、原則の対義語ではない。"}, {"text": "手順", "is_correct": false, "explanation": "手順は作業の順序で、原則の対義語ではない。"}], "correct_answer": "例外", "explanations": {"例外": "基本的なきまりとしての原則の対義語。原則を決めても例外が生じるという関係にある。", "目標": "目標は目指す到達点で、原則の対義語ではない。", "結果": "結果は出来事の終わりの状態で、原則の対義語ではない。", "手順": "手順は作業の順序で、原則の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38839, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「原則を確認した」の目的語を示す助詞。確認する対象は原則なので「を」が正しい。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「原則と確認した」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、「原則より確認した」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「原則の確認した」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「原則を確認した」の目的語を示す助詞。確認する対象は原則なので「を」が正しい。", "と": "「と」は相手や並列を示すが、「原則と確認した」は成り立たない。", "より": "「より」は比較を示すが、「原則より確認した」は意味が通らない。", "の": "「の」は名詞をつなぐ助詞で、「原則の確認した」は文として成り立たない。"}, "error_tags": {"と": "相手・並列の誤り", "より": "比較の誤り", "の": "連体修飾の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "例外", "is_correct": true, "explanation": "基本的なきまりとしての原則の対義語。原則として教えた内容にも例外が生じうるという関係にある。"}, {"text": "手本", "is_correct": false, "explanation": "手本は見習うべき模範で、原則の対義語ではない。"}, {"text": "記録", "is_correct": false, "explanation": "記録は事実を書き残すことで、原則の対義語ではない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は一年の区分で、原則の対義語ではない。"}], "correct_answer": "例外", "explanations": {"例外": "基本的なきまりとしての原則の対義語。原則として教えた内容にも例外が生じうるという関係にある。", "手本": "手本は見習うべき模範で、原則の対義語ではない。", "記録": "記録は事実を書き残すことで、原則の対義語ではない。", "季節": "季節は一年の区分で、原則の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38839, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を行うときの、基本的なきまりや方針。多くの場合に当てはまる基準。", "primary_collocate": null, "pronunciation": "げんそく", "ipa": "ɡensokɯ", "syllable_count": 4, "sentences": [{"text": "民主主義の原則は、国民が国の主役であるということだ。", "target_word": "原則", "complexity_tier": "T3", "furigana": "民主主義(みんしゅしゅぎ)の原則(げんそく)は、国民(こくみん)が国(くに)の主役(しゅやく)であるということだ。", "sentence_source": "generated"}, {"text": "会社は、お客様第一という原則に従って経営している。", "target_word": "原則", "complexity_tier": "T3", "furigana": "会社(かいしゃ)は、お客様(きゃくさま)第一(だいいち)という原則(げんそく)に従(したが)って経営(けいえい)している。", "sentence_source": "generated"}, {"text": "彼は自分の原則を曲げず、最後まで正直に生きた。", "target_word": "原則", "complexity_tier": "T3", "furigana": "彼(かれ)は自分(じぶん)の原則(げんそく)を曲(ま)げず、最後(さいご)まで正直(しょうじき)に生(い)きた。", "sentence_source": "generated"}, {"text": "原則を決めておけば、判断に迷ったときも困らない。", "target_word": "原則", "complexity_tier": "T3", "furigana": "原則(げんそく)を決(き)めておけば、判断(はんだん)に迷(まよ)ったときも困(こま)らない。", "sentence_source": "generated"}, {"text": "この法律は、男女平等の原則に基づいて作られた。", "target_word": "原則", "complexity_tier": "T3", "furigana": "この法律(ほうりつ)は、男女(だんじょ)平等(びょうどう)の原則(げんそく)に基(もと)づいて作(つく)られた。", "sentence_source": "generated"}, {"text": "契約を守ることは、取引の基本的な原則だ。", "target_word": "原則", "complexity_tier": "T3", "furigana": "契約(けいやく)を守(まも)ることは、取引(とりひき)の基本的(きほんてき)な原則(げんそく)だ。", "sentence_source": "generated"}, {"text": "原則に例外を認めすぎると、規則の意味がなくなる。", "target_word": "原則", "complexity_tier": "T3", "furigana": "原則(げんそく)に例外(れいがい)を認(みと)めすぎると、規則(きそく)の意味(いみ)がなくなる。", "sentence_source": "generated"}, {"text": "新しいチームでは、まず話し合いの原則を確認した。", "target_word": "原則", "complexity_tier": "T3", "furigana": "新(あたら)しいチームでは、まず話(はな)し合(あ)いの原則(げんそく)を確認(かくにん)した。", "sentence_source": "generated"}, {"text": "科学の研究では、結果を公開することが原則とされる。", "target_word": "原則", "complexity_tier": "T3", "furigana": "科学(かがく)の研究(けんきゅう)では、結果(けっか)を公開(こうかい)することが原則(げんそく)とされる。", "sentence_source": "generated"}, {"text": "彼女は「嘘をつかない」という原則を子どもに教えた。", "target_word": "原則", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は「嘘(うそ)をつかない」という原則(げんそく)を子(こ)どもに教(おし)えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原則", "label": "基本形"}], "register": "普通体(だ・である体)", "sense_fingerprint": "物事の基本的なきまりや方針。多くの場合に当てはまる基準", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0568bb4e-9a35-4f81-9107-29aa110f32d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38839, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原則", "is_correct": true, "explanation": "「民主主義の〜は、国民が国の主役であるということだ」に入るのは、基本的なきまりを表す原則だけ。"}, {"text": "予算", "is_correct": false, "explanation": "予算は使うお金の計画で、「民主主義の予算は」と続けても意味が通らない。"}, {"text": "期限", "is_correct": false, "explanation": "期限は締め切りの時期で、「民主主義の期限は」では文の意味が成り立たない。"}, {"text": "手順", "is_correct": false, "explanation": "手順は作業の順序で、「民主主義の手順は」と続けても基本的なきまりの文にならない。"}], "explanations": {"原則": "「民主主義の〜は、国民が国の主役であるということだ」に入るのは、基本的なきまりを表す原則だけ。", "予算": "予算は使うお金の計画で、「民主主義の予算は」と続けても意味が通らない。", "期限": "期限は締め切りの時期で、「民主主義の期限は」では文の意味が成り立たない。", "手順": "手順は作業の順序で、「民主主義の手順は」と続けても基本的なきまりの文にならない。"}, "sentence_index": 0, "correct_answer": "原則"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画の原則を一言で言うと、感動的だ。", "explanation": "ここは〈感想〉の意味。個人の受け止め方は、基本的なきまりや方針を指す原則とは合わない。"}, {"text": "ゴッホの原則は、美術館に展示されている。", "explanation": "ここは〈原画〉の意味。美術館に展示されるのは原画で、きまりを表す原則は展示される作品を指さないので合わない。"}, {"text": "この商品の原則は、千円だ。", "explanation": "ここは〈原価〉（商品を作るためにかかった費用）の意味。原則は決まりや方針なので、金額を指す言葉としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38839, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原則", "is_correct": true, "explanation": "「原則に例外を認めすぎると」と続けられるのは、基本的なきまりを表す原則だけ。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の状態で、「天気に例外を認めすぎると」は意味が通らない。"}, {"text": "食卓", "is_correct": false, "explanation": "食卓は食事をする台で、「食卓に例外を認めすぎると」は成り立たない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機は家電で、例外を認める対象として文が成り立たない。"}], "explanations": {"原則": "「原則に例外を認めすぎると」と続けられるのは、基本的なきまりを表す原則だけ。", "天気": "天気は空の状態で、「天気に例外を認めすぎると」は意味が通らない。", "食卓": "食卓は食事をする台で、「食卓に例外を認めすぎると」は成り立たない。", "洗濯機": "洗濯機は家電で、例外を認める対象として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "原則"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "裁判で、原則が被告を訴えた。", "explanation": "ここは〈原告〉（訴えを起こす人）の意味。訴えを起こすのは原告で、きまりを表す原則は訴える主体にならないので合わない。"}, {"text": "この論文の原則は、実験で確かめられた事実だ。", "explanation": "ここは〈結論〉の意味。論文の最後にたどり着く判断は、基本的なきまりや方針を指す原則とは合わない。"}, {"text": "この油田では、良質な原則が採れる。", "explanation": "ここは〈原油〉の意味。原則は決まりや方針を表す語で、油田から採れる物質ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38839, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "平等の原則が、社員全員で共有する。", "corrected_sentence": "平等の原則を、社員全員で共有する。", "error_description": "「共有する」の目的語は「原則」なので「を」が正しい。「が」は主語を表すため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38839, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "原則を守るば、判断がぶれない。", "corrected_sentence": "原則を守れば、判断がぶれない。", "error_description": "「守る」の仮定形は「守れば」が正しい。「守るば」は活用の誤りで成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f9513c-6780-4b7b-9492-de43d4fd5af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38840, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ごみを排除する」の「を」で、取り除く対象を示す。排除の直前に来る正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「ごみが排除する」だと、ごみが取り除く側（主語）になり、意味が反転する。"}, {"text": "に", "is_correct": false, "explanation": "「ごみに排除する」は、取り除く相手として不自然で、対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「ごみと排除する」は一緒に取り除くという不自然な並列になり、対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「ごみを排除する」の「を」で、取り除く対象を示す。排除の直前に来る正しい助詞。", "が": "「ごみが排除する」だと、ごみが取り除く側（主語）になり、意味が反転する。", "に": "「ごみに排除する」は、取り除く相手として不自然で、対象を示せない。", "と": "「ごみと排除する」は一緒に取り除くという不自然な並列になり、対象を示せない。"}, "error_tags": {"が": "主語を示す", "に": "位置・相手", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38840, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「雑音を排除すれば」の「を」で、取り除く対象を示す。排除の直前に来る正しい助詞。"}, {"text": "で", "is_correct": false, "explanation": "「雑音で排除すれば」は手段の意味になり、取り除く対象を示せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す助詞で、「雑音より排除」は取り除く対象にならず意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「雑音の排除すれば」は動詞に正しく続かず、文法的に不自然。"}], "correct_answer": "を", "explanations": {"を": "「雑音を排除すれば」の「を」で、取り除く対象を示す。排除の直前に来る正しい助詞。", "で": "「雑音で排除すれば」は手段の意味になり、取り除く対象を示せず不自然。", "より": "比較を示す助詞で、「雑音より排除」は取り除く対象にならず意味が通らない。", "の": "「雑音の排除すれば」は動詞に正しく続かず、文法的に不自然。"}, "error_tags": {"で": "手段", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38840, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "いらないものを、のけること。", "primary_collocate": null, "pronunciation": "はいじょ", "ipa": "haidʑo", "syllable_count": 3, "sentences": [{"text": "畑の雑草を排除しないと、野菜がうまく育たない。", "target_word": "排除", "complexity_tier": "T3", "furigana": "畑[はたけ]の雑草[ざっそう]を排除[はいじょ]しないと、野菜[やさい]がうまく育[そだ]たない。", "sentence_source": "generated"}, {"text": "川にたまったごみを排除する作業が続いている。", "target_word": "排除", "complexity_tier": "T3", "furigana": "川[かわ]にたまったごみを排除[はいじょ]する作業[さぎょう]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "水の中の不純物を排除するために、特別なフィルターを使う。", "target_word": "排除", "complexity_tier": "T3", "furigana": "水[みず]の中[なか]の不純物[ふじゅんぶつ]を排除[はいじょ]するために、特別[とくべつ]なフィルターを使[つか]う。", "sentence_source": "generated"}, {"text": "事故の原因になりそうな危険物の排除が最優先だ。", "target_word": "排除", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]になりそうな危険物[きけんぶつ]の排除[はいじょ]が最優先[さいゆうせん]だ。", "sentence_source": "generated"}, {"text": "機械から余分な熱を排除する仕組みを考えた。", "target_word": "排除", "complexity_tier": "T3", "furigana": "機械[きかい]から余分[よぶん]な熱[ねつ]を排除[はいじょ]する仕組[しく]みを考[かんが]えた。", "sentence_source": "generated"}, {"text": "工事の邪魔になる石を排除したので、道が通れるようになった。", "target_word": "排除", "complexity_tier": "T3", "furigana": "工事[こうじ]の邪魔[じゃま]になる石[いし]を排除[はいじょ]したので、道[みち]が通[とお]れるようになった。", "sentence_source": "generated"}, {"text": "食品から有害な物質を排除するため、工場では製造の手順を見直している。", "target_word": "排除", "complexity_tier": "T3", "furigana": "食品[しょくひん]から有害[ゆうがい]な物質[ぶっしつ]を排除[はいじょ]するため、工場[こうじょう]では製造[せいぞう]の手順[てじゅん]を見直[みなお]している。", "sentence_source": "generated"}, {"text": "雑音を排除すれば、この録音はもっと聞きやすくなる。", "target_word": "排除", "complexity_tier": "T3", "furigana": "雑音[ざつおん]を排除[はいじょ]すれば、この録音[ろくおん]はもっと聞[き]きやすくなる。", "sentence_source": "generated"}, {"text": "無駄な作業を排除した結果、仕事が一時間早く終わった。", "target_word": "排除", "complexity_tier": "T3", "furigana": "無駄[むだ]な作業[さぎょう]を排除[はいじょ]した結果[けっか]、仕事[しごと]が一時間[いちじかん]早[はや]く終[お]わった。", "sentence_source": "generated"}, {"text": "池の外来魚を排除する活動に、地元の人が参加した。", "target_word": "排除", "complexity_tier": "T3", "furigana": "池[いけ]の外来魚[がいらいぎょ]を排除[はいじょ]する活動[かつどう]に、地元[じもと]の人[ひと]が参加[さんか]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "排除する", "label": "辞書形"}, {"form": "排除した", "label": "過去形"}, {"form": "排除しない", "label": "否定形"}, {"form": "排除される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "不要なものや邪魔なものを取り除くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44bb0fd-3452-43af-b204-23fdee287513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38840, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排除", "is_correct": true, "explanation": "取り除くという意味で、畑の雑草を取り除かないと野菜が育たない、という文脈に合う。"}, {"text": "収穫", "is_correct": false, "explanation": "実った作物を取り入れる意味。雑草を収穫するという文は成り立たない。"}, {"text": "施肥", "is_correct": false, "explanation": "作物に肥料をまく意味。雑草を施肥しても野菜が育つ理屈にならず、文脈に合わない。"}, {"text": "散布", "is_correct": false, "explanation": "薬剤などを広くまく意味。雑草を散布しないという文は、取り除く流れと合わない。"}], "explanations": {"排除": "取り除くという意味で、畑の雑草を取り除かないと野菜が育たない、という文脈に合う。", "収穫": "実った作物を取り入れる意味。雑草を収穫するという文は成り立たない。", "施肥": "作物に肥料をまく意味。雑草を施肥しても野菜が育つ理屈にならず、文脈に合わない。", "散布": "薬剤などを広くまく意味。雑草を散布しないという文は、取り除く流れと合わない。"}, "sentence_index": 0, "correct_answer": "排除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい夢を排除して、その夢を追い続けた。", "explanation": "排除は取り除く語なので、夢を追い続けるという文と矛盾する。"}, {"text": "大事な部品を排除して、機械に組み込んだ。", "explanation": "排除は取り除くことなので、部品を組み込む文と矛盾する。"}, {"text": "大切な書類を排除して、金庫にしまった。", "explanation": "排除は取り除く語なので、大切な書類を金庫にしまう文と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38840, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排除", "is_correct": true, "explanation": "取り除くという意味で、有害な物質を取り除くため手順を見直す、という文脈に合う。"}, {"text": "販売", "is_correct": false, "explanation": "商品として売る意味。有害な物質を販売するという文は、取り除く目的と合わない。"}, {"text": "栽培", "is_correct": false, "explanation": "植物を育てる意味で、物質には使わない。文脈に合わない。"}, {"text": "脱穀", "is_correct": false, "explanation": "穀物から実を取り出す作業。有害な物質には使えず、文脈に合わない。"}], "explanations": {"排除": "取り除くという意味で、有害な物質を取り除くため手順を見直す、という文脈に合う。", "販売": "商品として売る意味。有害な物質を販売するという文は、取り除く目的と合わない。", "栽培": "植物を育てる意味で、物質には使わない。文脈に合わない。", "脱穀": "穀物から実を取り出す作業。有害な物質には使えず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "排除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "池で育てている鯉を排除して、大事に世話をした。", "explanation": "排除は取り除く語なので、大事に世話をする文と矛盾する。"}, {"text": "絶滅しそうな魚を排除して、大切に守った。", "explanation": "排除は取り除く語なので、大切に守る文と矛盾する。"}, {"text": "池に稚魚を排除して、川から運び込んだ。", "explanation": "排除は取り除く語なので、稚魚を運び込む文と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38840, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池にたまった藻に排除する作業が、今日も続いている。", "corrected_sentence": "池にたまった藻を排除する作業が、今日も続いている。", "error_description": "「排除する」は取り除く対象を「を」で示すため、「藻に」は誤り。正しくは「藻を排除する」。「に」は相手や場所を表し、目的語にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38840, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ダムの中の土砂を排除る工事が、来月から始まる。", "corrected_sentence": "ダムの中の土砂を排除する工事が、来月から始まる。", "error_description": "「排除る」は「排除する」の「する」が抜けた誤り。サ変動詞の正しい形は「排除する」で、名詞の後に続けて動詞として活用させる必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38841, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「仲間に排除され」の「に」で、排除される相手や起点を示す。正しい助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「仲間へ排除され」は方向を表すため、排除される関係にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「仲間と排除され」は並列の意味になり、排除の相手を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「仲間の排除され」は名詞を修飾する形で、受身の動詞に続かず不自然。"}], "correct_answer": "に", "explanations": {"に": "「仲間に排除され」の「に」で、排除される相手や起点を示す。正しい助詞。", "へ": "「仲間へ排除され」は方向を表すため、排除される関係にならず不自然。", "と": "「仲間と排除され」は並列の意味になり、排除の相手を示せない。", "の": "「仲間の排除され」は名詞を修飾する形で、受身の動詞に続かず不自然。"}, "error_tags": {"へ": "方向", "と": "並列", "の": "連体修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "包含", "is_correct": true, "explanation": "社会的排除の対義語として使われ、外さずに中に含めるという意味で、排除と反対の関係にある。"}, {"text": "運搬", "is_correct": false, "explanation": "物を別の場所へ運ぶ意味で、排除の対義語ではない。"}, {"text": "測量", "is_correct": false, "explanation": "土地の広さや位置を測る意味で、排除の対義語ではない。"}, {"text": "翻訳", "is_correct": false, "explanation": "ある言語の文を別の言語に置き換える意味で、排除の対義語ではない。"}], "correct_answer": "包含", "explanations": {"包含": "社会的排除の対義語として使われ、外さずに中に含めるという意味で、排除と反対の関係にある。", "運搬": "物を別の場所へ運ぶ意味で、排除の対義語ではない。", "測量": "土地の広さや位置を測る意味で、排除の対義語ではない。", "翻訳": "ある言語の文を別の言語に置き換える意味で、排除の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38841, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「その人を排除して」の「を」で、取り除く対象を示す。排除の直前に来る正しい助詞。"}, {"text": "で", "is_correct": false, "explanation": "「その人で排除してはいけない」は手段の意味になり、対象を示せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「その人より排除」は取り除く対象にならず意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「その人の排除してはいけない」は動詞に正しく続かず、文法的に不自然。"}], "correct_answer": "を", "explanations": {"を": "「その人を排除して」の「を」で、取り除く対象を示す。排除の直前に来る正しい助詞。", "で": "「その人で排除してはいけない」は手段の意味になり、対象を示せず不自然。", "より": "比較の助詞で、「その人より排除」は取り除く対象にならず意味が通らない。", "の": "「その人の排除してはいけない」は動詞に正しく続かず、文法的に不自然。"}, "error_tags": {"で": "手段", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "包含", "is_correct": true, "explanation": "社会的排除の対義語として使われ、外さずに中に含めるという意味で、排除と反対の関係にある。"}, {"text": "印刷", "is_correct": false, "explanation": "文字や図を紙に刷る意味で、排除の対義語ではない。"}, {"text": "採掘", "is_correct": false, "explanation": "地中から鉱物を掘り出す意味で、排除の対義語ではない。"}, {"text": "寄付", "is_correct": false, "explanation": "金品を贈る意味で、排除とは反対の関係として扱われない。"}], "correct_answer": "包含", "explanations": {"包含": "社会的排除の対義語として使われ、外さずに中に含めるという意味で、排除と反対の関係にある。", "印刷": "文字や図を紙に刷る意味で、排除の対義語ではない。", "採掘": "地中から鉱物を掘り出す意味で、排除の対義語ではない。", "寄付": "金品を贈る意味で、排除とは反対の関係として扱われない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38841, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある集団や範囲から取り除くこと。除外すること。", "primary_collocate": null, "pronunciation": "はいじょ", "ipa": "haidʑo", "syllable_count": 3, "sentences": [{"text": "会議から反対する人を排除するのは、公平ではない。", "target_word": "排除", "complexity_tier": "T3", "furigana": "会議[かいぎ]から反対[はんたい]する人[ひと]を排除[はいじょ]するのは、公平[こうへい]ではない。", "sentence_source": "generated"}, {"text": "彼は仲間に排除され、一人で昼食を食べていた。", "target_word": "排除", "complexity_tier": "T3", "furigana": "彼[かれ]は仲間[なかま]に排除[はいじょ]され、一人[ひとり]で昼食[ちゅうしょく]を食[た]べていた。", "sentence_source": "generated"}, {"text": "外国人を排除する考え方は、今の社会に合わない。", "target_word": "排除", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]を排除[はいじょ]する考[かんが]え方[かた]は、今[いま]の社会[しゃかい]に合[あ]わない。", "sentence_source": "generated"}, {"text": "犯人の可能性を排除せずに、捜査を続けている。", "target_word": "排除", "complexity_tier": "T3", "furigana": "犯人[はんにん]の可能性[かのうせい]を排除[はいじょ]せずに、捜査[そうさ]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "候補者の名簿から、規則に違反した人が排除された。", "target_word": "排除", "complexity_tier": "T3", "furigana": "候補者[こうほしゃ]の名簿[めいぼ]から、規則[きそく]に違反[いはん]した人[ひと]が排除[はいじょ]された。", "sentence_source": "generated"}, {"text": "病気の原因として、ウイルスの可能性は排除できない。", "target_word": "排除", "complexity_tier": "T3", "furigana": "病気[びょうき]の原因[げんいん]として、ウイルスの可能性[かのうせい]は排除[はいじょ]できない。", "sentence_source": "generated"}, {"text": "特定の会社を排除した入札は、問題になった。", "target_word": "排除", "complexity_tier": "T3", "furigana": "特定[とくてい]の会社[かいしゃ]を排除[はいじょ]した入札[にゅうさつ]は、問題[もんだい]になった。", "sentence_source": "generated"}, {"text": "意見が違うからといって、その人を排除してはいけない。", "target_word": "排除", "complexity_tier": "T3", "furigana": "意見[いけん]が違[ちが]うからといって、その人[ひと]を排除[はいじょ]してはいけない。", "sentence_source": "generated"}, {"text": "新しいメンバーを排除する雰囲気が、チームにあった。", "target_word": "排除", "complexity_tier": "T3", "furigana": "新[あたら]しいメンバーを排除[はいじょ]する雰囲気[ふんいき]が、チームにあった。", "sentence_source": "generated"}, {"text": "少数派の排除をなくすため、学校は話し合いの場を作った。", "target_word": "排除", "complexity_tier": "T3", "furigana": "少数派[しょうすうは]の排除[はいじょ]をなくすため、学校[がっこう]は話[はなし]し合[あ]いの場[ば]を作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "排除する", "label": "辞書形"}, {"form": "排除した", "label": "過去形"}, {"form": "排除しない", "label": "否定形"}, {"form": "排除される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "人や可能性を集団や範囲から外して除くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44bb0fd-3452-43af-b204-23fdee287513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38841, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排除", "is_correct": true, "explanation": "集団から外して除く意味で、反対する人を会議から外すのは公平ではない、という文脈に合う。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつける意味。人を会議から外す文脈には合わない。"}, {"text": "配布", "is_correct": false, "explanation": "配って渡す意味。反対する人を配るという文は意味が通らない。"}, {"text": "乾杯", "is_correct": false, "explanation": "杯を上げて祝う動作。会議から人を外す文脈とは合わない。"}], "explanations": {"排除": "集団から外して除く意味で、反対する人を会議から外すのは公平ではない、という文脈に合う。", "採点": "点数をつける意味。人を会議から外す文脈には合わない。", "配布": "配って渡す意味。反対する人を配るという文は意味が通らない。", "乾杯": "杯を上げて祝う動作。会議から人を外す文脈とは合わない。"}, "sentence_index": 0, "correct_answer": "排除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい仲間を排除して、歓迎会を開いた。", "explanation": "排除は取り除く語なので、歓迎会を開く文と矛盾する。"}, {"text": "新しい社員を排除して、採用を決めた。", "explanation": "排除は取り除く語なので、社員を採用する文と矛盾する。"}, {"text": "新しい会員を排除して、みんなで招待状を送った。", "explanation": "排除は取り除く語なので、会員に招待状を送る文と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38841, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排除", "is_correct": true, "explanation": "集団から外して除く意味で、特定の会社を外した入札が問題になった、という文脈に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "言葉を別の言語に置き換える意味。会社を翻訳するという文は成り立たない。"}, {"text": "採寸", "is_correct": false, "explanation": "寸法を測る意味。会社を採寸するという文は意味が通らない。"}, {"text": "焼却", "is_correct": false, "explanation": "燃やして処分する意味。会社を焼却する入札という文は文脈と合わない。"}], "explanations": {"排除": "集団から外して除く意味で、特定の会社を外した入札が問題になった、という文脈に合う。", "翻訳": "言葉を別の言語に置き換える意味。会社を翻訳するという文は成り立たない。", "採寸": "寸法を測る意味。会社を採寸するという文は意味が通らない。", "焼却": "燃やして処分する意味。会社を焼却する入札という文は文脈と合わない。"}, "sentence_index": 6, "correct_answer": "排除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "少数派を排除して、少数派を守る制度を作った。", "explanation": "排除は取り除く語なので、少数派を守る制度の文と矛盾する。"}, {"text": "困っている人を排除して、救済策を広げた。", "explanation": "排除は取り除く語なので、救済策を広げる文と矛盾する。"}, {"text": "友達の笑顔を排除して、楽しく話をした。", "explanation": "排除は取り除く語なので、笑顔で楽しく話す文と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38841, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "意見の違う人に排除せずに、話し合いを続けた。", "corrected_sentence": "意見の違う人を排除せずに、話し合いを続けた。", "error_description": "「排除する」は取り除く対象を「を」で取るため、「人に」は誤り。正しくは「人を排除せずに」。「に」では取り除く相手を示せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38841, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その候補者は、規則違反を理由に排除られた。", "corrected_sentence": "その候補者は、規則違反を理由に排除された。", "error_description": "「排除られた」は誤った受身形。サ変動詞「排除する」の受身は「排除される」なので、「排除された」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38842, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「粉末の」は名詞を修飾する「の」で、『粉末のスープ』として自然。"}, {"text": "を", "is_correct": false, "explanation": "「粉末を」とすると「を」が二つ並び、『スープに熱いお湯を入れる』の文が成り立たないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「粉末が」とすると粉末が主語になり、お湯を入れる動作の主体と合わないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、粉末の所属を示す位置には合わないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「粉末の」は名詞を修飾する「の」で、『粉末のスープ』として自然。", "を": "「粉末を」とすると「を」が二つ並び、『スープに熱いお湯を入れる』の文が成り立たないので合わない。", "が": "「粉末が」とすると粉末が主語になり、お湯を入れる動作の主体と合わないので合わない。", "へ": "「へ」は方向を表すが、粉末の所属を示す位置には合わないので合わない。"}, "error_tags": {"を": "目的語の重複", "が": "主語の不一致", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38842, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この粉末は」と主題を示す「は」で、後ろの『細かすぎて』の主題として自然。"}, {"text": "に", "is_correct": false, "explanation": "「この粉末に細かすぎて」では後ろの述語と結びつかず、文が成り立たないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すが、「この粉末から細かすぎて」は意味が通らないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表すが、「この粉末と細かすぎて」は意味が通らないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「この粉末は」と主題を示す「は」で、後ろの『細かすぎて』の主題として自然。", "に": "「この粉末に細かすぎて」では後ろの述語と結びつかず、文が成り立たないので合わない。", "から": "「から」は起点を表すが、「この粉末から細かすぎて」は意味が通らないので合わない。", "と": "「と」は並列を表すが、「この粉末と細かすぎて」は意味が通らないので合わない。"}, "error_tags": {"に": "結果・位置", "から": "起点", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38842, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "こなのように、とても細かいものです。", "primary_collocate": null, "pronunciation": "ふんまつ", "ipa": "ɸɯmmatsɯ", "syllable_count": 4, "sentences": [{"text": "この薬は粉末なので、水に溶かして飲みます。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "この薬[くすり]は粉末[ふんまつ]なので、水[みず]に溶[と]かして飲[の]みます。", "sentence_source": "generated"}, {"text": "粉末のスープに熱いお湯を入れました。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "粉末[ふんまつ]のスープに熱[あつ]いお湯[ゆ]を入[い]れました。", "sentence_source": "generated"}, {"text": "緑茶を粉末にして、お菓子に混ぜます。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "緑茶[りょくちゃ]を粉末[ふんまつ]にして、お菓子[かし]に混[ま]ぜます。", "sentence_source": "generated"}, {"text": "粉末は軽いので、風が吹くと飛んでしまいます。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "粉末[ふんまつ]は軽[かる]いので、風[かぜ]が吹[ふ]くと飛[と]んでしまいます。", "sentence_source": "generated"}, {"text": "粉末のジュースは、水を入れるだけで作れます。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "粉末[ふんまつ]のジュースは、水[みず]を入[い]れるだけで作[つく]れます。", "sentence_source": "generated"}, {"text": "弟は粉末の薬が苦手で、いつも錠剤をもらいます。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "弟[おとうと]は粉末[ふんまつ]の薬[くすり]が苦手[にがて]で、いつも錠剤[じょうざい]をもらいます。", "sentence_source": "generated"}, {"text": "粉末の洗剤を使うと、服が白くなります。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "粉末[ふんまつ]の洗剤[せんざい]を使[つか]うと、服[ふく]が白[しろ]くなります。", "sentence_source": "generated"}, {"text": "この粉末は細かすぎて、手で触るとすぐ広がってしまいます。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "この粉末[ふんまつ]は細[こま]かすぎて、手[て]で触[さわ]るとすぐ広[ひろ]がってしまいます。", "sentence_source": "generated"}, {"text": "粉末ではなく、固形のスープを買いました。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "粉末[ふんまつ]ではなく、固形[こけい]のスープを買[か]いました。", "sentence_source": "generated"}, {"text": "粉末のコーヒーは、豆から入れるものより手軽です。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "粉末[ふんまつ]のコーヒーは、豆[まめ]から入[い]れるものより手軽[てがる]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "粉末", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "こなのように非常に細かい状態のもの。薬・スープ・洗剤などの粉状の製品を指す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce196816-dc31-4b51-9de7-173ff8500542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38842, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粉末", "is_correct": true, "explanation": "水に溶かして飲む薬の形状を表す語で、この文に合う。"}, {"text": "湿布", "is_correct": false, "explanation": "湿布は皮膚に貼る薬で、水に溶かして飲むものではないので合わない。"}, {"text": "軟膏", "is_correct": false, "explanation": "軟膏は皮膚に塗る薬で、水に溶かして飲むことはできないので合わない。"}, {"text": "坐薬", "is_correct": false, "explanation": "坐薬は体内に入れる薬で、水に溶かして飲むものではないので合わない。"}], "explanations": {"粉末": "水に溶かして飲む薬の形状を表す語で、この文に合う。", "湿布": "湿布は皮膚に貼る薬で、水に溶かして飲むものではないので合わない。", "軟膏": "軟膏は皮膚に塗る薬で、水に溶かして飲むことはできないので合わない。", "坐薬": "坐薬は体内に入れる薬で、水に溶かして飲むものではないので合わない。"}, "sentence_index": 0, "correct_answer": "粉末"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このお米は粉末なので、よく洗ってから炊きます。", "explanation": "ここは〈粒〉の意味。お米は粒状のものなので、粉末とは言わず合わない。"}, {"text": "今朝は粉末が降って、道が真っ白になりました。", "explanation": "ここは〈粉雪〉の意味。空から降る細かい雪は粉雪であって、粉末とは言わないので合わない。"}, {"text": "水は粉末で、コップに注ぎます。", "explanation": "ここは〈液体〉の意味。水は液体なので、粉末とは言わず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38842, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粉末", "is_correct": true, "explanation": "粉状の洗剤を表す語で、『粉末の洗剤』として自然に合う。"}, {"text": "洗濯物", "is_correct": false, "explanation": "「洗濯物の洗剤」では洗われる対象が洗剤になり、意味が通らないので合わない。"}, {"text": "柔軟剤", "is_correct": false, "explanation": "柔軟剤は衣類をやわらかくする別の製品で、洗剤の形状を表す語ではないので合わない。"}, {"text": "歯磨き", "is_correct": false, "explanation": "歯磨きは口の中に使うもので、洗濯の洗剤の種類にはならないので合わない。"}], "explanations": {"粉末": "粉状の洗剤を表す語で、『粉末の洗剤』として自然に合う。", "洗濯物": "「洗濯物の洗剤」では洗われる対象が洗剤になり、意味が通らないので合わない。", "柔軟剤": "柔軟剤は衣類をやわらかくする別の製品で、洗剤の形状を表す語ではないので合わない。", "歯磨き": "歯磨きは口の中に使うもので、洗濯の洗剤の種類にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "粉末"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "粉末を手でちぎって、スープに入れます。", "explanation": "ここは〈塊〉の意味。ちぎれるのはパンのような塊で、細かい粉末は塊ではないので合わない。"}, {"text": "粉末で、マフラーを編みます。", "explanation": "ここは〈毛糸〉の意味。マフラーを作る材料は毛糸などの糸で、細かい粉末では編めないので合わない。"}, {"text": "風邪薬は、粉末を一錠ずつ飲みます。", "explanation": "ここは〈錠剤〉の意味。〈一錠〉は錠剤を数える語で、粉末には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38842, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このお茶は、粉末に売っています。", "corrected_sentence": "このお茶は、粉末で売っています。", "error_description": "誤: 粉末に売る → 正: 粉末で売る。形状・方法を示す『で』が正しく、『に』は文として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38842, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この粉末を、お湯を少し入れてください。", "corrected_sentence": "この粉末に、お湯を少し入れてください。", "error_description": "誤: 粉末を → 正: 粉末に。『粉末にお湯を入れる』は『に』が正しく、『を』だと目的語が二つ並ぶ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38843, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「銀色の粉末」と名詞を修飾する「の」で、粉末の色を示して自然。"}, {"text": "を", "is_correct": false, "explanation": "「銀色を粉末を」では「を」が二つ並び、『粉末を集める』の文として成り立たないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「銀色へ粉末を集め」は方向として意味が通らないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「銀色が粉末を集めました」では銀色が集める主体になり、文が成り立たないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「銀色の粉末」と名詞を修飾する「の」で、粉末の色を示して自然。", "を": "「銀色を粉末を」では「を」が二つ並び、『粉末を集める』の文として成り立たないので合わない。", "へ": "「銀色へ粉末を集め」は方向として意味が通らないので合わない。", "が": "「銀色が粉末を集めました」では銀色が集める主体になり、文が成り立たないので合わない。"}, "error_tags": {"を": "目的語の重複", "へ": "方向", "が": "主語の不一致"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38843, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「灰色の粉末」と名詞を修飾する「の」で、粉末の色を示して自然。"}, {"text": "に", "is_correct": false, "explanation": "「灰色に粉末を作ります」では結果を表す「に」が合わず、意味が通らないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「灰色と粉末を作ります」は並列になり、意味が通らないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「灰色より粉末を作ります」は文の流れに合わないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「灰色の粉末」と名詞を修飾する「の」で、粉末の色を示して自然。", "に": "「灰色に粉末を作ります」では結果を表す「に」が合わず、意味が通らないので合わない。", "と": "「灰色と粉末を作ります」は並列になり、意味が通らないので合わない。", "より": "「より」は比較を表すので、「灰色より粉末を作ります」は文の流れに合わないので合わない。"}, "error_tags": {"に": "結果", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38843, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "固体が細かく砕けて、粉のようになったもの。", "primary_collocate": null, "pronunciation": "ふんまつ", "ipa": "ɸɯmmatsɯ", "syllable_count": 4, "sentences": [{"text": "石を細かく砕くと、白い粉末になりました。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "石[いし]を細[こま]かく砕[くだ]くと、白[しろ]い粉末[ふんまつ]になりました。", "sentence_source": "generated"}, {"text": "実験で金属を削って、銀色の粉末を集めました。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "実験[じっけん]で金属[きんぞく]を削[けず]って、銀色[ぎんいろ]の粉末[ふんまつ]を集[あつ]めました。", "sentence_source": "generated"}, {"text": "貝がらを砕いた粉末は、肥料に使われます。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "貝[かい]がらを砕[くだ]いた粉末[ふんまつ]は、肥料[ひりょう]に使[つか]われます。", "sentence_source": "generated"}, {"text": "机の上に落ちた粉末を、ほうきで集めました。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に落[お]ちた粉末[ふんまつ]を、ほうきで集[あつ]めました。", "sentence_source": "generated"}, {"text": "チョークが折れて、床に白い粉末が散らばりました。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "チョークが折[お]れて、床[ゆか]に白[しろ]い粉末[ふんまつ]が散[ち]らばりました。", "sentence_source": "generated"}, {"text": "骨を砕いて粉末にし、畑にまくことがあります。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "骨[ほね]を砕[くだ]いて粉末[ふんまつ]にし、畑[はたけ]にまくことがあります。", "sentence_source": "generated"}, {"text": "先生は固い塩の塊をすりつぶして、粉末にしました。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "先生[せんせい]は固[かた]い塩[しお]の塊[かたまり]をすりつぶして、粉末[ふんまつ]にしました。", "sentence_source": "generated"}, {"text": "岩を機械で砕いて、灰色の粉末を作ります。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "岩[いわ]を機械[きかい]で砕[くだ]いて、灰色[はいいろ]の粉末[ふんまつ]を作[つく]ります。", "sentence_source": "generated"}, {"text": "粉末が目に入ったので、水で洗いました。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "粉末[ふんまつ]が目[め]に入[はい]ったので、水[みず]で洗[あら]いました。", "sentence_source": "generated"}, {"text": "木を削ると、細かい粉末が出ます。", "target_word": "粉末", "complexity_tier": "T3", "furigana": "木[き]を削[けず]ると、細[こま]かい粉末[ふんまつ]が出[で]ます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "粉末", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "石・金属・骨などの固体を砕いたり削ったりしてできた、粉状になったもの。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce196816-dc31-4b51-9de7-173ff8500542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38843, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粉末", "is_correct": true, "explanation": "石を砕いてできる粉状のものを表し、この文に合う。"}, {"text": "液体", "is_correct": false, "explanation": "石を砕いても液体にはならないので合わない。"}, {"text": "氷", "is_correct": false, "explanation": "石を砕いても氷にはならないので合わない。"}, {"text": "布", "is_correct": false, "explanation": "石を砕いても布にはならないので合わない。"}], "explanations": {"粉末": "石を砕いてできる粉状のものを表し、この文に合う。", "液体": "石を砕いても液体にはならないので合わない。", "氷": "石を砕いても氷にはならないので合わない。", "布": "石を砕いても布にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "粉末"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "石の粉末を、ハンマーで割りました。", "explanation": "ここは〈塊〉の意味。石の塊なら砕けるが、細かい粉末は塊ではないので合わない。"}, {"text": "机の上に落ちた粉末を、一切れずつ切り分けました。", "explanation": "ここは〈ケーキ〉の意味。ケーキは固まりを分けて食べるが、細かい粉末は固まりではないので合わない。"}, {"text": "机の上に落ちた粉末を、雑巾で絞りました。", "explanation": "ここは〈濡れた布〉の意味。水を含んだ布のように水気があるものが対象で、乾いた粉末は水気がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38843, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粉末", "is_correct": true, "explanation": "すりつぶした結果として細かい粉状になったものを表し、この文に合う。"}, {"text": "灰", "is_correct": false, "explanation": "灰は燃やした後に残るもので、すりつぶしてできるものではないので合わない。"}, {"text": "塊", "is_correct": false, "explanation": "すりつぶすと細かくなるので、塊になるとは言わないので合わない。"}, {"text": "煙", "is_correct": false, "explanation": "煙は気体として立ちのぼるもので、すりつぶして作るものではないので合わない。"}], "explanations": {"粉末": "すりつぶした結果として細かい粉状になったものを表し、この文に合う。", "灰": "灰は燃やした後に残るもので、すりつぶしてできるものではないので合わない。", "塊": "すりつぶすと細かくなるので、塊になるとは言わないので合わない。", "煙": "煙は気体として立ちのぼるもので、すりつぶして作るものではないので合わない。"}, "sentence_index": 6, "correct_answer": "粉末"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "粉末を、丸ごとかじります。", "explanation": "ここは〈果物〉の意味。果物は固い食べ物で、細かい粉末はそのように食べるものではないので合わない。"}, {"text": "粉末を編んで、マフラーを作ります。", "explanation": "ここは〈羊毛〉の意味。マフラーを作る材料は羊毛などの糸で、細かい粉末では作れないので合わない。"}, {"text": "粉末を一本、削ります。", "explanation": "ここは〈鉛筆〉の意味。〈一本〉は細長い物を数える語で、粉末には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38843, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鉄を削って、粉末を作るします。", "corrected_sentence": "鉄を削って、粉末を作ります。", "error_description": "誤: 作るします → 正: 作ります。動詞の辞書形に『ます』は続かず、連用形『作り』にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38843, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "卵の殻を砕いて、粉末をします。", "corrected_sentence": "卵の殻を砕いて、粉末にします。", "error_description": "誤: 粉末を → 正: 粉末に。『〜にします』の『に』が正しく、『を』は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
