INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38844, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「真ん中から」の「から」で、割れ始める起点を示して自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、起点を表す文脈には合わないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「真ん中より割れて」は意味が通らないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「真ん中の割れて」は名詞修飾となり、文として成り立たないので合わない。"}], "correct_answer": "から", "explanations": {"から": "「真ん中から」の「から」で、割れ始める起点を示して自然。", "へ": "「へ」は方向を示すが、起点を表す文脈には合わないので合わない。", "より": "「より」は比較を表すので、「真ん中より割れて」は意味が通らないので合わない。", "の": "「真ん中の割れて」は名詞修飾となり、文として成り立たないので合わない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "名詞修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38844, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物が力を加えられて、いくつかの小さな部分に分かれること。", "primary_collocate": null, "pronunciation": "われる", "ipa": "waɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "落としたお皿が、三つに割れました。", "target_word": "割れ", "complexity_tier": "T3", "furigana": "落[お]としたお皿[さら]が、三[みっ]つに割[わ]れました。", "sentence_source": "generated"}, {"text": "氷にお湯をかけると、ぴしっと割れます。", "target_word": "割れ", "complexity_tier": "T3", "furigana": "氷[こおり]にお湯[ゆ]をかけると、ぴしっと割[わ]れます。", "sentence_source": "generated"}, {"text": "卵は力を入れすぎると割れるので、そっと持ってください。", "target_word": "割れる", "complexity_tier": "T3", "furigana": "卵[たまご]は力[ちから]を入[い]れすぎると割[わ]れるので、そっと持[も]ってください。", "sentence_source": "generated"}, {"text": "地震で道路が割れて、車が通れなくなりました。", "target_word": "割れて", "complexity_tier": "T3", "furigana": "地震[じしん]で道路[どうろ]が割[わ]れて、車[くるま]が通[とお]れなくなりました。", "sentence_source": "generated"}, {"text": "固いクッキーは、手で押すと二つに割れます。", "target_word": "割れ", "complexity_tier": "T3", "furigana": "固[かた]いクッキーは、手[て]で押[お]すと二[ふた]つに割[わ]れます。", "sentence_source": "generated"}, {"text": "熟したスイカは、切らなくても自然に割れることがあります。", "target_word": "割れる", "complexity_tier": "T3", "furigana": "熟[じゅく]したスイカは、切[き]らなくても自然[しぜん]に割[わ]れることがあります。", "sentence_source": "generated"}, {"text": "寒い日にコップに熱いお湯を入れたら、割れてしまいました。", "target_word": "割れて", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]にコップに熱[あつ]いお湯[ゆ]を入[い]れたら、割[わ]れてしまいました。", "sentence_source": "generated"}, {"text": "木の板が真ん中から割れて、使えなくなりました。", "target_word": "割れて", "complexity_tier": "T3", "furigana": "木[き]の板[いた]が真[ま]ん中[なか]から割[わ]れて、使[つか]えなくなりました。", "sentence_source": "generated"}, {"text": "根が育ちすぎて、植木鉢が割れました。", "target_word": "割れ", "complexity_tier": "T3", "furigana": "根[ね]が育[そだ]ちすぎて、植木鉢[うえきばち]が割[わ]れました。", "sentence_source": "generated"}, {"text": "割れた茶碗を、接着剤でつなぎました。", "target_word": "割れた", "complexity_tier": "T3", "furigana": "割[わ]れた茶碗[ちゃわん]を、接着剤[せっちゃくざい]でつなぎました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "割れる", "label": "辞書形"}, {"form": "割れます", "label": "丁寧形"}, {"form": "割れない", "label": "否定形"}, {"form": "割れた", "label": "過去形"}, {"form": "割れて", "label": "て形"}], "register": "丁寧", "sense_fingerprint": "皿・氷・板などの物が力で二つ以上の部分に分かれる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T4: contains vocabulary far above tier T4: ぴしっと (Zipf 1.32)']::text[], 'ce196816-dc31-4b51-9de7-173ff8500542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38844, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "割れ", "is_correct": true, "explanation": "「割れ」＋「ました」で、お皿が分かれる動作を表し、この文に合う。"}, {"text": "割り", "is_correct": false, "explanation": "割るは他動詞で、お皿が主語の文には合わないので合わない。"}, {"text": "折れ", "is_correct": false, "explanation": "折れるは棒状のものが曲がって切れる意味で、皿が分かれる文には合わないので合わない。"}, {"text": "濡れ", "is_correct": false, "explanation": "濡れるは水にぬれる意味で、割れて分かれる文の結果には合わないので合わない。"}], "explanations": {"割れ": "「割れ」＋「ました」で、お皿が分かれる動作を表し、この文に合う。", "割り": "割るは他動詞で、お皿が主語の文には合わないので合わない。", "折れ": "折れるは棒状のものが曲がって切れる意味で、皿が分かれる文には合わないので合わない。", "濡れ": "濡れるは水にぬれる意味で、割れて分かれる文の結果には合わないので合わない。"}, "sentence_index": 0, "correct_answer": "割れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風で布が割れて、大きな穴があきました。", "explanation": "ここは〈裂ける〉の意味。布は割れるのではなく裂けるので合わない。"}, {"text": "引っ張った紙が割れてしまいました。", "explanation": "ここは〈ちぎれる〉の意味。紙は割れるのではなくちぎれるので合わない。"}, {"text": "服の袖が割れて、糸が出てきました。", "explanation": "ここは〈ほつれる〉の意味。布製の服は割れるのではなくほつれるので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38844, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "割れて", "is_correct": true, "explanation": "「割れてしまいました」の形で、コップが壊れてしまった結果を表し、この文に合う。"}, {"text": "割れた", "is_correct": false, "explanation": "過去形は「てしまいました」の前には続かないので合わない。"}, {"text": "割れ", "is_correct": false, "explanation": "連用形は「てしまいました」の前には続かないので合わない。"}, {"text": "凍って", "is_correct": false, "explanation": "凍るは冷たくなって固まる意味で、熱いお湯を入れた結果には合わないので合わない。"}], "explanations": {"割れて": "「割れてしまいました」の形で、コップが壊れてしまった結果を表し、この文に合う。", "割れた": "過去形は「てしまいました」の前には続かないので合わない。", "割れ": "連用形は「てしまいました」の前には続かないので合わない。", "凍って": "凍るは冷たくなって固まる意味で、熱いお湯を入れた結果には合わないので合わない。"}, "sentence_index": 6, "correct_answer": "割れて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "アイスクリームが割れてしまいました。", "explanation": "ここは〈溶ける〉の意味。アイスクリームは溶けるもので、割れるとは言わないので合わない。"}, {"text": "花が割れてしまいました。", "explanation": "ここは〈枯れる〉の意味。花は枯れるもので、割れるとは言わないので合わない。"}, {"text": "靴が割れたので、洗いました。", "explanation": "ここは〈汚れる〉の意味。靴は汚れるもので、割れるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38844, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ガラスは、強く当たると割ります。", "corrected_sentence": "ガラスは、強く当たると割れます。", "error_description": "誤: 割ります → 正: 割れます。ガラスが主語なので自動詞『割れる』を使う。『割る』は他動詞。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "割れ", "is_correct": true, "explanation": "「ます」の前に入る連用形で、この文の形に合う。"}, {"text": "割れる", "is_correct": false, "explanation": "辞書形は「ます」の前には使えないので合わない。"}, {"text": "割れない", "is_correct": false, "explanation": "否定形は肯定の事実を述べる文に合わないので合わない。"}, {"text": "割れよう", "is_correct": false, "explanation": "意向形は事実を述べる文には合わないので合わない。"}], "correct_form": "割れ", "base_form": "割れる", "form_label": "連用形", "sentence_index": 1, "explanations": {"割れ": "「ます」の前に入る連用形で、この文の形に合う。", "割れる": "辞書形は「ます」の前には使えないので合わない。", "割れない": "否定形は肯定の事実を述べる文に合わないので合わない。", "割れよう": "意向形は事実を述べる文には合わないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38844, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この板は、力を入れると割りてしまいます。", "corrected_sentence": "この板は、力を入れると割れてしまいます。", "error_description": "誤: 割りてしまいます → 正: 割れてしまいます。『割れる』の連用形は『割れて』で、『割りて』は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "割れて", "is_correct": true, "explanation": "「て形」で、後ろに文が続く接続の形に合う。"}, {"text": "割れた", "is_correct": false, "explanation": "過去形は「て」で続く文の途中には使えないので合わない。"}, {"text": "割れれば", "is_correct": false, "explanation": "仮定形は「て」で続く文の途中には使えないので合わない。"}, {"text": "割れなかった", "is_correct": false, "explanation": "否定の過去形は、板が割れた事実を述べる文には合わないので合わない。"}], "correct_form": "割れて", "base_form": "割れる", "form_label": "て形", "sentence_index": 7, "explanations": {"割れて": "「て形」で、後ろに文が続く接続の形に合う。", "割れた": "過去形は「て」で続く文の途中には使えないので合わない。", "割れれば": "仮定形は「て」で続く文の途中には使えないので合わない。", "割れなかった": "否定の過去形は、板が割れた事実を述べる文には合わないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
