INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38845, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「氷が割れて」の「が」で、割れる主語を示して自然。"}, {"text": "より", "is_correct": false, "explanation": "「氷より割れて」は比較の意味になり、主語を示す文に合わないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「氷の割れて」は名詞修飾になり、文が続かないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「氷に割れて」は結果や位置を示す「に」が合わず、割れる主体を示せないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「氷が割れて」の「が」で、割れる主語を示して自然。", "より": "「氷より割れて」は比較の意味になり、主語を示す文に合わないので合わない。", "の": "「氷の割れて」は名詞修飾になり、文が続かないので合わない。", "に": "「氷に割れて」は結果や位置を示す「に」が合わず、割れる主体を示せないので合わない。"}, "error_tags": {"より": "比較", "の": "名詞修飾", "に": "結果・位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38845, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物が衝撃や圧力で細かく砕けること。また、壊れて分かれること。", "primary_collocate": null, "pronunciation": "われる", "ipa": "waɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "ボールが当たって、窓ガラスが割れました。", "target_word": "割れ", "complexity_tier": "T3", "furigana": "ボールが当[あ]たって、窓[まど]ガラスが割[わ]れました。", "sentence_source": "generated"}, {"text": "強い風で花びんが落ちて割れました。", "target_word": "割れ", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]で花[か]びんが落[お]ちて割[わ]れました。", "sentence_source": "generated"}, {"text": "子どもが転んだ時、メガネのレンズが割れました。", "target_word": "割れ", "complexity_tier": "T3", "furigana": "子[こ]どもが転[ころ]んだ時[とき]、メガネのレンズが割[わ]れました。", "sentence_source": "generated"}, {"text": "重い荷物をのせたら、箱の底が割れてしまいました。", "target_word": "割れて", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]をのせたら、箱[はこ]の底[そこ]が割[わ]れてしまいました。", "sentence_source": "generated"}, {"text": "ガラスが割れて危ないので、触らないでください。", "target_word": "割れて", "complexity_tier": "T3", "furigana": "ガラスが割[わ]れて危[あぶ]ないので、触[さわ]らないでください。", "sentence_source": "generated"}, {"text": "電球は落とすと、すぐ割れます。", "target_word": "割れ", "complexity_tier": "T3", "furigana": "電球[でんきゅう]は落[お]とすと、すぐ割[わ]れます。", "sentence_source": "generated"}, {"text": "事故でフロントガラスが割れて、破片が飛び散りました。", "target_word": "割れて", "complexity_tier": "T3", "furigana": "事故[じこ]でフロントガラスが割[わ]れて、破片[はへん]が飛[と]び散[ち]りました。", "sentence_source": "generated"}, {"text": "薄い氷の上に乗ったら、氷が割れて足が水に落ちました。", "target_word": "割れて", "complexity_tier": "T3", "furigana": "薄[うす]い氷[こおり]の上[うえ]に乗[の]ったら、氷[こおり]が割[わ]れて足[あし]が水[みず]に落[お]ちました。", "sentence_source": "generated"}, {"text": "携帯電話の画面が割れたので、修理に出しました。", "target_word": "割れた", "complexity_tier": "T3", "furigana": "携帯電話[けいたいでんわ]の画面[がめん]が割[わ]れたので、修理[しゅうり]に出[だ]しました。", "sentence_source": "generated"}, {"text": "このグラスはぶつかると割れるので、丁寧に運んでください。", "target_word": "割れる", "complexity_tier": "T3", "furigana": "このグラスはぶつかると割[わ]れるので、丁寧[ていねい]に運[はこ]んでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "割れる", "label": "辞書形"}, {"form": "割れます", "label": "丁寧形"}, {"form": "割れない", "label": "否定形"}, {"form": "割れた", "label": "過去形"}, {"form": "割れて", "label": "て形"}], "register": "丁寧", "sense_fingerprint": "ガラス・電球・画面などが衝撃や圧力を受けて砕ける、壊れる。破片が飛び散るような壊れ方。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce196816-dc31-4b51-9de7-173ff8500542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38845, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "割れ", "is_correct": true, "explanation": "「割れました」で、ボールの衝撃でガラスが砕けた結果を表し、この文に合う。"}, {"text": "乾き", "is_correct": false, "explanation": "乾くは水分がなくなる意味で、ボールの衝撃の結果には合わないので合わない。"}, {"text": "濡れ", "is_correct": false, "explanation": "濡れるは水にぬれる意味で、衝撃で窓ガラスが壊れる文には合わないので合わない。"}, {"text": "膨らみ", "is_correct": false, "explanation": "膨らむは大きくなる意味で、窓ガラスが衝撃で砕ける文には合わないので合わない。"}], "explanations": {"割れ": "「割れました」で、ボールの衝撃でガラスが砕けた結果を表し、この文に合う。", "乾き": "乾くは水分がなくなる意味で、ボールの衝撃の結果には合わないので合わない。", "濡れ": "濡れるは水にぬれる意味で、衝撃で窓ガラスが壊れる文には合わないので合わない。", "膨らみ": "膨らむは大きくなる意味で、窓ガラスが衝撃で砕ける文には合わないので合わない。"}, "sentence_index": 0, "correct_answer": "割れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "引っ張ったら、紙袋が割れてしまいました。", "explanation": "ここは〈裂ける〉の意味。紙袋は割れるのではなく裂けるので合わない。"}, {"text": "雨が降って、傘が割れてしまいました。", "explanation": "ここは〈折れる〉の意味。傘は骨が折れることはあるが、割れるとは言わないので合わない。"}, {"text": "冷蔵庫に入れ忘れた肉が、割れてしまいました。", "explanation": "ここは〈腐る〉の意味。肉は傷んで腐るもので、割れるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38845, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "割れて", "is_correct": true, "explanation": "「割れて」で、フロントガラスが砕けてから破片が飛び散る流れに合い、事故の結果として自然。"}, {"text": "濡れて", "is_correct": false, "explanation": "濡れるは水にぬれる意味で、事故で破片が飛び散る文には合わないので合わない。"}, {"text": "乾いて", "is_correct": false, "explanation": "乾くは水分がなくなる意味で、破片が飛び散る流れには合わないので合わない。"}, {"text": "冷えて", "is_correct": false, "explanation": "冷えるは温度が下がる意味で、事故でガラスが砕ける文には合わないので合わない。"}], "explanations": {"割れて": "「割れて」で、フロントガラスが砕けてから破片が飛び散る流れに合い、事故の結果として自然。", "濡れて": "濡れるは水にぬれる意味で、事故で破片が飛び散る文には合わないので合わない。", "乾いて": "乾くは水分がなくなる意味で、破片が飛び散る流れには合わないので合わない。", "冷えて": "冷えるは温度が下がる意味で、事故でガラスが砕ける文には合わないので合わない。"}, "sentence_index": 6, "correct_answer": "割れて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古いくぎが割れてしまいました。", "explanation": "ここは〈さびる〉の意味。くぎは水分や空気でさびるもので、割れるとは言わないので合わない。"}, {"text": "日に当たって、カーテンの色が割れました。", "explanation": "ここは〈色あせる〉の意味。日光で変わるのは色のあせり方で、割れるとは言わないので合わない。"}, {"text": "洗濯したら、服が割れてしまいました。", "explanation": "ここは〈しわになる〉の意味。洗濯で布にできるのはしわで、割れるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38845, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "スマホの画面は、落とすと割れことがあります。", "corrected_sentence": "スマホの画面は、落とすと割れることがあります。", "error_description": "誤: 割れこと → 正: 割れること。『割れる』は辞書形の『る』を残して『こと』に続けるので、『る』を落とすと誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "割れ", "is_correct": true, "explanation": "「ました」の前に入る連用形で、この文の形に合う。"}, {"text": "割れる", "is_correct": false, "explanation": "辞書形は「ました」の前には使えないので合わない。"}, {"text": "割れない", "is_correct": false, "explanation": "否定形は、花びんが割れた事実を述べる文に合わないので合わない。"}, {"text": "割れよう", "is_correct": false, "explanation": "意向形は事実を述べる文には合わないので合わない。"}], "correct_form": "割れ", "base_form": "割れる", "form_label": "連用形", "sentence_index": 1, "explanations": {"割れ": "「ました」の前に入る連用形で、この文の形に合う。", "割れる": "辞書形は「ました」の前には使えないので合わない。", "割れない": "否定形は、花びんが割れた事実を述べる文に合わないので合わない。", "割れよう": "意向形は事実を述べる文には合わないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38845, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この皿は、落とすと割れでしまいます。", "corrected_sentence": "この皿は、落とすと割れてしまいます。", "error_description": "誤: 割れでしまいます → 正: 割れてしまいます。『割れる』のて形は『割れて』で、『てしまう』に続けても『て』のまま。『で』と濁らせたのが誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "割れて", "is_correct": true, "explanation": "「て形」で、後ろに文が続く接続の形に合う。"}, {"text": "割れた", "is_correct": false, "explanation": "過去形は「て」で続く文の途中には使えないので合わない。"}, {"text": "割れます", "is_correct": false, "explanation": "「ます」で文を終えるので、後ろに文が続く形の途中には使えないので合わない。"}, {"text": "割れなかった", "is_correct": false, "explanation": "否定の過去形は、氷が割れた事実を述べる文に合わないので合わない。"}], "correct_form": "割れて", "base_form": "割れる", "form_label": "て形", "sentence_index": 7, "explanations": {"割れて": "「て形」で、後ろに文が続く接続の形に合う。", "割れた": "過去形は「て」で続く文の途中には使えないので合わない。", "割れます": "「ます」で文を終えるので、後ろに文が続く形の途中には使えないので合わない。", "割れなかった": "否定の過去形は、氷が割れた事実を述べる文に合わないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
