INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38848, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "数字の二十五のこと。", "primary_collocate": null, "pronunciation": "にじゅうご", "ipa": "nidʑɯːɡo", "syllable_count": 4, "sentences": [{"text": "5に5をかけると 25 になります。", "target_word": "25", "complexity_tier": "T3", "furigana": "5に5をかけると 25[にじゅうご] になります。", "sentence_source": "generated"}, {"text": "電話番号の下二桁は 25 です。", "target_word": "25", "complexity_tier": "T3", "furigana": "電話番号[でんわばんごう]の下[した]二桁[にけた]は 25[にじゅうご] です。", "sentence_source": "generated"}, {"text": "黒板に大きく 25 と書きました。", "target_word": "25", "complexity_tier": "T3", "furigana": "黒板[こくばん]に大[おお]きく 25[にじゅうご] と書[か]きました。", "sentence_source": "generated"}, {"text": "時計の数字は12までなので、 25 はありません。", "target_word": "25", "complexity_tier": "T3", "furigana": "時計[とけい]の数字[すうじ]は12[じゅうに]までなので、 25[にじゅうご] はありません。", "sentence_source": "generated"}, {"text": "私の席の番号は 25 です。", "target_word": "25", "complexity_tier": "T3", "furigana": "私[わたし]の席[せき]の番号[ばんごう]は 25[にじゅうご] です。", "sentence_source": "generated"}, {"text": "25 という数字は、5の二乗です。", "target_word": "25", "complexity_tier": "T3", "furigana": "25[にじゅうご] という数字[すうじ]は、5の二乗[にじょう]です。", "sentence_source": "generated"}, {"text": "17に8を足すと 25 です。", "target_word": "25", "complexity_tier": "T3", "furigana": "17[じゅうなな]に8[はち]を足[た]すと 25[にじゅうご] です。", "sentence_source": "generated"}, {"text": "くじの番号が 25 だったので、賞品をもらいました。", "target_word": "25", "complexity_tier": "T3", "furigana": "くじの番号[ばんごう]が 25[にじゅうご] だったので、賞品[しょうひん]をもらいました。", "sentence_source": "generated"}, {"text": "100を4で割ると 25 です。", "target_word": "25", "complexity_tier": "T3", "furigana": "100[ひゃく]を4[よん]で割[わ]ると 25[にじゅうご] です。", "sentence_source": "generated"}, {"text": "25 のあとは26で、その前は24です。", "target_word": "25", "complexity_tier": "T3", "furigana": "25[にじゅうご] のあとは26[にじゅうろく]で、その前[まえ]は24[にじゅうよん]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "25", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "数字として書き表される二十五。24の次で26の前の数字。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce196816-dc31-4b51-9de7-173ff8500542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38848, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "25", "is_correct": true, "explanation": "5×5は25なので、ここには25が入る。"}, {"text": "16", "is_correct": false, "explanation": "16は4×4の答えで、5×5の答えではない。"}, {"text": "24", "is_correct": false, "explanation": "24は25の一つ前の数で、5×5の答えではない。"}, {"text": "36", "is_correct": false, "explanation": "36は6×6の答えで、5×5の答えではない。"}], "explanations": {"25": "5×5は25なので、ここには25が入る。", "16": "16は4×4の答えで、5×5の答えではない。", "24": "24は25の一つ前の数で、5×5の答えではない。", "36": "36は6×6の答えで、5×5の答えではない。"}, "sentence_index": 0, "correct_answer": "25"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の名前は25です。", "explanation": "ここは〈名前〉の意味。25は数字なので、人の名前には使わず合わない。"}, {"text": "彼の優しさは25だ。", "explanation": "ここは〈優しさの程度〉の意味。25は数字で、人の優しさの度合いは表さないので合わない。"}, {"text": "彼女は25の声で笑った。", "explanation": "ここは〈声の高さ・音色〉の意味。25は数字なので、声の調子は表さず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
