INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38849, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二十五。数のこと。", "primary_collocate": null, "pronunciation": "にじゅうご", "ipa": "nidʑɯːɡo", "syllable_count": 4, "sentences": [{"text": "クラスの生徒の数は 25 です。", "target_word": "25", "complexity_tier": "T3", "furigana": "クラスの生徒[せいと]の数[かず]は 25[にじゅうご] です。", "sentence_source": "generated"}, {"text": "箱の中のりんごは、数えると 25 個ありました。", "target_word": "25", "complexity_tier": "T3", "furigana": "箱[はこ]の中[なか]のりんごは、数[かぞ]えると 25[にじゅうご] 個[こ]ありました。", "sentence_source": "generated"}, {"text": "参加者の数は、去年の20から 25 に増えました。", "target_word": "25", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]の数[かず]は、去年[きょねん]の20[にじゅう]から 25[にじゅうご] に増[ふ]えました。", "sentence_source": "generated"}, {"text": "試験の点数は、100点中 25 でした。", "target_word": "25", "complexity_tier": "T3", "furigana": "試験[しけん]の点数[てんすう]は、100点中[ひゃくてんちゅう] 25[にじゅうご] でした。", "sentence_source": "generated"}, {"text": "25 から5を引くと20です。", "target_word": "25", "complexity_tier": "T3", "furigana": "25[にじゅうご] から5[ご]を引[ひ]くと20[にじゅう]です。", "sentence_source": "generated"}, {"text": "10と15を足した数は 25 です。", "target_word": "25", "complexity_tier": "T3", "furigana": "10[じゅう]と15[じゅうご]を足[た]した数[かず]は 25[にじゅうご] です。", "sentence_source": "generated"}, {"text": "本のページの数は、全部で 25 です。", "target_word": "25", "complexity_tier": "T3", "furigana": "本[ほん]のページの数[かず]は、全部[ぜんぶ]で 25[にじゅうご] です。", "sentence_source": "generated"}, {"text": "半分に分けると12と13で、合わせて 25 です。", "target_word": "25", "complexity_tier": "T3", "furigana": "半分[はんぶん]に分[わ]けると12[じゅうに]と13[じゅうさん]で、合[あ]わせて 25[にじゅうご] です。", "sentence_source": "generated"}, {"text": "25 は偶数ではなく、奇数です。", "target_word": "25", "complexity_tier": "T3", "furigana": "25[にじゅうご] は偶数[ぐうすう]ではなく、奇数[きすう]です。", "sentence_source": "generated"}, {"text": "カードの数は、最初が1で最後が 25 です。", "target_word": "25", "complexity_tier": "T3", "furigana": "カードの数[かず]は、最初[さいしょ]が1[いち]で最後[さいご]が 25[にじゅうご] です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "25", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "物の数や点数などの量を表す二十五。20と5を合わせた数。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce196816-dc31-4b51-9de7-173ff8500542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38849, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "25", "is_correct": true, "explanation": "学級の生徒数として自然な数なので、ここには25が入る。"}, {"text": "2500", "is_correct": false, "explanation": "2500人は学級の人数としては多すぎる。"}, {"text": "0.5", "is_correct": false, "explanation": "人の数は整数なので、0.5人はあり得ない。"}, {"text": "250", "is_correct": false, "explanation": "250人は学級の人数としては多すぎる。"}], "explanations": {"25": "学級の生徒数として自然な数なので、ここには25が入る。", "2500": "2500人は学級の人数としては多すぎる。", "0.5": "人の数は整数なので、0.5人はあり得ない。", "250": "250人は学級の人数としては多すぎる。"}, "sentence_index": 0, "correct_answer": "25"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は25の香りがする。", "explanation": "ここは〈香り〉の意味。25は数字なので、香りの種類は表さず合わない。"}, {"text": "彼は25の声で歌った。", "explanation": "ここは〈声の高さ・音色〉の意味。25は数字なので、声の調子は表さず合わない。"}, {"text": "この料理は25の味がする。", "explanation": "ここは〈味〉の意味。25は数字なので、料理の味は表さず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
