INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38852, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈間違える〉は目的語に〈を〉を取るので、比率を間違えるという文になる。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉を入れると比率が間違えるという主語になり、文の意味が合わない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉を入れると相手を表す文になり、比率を間違えるという文の意味に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を表すので、間違える対象を示す文には合わない。"}], "correct_answer": "を", "explanations": {"を": "〈間違える〉は目的語に〈を〉を取るので、比率を間違えるという文になる。", "が": "〈が〉を入れると比率が間違えるという主語になり、文の意味が合わない。", "に": "〈に〉を入れると相手を表す文になり、比率を間違えるという文の意味に合わない。", "へ": "〈へ〉は方向を表すので、間違える対象を示す文には合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
