INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38852, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つの数字を比べたときの大きさの関係です。", "primary_collocate": null, "pronunciation": "ひりつ", "ipa": "çiɾitsɯ", "syllable_count": 3, "sentences": [{"text": "このクラスは男子と女子の比率が一対一だ。", "target_word": "比率", "complexity_tier": "T3", "furigana": "このクラスは男子[だんし]と女子[じょし]の比率[ひりつ]が一対一[いったいいち]だ。", "sentence_source": "generated"}, {"text": "砂糖と水の比率を間違えると、シロップが甘すぎてしまう。", "target_word": "比率", "complexity_tier": "T3", "furigana": "砂糖[さとう]と水[みず]の比率[ひりつ]を間違[まちが]えると、シロップが甘[あま]すぎてしまう。", "sentence_source": "generated"}, {"text": "二つの数の比率を調べるために、まず割り算をした。", "target_word": "比率", "complexity_tier": "T3", "furigana": "二[ふた]つの数[かず]の比率[ひりつ]を調[しら]べるために、まず割[わ]り算[ざん]をした。", "sentence_source": "generated"}, {"text": "赤と白の絵の具を三対一の比率で混ぜると、ちょうどよいピンク色になる。", "target_word": "比率", "complexity_tier": "T4", "furigana": "赤[あか]と白[しろ]の絵[え]の具[ぐ]を三対一[さんたいいち]の比率[ひりつ]で混[ま]ぜると、ちょうどよいピンク色[いろ]になる。", "sentence_source": "generated"}, {"text": "縦と横の比率が同じなので、写真を小さくしても形は変わらない。", "target_word": "比率", "complexity_tier": "T3", "furigana": "縦[たて]と横[よこ]の比率[ひりつ]が同[おな]じなので、写真[しゃしん]を小[ちい]さくしても形[かたち]は変[か]わらない。", "sentence_source": "generated"}, {"text": "先生は、黒い石と白い石の比率を黒板に書いて説明した。", "target_word": "比率", "complexity_tier": "T3", "furigana": "先生[せんせい]は、黒[くろ]い石[いし]と白[しろ]い石[いし]の比率[ひりつ]を黒板[こくばん]に書[か]いて説明[せつめい]した。", "sentence_source": "generated"}, {"text": "この模型は、実物と十分の一の比率で作られている。", "target_word": "比率", "complexity_tier": "T3", "furigana": "この模型[もけい]は、実物[じつぶつ]と十分[じゅうぶん]の一[いち]の比率[ひりつ]で作[つく]られている。", "sentence_source": "generated"}, {"text": "水と粉の比率を二対一にすると、生地がやわらかくなる。", "target_word": "比率", "complexity_tier": "T3", "furigana": "水[みず]と粉[こな]の比率[ひりつ]を二対一[にたいいち]にすると、生地[きじ]がやわらかくなる。", "sentence_source": "generated"}, {"text": "去年と今年で、男の子と女の子の比率はほとんど変わらなかった。", "target_word": "比率", "complexity_tier": "T3", "furigana": "去年[きょねん]と今年[ことし]で、男[おとこ]の子[こ]と女[おんな]の子[こ]の比率[ひりつ]はほとんど変[か]わらなかった。", "sentence_source": "generated"}, {"text": "長さの比率が同じなら、二つの三角形は形が似ている。", "target_word": "比率", "complexity_tier": "T3", "furigana": "長[なが]さの比率[ひりつ]が同[おな]じなら、二[ふた]つの三角形[さんかっけい]は形[かたち]が似[に]ている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "比率", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "二つの数を比べた大きさの関係", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce196816-dc31-4b51-9de7-173ff8500542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38852, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比率", "is_correct": true, "explanation": "二つの数量の大きさの関係を表す比率が一対一なので、ここには比率が入る。"}, {"text": "平均", "is_correct": false, "explanation": "平均は一つの数量の代表値で、二つの数の関係を表す一対一には合わない。"}, {"text": "合計", "is_correct": false, "explanation": "合計は数を足した結果で、二つの数の関係を表す一対一には合わない。"}, {"text": "面積", "is_correct": false, "explanation": "面積は広さを表すので、男子と女子の数の関係には合わない。"}], "explanations": {"比率": "二つの数量の大きさの関係を表す比率が一対一なので、ここには比率が入る。", "平均": "平均は一つの数量の代表値で、二つの数の関係を表す一対一には合わない。", "合計": "合計は数を足した結果で、二つの数の関係を表す一対一には合わない。", "面積": "面積は広さを表すので、男子と女子の数の関係には合わない。"}, "sentence_index": 0, "correct_answer": "比率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の比率は火曜日だ。", "explanation": "ここは〈曜日〉の意味。比率は数の関係で、曜日は表さないので合わない。"}, {"text": "このテストの比率は七十点だ。", "explanation": "ここは〈平均〉の意味。比率は数の比なので、点数の代表値には使わない。"}, {"text": "祖母の比率は七十歳だ。", "explanation": "ここは〈年齢〉の意味。比率は年齢を表す言葉ではないので使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38852, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比率", "is_correct": true, "explanation": "縮尺の関係を表す比率で作られているという文なので、ここには比率が入る。"}, {"text": "郵便番号", "is_correct": false, "explanation": "郵便番号では模型の作り方の縮尺を表せないので合わない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は模型の大きさの関係を表さないので合わない。"}, {"text": "年号", "is_correct": false, "explanation": "年号は大きさの関係を表さないので合わない。"}], "explanations": {"比率": "縮尺の関係を表す比率で作られているという文なので、ここには比率が入る。", "郵便番号": "郵便番号では模型の作り方の縮尺を表せないので合わない。", "時刻": "時刻は模型の大きさの関係を表さないので合わない。", "年号": "年号は大きさの関係を表さないので合わない。"}, "sentence_index": 6, "correct_answer": "比率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夫婦の比率は良好だ。", "explanation": "ここは〈関係〉の意味。比率は数の比なので、人間関係の良し悪しには使わない。"}, {"text": "この品の比率は千円だ。", "explanation": "ここは〈値段〉の意味。比率は価格を表す言葉ではないので使わない。"}, {"text": "駅までの比率は二キロだ。", "explanation": "ここは〈距離〉の意味。比率は距離の数値を表す言葉ではないので使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
