INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38852, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地図は、実際の距離と同じ比率に描かれている。", "corrected_sentence": "この地図は、実際の距離と同じ比率で描かれている。", "error_description": "〈比率で描く〉の〈で〉は手段を表す。〈に〉を使うのは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38853, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "〈比率は四十パーセントだ〉の文の主題を示すので、ここには〈は〉が入る。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示す。比率を四十パーセントだとは言えないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は帰着点を示す。比率に四十パーセントだという文は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示す。比率で四十パーセントだという文は不自然で合わない。"}], "correct_answer": "は", "explanations": {"は": "〈比率は四十パーセントだ〉の文の主題を示すので、ここには〈は〉が入る。", "を": "〈を〉は目的語を示す。比率を四十パーセントだとは言えないので合わない。", "に": "〈に〉は帰着点を示す。比率に四十パーセントだという文は成り立たない。", "で": "〈で〉は手段や場所を示す。比率で四十パーセントだという文は不自然で合わない。"}, "error_tags": {"を": "目的語", "に": "帰着点", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
