INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38853, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つの数量の間の割合や関係を示す数値。", "primary_collocate": null, "pronunciation": "ひりつ", "ipa": "çiɾitsɯ", "syllable_count": 3, "sentences": [{"text": "この町では、お年寄りの比率が年々高くなっている。", "target_word": "比率", "complexity_tier": "T3", "furigana": "この町[まち]では、お年寄[としよ]りの比率[ひりつ]が年々[ねんねん]高[たか]くなっている。", "sentence_source": "generated"}, {"text": "社員のうち女性の比率は四十パーセントだ。", "target_word": "比率", "complexity_tier": "T3", "furigana": "社員[しゃいん]のうち女性[じょせい]の比率[ひりつ]は四十[よんじゅう]パーセントだ。", "sentence_source": "generated"}, {"text": "果物ジュースは、水の比率が高いほどうすい味になる。", "target_word": "比率", "complexity_tier": "T3", "furigana": "果物[くだもの]ジュースは、水[みず]の比率[ひりつ]が高[たか]いほどうすい味[あじ]になる。", "sentence_source": "generated"}, {"text": "外国から来た観光客の比率が、去年より少し上がった。", "target_word": "比率", "complexity_tier": "T3", "furigana": "外国[がいこく]から来[き]た観光客[かんこうきゃく]の比率[ひりつ]が、去年[きょねん]より少[すこ]し上[あ]がった。", "sentence_source": "generated"}, {"text": "この合金は、銅とすずの比率によってかたさが変わる。", "target_word": "比率", "complexity_tier": "T4", "furigana": "この合金[ごうきん]は、銅[どう]とすずの比率[ひりつ]によってかたさが変[か]わる。", "sentence_source": "generated"}, {"text": "学生の数に対する先生の比率が低いので、授業で質問しにくい。", "target_word": "比率", "complexity_tier": "T4", "furigana": "学生[がくせい]の数[かず]に対[たい]する先生[せんせい]の比率[ひりつ]が低[ひく]いので、授業[じゅぎょう]で質問[しつもん]しにくい。", "sentence_source": "generated"}, {"text": "体の中の水分の比率は、年をとると小さくなる。", "target_word": "比率", "complexity_tier": "T3", "furigana": "体[からだ]の中[なか]の水分[すいぶん]の比率[ひりつ]は、年[とし]をとると小[ちい]さくなる。", "sentence_source": "generated"}, {"text": "畑の面積に対して、野菜を作る場所の比率を増やすことにした。", "target_word": "比率", "complexity_tier": "T4", "furigana": "畑[はたけ]の面積[めんせき]に対[たい]して、野菜[やさい]を作[つく]る場所[ばしょ]の比率[ひりつ]を増[ふ]やすことにした。", "sentence_source": "generated"}, {"text": "輸入品の比率が大きくなると、国内の店の値段にも影響する。", "target_word": "比率", "complexity_tier": "T4", "furigana": "輸入品[ゆにゅうひん]の比率[ひりつ]が大[おお]きくなると、国内[こくない]の店[みせ]の値段[ねだん]にも影響[えいきょう]する。", "sentence_source": "generated"}, {"text": "結果を比べるため、全体に占める各国の比率を表にまとめた。", "target_word": "比率", "complexity_tier": "T4", "furigana": "結果[けっか]を比[くら]べるため、全体[ぜんたい]に占[し]める各国[かっこく]の比率[ひりつ]を表[ひょう]にまとめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "比率", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "全体や他と比べた数量の割合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce196816-dc31-4b51-9de7-173ff8500542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38853, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比率", "is_correct": true, "explanation": "全体に占めるお年寄りの割合として比率が高くなるのは自然なので、ここには比率が入る。"}, {"text": "面積", "is_correct": false, "explanation": "面積は広さを表すので、お年寄りの割合が高くなるという文には合わない。"}, {"text": "郵便番号", "is_correct": false, "explanation": "郵便番号は割合を表さないので、高くなるという文には合わない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は割合を表さないので、高くなるという文には合わない。"}], "explanations": {"比率": "全体に占めるお年寄りの割合として比率が高くなるのは自然なので、ここには比率が入る。", "面積": "面積は広さを表すので、お年寄りの割合が高くなるという文には合わない。", "郵便番号": "郵便番号は割合を表さないので、高くなるという文には合わない。", "時刻": "時刻は割合を表さないので、高くなるという文には合わない。"}, "sentence_index": 0, "correct_answer": "比率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会社の比率は百人だ。", "explanation": "ここは〈人数〉の意味。比率は全体に対する割合で、人の数は表さないので合わない。"}, {"text": "今週の比率は月曜日からだ。", "explanation": "ここは〈曜日・期間〉の意味。比率は数の関係で、曜日や期間は表さないので合わない。"}, {"text": "テストの比率は七十点だ。", "explanation": "ここは〈平均〉の意味。比率は全体の割合で、点数の代表値を表す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38853, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比率", "is_correct": true, "explanation": "体の中で水分が全体に占める割合が小さくなるという文なので、ここには比率が入る。"}, {"text": "色", "is_correct": false, "explanation": "色は割合の大きさの変化を表さないので、小さくなるという文には合わない。"}, {"text": "音", "is_correct": false, "explanation": "音は水分の割合を表さないので、小さくなるという文には合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は体の水分の割合を表さないので、ここには合わない。"}], "explanations": {"比率": "体の中で水分が全体に占める割合が小さくなるという文なので、ここには比率が入る。", "色": "色は割合の大きさの変化を表さないので、小さくなるという文には合わない。", "音": "音は水分の割合を表さないので、小さくなるという文には合わない。", "天気": "天気は体の水分の割合を表さないので、ここには合わない。"}, "sentence_index": 6, "correct_answer": "比率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父の比率は五十歳だ。", "explanation": "ここは〈年齢〉の意味。比率は全体に対する割合で、年齢の数値は表さないので合わない。"}, {"text": "この本の比率は千円だ。", "explanation": "ここは〈値段〉の意味。比率は価格を表す言葉ではないので使わない。"}, {"text": "家から駅までの比率は二キロだ。", "explanation": "ここは〈距離〉の意味。比率は全体に占める割合で、距離の数値を表さないので使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38853, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この地域では、子どもの比率を年々低くなっている。", "corrected_sentence": "この地域では、子どもの比率が年々低くなっている。", "error_description": "〈なる〉の主語は〈が〉で表す。ここで〈を〉を使うのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38853, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "利益は、二人の出資額の比率に分けられた。", "corrected_sentence": "利益は、二人の出資額の比率で分けられた。", "error_description": "〈比率で分ける〉の〈で〉は手段を表す。〈に〉を使うのは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
