INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38854, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものがくさって、いやなにおいがすること。", "primary_collocate": null, "pronunciation": "ふはい", "ipa": "ɸɯhai", "syllable_count": 3, "sentences": [{"text": "夏は暑いので、肉や魚の腐敗が早い。", "target_word": "腐敗", "complexity_tier": "T3", "furigana": "夏[なつ]は暑[あつ]いので、肉[にく]や魚[さかな]の腐敗[ふはい]が早[はや]い。", "sentence_source": "generated"}, {"text": "冷蔵庫に入れ忘れた牛乳は、腐敗して酸っぱいにおいがした。", "target_word": "腐敗", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]に入[い]れ忘[わす]れた牛乳[ぎゅうにゅう]は、腐敗[ふはい]して酸[す]っぱいにおいがした。", "sentence_source": "generated"}, {"text": "ごみ箱から腐敗したにおいがして、窓を開けた。", "target_word": "腐敗", "complexity_tier": "T3", "furigana": "ごみ箱[ばこ]から腐敗[ふはい]したにおいがして、窓[まど]を開[あ]けた。", "sentence_source": "generated"}, {"text": "野菜が腐敗しないように、冷蔵庫の中で冷やしておく。", "target_word": "腐敗", "complexity_tier": "T3", "furigana": "野菜[やさい]が腐敗[ふはい]しないように、冷蔵庫[れいぞうこ]の中[なか]で冷[ひ]やしておく。", "sentence_source": "generated"}, {"text": "長い間置いた弁当は腐敗が進み、食べられなくなっていた。", "target_word": "腐敗", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]置[お]いた弁当[べんとう]は腐敗[ふはい]が進[すす]み、食[た]べられなくなっていた。", "sentence_source": "generated"}, {"text": "腐敗した果物にはハエが集まってくる。", "target_word": "腐敗", "complexity_tier": "T2", "furigana": "腐敗[ふはい]した果物[くだもの]にはハエが集[あつ]まってくる。", "sentence_source": "generated"}, {"text": "台風で停電になり、冷凍庫の食べ物が腐敗してしまった。", "target_word": "腐敗", "complexity_tier": "T3", "furigana": "台風[たいふう]で停電[ていでん]になり、冷凍庫[れいとうこ]の食[た]べ物[もの]が腐敗[ふはい]してしまった。", "sentence_source": "generated"}, {"text": "塩をかけると、魚の腐敗をおそくすることができる。", "target_word": "腐敗", "complexity_tier": "T3", "furigana": "塩[しお]をかけると、魚[さかな]の腐敗[ふはい]をおそくすることができる。", "sentence_source": "generated"}, {"text": "暑い部屋に置いた卵は、腐敗したにおいを出していた。", "target_word": "腐敗", "complexity_tier": "T3", "furigana": "暑[あつ]い部屋[へや]に置[お]いた卵[たまご]は、腐敗[ふはい]したにおいを出[だ]していた。", "sentence_source": "generated"}, {"text": "腐敗の原因は、食べ物についた細菌だと先生が教えてくれた。", "target_word": "腐敗", "complexity_tier": "T4", "furigana": "腐敗[ふはい]の原因[げんいん]は、食[た]べ物[もの]についた細菌[さいきん]だと先生[せんせい]が教[おし]えてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "腐敗", "label": "基本形"}, {"form": "腐敗する", "label": "動詞形"}, {"form": "腐敗した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "食べ物などがくさること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce196816-dc31-4b51-9de7-173ff8500542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38854, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腐敗", "is_correct": true, "explanation": "ものがくさる意味で、「肉や魚の腐敗が早い」と自然につながる。"}, {"text": "点火", "is_correct": false, "explanation": "火をつけること。肉や魚の状態には使わないので、空所に入らない。"}, {"text": "両替", "is_correct": false, "explanation": "お金を別の種類にかえること。「肉や魚の両替が早い」は成り立たない。"}, {"text": "消灯", "is_correct": false, "explanation": "明かりを消すこと。食べ物の変化を表さないので、この文には合わない。"}], "explanations": {"腐敗": "ものがくさる意味で、「肉や魚の腐敗が早い」と自然につながる。", "点火": "火をつけること。肉や魚の状態には使わないので、空所に入らない。", "両替": "お金を別の種類にかえること。「肉や魚の両替が早い」は成り立たない。", "消灯": "明かりを消すこと。食べ物の変化を表さないので、この文には合わない。"}, "sentence_index": 0, "correct_answer": "腐敗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ワインは樽で寝かせるうちに腐敗して、味がまろやかになった。", "explanation": "ここは〈熟成〉の意味。ワインが時間をかけて味をまろやかにする変化で、いやなにおいを伴う腐敗とは違う。"}, {"text": "パンは酵母の働きで腐敗して、ふくらんでいく。", "explanation": "ここは〈発酵〉の意味。パン生地がふくらむのは発酵で、いやなにおいを伴ってくさる腐敗とは違う。"}, {"text": "ゲームのディスクが腐敗して、読み込めなくなった。", "explanation": "ここは〈劣化〉の意味。機器の性能が落ちることで、食べ物がくさる腐敗とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38854, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腐敗", "is_correct": true, "explanation": "食べ物がくさる意味で、停電で冷凍庫の食べ物がだめになった文に合う。"}, {"text": "感電", "is_correct": false, "explanation": "電気が体や物に流れて傷つくこと。食べ物には当てはまらない。"}, {"text": "延期", "is_correct": false, "explanation": "予定を先に延ばすこと。食べ物の状態には使わない。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点をつけること。食べ物には使わないので合わない。"}], "explanations": {"腐敗": "食べ物がくさる意味で、停電で冷凍庫の食べ物がだめになった文に合う。", "感電": "電気が体や物に流れて傷つくこと。食べ物には当てはまらない。", "延期": "予定を先に延ばすこと。食べ物の状態には使わない。", "採点": "答案などに点をつけること。食べ物には使わないので合わない。"}, "sentence_index": 6, "correct_answer": "腐敗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨風で鉄の橋が腐敗して、ぼろぼろになった。", "explanation": "ここは〈腐食〉の意味。金属がさびて傷むことを言うので、食べ物や生物がくさる腐敗とは違う。"}, {"text": "日差しが強く、水たまりの水が腐敗して消えた。", "explanation": "ここは〈蒸発〉の意味。水が気体になって消えることで、くさる腐敗ではない。"}, {"text": "夜更かしが続いて、肌の腐敗が進んでしまった。", "explanation": "ここは〈老化〉の意味。肌の衰えは老化と言い、腐敗は食べ物がくさる変化を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38854, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ひと晩置いた煮物は腐敗に、すえたにおいがしていた。", "corrected_sentence": "ひと晩置いた煮物は腐敗して、すえたにおいがしていた。", "error_description": "「腐敗」の直後に「に」が付いているのが誤り。「腐敗する」の形は「腐敗して」と続けて、後ろの「すえたにおいがしていた」につなぐ。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38854, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の車内に置いた弁当は、すっかり腐敗しよう。", "corrected_sentence": "夏の車内に置いた弁当は、すっかり腐敗した。", "error_description": "「腐敗しよう」は意志・勧誘の形で、弁当がくさってしまった結果を述べる文に合わない。過去の結果を表す「腐敗した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38855, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「腐敗が進むと」の主語を示す「が」。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「腐敗を進むと」は目的語の形にならず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「腐敗に進むと」は文の意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「腐敗で進むと」は手段の意味にならず不自然。"}], "correct_answer": "が", "explanations": {"が": "「腐敗が進むと」の主語を示す「が」。正しい。", "を": "「腐敗を進むと」は目的語の形にならず、文が成り立たない。", "に": "「腐敗に進むと」は文の意味が通らない。", "で": "「腐敗で進むと」は手段の意味にならず不自然。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38855, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38855, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物が微生物の働きによって分解され、悪臭を放つ状態になること。また、その状態。", "primary_collocate": null, "pronunciation": "ふはい", "ipa": "ɸɯhai", "syllable_count": 3, "sentences": [{"text": "開封後の牛乳は、微生物の働きで急速に腐敗する。", "target_word": "腐敗", "complexity_tier": "T3", "furigana": "開封[かいふう]後[ご]の牛乳[ぎゅうにゅう]は、微生物[びせいぶつ]の働[はたら]きで急速[きゅうそく]に腐敗[ふはい]する。", "sentence_source": "generated"}, {"text": "腐敗が進むと、タンパク質が分解されて悪臭を放つ。", "target_word": "腐敗", "complexity_tier": "T4", "furigana": "腐敗[ふはい]が進[すす]むと、タンパク質[しつ]が分解[ぶんかい]されて悪臭[あくしゅう]を放[はな]つ。", "sentence_source": "generated"}, {"text": "実験では、肉の腐敗を調べるために温度を変えて観察した。", "target_word": "腐敗", "complexity_tier": "T4", "furigana": "実験[じっけん]では、肉[にく]の腐敗[ふはい]を調[しら]べるために温度[おんど]を変[か]えて観察[かんさつ]した。", "sentence_source": "generated"}, {"text": "空気が少ない場所では、嫌気性の菌による腐敗が起こりやすい。", "target_word": "腐敗", "complexity_tier": "T4", "furigana": "空気[くうき]が少[すく]ない場所[ばしょ]では、嫌気性[けんきせい]の菌[きん]による腐敗[ふはい]が起[お]こりやすい。", "sentence_source": "generated"}, {"text": "食品の腐敗を防ぐため、工場では殺菌と低温保存を行っている。", "target_word": "腐敗", "complexity_tier": "T4", "furigana": "食品[しょくひん]の腐敗[ふはい]を防[ふせ]ぐため、工場[こうじょう]では殺菌[さっきん]と低温保存[ていおんほぞん]を行[おこな]っている。", "sentence_source": "generated"}, {"text": "死んだ動物の体は、細菌によって腐敗していく。", "target_word": "腐敗", "complexity_tier": "T3", "furigana": "死[し]んだ動物[どうぶつ]の体[からだ]は、細菌[さいきん]によって腐敗[ふはい]していく。", "sentence_source": "generated"}, {"text": "魚が腐敗するとアンモニアなどの悪臭物質が出る。", "target_word": "腐敗", "complexity_tier": "T4", "furigana": "魚[さかな]が腐敗[ふはい]するとアンモニアなどの悪臭物質[あくしゅうぶっしつ]が出[で]る。", "sentence_source": "generated"}, {"text": "缶詰は空気にふれないので、腐敗しにくい。", "target_word": "腐敗", "complexity_tier": "T3", "furigana": "缶詰[かんづめ]は空気[くうき]にふれないので、腐敗[ふはい]しにくい。", "sentence_source": "generated"}, {"text": "湿った生ごみは、微生物が増えて腐敗が早まる。", "target_word": "腐敗", "complexity_tier": "T4", "furigana": "湿[しめ]った生[なま]ごみは、微生物[びせいぶつ]が増[ふ]えて腐敗[ふはい]が早[はや]まる。", "sentence_source": "generated"}, {"text": "腐敗した食品を食べると、食中毒になることがある。", "target_word": "腐敗", "complexity_tier": "T3", "furigana": "腐敗[ふはい]した食品[しょくひん]を食[た]べると、食中毒[しょくちゅうどく]になることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "腐敗", "label": "基本形"}, {"form": "腐敗する", "label": "動詞形"}, {"form": "腐敗した", "label": "過去形"}], "register": "formal", "sense_fingerprint": "微生物による分解と悪臭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce196816-dc31-4b51-9de7-173ff8500542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38855, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腐敗", "is_correct": true, "explanation": "微生物の働きでくさる意味。「微生物の働きで急速に腐敗する」と自然につながる。"}, {"text": "施錠", "is_correct": false, "explanation": "かぎをかけること。牛乳には使わないので、この文に合わない。"}, {"text": "謝罪", "is_correct": false, "explanation": "謝ること。牛乳が謝罪するとは言わないので合わない。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりがつくこと。牛乳の変化を表さないので空所に入らない。"}], "explanations": {"腐敗": "微生物の働きでくさる意味。「微生物の働きで急速に腐敗する」と自然につながる。", "施錠": "かぎをかけること。牛乳には使わないので、この文に合わない。", "謝罪": "謝ること。牛乳が謝罪するとは言わないので合わない。", "点灯": "明かりがつくこと。牛乳の変化を表さないので空所に入らない。"}, "sentence_index": 0, "correct_answer": "腐敗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨ざらしの鉄の柵は、腐敗して赤くなった。", "explanation": "ここは〈腐食〉の意味。金属がさびて赤くなることで、微生物の働きによる分解の腐敗とは違う。"}, {"text": "ヨーグルトは乳酸菌の働きで腐敗して、酸味が出る。", "explanation": "ここは〈発酵〉の意味。乳酸菌による有用な変化は発酵で、悪臭を伴う腐敗とは違う。"}, {"text": "ノートパソコンのバッテリーが腐敗して、充電しにくくなった。", "explanation": "ここは〈劣化〉の意味。機器の性能が落ちることで、微生物による分解の腐敗とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38855, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腐敗", "is_correct": true, "explanation": "微生物の働きでくさる意味。「魚が腐敗するとアンモニアが出る」と自然につながる。"}, {"text": "混入", "is_correct": false, "explanation": "異物が入り込むこと。魚の変化を表さないので、この文には合わない。"}, {"text": "点検", "is_correct": false, "explanation": "機械などを調べること。魚が点検するとは言わないので合わない。"}, {"text": "絶縁", "is_correct": false, "explanation": "電気を通さないようにすること。魚には使わないので空所に入らない。"}], "explanations": {"腐敗": "微生物の働きでくさる意味。「魚が腐敗するとアンモニアが出る」と自然につながる。", "混入": "異物が入り込むこと。魚の変化を表さないので、この文には合わない。", "点検": "機械などを調べること。魚が点検するとは言わないので合わない。", "絶縁": "電気を通さないようにすること。魚には使わないので空所に入らない。"}, "sentence_index": 6, "correct_answer": "腐敗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長年の風雨で岩が腐敗して、もろくなった。", "explanation": "ここは〈風化〉の意味。岩が風や雨で砕けていく変化で、微生物による分解の腐敗とは違う。"}, {"text": "水たまりの水が腐敗して、ほとんど消えてしまった。", "explanation": "ここは〈蒸発〉の意味。水が気体になって減ることで、くさる腐敗ではない。"}, {"text": "直射日光で布が腐敗して、色が薄くなった。", "explanation": "ここは〈退色〉の意味。色があせることで、いやなにおいを伴う腐敗とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38855, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冷蔵庫に入れれば、食材の腐敗で遅らせることができる。", "corrected_sentence": "冷蔵庫に入れれば、食材の腐敗を遅らせることができる。", "error_description": "「遅らせる」の目的語は「〜を」で示す。「腐敗で」は手段の「で」になり、「腐敗を遅らせる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38855, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冷蔵庫の電源が落ちて、食材が腐敗させた。", "corrected_sentence": "冷蔵庫の電源が落ちて、食材が腐敗した。", "error_description": "「腐敗させる」は他動詞で、「〜を腐敗させる」の形で使う。「食材が」を主語にするなら、自動詞の「腐敗した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
