INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38856, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空にある白くて丸い形のもので、夜に光っています。", "primary_collocate": null, "pronunciation": "つき", "ipa": "tsɯki", "syllable_count": 2, "sentences": [{"text": "夜空に白くて丸い月が出ている。", "target_word": "月", "complexity_tier": "T2", "furigana": "夜空[よぞら]に白[しろ]くて丸[まる]い月[つき]が出[で]ている。", "sentence_source": "generated"}, {"text": "今夜は雲がなくて、月がとてもきれいに見える。", "target_word": "月", "complexity_tier": "T2", "furigana": "今夜[こんや]は雲[くも]がなくて、月[つき]がとてもきれいに見[み]える。", "sentence_source": "generated"}, {"text": "月の光で、暗い道もよく見えた。", "target_word": "月", "complexity_tier": "T2", "furigana": "月[つき]の光[ひかり]で、暗[くら]い道[みち]もよく見[み]えた。", "sentence_source": "generated"}, {"text": "子どもたちは窓から月を見て、ウサギの形を探した。", "target_word": "月", "complexity_tier": "T3", "furigana": "子[こ]どもたちは窓[まど]から月[つき]を見[み]て、ウサギの形[かたち]を探[さが]した。", "sentence_source": "generated"}, {"text": "月が雲にかくれて、あたりが急に暗くなった。", "target_word": "月", "complexity_tier": "T3", "furigana": "月[つき]が雲[くも]にかくれて、あたりが急[きゅう]に暗[くら]くなった。", "sentence_source": "generated"}, {"text": "山の上に大きな月が昇ってきた。", "target_word": "月", "complexity_tier": "T2", "furigana": "山[やま]の上[うえ]に大[おお]きな月[つき]が昇[のぼ]ってきた。", "sentence_source": "generated"}, {"text": "夜、月を見ながら家族でお茶を飲んだ。", "target_word": "月", "complexity_tier": "T2", "furigana": "夜[よる]、月[つき]を見[み]ながら家族[かぞく]でお茶[ちゃ]を飲[の]んだ。", "sentence_source": "generated"}, {"text": "月は夜になると明るく光るが、昼間にも見えることがある。", "target_word": "月", "complexity_tier": "T3", "furigana": "月[つき]は夜[よる]になると明[あか]るく光[ひか]るが、昼間[ひるま]にも見[み]えることがある。", "sentence_source": "generated"}, {"text": "池の水に月がうつって、ゆれていた。", "target_word": "月", "complexity_tier": "T3", "furigana": "池[いけ]の水[みず]に月[つき]がうつって、ゆれていた。", "sentence_source": "generated"}, {"text": "その夜は月が明るくて、星が少ししか見えなかった。", "target_word": "月", "complexity_tier": "T3", "furigana": "その夜[よる]は月[つき]が明[あか]るくて、星[ほし]が少[すこ]ししか見[み]えなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "月", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "夜空に光る白くて丸いもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 夜空 (Zipf 3.49), 白く (Zipf 3.78), 丸い (Zipf 3.69)']::text[], 'ce196816-dc31-4b51-9de7-173ff8500542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38856, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月", "is_correct": true, "explanation": "夜空に出る白くて丸いものを指し、「夜空に白くて丸い月が出ている」と自然につながる。"}, {"text": "金魚", "is_correct": false, "explanation": "水の中で泳ぐ魚。夜空に出るものではないので合わない。"}, {"text": "電車", "is_correct": false, "explanation": "線路を走る乗り物。夜空に出るものではないので空所に入らない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車や入場に使う紙。夜空に出るものではないので合わない。"}], "explanations": {"月": "夜空に出る白くて丸いものを指し、「夜空に白くて丸い月が出ている」と自然につながる。", "金魚": "水の中で泳ぐ魚。夜空に出るものではないので合わない。", "電車": "線路を走る乗り物。夜空に出るものではないので空所に入らない。", "切符": "乗車や入場に使う紙。夜空に出るものではないので合わない。"}, "sentence_index": 0, "correct_answer": "月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の夜、庭の草むらに月がふわりと飛んでいる。", "explanation": "ここは〈蛍〉の場面。夜にふわふわ飛ぶのは蛍で、空に浮かぶ月は飛ばない。"}, {"text": "夏の昼間は月がじりじり照りつける。", "explanation": "ここは太陽について言う場面。じりじり照りつけるのは太陽で、夜に光る月には使わない。"}, {"text": "天井の月が部屋をやわらかく照らしている。", "explanation": "ここは電灯について言う場面。天井について部屋を照らすのは電灯で、月は天井にはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38856, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月", "is_correct": true, "explanation": "夜空の天体として、夜に家族で見ながらお茶を飲む文に自然に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食べ物を冷やす家電。夜に見ながらお茶を飲む対象ではないので合わない。"}, {"text": "掃除機", "is_correct": false, "explanation": "ごみを吸う家電。見ながらお茶を飲む対象ではないので合わない。"}, {"text": "電卓", "is_correct": false, "explanation": "計算に使う道具。夜に見ながらお茶を飲む対象としては成り立たない。"}], "explanations": {"月": "夜空の天体として、夜に家族で見ながらお茶を飲む文に自然に合う。", "冷蔵庫": "食べ物を冷やす家電。夜に見ながらお茶を飲む対象ではないので合わない。", "掃除機": "ごみを吸う家電。見ながらお茶を飲む対象ではないので合わない。", "電卓": "計算に使う道具。夜に見ながらお茶を飲む対象としては成り立たない。"}, "sentence_index": 6, "correct_answer": "月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜空に月がまたたいている。", "explanation": "ここは星について言う場面。またたくのは星の特徴で、月には使わない。"}, {"text": "夏の夜空に月が次々と上がった。", "explanation": "ここは花火について言う場面。次々と上がるのは花火で、月は一つしかなく次々とは上がらない。"}, {"text": "机の月がやわらかく光っている。", "explanation": "ここはランプについて言う場面。机の上で光るのはランプで、月は机の上にはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38856, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓から月と見ていたら、ウサギに見えた。", "corrected_sentence": "窓から月を見ていたら、ウサギに見えた。", "error_description": "「見る」の対象は「を」で示す。「月と」は「月と一緒に」の意味になるので誤り。「月を見ていたら」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38856, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓の外に大きな月が浮かぶている。", "corrected_sentence": "窓の外に大きな月が浮かんでいる。", "error_description": "「浮かぶ」の活用が誤り。状態を表す「浮かんでいる」（ている形）が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38857, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「月の形が変わる」と名詞をつなぐ「の」。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「月を形が変わる」は文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「月に形が変わる」は場所や相手の意味にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「月へ形が変わる」は語順が成り立たず、不自然な文になる。"}], "correct_answer": "の", "explanations": {"の": "「月の形が変わる」と名詞をつなぐ「の」。正しい。", "を": "「月を形が変わる」は文が成り立たない。", "に": "「月に形が変わる」は場所や相手の意味にならず不自然。", "へ": "「月へ形が変わる」は語順が成り立たず、不自然な文になる。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38857, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「月が地球と太陽の間に入ると」の主語を示す「が」。正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「月へ地球と太陽の間に入る」は方向の意味になり、主語を示せず文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「月を」は目的語となるが、「地球と太陽の間に入る」の主語として文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「月より地球と太陽の間に入る」は比較の意味になり、文の主語にならず不自然。"}], "correct_answer": "が", "explanations": {"が": "「月が地球と太陽の間に入ると」の主語を示す「が」。正しい。", "へ": "「月へ地球と太陽の間に入る」は方向の意味になり、主語を示せず文が成り立たない。", "を": "「月を」は目的語となるが、「地球と太陽の間に入る」の主語として文が成り立たない。", "より": "「月より地球と太陽の間に入る」は比較の意味になり、文の主語にならず不自然。"}, "error_tags": {"へ": "方向", "を": "目的語", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38857, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地球の周りを回っている天体で、夜に光って見えます。満ち欠けがあり、暦の基準にもなります。", "primary_collocate": null, "pronunciation": "つき", "ipa": "tsɯki", "syllable_count": 2, "sentences": [{"text": "月は地球の周りを約二十七日で一周する。", "target_word": "月", "complexity_tier": "T4", "furigana": "月[つき]は地球[ちきゅう]の周[まわ]りを約[やく]二十七日[にじゅうしちにち]で一周[いっしゅう]する。", "sentence_source": "generated"}, {"text": "月の形が変わるのは、太陽の光が当たる部分が違って見えるからだ。", "target_word": "月", "complexity_tier": "T4", "furigana": "月[つき]の形[かたち]が変[か]わるのは、太陽[たいよう]の光[ひかり]が当[あ]たる部分[ぶぶん]が違[ちが]って見[み]えるからだ。", "sentence_source": "generated"}, {"text": "昔の暦は、月の満ち欠けをもとに作られていた。", "target_word": "月", "complexity_tier": "T4", "furigana": "昔[むかし]の暦[こよみ]は、月[つき]の満[み]ち欠[か]けをもとに作[つく]られていた。", "sentence_source": "generated"}, {"text": "月には空気がないので、音が伝わらない。", "target_word": "月", "complexity_tier": "T3", "furigana": "月[つき]には空気[くうき]がないので、音[おと]が伝[つた]わらない。", "sentence_source": "generated"}, {"text": "月の引力のえいきょうで、海の潮が満ちたり引いたりする。", "target_word": "月", "complexity_tier": "T4", "furigana": "月[つき]の引力[いんりょく]のえいきょうで、海[うみ]の潮[しお]が満[み]ちたり引[ひ]いたりする。", "sentence_source": "generated"}, {"text": "宇宙飛行士は初めて月に降り立ち、地面の砂を持ち帰った。", "target_word": "月", "complexity_tier": "T4", "furigana": "宇宙飛行士[うちゅうひこうし]は初[はじ]めて月[つき]に降[お]り立[た]ち、地面[じめん]の砂[すな]を持[も]ち帰[かえ]った。", "sentence_source": "generated"}, {"text": "月は自分では光らず、太陽の光を反射して輝いている。", "target_word": "月", "complexity_tier": "T4", "furigana": "月[つき]は自分[じぶん]では光[ひか]らず、太陽[たいよう]の光[ひかり]を反射[はんしゃ]して輝[かがや]いている。", "sentence_source": "generated"}, {"text": "月が地球と太陽の間に入ると、日食が起こる。", "target_word": "月", "complexity_tier": "T4", "furigana": "月[つき]が地球[ちきゅう]と太陽[たいよう]の間[あいだ]に入[はい]ると、日食[にっしょく]が起[お]こる。", "sentence_source": "generated"}, {"text": "月の表面には、たくさんのクレーターがある。", "target_word": "月", "complexity_tier": "T3", "furigana": "月[つき]の表面[ひょうめん]には、たくさんのクレーターがある。", "sentence_source": "generated"}, {"text": "月は地球の唯一の自然の衛星で、いつも同じ面を向けている。", "target_word": "月", "complexity_tier": "T4", "furigana": "月[つき]は地球[ちきゅう]の唯一[ゆいいつ]の自然[しぜん]の衛星[えいせい]で、いつも同[おな]じ面[めん]を向[む]けている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "月", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "地球を回る天体、満ち欠けと暦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: 満ち欠け (Zipf 2.26)','sentence 5 above tier T1: contains vocabulary far above tier T1: 降り立ち (Zipf 2.47)']::text[], 'ce196816-dc31-4b51-9de7-173ff8500542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38857, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月", "is_correct": true, "explanation": "地球の周りを約二十七日で一周する天体で、文の主語として自然。"}, {"text": "電車", "is_correct": false, "explanation": "線路を走る乗り物。地球の周りを回る天体ではないので合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "言葉を調べる本。地球の周りを回る天体ではないので合わない。"}, {"text": "空気", "is_correct": false, "explanation": "地球を取り巻く気体。周りを一周するという動きを表す主語としては合わない。"}], "explanations": {"月": "地球の周りを約二十七日で一周する天体で、文の主語として自然。", "電車": "線路を走る乗り物。地球の周りを回る天体ではないので合わない。", "辞書": "言葉を調べる本。地球の周りを回る天体ではないので合わない。", "空気": "地球を取り巻く気体。周りを一周するという動きを表す主語としては合わない。"}, "sentence_index": 0, "correct_answer": "月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月が長い尾を引いて、夜空をよぎっていった。", "explanation": "ここは〈彗星〉の場面。長い尾を引いて夜空を横切るのは彗星で、尾のない月には合わない。"}, {"text": "月を磨いて、顔を映した。", "explanation": "ここは〈鏡〉の場面。磨いて顔を映すのは鏡で、天体の月は磨けない。"}, {"text": "夜空に月が一瞬で現れて、すっと消えた。", "explanation": "ここは〈流れ星〉の場面。一瞬で現れて消えるのは流れ星で、月はゆっくり動く天体だ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38857, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月", "is_correct": true, "explanation": "自分では光らず太陽の光を反射して輝く天体で、この文の主語に合う。"}, {"text": "電灯", "is_correct": false, "explanation": "自分で光を出す照明。「自分では光らず」と矛盾するので合わない。"}, {"text": "花火", "is_correct": false, "explanation": "自分で光を出して輝くもの。「自分では光らず」と矛盾するので合わない。"}, {"text": "ろうそく", "is_correct": false, "explanation": "自分で炎を出して光るもの。「自分では光らず」と矛盾するので合わない。"}], "explanations": {"月": "自分では光らず太陽の光を反射して輝く天体で、この文の主語に合う。", "電灯": "自分で光を出す照明。「自分では光らず」と矛盾するので合わない。", "花火": "自分で光を出して輝くもの。「自分では光らず」と矛盾するので合わない。", "ろうそく": "自分で炎を出して光るもの。「自分では光らず」と矛盾するので合わない。"}, "sentence_index": 6, "correct_answer": "月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月が夜の七時に、駅のホームへ着いた。", "explanation": "ここは〈電車〉の場面。駅のホームに着くのは電車で、天体の月は乗り物ではないので合わない。"}, {"text": "夜更けに、月を開けて風を入れた。", "explanation": "ここは〈窓〉の場面。開けて風を入れるのは窓で、天体の月は開ける物ではない。"}, {"text": "月を火にかけて、ぐつぐつ煮た。", "explanation": "ここは〈鍋〉の場面。火にかけて煮るのは鍋や料理で、天体の月は火にかけられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38857, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "月は地球の周りを約二十七日で一周させている。", "corrected_sentence": "月は地球の周りを約二十七日で一周している。", "error_description": "「一周する」を使役形の「一周させる」にしたのが誤り。月は自分で回るので、「一周している」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38857, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "月に表面には、大小のクレーターが無数にある。", "corrected_sentence": "月の表面には、大小のクレーターが無数にある。", "error_description": "「月に」の「に」が誤り。「月の表面」と「の」でつなぐのが正しい。「月に表面」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf3aa5fc-c196-4fe5-9eb9-7372e1c850b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38860, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重い", "is_correct": true, "explanation": "ここは重さの意味。「軽い」の対義語は「重い」。"}, {"text": "硬い", "is_correct": false, "explanation": "固さを表す語で、重さの対義語ではない。"}, {"text": "細い", "is_correct": false, "explanation": "幅や太さを表す語で、重さとは反対の関係にない。"}, {"text": "高い", "is_correct": false, "explanation": "高さや値段を表す語で、重さの対義語ではない。"}], "correct_answer": "重い", "explanations": {"重い": "ここは重さの意味。「軽い」の対義語は「重い」。", "硬い": "固さを表す語で、重さの対義語ではない。", "細い": "幅や太さを表す語で、重さとは反対の関係にない。", "高い": "高さや値段を表す語で、重さの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38860, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重い", "is_correct": true, "explanation": "「軽い」（重さが少ない）の対義語は「重い」。荷物の重さに対応する。"}, {"text": "暗い", "is_correct": false, "explanation": "明るさを表す語で、重さの対義語ではない。"}, {"text": "深い", "is_correct": false, "explanation": "深さを表す語で、重さとは反対の関係にない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さを表す語で、重さの対義語ではない。"}], "correct_answer": "重い", "explanations": {"重い": "「軽い」（重さが少ない）の対義語は「重い」。荷物の重さに対応する。", "暗い": "明るさを表す語で、重さの対義語ではない。", "深い": "深さを表す語で、重さとは反対の関係にない。", "遅い": "速さを表す語で、重さの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38860, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "「かるい」は、重さが少ないという意味です。持っても疲れません。", "primary_collocate": null, "pronunciation": "かるい", "ipa": "kaɾɯi", "syllable_count": 3, "sentences": [{"text": "このかばんは軽いので、毎日持って歩いても疲れない。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "このかばんは軽[かる]いので、毎日[まいにち]持[も]って歩[ある]いても疲[つか]れない。", "sentence_source": "generated"}, {"text": "軽い荷物だけを持って、旅行に出かけた。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "軽[かる]い荷物[にもつ]だけを持[も]って、旅行[りょこう]に出[で]かけた。", "sentence_source": "generated"}, {"text": "新しいパソコンは前のより軽くて、持ち運びが楽だ。", "target_word": "軽くて", "complexity_tier": "T3", "furigana": "新[あたら]しいパソコンは前[まえ]のより軽[かる]くて、持[も]ち運[はこ]びが楽[らく]だ。", "sentence_source": "generated"}, {"text": "私の傘は軽いが、風にはとても強い。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "私[わたし]の傘[かさ]は軽[かる]いが、風[かぜ]にはとても強[つよ]い。", "sentence_source": "generated"}, {"text": "子どもでも持てるように、軽い箱を選んだ。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "子[こ]どもでも持[も]てるように、軽[かる]い箱[はこ]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "この靴は軽かったので、長い道を歩いても足が痛くならなかった。", "target_word": "軽かった", "complexity_tier": "T3", "furigana": "この靴[くつ]は軽[かる]かったので、長[なが]い道[みち]を歩[ある]いても足[あし]が痛[いた]くならなかった。", "sentence_source": "generated"}, {"text": "紙は軽いから、風が吹くとすぐに飛んでしまう。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "紙[かみ]は軽[かる]いから、風[かぜ]が吹[ふ]くとすぐに飛[と]んでしまう。", "sentence_source": "generated"}, {"text": "軽いコートを一枚着て、春の散歩に出かけた。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "軽[かる]いコートを一枚[いちまい]着[き]て、春[はる]の散歩[さんぽ]に出[で]かけた。", "sentence_source": "generated"}, {"text": "木のいすは鉄のいすより軽いので、一人で運べる。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "木[き]のいすは鉄[てつ]のいすより軽[かる]いので、一人[ひとり]で運[はこ]べる。", "sentence_source": "generated"}, {"text": "荷物が軽くなって、山道を歩くのが楽になった。", "target_word": "軽く", "complexity_tier": "T3", "furigana": "荷物[にもつ]が軽[かる]くなって、山道[やまみち]を歩[ある]くのが楽[らく]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "軽い", "label": "終止形・連体形"}, {"form": "軽く", "label": "連用形"}, {"form": "軽かった", "label": "過去形"}, {"form": "軽くない", "label": "否定形"}, {"form": "軽ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "物の重さが少ない。持ち運びが楽な様子。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80324491-1491-4ee3-96f9-8789a18dac12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38860, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "軽い", "is_correct": true, "explanation": "「軽い」は重さが少ないことを表し、「軽いので毎日持って歩いても疲れない」と文意が通る。"}, {"text": "重い", "is_correct": false, "explanation": "反対の重さを表すため、「重いので疲れない」は文意が逆になり合わない。"}, {"text": "硬い", "is_correct": false, "explanation": "固さの語で重さの話には合わない。「硬いので疲れない」は文が成り立たない。"}, {"text": "赤い", "is_correct": false, "explanation": "色の語で、疲れにくさの理由にならない。"}], "explanations": {"軽い": "「軽い」は重さが少ないことを表し、「軽いので毎日持って歩いても疲れない」と文意が通る。", "重い": "反対の重さを表すため、「重いので疲れない」は文意が逆になり合わない。", "硬い": "固さの語で重さの話には合わない。「硬いので疲れない」は文が成り立たない。", "赤い": "色の語で、疲れにくさの理由にならない。"}, "sentence_index": 0, "correct_answer": "軽い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この服は値段が軽くて、学生でも買いやすい。", "explanation": "ここの〈軽い〉は重さの意味。値段の安さは〈安い〉で表すので、〈軽い〉を値段に使うのは合わない。"}, {"text": "このガラスは軽くて、厚さが一ミリしかない。", "explanation": "厚さの薄さは〈薄い〉で表す。〈軽い〉は重さの語なので、厚さの説明には使えない。"}, {"text": "雨の日は客の入りが軽く、店はがらがらだった。", "explanation": "客の入りの少なさは〈少ない〉で表す。〈軽い〉は重さの語なので、客の数には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38860, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "軽い", "is_correct": true, "explanation": "重さが少なく、風で飛ぶ理由になるので「紙は軽いから飛んでしまう」と文意が通る。"}, {"text": "黒い", "is_correct": false, "explanation": "色の語で、飛ぶ理由にならない。"}, {"text": "太い", "is_correct": false, "explanation": "太さの語で、風で飛ぶ理由にならない。"}, {"text": "甘い", "is_correct": false, "explanation": "味の語で、紙の説明には合わない。"}], "explanations": {"軽い": "重さが少なく、風で飛ぶ理由になるので「紙は軽いから飛んでしまう」と文意が通る。", "黒い": "色の語で、飛ぶ理由にならない。", "太い": "太さの語で、風で飛ぶ理由にならない。", "甘い": "味の語で、紙の説明には合わない。"}, "sentence_index": 6, "correct_answer": "軽い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋は軽くて、日当たりがよい。", "explanation": "部屋の明るさは〈明るい〉で表す。〈軽い〉は重さの語なので、部屋の様子には使えない。"}, {"text": "このコートは軽いサイズで、私には合わなかった。", "explanation": "サイズの大きさは〈大きい〉で表す。〈軽い〉は重さの語なので、サイズには使えない。"}, {"text": "夜の町は軽くて、車の音が遠くから聞こえた。", "explanation": "町の静けさは〈静か〉で表す。〈軽い〉は重さの語なので、町の様子には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38860, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このかばんは軽いくて、毎日持ち歩くのにちょうどいい。", "corrected_sentence": "このかばんは軽くて、毎日持ち歩くのにちょうどいい。", "error_description": "誤り：「軽いくて」。正しくは「軽くて」。「て」で続けるときは形容詞の連用形「軽く」に「て」を付ける。「軽い」に直接「くて」を付けるのは形が不正。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "軽い", "is_correct": true, "explanation": "連体形で、名詞「荷物」を修飾する正しい形。"}, {"text": "軽く", "is_correct": false, "explanation": "連用形で、名詞を直接修飾できない。「軽く荷物」は成り立たない。"}, {"text": "軽かった", "is_correct": false, "explanation": "過去形で、名詞に直接続けると時制の意味になり、ここでは文が成り立たない。"}, {"text": "軽ければ", "is_correct": false, "explanation": "仮定形で、名詞「荷物」を修飾できない。"}], "correct_form": "軽い", "base_form": "軽い", "form_label": "連体形", "sentence_index": 1, "explanations": {"軽い": "連体形で、名詞「荷物」を修飾する正しい形。", "軽く": "連用形で、名詞を直接修飾できない。「軽く荷物」は成り立たない。", "軽かった": "過去形で、名詞に直接続けると時制の意味になり、ここでは文が成り立たない。", "軽ければ": "仮定形で、名詞「荷物」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38860, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "リュックの中身を減らすと、肩が軽いになって、歩くのが楽になった。", "corrected_sentence": "リュックの中身を減らすと、肩が軽くなって、歩くのが楽になった。", "error_description": "誤り：「軽いになって」。正しくは「軽くなって」。形容詞「軽い」が変化を表すときは連用形「軽く」に「なる」を付けるので、「軽い」に「になる」を付けるのは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "軽い", "is_correct": true, "explanation": "連体形で、名詞「コート」を修飾する正しい形。「軽いコートを一枚」と続く。"}, {"text": "軽くて", "is_correct": false, "explanation": "「て」で続ける形で、名詞「コート」を直接修飾できない。「軽くてコート」は成り立たない。"}, {"text": "軽かったら", "is_correct": false, "explanation": "仮定の形で、名詞「コート」を修飾できず、文が成り立たない。"}, {"text": "軽かろう", "is_correct": false, "explanation": "推量の形で、名詞「コート」を直接修飾できない。「軽かろうコート」は成り立たない。"}], "correct_form": "軽い", "base_form": "軽い", "form_label": "連体形", "sentence_index": 7, "explanations": {"軽い": "連体形で、名詞「コート」を修飾する正しい形。「軽いコートを一枚」と続く。", "軽くて": "「て」で続ける形で、名詞「コート」を直接修飾できない。「軽くてコート」は成り立たない。", "軽かったら": "仮定の形で、名詞「コート」を修飾できず、文が成り立たない。", "軽かろう": "推量の形で、名詞「コート」を直接修飾できない。「軽かろうコート」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38861, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重い", "is_correct": true, "explanation": "程度が大きい（重い病気）という意味で、程度の小さい〈軽い〉の対義語。"}, {"text": "厚い", "is_correct": false, "explanation": "厚みを表す語で、程度の反対語ではない。"}, {"text": "早い", "is_correct": false, "explanation": "時間や速さを表す語で、程度の対義語ではない。"}, {"text": "硬い", "is_correct": false, "explanation": "固さを表す語で、程度の対義語ではない。"}], "correct_answer": "重い", "explanations": {"重い": "程度が大きい（重い病気）という意味で、程度の小さい〈軽い〉の対義語。", "厚い": "厚みを表す語で、程度の反対語ではない。", "早い": "時間や速さを表す語で、程度の対義語ではない。", "硬い": "固さを表す語で、程度の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38861, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重い", "is_correct": true, "explanation": "量が多く重い食事の意味で、軽く食べるの対義語。"}, {"text": "寒い", "is_correct": false, "explanation": "温度を表す語で、反対の関係にない。"}, {"text": "太い", "is_correct": false, "explanation": "太さを表す語で、対義語ではない。"}, {"text": "広い", "is_correct": false, "explanation": "広さを表す語で、対義語ではない。"}], "correct_answer": "重い", "explanations": {"重い": "量が多く重い食事の意味で、軽く食べるの対義語。", "寒い": "温度を表す語で、反対の関係にない。", "太い": "太さを表す語で、対義語ではない。", "広い": "広さを表す語で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38861, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "「かるい」は、物理的な重さが少ないこと。また、程度が小さいことや、気軽な様子を表します。", "primary_collocate": null, "pronunciation": "かるい", "ipa": "kaɾɯi", "syllable_count": 3, "sentences": [{"text": "転んで軽いけがをしただけで、病院には行かなかった。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "転[ころ]んで軽[かる]いけがをしただけで、病院[びょういん]には行[い]かなかった。", "sentence_source": "generated"}, {"text": "朝は軽い食事で済ませて、すぐに家を出た。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "朝[あさ]は軽[かる]い食事[しょくじ]で済[す]ませて、すぐに家[いえ]を出[で]た。", "sentence_source": "generated"}, {"text": "軽い風邪なので、薬を飲んで寝れば治る。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "軽[かる]い風邪[かぜ]なので、薬[くすり]を飲[の]んで寝[ね]れば治[なお]る。", "sentence_source": "generated"}, {"text": "軽い気持ちで引き受けたら、思ったより大変な仕事だった。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "軽[かる]い気持[きも]ちで引[ひ]き受[う]けたら、思[おも]ったより大変[たいへん]な仕事[しごと]だった。", "sentence_source": "generated"}, {"text": "この箱は軽いので、女性でも一人で運べる。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "この箱[はこ]は軽[かる]いので、女性[じょせい]でも一人[ひとり]で運[はこ]べる。", "sentence_source": "generated"}, {"text": "彼は軽い冗談を言って、会議の空気を和らげた。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "彼[かれ]は軽[かる]い冗談[じょうだん]を言[い]って、会議[かいぎ]の空気[くうき]を和[やわ]らげた。", "sentence_source": "generated"}, {"text": "病気は軽かったので、二日で学校に戻れた。", "target_word": "軽かった", "complexity_tier": "T3", "furigana": "病気[びょうき]は軽[かる]かったので、二日[ふつか]で学校[がっこう]に戻[もど]れた。", "sentence_source": "generated"}, {"text": "軽い運動を毎日続けると、体の調子がよくなる。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "軽[かる]い運動[うんどう]を毎日[まいにち]続[つづ]けると、体[からだ]の調子[ちょうし]がよくなる。", "sentence_source": "generated"}, {"text": "先生は軽い口調で話したが、内容は大切な注意だった。", "target_word": "軽い", "complexity_tier": "T3", "furigana": "先生[せんせい]は軽[かる]い口調[くちょう]で話[はな]したが、内容[ないよう]は大切[たいせつ]な注意[ちゅうい]だった。", "sentence_source": "generated"}, {"text": "夜は軽く食べるだけにして、早く寝た。", "target_word": "軽く", "complexity_tier": "T3", "furigana": "夜[よる]は軽[かる]く食[た]べるだけにして、早[はや]く寝[ね]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "軽い", "label": "終止形・連体形"}, {"form": "軽く", "label": "連用形"}, {"form": "軽かった", "label": "過去形"}, {"form": "軽くない", "label": "否定形"}, {"form": "軽ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "重さが少ない。程度が小さい。深刻でなく気軽な様子。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80324491-1491-4ee3-96f9-8789a18dac12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38861, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "軽い", "is_correct": true, "explanation": "程度が小さいけがの意味で、病院に行かなかった理由に合う。"}, {"text": "冷たい", "is_correct": false, "explanation": "温度の語で、けがの程度を表さない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さの語で、けがの説明には合わない。"}, {"text": "丸い", "is_correct": false, "explanation": "形の語で、けがの程度には合わない。"}], "explanations": {"軽い": "程度が小さいけがの意味で、病院に行かなかった理由に合う。", "冷たい": "温度の語で、けがの程度を表さない。", "遅い": "速さの語で、けがの説明には合わない。", "丸い": "形の語で、けがの程度には合わない。"}, "sentence_index": 0, "correct_answer": "軽い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は家賃が軽くて、学生にも借りやすい。", "explanation": "家賃の安さは〈安い〉で表す。〈軽い〉は重さや程度の語なので、家賃には使えない。"}, {"text": "参加者の数は軽かったので、会場はがらがらだった。", "explanation": "数量の少なさは〈少ない〉で表す。〈軽い〉は人数や数には使えない。"}, {"text": "この肉は軽くて、噛むとすぐ切れる。", "explanation": "肉のやわらかさは〈柔らかい〉で表す。〈軽い〉は重さや程度の語なので、食感には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38861, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "軽かった", "is_correct": true, "explanation": "病気の程度が小さかったので二日で戻れた、と文意が通る。"}, {"text": "赤かった", "is_correct": false, "explanation": "色の語で、回復の理由にならない。"}, {"text": "甘かった", "is_correct": false, "explanation": "味の語で、病気の説明には合わない。"}, {"text": "黒かった", "is_correct": false, "explanation": "色の語で、病状の説明には合わない。"}], "explanations": {"軽かった": "病気の程度が小さかったので二日で戻れた、と文意が通る。", "赤かった": "色の語で、回復の理由にならない。", "甘かった": "味の語で、病気の説明には合わない。", "黒かった": "色の語で、病状の説明には合わない。"}, "sentence_index": 6, "correct_answer": "軽かった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜の道は軽くて、車の音が遠くから聞こえた。", "explanation": "道の静けさは〈静か〉で表す。〈軽い〉は重さや程度の語なので、道の様子には使えない。"}, {"text": "夜の空は軽く、星がよく見えた。", "explanation": "空の澄み具合は〈澄んでいる〉で表す。〈軽い〉は重さや程度の語なので、空の様子には使えない。"}, {"text": "駅までの道のりは軽く、歩いても十分とかからない。", "explanation": "距離の近さは〈近い〉で表す。〈軽い〉は重さや程度の語なので、道のりには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38861, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昼は軽いの食事で済ませて、午後の仕事に戻った。", "corrected_sentence": "昼は軽い食事で済ませて、午後の仕事に戻った。", "error_description": "誤り：「軽いの食事」。正しくは「軽い食事」。形容詞が名詞を修飾するときは「の」を付けず、そのまま続ける。「の」は名詞に付く助詞なので、形容詞「軽い」には付けられない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "軽い", "is_correct": true, "explanation": "連体形で、名詞「食事」を修飾する正しい形。"}, {"text": "軽く", "is_correct": false, "explanation": "連用形で、名詞を直接修飾できない。「軽く食事」は成り立たない。"}, {"text": "軽かった", "is_correct": false, "explanation": "過去形で、名詞に直接続けると文が成り立たない。"}, {"text": "軽ければ", "is_correct": false, "explanation": "仮定形で、名詞「食事」を修飾できない。"}], "correct_form": "軽い", "base_form": "軽い", "form_label": "連体形", "sentence_index": 1, "explanations": {"軽い": "連体形で、名詞「食事」を修飾する正しい形。", "軽く": "連用形で、名詞を直接修飾できない。「軽く食事」は成り立たない。", "軽かった": "過去形で、名詞に直接続けると文が成り立たない。", "軽ければ": "仮定形で、名詞「食事」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38861, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "咳は軽いで、午後には治まった。", "corrected_sentence": "咳は軽くて、午後には治まった。", "error_description": "誤り：「軽いで」。正しくは「軽くて」。形容詞を「て」で続けるときは連用形「軽く」に「て」を付ける。「軽いで」は形が不正。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "軽い", "is_correct": true, "explanation": "連体形で、名詞「運動」を修飾する正しい形。「軽い運動を毎日続ける」と続く。"}, {"text": "軽くて", "is_correct": false, "explanation": "「て」で続ける形で、名詞「運動」を直接修飾できない。「軽くて運動」は成り立たない。"}, {"text": "軽かったら", "is_correct": false, "explanation": "仮定の形で、名詞「運動」を修飾できず、文が成り立たない。"}, {"text": "軽かろう", "is_correct": false, "explanation": "推量の形で、名詞「運動」を直接修飾できない。「軽かろう運動」は成り立たない。"}], "correct_form": "軽い", "base_form": "軽い", "form_label": "連体形", "sentence_index": 7, "explanations": {"軽い": "連体形で、名詞「運動」を修飾する正しい形。「軽い運動を毎日続ける」と続く。", "軽くて": "「て」で続ける形で、名詞「運動」を直接修飾できない。「軽くて運動」は成り立たない。", "軽かったら": "仮定の形で、名詞「運動」を修飾できず、文が成り立たない。", "軽かろう": "推量の形で、名詞「運動」を直接修飾できない。「軽かろう運動」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
