INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38862, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "全体で同じくらいの大きさや割合であること。", "primary_collocate": null, "pronunciation": "きんいつ", "ipa": "kiɴitsɯ", "syllable_count": 4, "sentences": [{"text": "りんごの大きさが均一なので、箱に並べるときれいに見える。", "target_word": "均一", "complexity_tier": "T3", "furigana": "りんごの大(おお)きさが均一(きんいつ)なので、箱(はこ)に並(なら)べるときれいに見(み)える。", "sentence_source": "generated"}, {"text": "粒の大きさが均一な砂は、建築の材料に向いている。", "target_word": "均一", "complexity_tier": "T3", "furigana": "粒(つぶ)の大(おお)きさが均一(きんいつ)な砂(すな)は、建築(けんちく)の材料(ざいりょう)に向(む)いている。", "sentence_source": "generated"}, {"text": "クッキーの大きさが均一になるよう、生地を同じ量ずつ切り分けた。", "target_word": "均一", "complexity_tier": "T3", "furigana": "クッキーの大(おお)きさが均一(きんいつ)になるよう、生地(きじ)を同(おな)じ量(りょう)ずつ切(き)り分(わ)けた。", "sentence_source": "generated"}, {"text": "木の太さが均一でないため、柵の高さがそろわなかった。", "target_word": "均一", "complexity_tier": "T3", "furigana": "木(き)の太(ふと)さが均一(きんいつ)でないため、柵(さく)の高(たか)さがそろわなかった。", "sentence_source": "generated"}, {"text": "成分が均一に含まれているか、検査で確かめる。", "target_word": "均一", "complexity_tier": "T3", "furigana": "成分(せいぶん)が均一(きんいつ)に含(ふく)まれているか、検査(けんさ)で確(たし)かめる。", "sentence_source": "generated"}, {"text": "色の濃さが均一なタイルを選んで、床に敷いた。", "target_word": "均一", "complexity_tier": "T3", "furigana": "色(いろ)の濃(こ)さが均一(きんいつ)なタイルを選(えら)んで、床(ゆか)に敷(し)いた。", "sentence_source": "generated"}, {"text": "各チームの力が均一だったので、試合は最後まで結果が読めなかった。", "target_word": "均一", "complexity_tier": "T3", "furigana": "各(かく)チームの力(ちから)が均一(きんいつ)だったので、試合(しあい)は最後(さいご)まで結果(けっか)が読(よ)めなかった。", "sentence_source": "generated"}, {"text": "髪を均一な長さに切りそろえてもらった。", "target_word": "均一", "complexity_tier": "T3", "furigana": "髪(かみ)を均一(きんいつ)な長(なが)さに切(き)りそろえてもらった。", "sentence_source": "generated"}, {"text": "豆の大きさが均一なほど、コーヒーはむらなく挽ける。", "target_word": "均一", "complexity_tier": "T3", "furigana": "豆(まめ)の大(おお)きさが均一(きんいつ)なほど、コーヒーはむらなく挽(ひ)ける。", "sentence_source": "generated"}, {"text": "雨の量は地域ごとに違い、全国で均一ではない。", "target_word": "均一", "complexity_tier": "T3", "furigana": "雨(あめ)の量(りょう)は地域(ちいき)ごとに違(ちが)い、全国(ぜんこく)で均一(きんいつ)ではない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "均一", "label": "基本形"}, {"form": "均一な", "label": "連体形"}, {"form": "均一に", "label": "連用形"}, {"form": "均一だ", "label": "終止形"}], "register": "neutral", "sense_fingerprint": "全体を通して大きさや割合がほぼそろっていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T4: contains vocabulary far above tier T4: 挽け (Zipf 1.06)']::text[], '054d68fb-c4d4-40c1-91e6-960db9c1bc1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38862, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大胆", "is_correct": false, "explanation": "思い切ったさまを表し、大きさの状態を説明する語ではない。"}, {"text": "陰湿", "is_correct": false, "explanation": "ねちねちとしたさまを表し、りんごの大きさには使わない。"}, {"text": "均一", "is_correct": true, "explanation": "全体の大きさがそろっているという意味で、りんごを箱に並べたときの見え方に合う。"}, {"text": "遠大", "is_correct": false, "explanation": "規模や将来が大きいさまを表し、大きさがそろっている状態の説明にはならない。"}], "explanations": {"大胆": "思い切ったさまを表し、大きさの状態を説明する語ではない。", "陰湿": "ねちねちとしたさまを表し、りんごの大きさには使わない。", "均一": "全体の大きさがそろっているという意味で、りんごを箱に並べたときの見え方に合う。", "遠大": "規模や将来が大きいさまを表し、大きさがそろっている状態の説明にはならない。"}, "sentence_index": 0, "correct_answer": "均一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は話し方を均一に変えて、場の空気に合わせた。", "explanation": "話し方を変える動きは〈均一〉では表せない。ここは〈柔軟に〉の意味で、差がない状態を示す語ではない。"}, {"text": "店には均一な果物が多様な種類で並んでいる。", "explanation": "ここは〈多様〉の意味。均一は差がない状態を表し、種類の多さを言う語ではない。"}, {"text": "彼女は宿題を均一に終わらせた。", "explanation": "ここは〈さっさと〉の意味。均一は差がない状態を表し、作業の速さを言う語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38862, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "朴訥", "is_correct": false, "explanation": "飾り気がなく口数が少ないさまで、チームの力の状態には使わない。"}, {"text": "奔放", "is_correct": false, "explanation": "自由で型にはまらないさまで、力がそろっている状態の説明にはならない。"}, {"text": "卑近", "is_correct": false, "explanation": "身近で俗っぽいさまで、チームの力を表す語ではない。"}, {"text": "均一", "is_correct": true, "explanation": "力に差がないという意味で、結果が読めなかった理由として文脈に合う。"}], "explanations": {"朴訥": "飾り気がなく口数が少ないさまで、チームの力の状態には使わない。", "奔放": "自由で型にはまらないさまで、力がそろっている状態の説明にはならない。", "卑近": "身近で俗っぽいさまで、チームの力を表す語ではない。", "均一": "力に差がないという意味で、結果が読めなかった理由として文脈に合う。"}, "sentence_index": 6, "correct_answer": "均一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "税率が所得によって均一に変わる。", "explanation": "ここは〈累進〉の意味。均一は全体に差がない状態を表し、所得に応じて段階的に高くなる仕組みとは合わない。"}, {"text": "彼女は表情を均一に変えて、驚いたふりをした。", "explanation": "ここは〈顔色を変える〉の意味。均一は差がない状態を表し、驚いて顔色が変わる場面には使えない。"}, {"text": "不満を均一に伝えた。", "explanation": "ここは〈はっきり伝える〉の意味。均一は差がない状態を表すので、感情を伝える仕方には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38862, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "果物の大きさを均一でそろえると、箱詰めがしやすい。", "corrected_sentence": "果物の大きさを均一にそろえると、箱詰めがしやすい。", "error_description": "正しくは『均一に』（連用形）。『均一で』は断定の『だ』の連用形で、『そろえる』を正しく修飾できない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38862, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "野菜の切り方を均一がそろえると、火の通りがよくなる。", "corrected_sentence": "野菜の切り方を均一にそろえると、火の通りがよくなる。", "error_description": "正しくは『均一に』。『均一が』は主語を示す『が』で、『そろえる』の対象を示せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
