INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38863, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38863, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "複数のものの間に差がなく、一様であること。", "primary_collocate": null, "pronunciation": "きんいつ", "ipa": "kiɴitsɯ", "syllable_count": 4, "sentences": [{"text": "まず、良質な全粒粉のパンを用意し、その多孔質な表面にピーナッツバターを均一に塗る。", "target_word": "均一", "complexity_tier": "T4", "furigana": "まず、良質(りょうしつ)な全粒粉(ぜんりゅうふん)のパンを用意(ようい)し、その多孔質(たこうしつ)な表面(ひょうめん)にピーナッツバターを均一(きんいつ)に塗(ぬ)る。", "sentence_source": "mined"}, {"text": "色にむらが出ないように、壁の塗料を均一に塗ってください。", "target_word": "均一", "complexity_tier": "T3", "furigana": "色(いろ)にむらが出(で)ないように、壁(かべ)の塗料(とりょう)を均一(きんいつ)に塗(ぬ)ってください。", "sentence_source": "generated"}, {"text": "この工場では、均一な品質の製品を大量に作っている。", "target_word": "均一", "complexity_tier": "T3", "furigana": "この工場(こうじょう)では、均一(きんいつ)な品質(ひんしつ)の製品(せいひん)を大量(たいりょう)に作(つく)っている。", "sentence_source": "generated"}, {"text": "生地の厚さが均一でないと、焼きむらができてしまう。", "target_word": "均一", "complexity_tier": "T3", "furigana": "生地(きじ)の厚(あつ)さが均一(きんいつ)でないと、焼(や)きむらができてしまう。", "sentence_source": "generated"}, {"text": "肉に火を通すときは、熱が均一に伝わるように何度か裏返します。", "target_word": "均一", "complexity_tier": "T3", "furigana": "肉(にく)に火(ひ)を通(とお)すときは、熱(ねつ)が均一(きんいつ)に伝(つた)わるように何度(なんど)か裏返(うらがえ)します。", "sentence_source": "generated"}, {"text": "肥料を畑に均一にまくと、作物がそろって育つ。", "target_word": "均一", "complexity_tier": "T3", "furigana": "肥料(ひりょう)を畑(はたけ)に均一(きんいつ)にまくと、作物(さくもつ)がそろって育(そだ)つ。", "sentence_source": "generated"}, {"text": "光が均一に当たらないせいで、写真の一部だけ暗くなった。", "target_word": "均一", "complexity_tier": "T3", "furigana": "光(ひかり)が均一(きんいつ)に当(あ)たらないせいで、写真(しゃしん)の一部(いちぶ)だけ暗(くら)くなった。", "sentence_source": "generated"}, {"text": "このバスは距離に関係なく料金が均一だから、どこまで乗っても同じだ。", "target_word": "均一", "complexity_tier": "T3", "furigana": "このバスは距離(きょり)に関係(かんけい)なく料金(りょうきん)が均一(きんいつ)だから、どこまで乗(の)っても同(おな)じだ。", "sentence_source": "generated"}, {"text": "切り方が均一なほうが、野菜は同じ時間で煮える。", "target_word": "均一", "complexity_tier": "T3", "furigana": "切(き)り方(かた)が均一(きんいつ)なほうが、野菜(やさい)は同(おな)じ時間(じかん)で煮(に)える。", "sentence_source": "generated"}, {"text": "粉と水を均一に混ぜてから、冷蔵庫で休ませる。", "target_word": "均一", "complexity_tier": "T3", "furigana": "粉(こな)と水(みず)を均一(きんいつ)に混(ま)ぜてから、冷蔵庫(れいぞうこ)で休(やす)ませる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "均一", "label": "基本形"}, {"form": "均一な", "label": "連体形"}, {"form": "均一に", "label": "連用形"}, {"form": "均一だ", "label": "終止形"}], "register": "neutral", "sense_fingerprint": "ものの間に差がなく一様なこと。むらなく同じであるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '054d68fb-c4d4-40c1-91e6-960db9c1bc1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38863, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "均一", "is_correct": true, "explanation": "「むらなく同じ厚さに」の意味で、ピーナッツバターの塗り方を正しく表す。"}, {"text": "鮮明", "is_correct": false, "explanation": "色や輪郭がはっきりしているという意味で、バターを塗る仕方には合わない。"}, {"text": "頑強", "is_correct": false, "explanation": "しっかりして丈夫なさまを表し、塗り方の説明にはならない。"}, {"text": "無縁", "is_correct": false, "explanation": "かかわりがないという意味で、この文の『塗る』の修飾として成り立たない。"}], "explanations": {"均一": "「むらなく同じ厚さに」の意味で、ピーナッツバターの塗り方を正しく表す。", "鮮明": "色や輪郭がはっきりしているという意味で、バターを塗る仕方には合わない。", "頑強": "しっかりして丈夫なさまを表し、塗り方の説明にはならない。", "無縁": "かかわりがないという意味で、この文の『塗る』の修飾として成り立たない。"}, "sentence_index": 0, "correct_answer": "均一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二国の軍事力は、長いあいだ均一を競ってきた。", "explanation": "ここは〈競う〉の意味。均一は差がない状態を表し、競い合う対象にはならない。"}, {"text": "テストの点を均一に配って、平均を出した。", "explanation": "ここは〈配る〉の意味。均一は差がない状態で、点を配る動作には使わない。"}, {"text": "学校の均一を着て登校した。", "explanation": "ここは〈制服〉の意味。均一は差がない状態を表す語で、服の名前には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38863, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繊細", "is_correct": false, "explanation": "感覚や造りが細かく弱いさまを表し、光の当たり方には合わない。"}, {"text": "均一", "is_correct": true, "explanation": "すきまなく一様にという意味で、光が当たる範囲の状態を正しく表す。"}, {"text": "軽快", "is_correct": false, "explanation": "動きが軽やかなさまで、光が当たる様子とは結びつかない。"}, {"text": "無断", "is_correct": false, "explanation": "許可を取らないという意味で、光の当たり方の説明には使えない。"}], "explanations": {"繊細": "感覚や造りが細かく弱いさまを表し、光の当たり方には合わない。", "均一": "すきまなく一様にという意味で、光が当たる範囲の状態を正しく表す。", "軽快": "動きが軽やかなさまで、光が当たる様子とは結びつかない。", "無断": "許可を取らないという意味で、光の当たり方の説明には使えない。"}, "sentence_index": 6, "correct_answer": "均一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "勝負を均一に決めた。", "explanation": "ここは〈勝ち負けを決める〉の意味。均一は差がない状態を表し、勝敗を決める動作には使わない。"}, {"text": "彼女は怒りを均一に爆発させた。", "explanation": "ここは〈激しく〉の意味。均一は差がない状態を表し、勢いの強さは言わないので、爆発の仕方には使えない。"}, {"text": "季節ごとに、この店のメニューを均一に食べ比べる。", "explanation": "ここは〈食べ比べる〉の意味。均一は差がない状態で、味を比べる動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38863, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "スプーンでソースを均一な広げて、皿の端まで整えた。", "corrected_sentence": "スプーンでソースを均一に広げて、皿の端まで整えた。", "error_description": "正しくは『均一に』（連用形）。『均一な』は連体形で、動詞『広げて』を修飾できない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38863, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湯の温度を均一で保つと、茶葉がむらなく開く。", "corrected_sentence": "湯の温度を均一に保つと、茶葉がむらなく開く。", "error_description": "正しくは『均一に』（連用形）。『均一で』は断定の『だ』の連用形で、動詞『保つ』を正しく修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
