INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38864, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "同じようなものが、どこでも同じように混ざっていること。", "primary_collocate": null, "pronunciation": "きんしつ", "ipa": "kiɴɕitsɯ", "syllable_count": 4, "sentences": [{"text": "生地は均質になるまで、よくかき混ぜる。", "target_word": "均質", "complexity_tier": "T3", "furigana": "生地[きじ]は均質[きんしつ]になるまで、よくかき混[ま]ぜる。", "sentence_source": "generated"}, {"text": "絵の具を均質に溶かさないと、塗ったときに色むらが出る。", "target_word": "均質", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]を均質[きんしつ]に溶[と]かさないと、塗[ぬ]ったときに色[いろ]むらが出[で]る。", "sentence_source": "generated"}, {"text": "牛乳は、脂肪が均質に混ざるように処理されている。", "target_word": "均質", "complexity_tier": "T3", "furigana": "牛乳[ぎゅうにゅう]は、脂肪[しぼう]が均質[きんしつ]に混[ま]ざるように処理[しょり]されている。", "sentence_source": "generated"}, {"text": "このスープは具が均質に混ざっていて、どこをすくっても同じ味だ。", "target_word": "均質", "complexity_tier": "T3", "furigana": "このスープは具[ぐ]が均質[きんしつ]に混[ま]ざっていて、どこをすくっても同[おな]じ味[あじ]だ。", "sentence_source": "generated"}, {"text": "合金は、金属が均質に溶け合っているほど丈夫になる。", "target_word": "均質", "complexity_tier": "T3", "furigana": "合金[ごうきん]は、金属[きんぞく]が均質[きんしつ]に溶[と]け合[あ]っているほど丈夫[じょうぶ]になる。", "sentence_source": "generated"}, {"text": "肥料を土に均質に混ぜると、どの苗もよく育つ。", "target_word": "均質", "complexity_tier": "T3", "furigana": "肥料[ひりょう]を土[つち]に均質[きんしつ]に混[ま]ぜると、どの苗[なえ]もよく育[そだ]つ。", "sentence_source": "generated"}, {"text": "混ぜ方が足りず、砂糖が均質に行き渡らなかった。", "target_word": "均質", "complexity_tier": "T3", "furigana": "混[ま]ぜ方[かた]が足[た]りず、砂糖[さとう]が均質[きんしつ]に行[い]き渡[わた]らなかった。", "sentence_source": "generated"}, {"text": "コンクリートは、砂とセメントと水が均質に混ざった状態で固める。", "target_word": "均質", "complexity_tier": "T3", "furigana": "コンクリートは、砂[すな]とセメントと水[みず]が均質[きんしつ]に混[ま]ざった状態[じょうたい]で固[かた]める。", "sentence_source": "generated"}, {"text": "溶液を均質に保つため、実験中は常にかき混ぜておく。", "target_word": "均質", "complexity_tier": "T3", "furigana": "溶液[ようえき]を均質[きんしつ]に保[たも]つため、実験中[じっけんちゅう]は常[つね]にかき混[ま]ぜておく。", "sentence_source": "generated"}, {"text": "ミキサーにかけたジュースは、どこを飲んでも均質だ。", "target_word": "均質", "complexity_tier": "T3", "furigana": "ミキサーにかけたジュースは、どこを飲[の]んでも均質[きんしつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "均質", "label": "基本形"}, {"form": "均質な", "label": "連体形"}, {"form": "均質に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "混ぜたものが全体にむらなく同じように行き渡っている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b809ef64-f595-4298-95cf-ff21c951f823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38864, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "均質", "is_correct": true, "explanation": "均質は、中身にむらがなく一様になった状態を表す。よくかき混ぜて目指す仕上がりに合う。"}, {"text": "乾燥", "is_correct": false, "explanation": "乾燥は水分がなくなることを表す。混ぜ合わせた生地の状態を言うには合わない。"}, {"text": "相違", "is_correct": false, "explanation": "相違は違いがあることを表す。混ぜて一様になった生地の状態にはならない。"}, {"text": "冷静", "is_correct": false, "explanation": "冷静は落ち着いた態度を表す。生地の状態には使えない。"}], "explanations": {"均質": "均質は、中身にむらがなく一様になった状態を表す。よくかき混ぜて目指す仕上がりに合う。", "乾燥": "乾燥は水分がなくなることを表す。混ぜ合わせた生地の状態を言うには合わない。", "相違": "相違は違いがあることを表す。混ぜて一様になった生地の状態にはならない。", "冷静": "冷静は落ち着いた態度を表す。生地の状態には使えない。"}, "sentence_index": 0, "correct_answer": "均質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ケーキを、四人で均質に四等分した。", "explanation": "ここは〈等分〉の意味。均質は中身の性質がそろっていることで、分ける量をそろえる場面には等分を使う。"}, {"text": "三人の点数を合計して三で割ると、均質な値になる。", "explanation": "ここは〈平均〉の計算結果の場面。均質は中身の性質がそろっていることで、数値の平均を言うときには使わない。"}, {"text": "生徒たちは、先生の合図で均質に手を挙げた。", "explanation": "ここは〈一斉〉の意味。均質は中身のむらのなさで、動作がそろう様子には一斉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38864, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "均質", "is_correct": true, "explanation": "均質は、一様になって行き渡った状態を表す。砂糖が溶液全体に行き渡らなかったという文脈に合う。"}, {"text": "冷静", "is_correct": false, "explanation": "冷静は落ち着いた態度を表す。砂糖が行き渡る様子には合わない。"}, {"text": "鮮明", "is_correct": false, "explanation": "鮮明は色や像がはっきりしていることを表す。行き渡る状態には使わない。"}, {"text": "豊満", "is_correct": false, "explanation": "豊満は量や体つきが豊かな様子を表す。行き渡り方の説明には合わない。"}], "explanations": {"均質": "均質は、一様になって行き渡った状態を表す。砂糖が溶液全体に行き渡らなかったという文脈に合う。", "冷静": "冷静は落ち着いた態度を表す。砂糖が行き渡る様子には合わない。", "鮮明": "鮮明は色や像がはっきりしていることを表す。行き渡る状態には使わない。", "豊満": "豊満は量や体つきが豊かな様子を表す。行き渡り方の説明には合わない。"}, "sentence_index": 6, "correct_answer": "均質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議では、全員の発言の機会を均質に与えている。", "explanation": "ここは〈平等〉の意味。均質は中身や性質が一様なことで、人の機会を等しく与える場面には平等を使う。"}, {"text": "この市では、全世帯の税金を均質に定めている。", "explanation": "ここは〈一律〉の意味。均質は中身の一様さで、制度として同じ額を定める場合には一律を使う。"}, {"text": "この建物は、左右の窓の配置が均質に整っている。", "explanation": "ここは〈均斉〉の意味。均質は中身の一様さで、左右の釣り合いや整い具合には均斉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38864, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "生地が均質の混ざるまで、よくかき混ぜる。", "corrected_sentence": "生地が均質に混ざるまで、よくかき混ぜる。", "error_description": "誤りは「均質の」。「均質」は後ろの動詞「混ざる」を修飾するので、連用形の「均質に」が必要。連体修飾の「の」は動詞には付かないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38864, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この飲み物は、果汁と水が均質を混ざっている。", "corrected_sentence": "この飲み物は、果汁と水が均質に混ざっている。", "error_description": "誤りは「均質を」。「混ざる」を修飾するには連用形の「均質に」が必要で、目的語の「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
