INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38865, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "性質や状態が一様で、むらがないこと。また、そのさま。", "primary_collocate": null, "pronunciation": "きんしつ", "ipa": "kiɴɕitsɯ", "syllable_count": 4, "sentences": [{"text": "この布は、色むらがなく均質で、どこを見ても同じ濃さだ。", "target_word": "均質", "complexity_tier": "T3", "furigana": "この布[ぬの]は、色[いろ]むらがなく均質[きんしつ]で、どこを見[み]ても同[おな]じ濃[こ]さだ。", "sentence_source": "generated"}, {"text": "均質な製品を大量に作れるのが、機械の強みだ。", "target_word": "均質", "complexity_tier": "T3", "furigana": "均質[きんしつ]な製品[せいひん]を大量[たいりょう]に作[つく]れるのが、機械[きかい]の強[つよ]みだ。", "sentence_source": "generated"}, {"text": "手作りの品は一つずつ違うが、機械で作った品は均質だ。", "target_word": "均質", "complexity_tier": "T3", "furigana": "手作[てづく]りの品[しな]は一[ひと]つずつ違[ちが]うが、機械[きかい]で作[つく]った品[しな]は均質[きんしつ]だ。", "sentence_source": "generated"}, {"text": "大量生産では、どの製品も均質であることが求められる。", "target_word": "均質", "complexity_tier": "T3", "furigana": "大量生産[たいりょうせいさん]では、どの製品[せいひん]も均質[きんしつ]であることが求[もと]められる。", "sentence_source": "generated"}, {"text": "この畑の土は均質で、どこを掘っても同じ色をしている。", "target_word": "均質", "complexity_tier": "T3", "furigana": "この畑[はたけ]の土[つち]は均質[きんしつ]で、どこを掘[ほ]っても同[おな]じ色[いろ]をしている。", "sentence_source": "generated"}, {"text": "天然の木材は節があるので、人工の板ほど均質ではない。", "target_word": "均質", "complexity_tier": "T3", "furigana": "天然[てんねん]の木材[もくざい]は節[ふし]があるので、人工[じんこう]の板[いた]ほど均質[きんしつ]ではない。", "sentence_source": "generated"}, {"text": "生徒の学力が均質な学級は、同じ速さで授業を進めやすい。", "target_word": "均質", "complexity_tier": "T3", "furigana": "生徒[せいと]の学力[がくりょく]が均質[きんしつ]な学級[がっきゅう]は、同[おな]じ速[はや]さで授業[じゅぎょう]を進[すす]めやすい。", "sentence_source": "generated"}, {"text": "検査の結果、布の厚さは均質で、むらは見つからなかった。", "target_word": "均質", "complexity_tier": "T3", "furigana": "検査[けんさ]の結果[けっか]、布[ぬの]の厚[あつ]さは均質[きんしつ]で、むらは見[み]つからなかった。", "sentence_source": "generated"}, {"text": "同じ形の家が並ぶ町は、どこか均質な印象を与える。", "target_word": "均質", "complexity_tier": "T3", "furigana": "同[おな]じ形[かたち]の家[いえ]が並[なら]ぶ町[まち]は、どこか均質[きんしつ]な印象[いんしょう]を与[あた]える。", "sentence_source": "generated"}, {"text": "この米は、大きさも味も均質で、炊き上がりが美しい。", "target_word": "均質", "complexity_tier": "T3", "furigana": "この米[こめ]は、大[おお]きさも味[あじ]も均質[きんしつ]で、炊[た]き上[あ]がりが美[うつく]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "均質", "label": "基本形"}, {"form": "均質な", "label": "連体形"}, {"form": "均質に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "品質・性質が全体で一様で、ばらつきやむらがないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b809ef64-f595-4298-95cf-ff21c951f823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38865, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "均質", "is_correct": true, "explanation": "均質は性質や状態が一様でむらがないことを表す。色むらがない布の状態に合う。"}, {"text": "楔", "is_correct": false, "explanation": "楔は物を打ち込む道具の名で、布の状態を言うには合わない。"}, {"text": "挑発", "is_correct": false, "explanation": "挑発は相手を刺激する行為を指す。布の色の状態には使えない。"}, {"text": "相違", "is_correct": false, "explanation": "相違は違いがあることを表す。色むらがない状態を述べる文には合わない。"}], "explanations": {"均質": "均質は性質や状態が一様でむらがないことを表す。色むらがない布の状態に合う。", "楔": "楔は物を打ち込む道具の名で、布の状態を言うには合わない。", "挑発": "挑発は相手を刺激する行為を指す。布の色の状態には使えない。", "相違": "相違は違いがあることを表す。色むらがない状態を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "均質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姉と弟の小遣いを、均質に半分ずつ分けた。", "explanation": "ここは〈均等〉の意味。均質は中身や性質が一様なことで、金額を等しく分ける場面には均等を使う。"}, {"text": "審判は、両チームの反則を均質に判定した。", "explanation": "ここは〈公正〉の意味。均質は中身や性質の一様さで、判定の扱いが公正かどうかには公正を使う。"}, {"text": "両国の軍備は均質に保たれていて、どちらも攻め込めない。", "explanation": "ここは〈均衡〉の意味。均質は中身や性質が一様なことで、力が釣り合っている状態には均衡を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38865, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "均質", "is_correct": true, "explanation": "均質は、性質や状態が一様でむらがないことを表す。学力がそろっている学級という文脈に合う。"}, {"text": "容易", "is_correct": false, "explanation": "容易は「たやすい」という意味で、学力の状態を表すには合わない。"}, {"text": "鮮明", "is_correct": false, "explanation": "鮮明は輪郭や色がはっきりしている様子で、学力の一様さを表さない。"}, {"text": "密接", "is_correct": false, "explanation": "密接は関係が近いことを表す。学力の状態を述べる語ではない。"}], "explanations": {"均質": "均質は、性質や状態が一様でむらがないことを表す。学力がそろっている学級という文脈に合う。", "容易": "容易は「たやすい」という意味で、学力の状態を表すには合わない。", "鮮明": "鮮明は輪郭や色がはっきりしている様子で、学力の一様さを表さない。", "密接": "密接は関係が近いことを表す。学力の状態を述べる語ではない。"}, "sentence_index": 6, "correct_answer": "均質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国では、男女の権利が均質に保障されている。", "explanation": "ここは〈平等〉の意味。均質は中身や性質が一様なことで、人の権利を等しく扱う場面には平等を使う。"}, {"text": "三人の点数を合計して三で均質に割ると、平均はおよそ七十点になる。", "explanation": "ここは〈平均〉の計算の場面。均質は性質がそろっていることで、数を割る操作の仕方には使わない。"}, {"text": "会社では、社員の給料を均質に決めている。", "explanation": "ここは〈一律〉の意味。均質は中身の一様さで、制度として同じ額に決める場合には一律を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38865, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この板は厚さが均質を、どこを測っても同じだ。", "corrected_sentence": "この板は厚さが均質で、どこを測っても同じだ。", "error_description": "誤りは「均質を」。「均質」は状態を表すので、後ろに目的語の「を」は付かない。正しくは状態を述べる「で」（均質で）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38865, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この茶は色が均質へ、どの湯飲みに注いでも同じだ。", "corrected_sentence": "この茶は色が均質で、どの湯飲みに注いでも同じだ。", "error_description": "誤りは「均質へ」。「均質」は状態を表すので、方向を示す「へ」は付かない。正しくは状態を述べる「で」（均質で）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38866, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「便宜を図った」で、対象を示す正しい格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「便宜に図った」では対象を示せず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示すため、「便宜で図った」では対象を表せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すため、「便宜より図った」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「便宜を図った」で、対象を示す正しい格助詞。", "に": "「便宜に図った」では対象を示せず、文が成り立たない。", "で": "手段を示すため、「便宜で図った」では対象を表せず不自然。", "より": "比較を示すため、「便宜より図った」では意味が通らない。"}, "error_tags": {"に": "位置・相手", "で": "手段", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
