INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38866, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをうまくできるように、心を動かして動くこと。", "primary_collocate": null, "pronunciation": "はかる", "ipa": "hakaɾɯ", "syllable_count": 3, "sentences": [{"text": "先生は新入生が早くなじめるよう、クラスの交流を図った。", "target_word": "図った", "complexity_tier": "T3", "furigana": "先生[せんせい]は新入生[しんにゅうせい]が早[はや]くなじめるよう、クラスの交流[こうりゅう]を図[はか]った。", "sentence_source": "generated"}, {"text": "社長は取引先のために、できるだけの便宜を図った。", "target_word": "図った", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は取引先[とりひきさき]のために、できるだけの便宜[べんぎ]を図[はか]った。", "sentence_source": "generated"}, {"text": "町は観光客を増やそうと、駅前の活性化を図っています。", "target_word": "図って", "complexity_tier": "T3", "furigana": "町[まち]は観光客[かんこうきゃく]を増[ふ]やそうと、駅前[えきまえ]の活性化[かっせいか]を図[はか]っています。", "sentence_source": "generated"}, {"text": "両親との意思の疎通を図るため、毎週手紙を書いています。", "target_word": "図る", "complexity_tier": "T3", "furigana": "両親[りょうしん]との意思[いし]の疎通[そつう]を図[はか]るため、毎週[まいしゅう]手紙[てがみ]を書[か]いています。", "sentence_source": "generated"}, {"text": "医師は患者の負担を軽くするため、治療の簡素化を図った。", "target_word": "図った", "complexity_tier": "T3", "furigana": "医師[いし]は患者[かんじゃ]の負担[ふたん]を軽[かる]くするため、治療[ちりょう]の簡素化[かんそか]を図[はか]った。", "sentence_source": "generated"}, {"text": "彼女は仲間との和解を図ろうとして、先に頭を下げた。", "target_word": "図ろう", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は仲間[なかま]との和解[わかい]を図[はか]ろうとして、先[さき]に頭[あたま]を下[さ]げた。", "sentence_source": "generated"}, {"text": "会社は赤字から抜け出そうと、経営の立て直しを図っている。", "target_word": "図って", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は赤字[あかじ]から抜[ぬ]け出[だ]そうと、経営[けいえい]の立[た]て直[なお]しを図[はか]っている。", "sentence_source": "generated"}, {"text": "新しい店長は職場の雰囲気の改善を図り、毎朝みんなに声をかけた。", "target_word": "図り", "complexity_tier": "T3", "furigana": "新[あたら]しい店長[てんちょう]は職場[しょくば]の雰囲気[ふんいき]の改善[かいぜん]を図[はか]り、毎朝[まいあさ]みんなに声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "近所どうしの連携を図って、見回りの当番を決めた。", "target_word": "図って", "complexity_tier": "T3", "furigana": "近所[きんじょ]どうしの連携[れんけい]を図[はか]って、見回[みまわ]りの当番[とうばん]を決[き]めた。", "sentence_source": "generated"}, {"text": "選手たちは調子を取り戻そうと、練習方法の見直しを図った。", "target_word": "図った", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは調子[ちょうし]を取[と]り戻[もど]そうと、練習方法[れんしゅうほうほう]の見直[みなお]しを図[はか]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "図る", "label": "終止形"}, {"form": "図り", "label": "連用形"}, {"form": "図って", "label": "て形"}, {"form": "図った", "label": "過去形"}, {"form": "図らない", "label": "否定形"}, {"form": "図ろう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "物事がうまく進むように、自分から考えて働きかける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: なじめる (Zipf 1.13)']::text[], 'c171a401-7adc-4cc9-9573-2a4e0f6702de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38866, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "図った", "is_correct": true, "explanation": "「クラスの交流を図った」で、交流を促すために働きかけたという意味になり、文脈に合う。"}, {"text": "叱った", "is_correct": false, "explanation": "「クラスの交流を叱った」は意味が通らず、新入生がなじめるよう配慮する文脈と合わない。"}, {"text": "叩いた", "is_correct": false, "explanation": "「クラスの交流を叩いた」は成り立たず、新入生を支える流れと合わない。"}, {"text": "誓った", "is_correct": false, "explanation": "「クラスの交流を誓った」は不自然で、交流を進める働きかけという文脈に合わない。"}], "explanations": {"図った": "「クラスの交流を図った」で、交流を促すために働きかけたという意味になり、文脈に合う。", "叱った": "「クラスの交流を叱った」は意味が通らず、新入生がなじめるよう配慮する文脈と合わない。", "叩いた": "「クラスの交流を叩いた」は成り立たず、新入生を支える流れと合わない。", "誓った": "「クラスの交流を誓った」は不自然で、交流を進める働きかけという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "図った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ストップウォッチで走る時間を図った。", "explanation": "ここは〈計る〉の意味。時間は計るもので、図るは心を動かして物事を進める意味なので合わない。"}, {"text": "彼女は庭の見取り図を図った。", "explanation": "ここは〈描く〉の意味。図面や見取り図を描く場合は描くを使い、図るは働きかける意味なので合わない。"}, {"text": "彼は込み上げる怒りを図った。", "explanation": "ここは〈抑える〉の意味。感情を抑える場合は抑えるを使い、図るは物事を進める働きかけを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38866, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "図って", "is_correct": true, "explanation": "「経営の立て直しを図っている」で、立て直しを進めている状態を表し、文脈に合う。"}, {"text": "拒んで", "is_correct": false, "explanation": "「立て直しを拒んでいる」は赤字から抜け出そうとする文脈と合わない。"}, {"text": "殴って", "is_correct": false, "explanation": "「立て直しを殴っている」は成り立たず、経営の改善という流れに合わない。"}, {"text": "蹴って", "is_correct": false, "explanation": "「立て直しを蹴っている」は不自然で、経営を改善する文脈と合わない。"}], "explanations": {"図って": "「経営の立て直しを図っている」で、立て直しを進めている状態を表し、文脈に合う。", "拒んで": "「立て直しを拒んでいる」は赤字から抜け出そうとする文脈と合わない。", "殴って": "「立て直しを殴っている」は成り立たず、経営の改善という流れに合わない。", "蹴って": "「立て直しを蹴っている」は不自然で、経営を改善する文脈と合わない。"}, "sentence_index": 6, "correct_answer": "図って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来月の議題を図った。", "explanation": "ここは〈諮る〉の意味。議題を会議にかける場合は諮るを使い、図るは働きかけの意味なので合わない。"}, {"text": "家族の記念写真を図った。", "explanation": "ここは〈撮る〉の意味。写真を写す場合は撮るを使い、図るは物事を進める働きかけを表すので合わない。"}, {"text": "隙間を図って、冷気を防いだ。", "explanation": "ここは〈塞ぐ〉の意味。隙間を埋める場合は塞ぐを使い、図るは働きかけを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38866, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店長は新人の成長を図っため、毎週面談をしている。", "corrected_sentence": "店長は新人の成長を図るため、毎週面談をしている。", "error_description": "誤りは「図っため」。正しくは「図るため」。「ため」は辞書形に続くので、「図っ」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "図った", "is_correct": true, "explanation": "「便宜を図った」で、過去の行為を述べる文として正しい。"}, {"text": "図って", "is_correct": false, "explanation": "て形のため文末に置けず、「便宜を図って。」では文が終わらない。"}, {"text": "図ろう", "is_correct": false, "explanation": "意志形で、過去に行った便宜を述べる文と合わない。"}, {"text": "図れ", "is_correct": false, "explanation": "命令形で、社長の行為を述べる文と合わない。"}], "correct_form": "図った", "base_form": "図る", "form_label": "過去形", "sentence_index": 1, "explanations": {"図った": "「便宜を図った」で、過去の行為を述べる文として正しい。", "図って": "て形のため文末に置けず、「便宜を図って。」では文が終わらない。", "図ろう": "意志形で、過去に行った便宜を述べる文と合わない。", "図れ": "命令形で、社長の行為を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38866, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は住民同士の交流に図るため、毎月祭りを開いている。", "corrected_sentence": "市は住民同士の交流を図るため、毎月祭りを開いている。", "error_description": "誤りは「交流に図る」。正しくは「交流を図る」。図るは「〜を図る」で対象を取るので、「に」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "図り", "is_correct": true, "explanation": "「改善を図り、」で連用形として後ろに続く文を作り、文脈に合う。"}, {"text": "図る", "is_correct": false, "explanation": "辞書形は「改善を図る、」と続けられず、文の流れが成り立たない。"}, {"text": "図られ", "is_correct": false, "explanation": "受身形で、「改善を図られ」は主語が「が」になる形で、目的語「を」と合わない。"}, {"text": "図りたい", "is_correct": false, "explanation": "願望の形で、店長の行動を述べる文と合わない。"}], "correct_form": "図り", "base_form": "図る", "form_label": "連用形", "sentence_index": 7, "explanations": {"図り": "「改善を図り、」で連用形として後ろに続く文を作り、文脈に合う。", "図る": "辞書形は「改善を図る、」と続けられず、文の流れが成り立たない。", "図られ": "受身形で、「改善を図られ」は主語が「が」になる形で、目的語「を」と合わない。", "図りたい": "願望の形で、店長の行動を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
