INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38867, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある目的を達成するために、方法や手段を考えて実行すること。", "primary_collocate": null, "pronunciation": "はかる", "ipa": "hakaɾɯ", "syllable_count": 3, "sentences": [{"text": "これにより、ムダを省きながら収量の「最適化」を図ることができます。", "target_word": "図る", "complexity_tier": "T3", "furigana": "これにより、ムダを省[はぶ]きながら収量[しゅうりょう]の「最適化[さいてきか]」を図[はか]ることができます。", "sentence_source": "mined"}, {"text": "会社は新しい機械を入れて、仕事の効率化を図った。", "target_word": "図った", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新[あたら]しい機械[きかい]を入[い]れて、仕事[しごと]の効率化[こうりつか]を図[はか]った。", "sentence_source": "generated"}, {"text": "市は住民との連携を図るため、毎月会議を開いています。", "target_word": "図る", "complexity_tier": "T3", "furigana": "市[し]は住民[じゅうみん]との連携[れんけい]を図[はか]るため、毎月[まいつき]会議[かいぎ]を開[ひら]いています。", "sentence_source": "generated"}, {"text": "彼は会社の売り上げを伸ばすため、新しい販売計画の実施を図った。", "target_word": "図った", "complexity_tier": "T3", "furigana": "彼[かれ]は会社[かいしゃ]の売[う]り上[あ]げを伸[の]ばすため、新[あたら]しい販売計画[はんばいけいかく]の実施[じっし]を図[はか]った。", "sentence_source": "generated"}, {"text": "店は売り上げの回復を図り、新しい商品を並べました。", "target_word": "図り", "complexity_tier": "T3", "furigana": "店[みせ]は売[う]り上[あ]げの回復[かいふく]を図[はか]り、新[あたら]しい商品[しょうひん]を並[なら]べました。", "sentence_source": "generated"}, {"text": "工場は費用を減らすため、作業の無駄を省いて合理化を図っている。", "target_word": "図って", "complexity_tier": "T3", "furigana": "工場[こうじょう]は費用[ひよう]を減[へ]らすため、作業[さぎょう]の無駄[むだ]を省[はぶ]いて合理化[ごうりか]を図[はか]っている。", "sentence_source": "generated"}, {"text": "チームの結束を図ろうと、監督は全員で食事に行くことにした。", "target_word": "図ろう", "complexity_tier": "T3", "furigana": "チームの結束[けっそく]を図[はか]ろうと、監督[かんとく]は全員[ぜんいん]で食事[しょくじ]に行[い]くことにした。", "sentence_source": "generated"}, {"text": "学校は生徒の安全の確保を図るため、門に見守りの人を置いています。", "target_word": "図る", "complexity_tier": "T3", "furigana": "学校[がっこう]は生徒[せいと]の安全[あんぜん]の確保[かくほ]を図[はか]るため、門[もん]に見守[みまも]りの人[ひと]を置[お]いています。", "sentence_source": "generated"}, {"text": "国は物価の安定を図る方針を発表した。", "target_word": "図る", "complexity_tier": "T3", "furigana": "国[くに]は物価[ぶっか]の安定[あんてい]を図[はか]る方針[ほうしん]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "早く問題の解決を図らなければ、被害が広がってしまう。", "target_word": "図ら", "complexity_tier": "T3", "furigana": "早[はや]く問題[もんだい]の解決[かいけつ]を図[はか]らなければ、被害[ひがい]が広[ひろ]がってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "図る", "label": "終止形"}, {"form": "図り", "label": "連用形"}, {"form": "図って", "label": "て形"}, {"form": "図った", "label": "過去形"}, {"form": "図らない", "label": "否定形"}, {"form": "図ろう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "目的の達成のために方法を考えて実行する(改善・連携・便宜などを図る)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c171a401-7adc-4cc9-9573-2a4e0f6702de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38867, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "図る", "is_correct": true, "explanation": "「最適化を図ることができます」で、目的のために手を打つという意味になり、文脈に合う。"}, {"text": "断る", "is_correct": false, "explanation": "「最適化を断ることができます」は意味が通らず、最適化を進める文脈と合わない。"}, {"text": "誓う", "is_correct": false, "explanation": "「最適化を誓うことができます」は成り立たず、効率よく収量を上げるという流れと合わない。"}, {"text": "拒む", "is_correct": false, "explanation": "「最適化を拒むことができます」は意味が通らず、収量を増やす文脈と合わない。"}], "explanations": {"図る": "「最適化を図ることができます」で、目的のために手を打つという意味になり、文脈に合う。", "断る": "「最適化を断ることができます」は意味が通らず、最適化を進める文脈と合わない。", "誓う": "「最適化を誓うことができます」は成り立たず、効率よく収量を上げるという流れと合わない。", "拒む": "「最適化を拒むことができます」は意味が通らず、収量を増やす文脈と合わない。"}, "sentence_index": 0, "correct_answer": "図る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、体重を図っている。", "explanation": "ここは〈量る〉の意味。体重など重さを量る場合は量るを使い、図るは目的のために手を打つ意味なので合わない。"}, {"text": "会議で来月の議題を図った。", "explanation": "ここは〈諮る〉の意味。議題を会議にかける場合は諮るを使い、図るは目的達成のために手段を実行する意味なので合わない。"}, {"text": "旅先の地図を図って、友人に渡した。", "explanation": "ここは〈描く〉の意味。地図を描く動作には描くを使い、図るは目的のために方法を実行する意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38867, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "図ろう", "is_correct": true, "explanation": "「チームの結束を図ろうと」で、目的のために行動するという意味になり、文脈に合う。"}, {"text": "諦めよう", "is_correct": false, "explanation": "「結束を諦めようと」は意味が通らず、結束を高める文脈と合わない。"}, {"text": "叱ろう", "is_correct": false, "explanation": "「結束を叱ろう」は成り立たず、全員で食事に行く流れと合わない。"}, {"text": "競おう", "is_correct": false, "explanation": "「結束を競おう」は不自然で、チームの結束を高めるという文脈に合わない。"}], "explanations": {"図ろう": "「チームの結束を図ろうと」で、目的のために行動するという意味になり、文脈に合う。", "諦めよう": "「結束を諦めようと」は意味が通らず、結束を高める文脈と合わない。", "叱ろう": "「結束を叱ろう」は成り立たず、全員で食事に行く流れと合わない。", "競おう": "「結束を競おう」は不自然で、チームの結束を高めるという文脈に合わない。"}, "sentence_index": 6, "correct_answer": "図ろう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅先で景色の写真を図った。", "explanation": "ここは〈撮る〉の意味。写真を写す場合は撮るを使い、図るは目的のために方法を実行する意味なので合わない。"}, {"text": "二人は別れ際に名刺を図った。", "explanation": "ここは〈交わす〉の意味。名刺は交わすもので、図るは目的達成のために方法を実行する意味なので合わない。"}, {"text": "テストで難しい数学の問題を図った。", "explanation": "ここは〈解く〉の意味。問題の答えを出す場合は解くを使い、図るは目的達成のための方法を実行する意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38867, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は住民の安全を図るを、道路の整備を進めている。", "corrected_sentence": "市は住民の安全を図るため、道路の整備を進めている。", "error_description": "誤りは「図るを」。「図る」の後に「を」は続かず、目的は「ため」で表す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "図った", "is_correct": true, "explanation": "「仕事の効率化を図った」で、過去の出来事を述べる文の文末として正しい。"}, {"text": "図って", "is_correct": false, "explanation": "て形のため文末に置けず、「図って。」では文が終わらない。"}, {"text": "図ろう", "is_correct": false, "explanation": "意志形で、過去の出来事を述べる文と合わない。"}, {"text": "図れ", "is_correct": false, "explanation": "命令形で、会社の行動を報告する文と合わない。"}], "correct_form": "図った", "base_form": "図る", "form_label": "過去形", "sentence_index": 1, "explanations": {"図った": "「仕事の効率化を図った」で、過去の出来事を述べる文の文末として正しい。", "図って": "て形のため文末に置けず、「図って。」では文が終わらない。", "図ろう": "意志形で、過去の出来事を述べる文と合わない。", "図れ": "命令形で、会社の行動を報告する文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38867, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "相手との関係の改善を図りため、まず話し合いの場を設けた。", "corrected_sentence": "相手との関係の改善を図るため、まず話し合いの場を設けた。", "error_description": "誤りは「図りため」。正しくは「図るため」。「ため」は辞書形に続くので、連用形の「図り」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "図る", "is_correct": true, "explanation": "「安全の確保を図るため」で、辞書形＋ため（目的）として正しい。"}, {"text": "図ります", "is_correct": false, "explanation": "丁寧形のため、「図りますため」は成り立たず、目的を表す文脈と合わない。"}, {"text": "図りなさい", "is_correct": false, "explanation": "命令の丁寧形で、「図りなさいため」は成り立たず、目的を表す文脈と合わない。"}, {"text": "図れば", "is_correct": false, "explanation": "仮定形のため、「図ればため」は成り立たず、目的を表す文脈と合わない。"}], "correct_form": "図る", "base_form": "図る", "form_label": "辞書形", "sentence_index": 7, "explanations": {"図る": "「安全の確保を図るため」で、辞書形＋ため（目的）として正しい。", "図ります": "丁寧形のため、「図りますため」は成り立たず、目的を表す文脈と合わない。", "図りなさい": "命令の丁寧形で、「図りなさいため」は成り立たず、目的を表す文脈と合わない。", "図れば": "仮定形のため、「図ればため」は成り立たず、目的を表す文脈と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38870, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「徐々に」の形で、暖かくなるという変化の様子を修飾する副詞句になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞。「徐々が暖かく」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す助詞。「徐々で暖かく」は文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。「徐々を暖かく」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「徐々に」の形で、暖かくなるという変化の様子を修飾する副詞句になる。", "が": "主語を示す助詞。「徐々が暖かく」は成り立たない。", "で": "場所や手段を示す助詞。「徐々で暖かく」は文が成り立たない。", "を": "目的語を示す助詞。「徐々を暖かく」は成り立たない。"}, "error_tags": {"に": "副詞化（様態）", "が": "主格", "で": "場所・手段", "を": "対格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38870, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「徐々に」の形で、弱くなるという変化の様子を修飾する。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞。「徐々の弱くなり」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。「徐々へ弱く」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞。「徐々から弱く」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「徐々に」の形で、弱くなるという変化の様子を修飾する。", "の": "連体修飾の助詞。「徐々の弱くなり」は文が成り立たない。", "へ": "方向を示す助詞。「徐々へ弱く」は成り立たない。", "から": "起点を示す助詞。「徐々から弱く」は成り立たない。"}, "error_tags": {"に": "副詞化（様態）", "の": "連体修飾", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38870, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "abstract", "definition": "だんだんと、ゆっくり変わっていくこと。", "primary_collocate": null, "pronunciation": "じょじょ", "ipa": "d͡ʑod͡ʑo", "syllable_count": 2, "sentences": [{"text": "薬を飲み始めて三日たち、熱が徐々に下がってきた。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]み始[はじ]めて三日[みっか]たち、熱[ねつ]が徐々[じょじょ]に下[さ]がってきた。", "sentence_source": "generated"}, {"text": "朝は寒かったが、日がのぼると徐々に暖かくなった。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "朝[あさ]は寒[さむ]かったが、日[ひ]がのぼると徐々[じょじょ]に暖[あたた]かくなった。", "sentence_source": "generated"}, {"text": "最初は緊張していたが、徐々に慣れて、笑顔で話せるようになった。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "最初[さいしょ]は緊張[きんちょう]していたが、徐々[じょじょ]に慣[な]れて、笑顔[えがお]で話[はな]せるようになった。", "sentence_source": "generated"}, {"text": "空が徐々に明るくなり、遠くの山が見えてきた。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "空[そら]が徐々[じょじょ]に明[あか]るくなり、遠[とお]くの山[やま]が見[み]えてきた。", "sentence_source": "generated"}, {"text": "日本語は、毎日勉強すれば徐々に上達する。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "日本語[にほんご]は、毎日[まいにち]勉強[べんきょう]すれば徐々[じょじょ]に上達[じょうたつ]する。", "sentence_source": "generated"}, {"text": "雨の音が徐々に小さくなって、やがて静かになった。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "雨[あめ]の音[おと]が徐々[じょじょ]に小[ちい]さくなって、やがて静[しず]かになった。", "sentence_source": "generated"}, {"text": "車は駅を出ると、徐々にスピードを上げていった。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "車[くるま]は駅[えき]を出[で]ると、徐々[じょじょ]にスピードを上[あ]げていった。", "sentence_source": "generated"}, {"text": "痛みは徐々に弱くなり、夜にはほとんど感じなくなった。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "痛[いた]みは徐々[じょじょ]に弱[よわ]くなり、夜[よる]にはほとんど感[かん]じなくなった。", "sentence_source": "generated"}, {"text": "人の数は、夕方から徐々に増えていった。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "人[ひと]の数[かず]は、夕方[ゆうがた]から徐々[じょじょ]に増[ふ]えていった。", "sentence_source": "generated"}, {"text": "一度に変えず、徐々に練習の量を増やしていこう。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "一度[いちど]に変[か]えず、徐々[じょじょ]に練習[れんしゅう]の量[りょう]を増[ふ]やしていこう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "徐々", "label": "基本形"}, {"form": "徐々に", "label": "副詞形"}], "register": "neutral", "sense_fingerprint": "急がず、少しずつゆっくり変化が進む様子。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80324491-1491-4ee3-96f9-8789a18dac12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38870, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "徐々", "is_correct": true, "explanation": "少しずつ変化する意味で、熱が下がっていく様子に合う。"}, {"text": "必ず", "is_correct": false, "explanation": "確実さを表す語で、熱の変化の様子には合わない。「必ずに」は成り立たない。"}, {"text": "決して", "is_correct": false, "explanation": "後に否定が続く語で、ここでは文が成り立たない。"}, {"text": "相変わらず", "is_correct": false, "explanation": "変わらない状態を表し、下がるという変化と合わない。"}], "explanations": {"徐々": "少しずつ変化する意味で、熱が下がっていく様子に合う。", "必ず": "確実さを表す語で、熱の変化の様子には合わない。「必ずに」は成り立たない。", "決して": "後に否定が続く語で、ここでは文が成り立たない。", "相変わらず": "変わらない状態を表し、下がるという変化と合わない。"}, "sentence_index": 0, "correct_answer": "徐々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボールがぶつかった次の瞬間、窓が徐々に割れた。", "explanation": "〈徐々〉は少しずつ進む意味。一瞬で割れる出来事には使えず、〈一瞬で〉が自然。"}, {"text": "サイレンが鳴ると、人が徐々に外へ飛び出した。", "explanation": "〈飛び出す〉は一気に起こる動き。〈一気に〉が合い、〈徐々〉は少しずつの変化を表すので合わない。"}, {"text": "彼は合図を聞いて、一斉に徐々に走り出した。", "explanation": "ここの〈徐々〉は少しずつ進む意味。全員が同時に動き出す場面とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38870, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "徐々", "is_correct": true, "explanation": "少しずつ速度を上げる様子を表し、車が速くなっていく文に合う。"}, {"text": "偶然", "is_correct": false, "explanation": "思いがけない出来事を表す語で、速度を上げる様子とは合わない。"}, {"text": "二度と", "is_correct": false, "explanation": "否定が続く表現で、ここでは文が成り立たない。"}, {"text": "軽々", "is_correct": false, "explanation": "「軽々しく」の意味で、速度の変化を表さず文が成り立たない。"}], "explanations": {"徐々": "少しずつ速度を上げる様子を表し、車が速くなっていく文に合う。", "偶然": "思いがけない出来事を表す語で、速度を上げる様子とは合わない。", "二度と": "否定が続く表現で、ここでは文が成り立たない。", "軽々": "「軽々しく」の意味で、速度の変化を表さず文が成り立たない。"}, "sentence_index": 6, "correct_answer": "徐々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宿題は徐々にまとめてやると、効率がいい。", "explanation": "〈まとめて〉は一度にの意味で、〈徐々〉と矛盾する。〈一度に〉の方が合う。"}, {"text": "合図が鳴ると、全員が徐々に一斉に立ち上がった。", "explanation": "〈一斉に〉は同時の意味で、少しずつ進む〈徐々〉と矛盾する。〈同時に〉の場面では〈徐々〉は使えない。"}, {"text": "先生の質問に、彼女は徐々に即答した。", "explanation": "ここの〈徐々〉は少しずつ進む意味。間を置かずに答えるという意味とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38870, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風邪が治るにつれ、鼻水が徐々減っていった。", "corrected_sentence": "風邪が治るにつれ、鼻水が徐々に減っていった。", "error_description": "誤り：「徐々減っていった」。正しくは「徐々に減っていった」。副詞「徐々」が動詞を修飾するときは「徐々に」の形をとるため、「に」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38870, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "坂道を徐々で登っていく。", "corrected_sentence": "坂道を徐々に登っていく。", "error_description": "誤り：「徐々で」。正しくは「徐々に」。副詞「徐々」は「に」を付けて動詞を修飾する。「で」は場所や手段を示す助詞で、ここでは成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38871, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「徐々に」の形で、変わっていく様子を修飾する副詞句になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞。「徐々が変わっていく」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す助詞。「徐々で変わっていく」は文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。「徐々を変わっていく」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「徐々に」の形で、変わっていく様子を修飾する副詞句になる。", "が": "主語を示す助詞。「徐々が変わっていく」は成り立たない。", "で": "場所や手段を示す助詞。「徐々で変わっていく」は文が成り立たない。", "を": "目的語を示す助詞。「徐々を変わっていく」は成り立たない。"}, "error_tags": {"に": "副詞化（様態）", "が": "主格", "で": "場所・手段", "を": "対格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38871, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「徐々に」の形で、戻っていく様子を修飾する副詞句になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。「徐々を戻りつつ」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞。「徐々から戻りつつ」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞。「徐々の戻りつつ」は文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「徐々に」の形で、戻っていく様子を修飾する副詞句になる。", "を": "目的語を示す助詞。「徐々を戻りつつ」は成り立たない。", "から": "起点を示す助詞。「徐々から戻りつつ」は成り立たない。", "の": "連体修飾の助詞。「徐々の戻りつつ」は文が成り立たない。"}, "error_tags": {"に": "副詞化（様態）", "から": "起点", "の": "連体修飾", "を": "対格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38871, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "abstract", "definition": "変化が少しずつ進むことを表す副詞。", "primary_collocate": null, "pronunciation": "じょじょ", "ipa": "d͡ʑod͡ʑo", "syllable_count": 2, "sentences": [{"text": "町の景気は、徐々にではあるが、回復している。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "町[まち]の景気[けいき]は、徐々[じょじょ]にではあるが、回復[かいふく]している。", "sentence_source": "generated"}, {"text": "季節が進み、木の葉の色が徐々に変わっていく。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "季節[きせつ]が進[すす]み、木[き]の葉[は]の色[いろ]が徐々[じょじょ]に変[か]わっていく。", "sentence_source": "generated"}, {"text": "子どもは成長して、徐々に自分で何でもできるようになった。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "子[こ]どもは成長[せいちょう]して、徐々[じょじょ]に自分[じぶん]で何[なん]でもできるようになった。", "sentence_source": "generated"}, {"text": "水の量を徐々に増やしながら、粉をまぜる。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "水[みず]の量[りょう]を徐々[じょじょ]に増[ふ]やしながら、粉[こな]をまぜる。", "sentence_source": "generated"}, {"text": "実験では、温度を徐々に上げて、変化を記録した。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "実験[じっけん]では、温度[おんど]を徐々[じょじょ]に上[あ]げて、変化[へんか]を記録[きろく]した。", "sentence_source": "generated"}, {"text": "彼女の声は徐々に大きくなり、最後は叫びになった。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の声[こえ]は徐々[じょじょ]に大[おお]きくなり、最後[さいご]は叫[さけ]びになった。", "sentence_source": "generated"}, {"text": "夜が深まるにつれ、町は徐々に静かになった。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "夜[よる]が深[ふか]まるにつれ、町[まち]は徐々[じょじょ]に静[しず]かになった。", "sentence_source": "generated"}, {"text": "湖の水位は、雨のおかげで徐々に戻りつつある。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "湖[みずうみ]の水位[すいい]は、雨[あめ]のおかげで徐々[じょじょ]に戻[もど]りつつある。", "sentence_source": "generated"}, {"text": "慣れるまで、仕事の量は徐々に増やす予定だ。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "慣[な]れるまで、仕事[しごと]の量[りょう]は徐々[じょじょ]に増[ふ]やす予定[よてい]だ。", "sentence_source": "generated"}, {"text": "霧が晴れて、景色が徐々にはっきり見えてきた。", "target_word": "徐々", "complexity_tier": "T3", "furigana": "霧[きり]が晴[は]れて、景色[けしき]が徐々[じょじょ]にはっきり見[み]えてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "徐々", "label": "基本形"}, {"form": "徐々に", "label": "副詞形"}], "register": "neutral", "sense_fingerprint": "変化や動作が少しずつ段階的に進む様子を表す副詞。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80324491-1491-4ee3-96f9-8789a18dac12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38871, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "徐々", "is_correct": true, "explanation": "少しずつ進む意味で、景気が少しずつ回復する文脈に合う。"}, {"text": "さっぱり", "is_correct": false, "explanation": "すっきりした様子を表す語で、景気の回復の進み方には合わない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "眠りの深さを表す語で、景気の話には合わない。"}, {"text": "大急ぎ", "is_correct": false, "explanation": "急いで、の意味で、ゆるやかな回復とは合わない。「大急ぎに」は成り立たない。"}], "explanations": {"徐々": "少しずつ進む意味で、景気が少しずつ回復する文脈に合う。", "さっぱり": "すっきりした様子を表す語で、景気の回復の進み方には合わない。", "ぐっすり": "眠りの深さを表す語で、景気の話には合わない。", "大急ぎ": "急いで、の意味で、ゆるやかな回復とは合わない。「大急ぎに」は成り立たない。"}, "sentence_index": 0, "correct_answer": "徐々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボールを強く投げた瞬間、窓ガラスが徐々に割れた。", "explanation": "ここの〈徐々〉は少しずつ進む意味。一瞬で起きる出来事とは合わない。"}, {"text": "会議の決定事項は、徐々にまとめて発表された。", "explanation": "〈まとめて〉は一度にの意味で、〈徐々〉と矛盾する。〈一度に〉が合う。"}, {"text": "彼は話を聞いて、即座に徐々に反応した。", "explanation": "〈即座に〉は間を置かずの意味で、少しずつ進む〈徐々〉と両立しない。〈すぐに〉が自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38871, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "徐々", "is_correct": true, "explanation": "少しずつ静かになる変化を表し、夜が深まる文脈に合う。"}, {"text": "猛烈に", "is_correct": false, "explanation": "勢いが激しい様子を表し、静かになる変化とは合わない。"}, {"text": "懸命に", "is_correct": false, "explanation": "力を尽くす様子を表し、静かになる変化の説明には合わない。"}, {"text": "今さら", "is_correct": false, "explanation": "今になって、の意味で、変化の様子を表さず文が成り立たない。"}], "explanations": {"徐々": "少しずつ静かになる変化を表し、夜が深まる文脈に合う。", "猛烈に": "勢いが激しい様子を表し、静かになる変化とは合わない。", "懸命に": "力を尽くす様子を表し、静かになる変化の説明には合わない。", "今さら": "今になって、の意味で、変化の様子を表さず文が成り立たない。"}, "sentence_index": 6, "correct_answer": "徐々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ドアを開けると、景色が徐々に一斉に見えた。", "explanation": "〈一斉に〉は同時の意味で、少しずつ見える〈徐々〉と矛盾する。〈一度に〉が合う。"}, {"text": "彼女は宿題を徐々に一度に全部終わらせた。", "explanation": "ここの〈徐々〉は少しずつ進む意味。全部を同時に終わらせる場面とは合わない。"}, {"text": "雷が鳴ると、空が徐々にぴかっと光った。", "explanation": "ここの〈徐々〉は少しずつ進む意味。一瞬で光る様子とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38871, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖の水が徐々の増えてきた。", "corrected_sentence": "湖の水が徐々に増えてきた。", "error_description": "誤り：「徐々の」。正しくは「徐々に」。副詞「徐々」は「に」を付けて動詞を修飾するので、「の」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38871, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜明けにかけて、徐々な変化が続き、景色が見えてきた。", "corrected_sentence": "夜明けにかけて、徐々に変化が続き、景色が見えてきた。", "error_description": "誤り：「徐々な変化」。正しくは「徐々に変化」。「徐々」は副詞なので、「な」を付けて名詞を修飾することはできず、「に」を付けて動詞や名詞句を修飾する。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38872, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「腐植」が「多い」の主語になるので「が」が入る。この位置で文が成り立つ唯一の格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「多い」は形容詞で目的語を取らないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着点や相手を示すが、「腐植に多い」は意味が通らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「腐植で多い」は不自然で合わないため不可。"}], "correct_answer": "が", "explanations": {"が": "「腐植」が「多い」の主語になるので「が」が入る。この位置で文が成り立つ唯一の格助詞。", "を": "「を」は目的語を示すが、「多い」は形容詞で目的語を取らないので合わない。", "に": "「に」は帰着点や相手を示すが、「腐植に多い」は意味が通らないので合わない。", "で": "「で」は場所や手段を示すが、「腐植で多い」は不自然で合わないため不可。"}, "error_tags": {"を": "目的語", "に": "帰着・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38872, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38872, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "土の中で、葉っぱや生き物の死がいが長い時間をかけてこわれてできた、茶色いふかふかしたもの。", "primary_collocate": null, "pronunciation": "ふしょく", "ipa": "ɸɯɕokɯ", "syllable_count": 3, "sentences": [{"text": "森の土には、落ち葉が分解してできた腐植がたくさん含まれている。", "target_word": "腐植", "complexity_tier": "T3", "furigana": "森[もり]の土[つち]には、落[お]ち葉[ば]が分解[ぶんかい]してできた腐植[ふしょく]がたくさん含[ふく]まれている。", "sentence_source": "generated"}, {"text": "腐植が多い土は茶色くて、触るとふかふかしている。", "target_word": "腐植", "complexity_tier": "T3", "furigana": "腐植[ふしょく]が多[おお]い土[つち]は茶色[ちゃいろ]くて、触[さわ]るとふかふかしている。", "sentence_source": "generated"}, {"text": "畑に腐植を入れると、野菜がよく育つ。", "target_word": "腐植", "complexity_tier": "T3", "furigana": "畑[はたけ]に腐植[ふしょく]を入[い]れると、野菜[やさい]がよく育[そだ]つ。", "sentence_source": "generated"}, {"text": "落ち葉は長い時間をかけて腐植になる。", "target_word": "腐植", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]は長[なが]い時間[じかん]をかけて腐植[ふしょく]になる。", "sentence_source": "generated"}, {"text": "砂ばかりの庭には腐植が少なく、植物が育ちにくい。", "target_word": "腐植", "complexity_tier": "T3", "furigana": "砂[すな]ばかりの庭[にわ]には腐植[ふしょく]が少[すく]なく、植物[しょくぶつ]が育[そだ]ちにくい。", "sentence_source": "generated"}, {"text": "森の腐植の層は、足で踏むとやわらかかった。", "target_word": "腐植", "complexity_tier": "T3", "furigana": "森[もり]の腐植[ふしょく]の層[そう]は、足[あし]で踏[ふ]むとやわらかかった。", "sentence_source": "generated"}, {"text": "腐植は茶色くて、土の養分のもとになる。", "target_word": "腐植", "complexity_tier": "T3", "furigana": "腐植[ふしょく]は茶色[ちゃいろ]くて、土[つち]の養分[ようぶん]のもとになる。", "sentence_source": "generated"}, {"text": "先生は、土の中の腐植を虫眼鏡で観察させた。", "target_word": "腐植", "complexity_tier": "T3", "furigana": "先生[せんせい]は、土[つち]の中[なか]の腐植[ふしょく]を虫眼鏡[むしめがね]で観察[かんさつ]させた。", "sentence_source": "generated"}, {"text": "森の木々は、地面に積もった腐植から養分をもらって育つ。", "target_word": "腐植", "complexity_tier": "T3", "furigana": "森[もり]の木々[きぎ]は、地面[じめん]に積[つ]もった腐植[ふしょく]から養分[ようぶん]をもらって育[そだ]つ。", "sentence_source": "generated"}, {"text": "腐植を増やすために、庭に枯れ葉を集めてうめた。", "target_word": "腐植", "complexity_tier": "T3", "furigana": "腐植[ふしょく]を増[ふ]やすために、庭[にわ]に枯[か]れ葉[ば]を集[あつ]めてうめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "腐植", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "落ち葉などが土の中で分解してできる、茶色くふかふかした土の成分。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80324491-1491-4ee3-96f9-8789a18dac12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38872, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腐植", "is_correct": true, "explanation": "落ち葉などが分解してできた土の成分なので、「分解してできた」に合い、ここに入る。"}, {"text": "砂", "is_correct": false, "explanation": "砂は岩が砕けたもので、落ち葉の分解では生じないため「分解してできた」に合わない。"}, {"text": "粘土", "is_correct": false, "explanation": "粘土は鉱物の細粒で、生物の遺体の分解でできるものではないため合わない。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉は植物の生殖に関わる粒で、落ち葉の分解によって生じるものではないため合わない。"}], "explanations": {"腐植": "落ち葉などが分解してできた土の成分なので、「分解してできた」に合い、ここに入る。", "砂": "砂は岩が砕けたもので、落ち葉の分解では生じないため「分解してできた」に合わない。", "粘土": "粘土は鉱物の細粒で、生物の遺体の分解でできるものではないため合わない。", "花粉": "花粉は植物の生殖に関わる粒で、落ち葉の分解によって生じるものではないため合わない。"}, "sentence_index": 0, "correct_answer": "腐植"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "腐植は、生ごみを発酵させて人が作る肥料のことだ。", "explanation": "ここは〈堆肥〉の意味。腐植は自然に分解されて土の中にできる成分で、人が作る肥料とは別のもの。"}, {"text": "腐植は、土の中で有機物を分解する細菌やカビのことだ。", "explanation": "ここは〈微生物〉の意味。腐植は分解されてできた物質で、分解を行う生き物を指す語ではない。"}, {"text": "腐植は、まだ分解されていない落ち葉や枯れ草のことだ。", "explanation": "ここは〈未分解の有機物〉の意味。腐植は分解が進んでできたもので、未分解の落ち葉のことではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38872, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腐植", "is_correct": true, "explanation": "茶色くて土の養分のもとになる物質なので、この文に合いここに入る。"}, {"text": "氷", "is_correct": false, "explanation": "氷は水が凍ったもので、茶色くなく、土の養分のもとにもならないので合わない。"}, {"text": "軽石", "is_correct": false, "explanation": "軽石は火山由来の多孔質の石で、土の養分のもとにはならないため合わない。"}, {"text": "チョコレート", "is_correct": false, "explanation": "チョコレートは食べ物で、茶色いが土の養分のもとにはならないので合わない。"}], "explanations": {"腐植": "茶色くて土の養分のもとになる物質なので、この文に合いここに入る。", "氷": "氷は水が凍ったもので、茶色くなく、土の養分のもとにもならないので合わない。", "軽石": "軽石は火山由来の多孔質の石で、土の養分のもとにはならないため合わない。", "チョコレート": "チョコレートは食べ物で、茶色いが土の養分のもとにはならないので合わない。"}, "sentence_index": 6, "correct_answer": "腐植"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷蔵庫に入れ忘れた肉は、腐植が進んで臭くなった。", "explanation": "ここは〈腐敗〉の意味。腐植は土の中で有機物が分解されてできた成分で、食べ物が傷んで臭くなることには使わないので誤り。"}, {"text": "橋の鉄が腐植して、ぼろぼろになった。", "explanation": "ここは〈腐食〉の意味。腐植は土の中で有機物が分解されてできた成分で、金属がさびて傷むことには使わないので誤り。"}, {"text": "腐植は硬くて、スコップで掘り返すと石のように割れる。", "explanation": "ここは〈土〉の意味。腐植はふかふかした成分で、硬く割れる土のかたまりを指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38872, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "畑の土には、落ち葉が分解してできた腐植を少し混ざっている。", "corrected_sentence": "畑の土には、落ち葉が分解してできた腐植が少し混ざっている。", "error_description": "「混ざる」の主語を示す「が」が「を」になっている。「腐植が混ざる」が正しく、「を」は目的語を示すので文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38872, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "畑の腐植を茶色くて、土を豊かにする。", "corrected_sentence": "畑の腐植は茶色くて、土を豊かにする。", "error_description": "「腐植」に続く係りの助詞が「を」になっている。主題を示す「は」が正しく、「を」では「茶色い」の成り立ちが崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38873, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「腐植を多く含む」の目的語を示す格助詞で、ここに入る。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着点や相手を示すが、「腐植に多く含み」は意味が通らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「腐植で多く含み」は不自然で合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐが、「腐植の多く含み」では文の骨格が成り立たないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「腐植を多く含む」の目的語を示す格助詞で、ここに入る。", "に": "「に」は帰着点や相手を示すが、「腐植に多く含み」は意味が通らないので合わない。", "で": "「で」は場所や手段を示すが、「腐植で多く含み」は不自然で合わない。", "の": "「の」は名詞をつなぐが、「腐植の多く含み」では文の骨格が成り立たないので合わない。"}, "error_tags": {"に": "帰着・相手", "で": "場所・手段", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38873, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38873, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物や動物の死がいなどが微生物によって分解されてできた、暗褐色で有機物に富んだ物質。土壌の肥沃度を高める。", "primary_collocate": null, "pronunciation": "ふしょく", "ipa": "ɸɯɕokɯ", "syllable_count": 3, "sentences": [{"text": "腐植は微生物による有機物の分解で生じ、土壌の肥沃度を高める。", "target_word": "腐植", "complexity_tier": "T4", "furigana": "腐植[ふしょく]は微生物[びせいぶつ]による有機物[ゆうきぶつ]の分解[ぶんかい]で生[しょう]じ、土壌[どじょう]の肥沃度[ひよくど]を高[たか]める。", "sentence_source": "generated"}, {"text": "この土壌は腐植を多く含み、農業に適している。", "target_word": "腐植", "complexity_tier": "T3", "furigana": "この土壌[どじょう]は腐植[ふしょく]を多[おお]く含[ふく]み、農業[のうぎょう]に適[てき]している。", "sentence_source": "generated"}, {"text": "腐植が不足した農地では、作物の収量が低下しやすい。", "target_word": "腐植", "complexity_tier": "T4", "furigana": "腐植[ふしょく]が不足[ふそく]した農地[のうち]では、作物[さくもつ]の収量[しゅうりょう]が低下[ていか]しやすい。", "sentence_source": "generated"}, {"text": "堆肥を継続して施用すると、土壌中の腐植が増加する。", "target_word": "腐植", "complexity_tier": "T4", "furigana": "堆肥[たいひ]を継続[けいぞく]して施用[せよう]すると、土壌中[どじょうちゅう]の腐植[ふしょく]が増加[ぞうか]する。", "sentence_source": "generated"}, {"text": "腐植は水分と養分を保持する力が強い。", "target_word": "腐植", "complexity_tier": "T3", "furigana": "腐植[ふしょく]は水分[すいぶん]と養分[ようぶん]を保持[ほじ]する力[ちから]が強[つよ]い。", "sentence_source": "generated"}, {"text": "森林土壌の表層には、腐植に富む暗褐色の層が発達する。", "target_word": "腐植", "complexity_tier": "T4", "furigana": "森林[しんりん]土壌[どじょう]の表層[ひょうそう]には、腐植[ふしょく]に富[と]む暗褐色[あんかっしょく]の層[そう]が発達[はったつ]する。", "sentence_source": "generated"}, {"text": "研究者は、土壌試料から腐植を抽出して成分を分析した。", "target_word": "腐植", "complexity_tier": "T4", "furigana": "研究者[けんきゅうしゃ]は、土壌[どじょう]試料[しりょう]から腐植[ふしょく]を抽出[ちゅうしゅつ]して成分[せいぶん]を分析[ぶんせき]した。", "sentence_source": "generated"}, {"text": "腐植は暗褐色を呈し、化学的に安定した物質である。", "target_word": "腐植", "complexity_tier": "T4", "furigana": "腐植[ふしょく]は暗褐色[あんかっしょく]を呈[てい]し、化学的[かがくてき]に安定[あんてい]した物質[ぶっしつ]である。", "sentence_source": "generated"}, {"text": "化学肥料だけに頼ると、土壌の腐植が年々減少する。", "target_word": "腐植", "complexity_tier": "T4", "furigana": "化学肥料[かがくひりょう]だけに頼[たよ]ると、土壌[どじょう]の腐植[ふしょく]が年々[ねんねん]減少[げんしょう]する。", "sentence_source": "generated"}, {"text": "腐植の分解速度は、気温と湿度によって大きく異なる。", "target_word": "腐植", "complexity_tier": "T4", "furigana": "腐植[ふしょく]の分解[ぶんかい]速度[そくど]は、気温[きおん]と湿度[しつど]によって大[おお]きく異[こと]なる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "腐植", "label": "基本形"}], "register": "formal", "sense_fingerprint": "動植物の遺体が微生物に分解されてできる、暗褐色の有機物質。土壌科学の用語。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80324491-1491-4ee3-96f9-8789a18dac12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38873, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腐植", "is_correct": true, "explanation": "微生物による有機物の分解で生じ、土壌の肥沃度を高める物質なので、ここに入る。"}, {"text": "石灰", "is_correct": false, "explanation": "石灰は鉱物由来で、有機物の分解によって生じるものではないため合わない。"}, {"text": "粘土", "is_correct": false, "explanation": "粘土は鉱物性の細粒で、微生物による分解で生じるものではないため合わない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は岩石の砕けたもので、有機物の分解とは無関係なので合わない。"}], "explanations": {"腐植": "微生物による有機物の分解で生じ、土壌の肥沃度を高める物質なので、ここに入る。", "石灰": "石灰は鉱物由来で、有機物の分解によって生じるものではないため合わない。", "粘土": "粘土は鉱物性の細粒で、微生物による分解で生じるものではないため合わない。", "砂": "砂は岩石の砕けたもので、有機物の分解とは無関係なので合わない。"}, "sentence_index": 0, "correct_answer": "腐植"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "魚の腐植が進んで、冷蔵庫の中が臭くなった。", "explanation": "ここは〈腐敗〉の意味。腐植は土壌中で分解が進んだ有機物で、食品の傷みを指さないので誤り。"}, {"text": "腐植は、土の中で長い年月をかけて固まった石炭のような燃料だ。", "explanation": "ここは〈化石燃料〉の意味。腐植は暗褐色の有機物で、エネルギー源として燃やす物質ではないので合わない。"}, {"text": "腐植は、落ち葉を積み重ねて人が作る土壌改良材のことだ。", "explanation": "ここは〈腐葉土〉の意味。腐植は土壌中の有機物成分で、人が作る資材を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38873, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腐植", "is_correct": true, "explanation": "土壌中の有機物成分で、化学分析のために抽出される対象なので、ここに入る。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は食品で、土壌試料から抽出して分析する成分ではないので合わない。"}, {"text": "牛乳", "is_correct": false, "explanation": "牛乳は飲み物で、土壌の成分として抽出される物質ではないので合わない。"}, {"text": "ビール", "is_correct": false, "explanation": "ビールは飲み物で、土壌の成分として抽出される物質ではないので合わない。"}], "explanations": {"腐植": "土壌中の有機物成分で、化学分析のために抽出される対象なので、ここに入る。", "砂糖": "砂糖は食品で、土壌試料から抽出して分析する成分ではないので合わない。", "牛乳": "牛乳は飲み物で、土壌の成分として抽出される物質ではないので合わない。", "ビール": "ビールは飲み物で、土壌の成分として抽出される物質ではないので合わない。"}, "sentence_index": 6, "correct_answer": "腐植"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "腐植は気温と湿度によって、ぐんぐん増殖する。", "explanation": "ここは〈微生物〉の意味。腐植は生き物ではないので、増殖するという使い方は誤り。"}, {"text": "船のエンジンの部品が、海水で腐植して使えなくなった。", "explanation": "ここは〈腐食〉の意味。腐植は土の中の有機物を指す語で、金属が海水で傷んでいくことには使わないので誤り。"}, {"text": "腐植は、冬の寒さで凍って、ぱらぱらに砕ける。", "explanation": "ここは〈氷〉の意味。腐植は分解された有機物なので、寒さで固まって砕ける水のような物質ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38873, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この畑は腐植を多く、作物がよく育つ。", "corrected_sentence": "この畑は腐植が多く、作物がよく育つ。", "error_description": "「多い」の主語を示す「が」が「を」になっている。「腐植が多い」が正しく、「を」は目的語を示すので形容詞の文に合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38873, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この実験では、腐植を土壌から抽出された。", "corrected_sentence": "この実験では、腐植が土壌から抽出された。", "error_description": "「抽出された」の主語を示す「が」が「を」になっている。受け身の文では対象を「が」で示すので、「腐植が抽出された」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38874, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「雨の粒」が「当たって」の主語を示す格助詞で、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「雨の粒を当たって」では主語が立たず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「雨の粒に」では主語が立たず、文の骨格が崩れるので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「雨の粒で」では主語が成り立たず、手段の意味にもならないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「雨の粒」が「当たって」の主語を示す格助詞で、ここに入る。", "を": "「を」は目的語を示すが、「雨の粒を当たって」では主語が立たず文が成り立たない。", "に": "「雨の粒に」では主語が立たず、文の骨格が崩れるので合わない。", "で": "「雨の粒で」では主語が成り立たず、手段の意味にもならないので合わない。"}, "error_tags": {"を": "目的語", "に": "帰着・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38874, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「氷の粒」が「溶けた」の主語を示す格助詞で、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「溶けた」は目的語を取らない自動詞なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すが、「氷の粒に溶けた」では主語が立たず合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「氷の粒と溶けた」は意味が通らないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「氷の粒」が「溶けた」の主語を示す格助詞で、ここに入る。", "を": "「を」は目的語を示すが、「溶けた」は目的語を取らない自動詞なので合わない。", "に": "「に」は場所や相手を示すが、「氷の粒に溶けた」では主語が立たず合わない。", "と": "「と」は並列や相手を示すが、「氷の粒と溶けた」は意味が通らないので合わない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38874, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小さくて丸いもののことです。", "primary_collocate": null, "pronunciation": "つぶ", "ipa": "tsɯbɯ", "syllable_count": 2, "sentences": [{"text": "砂の粒が靴の中に入って、歩くと痛い。", "target_word": "粒", "complexity_tier": "T3", "furigana": "砂[すな]の粒[つぶ]が靴[くつ]の中[なか]に入[はい]って、歩[ある]くと痛[いた]い。", "sentence_source": "generated"}, {"text": "雨の粒が窓ガラスに当たって、小さな音を立てた。", "target_word": "粒", "complexity_tier": "T3", "furigana": "雨[あめ]の粒[つぶ]が窓[まど]ガラスに当[あ]たって、小[ちい]さな音[おと]を立[た]てた。", "sentence_source": "generated"}, {"text": "塩の粒が大きいので、舌の上でじゃりじゃりした。", "target_word": "粒", "complexity_tier": "T3", "furigana": "塩[しお]の粒[つぶ]が大[おお]きいので、舌[した]の上[うえ]でじゃりじゃりした。", "sentence_source": "generated"}, {"text": "この薬は小さな粒なので、子どもでも飲みやすい。", "target_word": "粒", "complexity_tier": "T3", "furigana": "この薬[くすり]は小[ちい]さな粒[つぶ]なので、子[こ]どもでも飲[の]みやすい。", "sentence_source": "generated"}, {"text": "朝、草の上に光る水の粒を見つけた。", "target_word": "粒", "complexity_tier": "T3", "furigana": "朝[あさ]、草[くさ]の上[うえ]に光[ひか]る水[みず]の粒[つぶ]を見[み]つけた。", "sentence_source": "generated"}, {"text": "ごまの粒は小さいが、香りがとても強い。", "target_word": "粒", "complexity_tier": "T3", "furigana": "ごまの粒[つぶ]は小[ちい]さいが、香[かお]りがとても強[つよ]い。", "sentence_source": "generated"}, {"text": "粒の大きいぶどうを選んで買った。", "target_word": "粒", "complexity_tier": "T3", "furigana": "粒[つぶ]の大[おお]きいぶどうを選[えら]んで買[か]った。", "sentence_source": "generated"}, {"text": "手のひらに落ちた小さな氷の粒が、すぐに溶けた。", "target_word": "粒", "complexity_tier": "T3", "furigana": "手[て]のひらに落[お]ちた小[ちい]さな氷[こおり]の粒[つぶ]が、すぐに溶[と]けた。", "sentence_source": "generated"}, {"text": "粒がそろった豆は、見た目もきれいだ。", "target_word": "粒", "complexity_tier": "T3", "furigana": "粒[つぶ]がそろった豆[まめ]は、見[み]た目[め]もきれいだ。", "sentence_source": "generated"}, {"text": "机の上に落ちた砂糖の粒を、指で集めた。", "target_word": "粒", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に落[お]ちた砂糖[さとう]の粒[つぶ]を、指[ゆび]で集[あつ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "粒", "label": "基本形"}, {"form": "粒が", "label": "主語の形"}, {"form": "粒を", "label": "目的語の形"}], "register": "neutral", "sense_fingerprint": "砂・雨・塩・薬など、小さくて丸い物そのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80324491-1491-4ee3-96f9-8789a18dac12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38874, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粒", "is_correct": true, "explanation": "小さくて丸い砂の粒を指すので、「砂の___が靴の中に入る」に合いここに入る。"}, {"text": "波", "is_correct": false, "explanation": "波は水面の動きで、靴の中に入るものではないので合わない。"}, {"text": "花", "is_correct": false, "explanation": "花は植物の部分で、砂として靴に入るものではないので合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は空に浮かぶ水滴の集まりで、靴の中に入るものではないので合わない。"}], "explanations": {"粒": "小さくて丸い砂の粒を指すので、「砂の___が靴の中に入る」に合いここに入る。", "波": "波は水面の動きで、靴の中に入るものではないので合わない。", "花": "花は植物の部分で、砂として靴に入るものではないので合わない。", "雲": "雲は空に浮かぶ水滴の集まりで、靴の中に入るものではないので合わない。"}, "sentence_index": 0, "correct_answer": "粒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室に子どもが三粒いる。", "explanation": "ここは〈人を数える語〉の意味。粒は小さく丸いものを数える語で、人を数える語ではないので誤り。"}, {"text": "この粒は大きくて重く、持ち上げにくい。", "explanation": "ここは〈石〉の意味。粒は小さく丸いものを指すので、大きく重い物には使わないので誤り。"}, {"text": "この薬は透明な粒で、一本の糸のようにまっすぐ伸びる。", "explanation": "ここは〈線〉の意味。粒は小さく丸いものを指すので、細長く伸びる線状のものには使わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38874, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粒", "is_correct": true, "explanation": "ぶどうの一つ一つの実の大きさを表す語で、「___の大きいぶどう」に合いここに入る。"}, {"text": "花", "is_correct": false, "explanation": "花は植物の部分で、ぶどうの大きさを説明する語としては合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙はぶどうの大きさを表す語ではないので合わない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は細かい鉱物で、ぶどうの大きさを表す語としては合わない。"}], "explanations": {"粒": "ぶどうの一つ一つの実の大きさを表す語で、「___の大きいぶどう」に合いここに入る。", "花": "花は植物の部分で、ぶどうの大きさを説明する語としては合わない。", "紙": "紙はぶどうの大きさを表す語ではないので合わない。", "砂": "砂は細かい鉱物で、ぶどうの大きさを表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "粒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机の上に鉛筆を三粒並べて、指で集めた。", "explanation": "ここは〈本〉の意味。粒は小さく丸いものを数える語で、細長い鉛筆には使わないので誤り。"}, {"text": "机の上に、一粒のハンカチを広げて、ふき取った。", "explanation": "ここは〈布〉の意味。粒は小さく丸いものを数える語で、広げて使う平たい布には使わないので誤り。"}, {"text": "机の上に落ちた紙の粒を、指で集めた。", "explanation": "ここは〈紙片〉の意味。紙は粒状にはならないので、粒と言うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38874, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海辺の砂の粒を、ビーチサンダルの中に入った。", "corrected_sentence": "海辺の砂の粒が、ビーチサンダルの中に入った。", "error_description": "「入った」の主語を示す「が」が「を」になっている。「粒が入った」が正しく、「を」では目的語になり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38874, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店のぶどうは粒を大きくて、甘みが強い。", "corrected_sentence": "この店のぶどうは粒が大きくて、甘みが強い。", "error_description": "形容詞「大きい」の主語を示す「が」が「を」になっている。「粒が大きい」が正しく、「を」では形容詞の文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38875, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「イクラの粒」が「はじけた」の主語を示す格助詞で、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「はじけた」は目的語を取らない自動詞なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「イクラの粒に口の中ではじけた」では主語が立たず、文の骨格が崩れるので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「イクラの粒で口の中ではじけた」では主語が立たず、文が成り立たないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「イクラの粒」が「はじけた」の主語を示す格助詞で、ここに入る。", "を": "「を」は目的語を示すが、「はじけた」は目的語を取らない自動詞なので合わない。", "に": "「イクラの粒に口の中ではじけた」では主語が立たず、文の骨格が崩れるので合わない。", "で": "「イクラの粒で口の中ではじけた」では主語が立たず、文が成り立たないので合わない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
