INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38875, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小さくて丸い形をしたもの。また、そのような形をした一つ一つのもの。", "primary_collocate": null, "pronunciation": "つぶ", "ipa": "tsɯbɯ", "syllable_count": 2, "sentences": [{"text": "このお米は粒が大きくて、かむと甘みが出る。", "target_word": "粒", "complexity_tier": "T3", "furigana": "このお米[こめ]は粒[つぶ]が大[おお]きくて、かむと甘[あま]みが出[で]る。", "sentence_source": "generated"}, {"text": "イクラの粒が口の中ではじけた。", "target_word": "粒", "complexity_tier": "T3", "furigana": "イクラの粒[つぶ]が口[くち]の中[なか]ではじけた。", "sentence_source": "generated"}, {"text": "涙が大きな粒になって、ほおを流れた。", "target_word": "粒", "complexity_tier": "T3", "furigana": "涙[なみだ]が大[おお]きな粒[つぶ]になって、ほおを流[なが]れた。", "sentence_source": "generated"}, {"text": "このあめは粒が小さいので、一度にたくさん口に入る。", "target_word": "粒", "complexity_tier": "T3", "furigana": "このあめは粒[つぶ]が小[ちい]さいので、一度[いちど]にたくさん口[くち]に入[はい]る。", "sentence_source": "generated"}, {"text": "袋の底に残った粒まで、全部集めて食べた。", "target_word": "粒", "complexity_tier": "T3", "furigana": "袋[ふくろ]の底[そこ]に残[のこ]った粒[つぶ]まで、全部[ぜんぶ]集[あつ]めて食[た]べた。", "sentence_source": "generated"}, {"text": "このジャムはいちごの粒が残っていて、食感がいい。", "target_word": "粒", "complexity_tier": "T3", "furigana": "このジャムはいちごの粒[つぶ]が残[のこ]っていて、食感[しょっかん]がいい。", "sentence_source": "generated"}, {"text": "大きい粒だけを選んで、かごに入れた。", "target_word": "粒", "complexity_tier": "T3", "furigana": "大[おお]きい粒[つぶ]だけを選[えら]んで、かごに入[い]れた。", "sentence_source": "generated"}, {"text": "粒の細かい砂は、手からさらさらとこぼれ落ちる。", "target_word": "粒", "complexity_tier": "T3", "furigana": "粒[つぶ]の細[こま]かい砂[すな]は、手[て]からさらさらとこぼれ落[お]ちる。", "sentence_source": "generated"}, {"text": "粒の小さい種は、土を薄くかけるだけでいい。", "target_word": "粒", "complexity_tier": "T3", "furigana": "粒[つぶ]の小[ちい]さい種[たね]は、土[つち]を薄[うす]くかけるだけでいい。", "sentence_source": "generated"}, {"text": "ガラスの瓶に入った胡椒の粒を、すり鉢ですりつぶした。", "target_word": "粒", "complexity_tier": "T3", "furigana": "ガラスの瓶[びん]に入[はい]った胡椒[こしょう]の粒[つぶ]を、すり鉢[ばち]ですりつぶした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "粒", "label": "基本形"}, {"form": "粒が", "label": "主語の形"}, {"form": "粒の", "label": "連体の形"}], "register": "neutral", "sense_fingerprint": "米・イクラ・涙など、丸い形の一つ一つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80324491-1491-4ee3-96f9-8789a18dac12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38875, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粒", "is_correct": true, "explanation": "お米の一粒一粒を指すので、「お米は___が大きい」に合いここに入る。"}, {"text": "石", "is_correct": false, "explanation": "石はお米の一部ではなく、かむと甘みが出るという文に合わないので不可。"}, {"text": "花", "is_correct": false, "explanation": "花はお米の部分ではないので、ここに入るとお米の説明として成り立たない。"}, {"text": "雲", "is_correct": false, "explanation": "雲はお米の説明に使う語ではないので合わない。"}], "explanations": {"粒": "お米の一粒一粒を指すので、「お米は___が大きい」に合いここに入る。", "石": "石はお米の一部ではなく、かむと甘みが出るという文に合わないので不可。", "花": "花はお米の部分ではないので、ここに入るとお米の説明として成り立たない。", "雲": "雲はお米の説明に使う語ではないので合わない。"}, "sentence_index": 0, "correct_answer": "粒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このうどんは粒が細く長いので、一度に口に入る。", "explanation": "ここは〈麺〉の意味。粒は小さく丸いものを指し、細長いうどんには使わないので誤り。"}, {"text": "机の上に、一粒の箱が置いてある。", "explanation": "ここは〈個〉の意味。粒は小さく丸いものを数える語で、角張った物には使わないので誤り。"}, {"text": "この町は粒が多く、大きなビルが並んでいる。", "explanation": "ここは〈建物〉の意味。粒は小さく丸いものを指すので、大きな建物の並びには使わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38875, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粒", "is_correct": true, "explanation": "大きい粒を一つずつ選んでかごに入れるという文に合い、ここに入る。"}, {"text": "雲", "is_correct": false, "explanation": "雲は空に浮かぶもので、かごに入れることはできないので合わない。"}, {"text": "波", "is_correct": false, "explanation": "波は水の動きで、かごに入れて選ぶものではないので合わない。"}, {"text": "星", "is_correct": false, "explanation": "星は夜空に見えるもので、かごに入れるものではないので合わない。"}], "explanations": {"粒": "大きい粒を一つずつ選んでかごに入れるという文に合い、ここに入る。", "雲": "雲は空に浮かぶもので、かごに入れることはできないので合わない。", "波": "波は水の動きで、かごに入れて選ぶものではないので合わない。", "星": "星は夜空に見えるもので、かごに入れるものではないので合わない。"}, "sentence_index": 6, "correct_answer": "粒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ガラスの瓶に入った椅子の粒を、すり鉢ですりつぶした。", "explanation": "ここは〈家具〉の意味。粒は小さく丸いものを指すので、大きな家具には使わないので誤り。"}, {"text": "ガラスの瓶に入った柱の粒を、すり鉢ですりつぶした。", "explanation": "ここは〈太い棒状の物〉の意味。粒は小さく丸いものを指すので、細長く太い物には使わないので誤り。"}, {"text": "ガラスの瓶に入った船の粒を、すり鉢ですりつぶした。", "explanation": "ここは〈乗り物〉の意味。粒は小さく丸いものを指すので、大きな乗り物には使わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
