INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38875, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭のさくらんぼは粒を大きく、ジャムにするとおいしい。", "corrected_sentence": "庭のさくらんぼは粒が大きく、ジャムにするとおいしい。", "error_description": "形容詞「大きい」の主語を示す「が」が「を」になっている。「粒が大きい」が正しく、「を」では形容詞の文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38876, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遠い", "is_correct": true, "explanation": "「近い」の対義語。距離が大きいことを表す「遠い」が対になる。"}, {"text": "深い", "is_correct": false, "explanation": "「深い」は深さの意味で、「近い」の対義語ではない。"}, {"text": "太い", "is_correct": false, "explanation": "「太い」は太さの意味で、距離の対義語ではない。"}, {"text": "厚い", "is_correct": false, "explanation": "「厚い」は厚みの意味で、距離の対義語ではない。"}], "correct_answer": "遠い", "explanations": {"遠い": "「近い」の対義語。距離が大きいことを表す「遠い」が対になる。", "深い": "「深い」は深さの意味で、「近い」の対義語ではない。", "太い": "「太い」は太さの意味で、距離の対義語ではない。", "厚い": "「厚い」は厚みの意味で、距離の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
