INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38876, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "二つのものの間の距離が小さいこと。", "primary_collocate": null, "pronunciation": "ちかい", "ipa": "tɕikai", "syllable_count": 3, "sentences": [{"text": "家が駅に近いので、毎日歩いて帰る。", "target_word": "近い", "complexity_tier": "T3", "furigana": "家[いえ]が駅[えき]に近[ちか]いので、毎日[まいにち]歩[ある]いて帰[かえ]る。", "sentence_source": "generated"}, {"text": "学校が近いから、朝はゆっくり出られる。", "target_word": "近い", "complexity_tier": "T3", "furigana": "学校[がっこう]が近[ちか]いから、朝[あさ]はゆっくり出[で]られる。", "sentence_source": "generated"}, {"text": "この店は私の会社に近いので、昼によく行く。", "target_word": "近い", "complexity_tier": "T3", "furigana": "この店[みせ]は私[わたし]の会社[かいしゃ]に近[ちか]いので、昼[ひる]によく行[い]く。", "sentence_source": "generated"}, {"text": "海に近い町に住んでいるので、魚がおいしい。", "target_word": "近い", "complexity_tier": "T3", "furigana": "海[うみ]に近[ちか]い町[まち]に住[す]んでいるので、魚[さかな]がおいしい。", "sentence_source": "generated"}, {"text": "病院が近くて、夜に熱が出たときも安心だ。", "target_word": "近く", "complexity_tier": "T3", "furigana": "病院[びょういん]が近[ちか]くて、夜[よる]に熱[ねつ]が出[で]たときも安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "前は家が近かったので、よく友だちが遊びに来た。", "target_word": "近かった", "complexity_tier": "T3", "furigana": "前[まえ]は家[いえ]が近[ちか]かったので、よく友[とも]だちが遊[あそ]びに来[き]た。", "sentence_source": "generated"}, {"text": "窓に近い席は、冬になると少し寒い。", "target_word": "近い", "complexity_tier": "T3", "furigana": "窓[まど]に近[ちか]い席[せき]は、冬[ふゆ]になると少[すこ]し寒[さむ]い。", "sentence_source": "generated"}, {"text": "公園が近ければ、子どもを連れて毎日行けるのに。", "target_word": "近ければ", "complexity_tier": "T3", "furigana": "公園[こうえん]が近[ちか]ければ、子[こ]どもを連[つ]れて毎日[まいにち]行[い]けるのに。", "sentence_source": "generated"}, {"text": "駅に近い部屋は便利だが、家賃が高い。", "target_word": "近い", "complexity_tier": "T3", "furigana": "駅[えき]に近[ちか]い部屋[へや]は便利[べんり]だが、家賃[やちん]が高[たか]い。", "sentence_source": "generated"}, {"text": "空港から近いホテルを予約しておいた。", "target_word": "近い", "complexity_tier": "T3", "furigana": "空港[くうこう]から近[ちか]いホテルを予約[よやく]しておいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "近い", "label": "終止形・連体形"}, {"form": "近く", "label": "連用形"}, {"form": "近かった", "label": "過去形"}, {"form": "近ければ", "label": "仮定形"}, {"form": "近くない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "家・駅・店など、場所と場所の距離が小さい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80324491-1491-4ee3-96f9-8789a18dac12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38876, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近い", "is_correct": true, "explanation": "正解。「駅に近い」で、場所との距離が小さいことを表す。"}, {"text": "高い", "is_correct": false, "explanation": "「駅に高い」では距離を表せない。「高い」は高さや値段の意味。"}, {"text": "重い", "is_correct": false, "explanation": "「重い」は重さの意味で、場所の距離には合わない。"}, {"text": "赤い", "is_correct": false, "explanation": "「赤い」は色の意味で、駅との距離を表せない。"}], "explanations": {"近い": "正解。「駅に近い」で、場所との距離が小さいことを表す。", "高い": "「駅に高い」では距離を表せない。「高い」は高さや値段の意味。", "重い": "「重い」は重さの意味で、場所の距離には合わない。", "赤い": "「赤い」は色の意味で、駅との距離を表せない。"}, "sentence_index": 0, "correct_answer": "近い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この紙は近いので、向こうの字が透けて見える。", "explanation": "ここは〈薄い〉の意味。紙の薄さは〈薄い〉で表し、〈近い〉は距離に使うので合わない。"}, {"text": "今日は帰りが近いので、一緒に夕飯を食べよう。", "explanation": "ここは〈時間的に近い〉の意味。時間の隔たりの義項であり、空間的な距離を表す本義項とは別。"}, {"text": "この箱は近いので、一人では持ち上げられない。", "explanation": "ここは〈重い〉の意味。物の重さは〈重い〉で表し、〈近い〉は距離に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38876, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近い", "is_correct": true, "explanation": "正解。「窓に近い席」で、窓との距離が小さい席を表す。"}, {"text": "柔らかい", "is_correct": false, "explanation": "「柔らかい」は手触りや性質の意味で、窓との距離を表せない。"}, {"text": "軽い", "is_correct": false, "explanation": "「軽い」は重さの意味で、窓との距離には合わない。"}, {"text": "固い", "is_correct": false, "explanation": "「固い」は硬さの意味で、窓との距離を表せない。"}], "explanations": {"近い": "正解。「窓に近い席」で、窓との距離が小さい席を表す。", "柔らかい": "「柔らかい」は手触りや性質の意味で、窓との距離を表せない。", "軽い": "「軽い」は重さの意味で、窓との距離には合わない。", "固い": "「固い」は硬さの意味で、窓との距離を表せない。"}, "sentence_index": 6, "correct_answer": "近い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このコーヒーは近いので、夜も眠れなくなる。", "explanation": "ここは〈濃い〉の意味。飲み物の濃さは〈濃い〉で表し、〈近い〉は距離に使うので合わない。"}, {"text": "行列の待ち時間が近いので、昼食はすぐ食べられた。", "explanation": "ここは〈短い〉の意味。待ち時間の長さは〈短い〉で表し、〈近い〉は二つのものの距離には使わないので合わない。"}, {"text": "この通路は近いので、二人並んで歩くのに困る。", "explanation": "ここは〈狭い〉の意味。通路の幅の小ささは〈狭い〉で表すので、〈近い〉では困る理由が成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38876, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の家は駅を近いので、毎朝歩いて会社へ行く。", "corrected_sentence": "私の家は駅に近いので、毎朝歩いて会社へ行く。", "error_description": "正しくは「駅に近い」。「近い」は基準の場所を助詞「に」で示すので、「駅を」は誤り。助詞「に」が「を」になっている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "近い", "is_correct": true, "explanation": "正解。「学校が近いから」の形。終止形・連体形で、理由の「から」に続く。"}, {"text": "近く", "is_correct": false, "explanation": "連用形。「近くから」とは続かず、理由を述べる文にならない。"}, {"text": "近くて", "is_correct": false, "explanation": "て形。「学校が近くてから」とは続かず、理由の文にならない。"}, {"text": "近ければ", "is_correct": false, "explanation": "仮定形。条件を表す形で、理由を述べる「から」の文とは合わない。"}], "correct_form": "近い", "base_form": "近い", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"近い": "正解。「学校が近いから」の形。終止形・連体形で、理由の「から」に続く。", "近く": "連用形。「近くから」とは続かず、理由を述べる文にならない。", "近くて": "て形。「学校が近くてから」とは続かず、理由の文にならない。", "近ければ": "仮定形。条件を表す形で、理由を述べる「から」の文とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38876, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その店は駅に近くので、昼にいつも混む。", "corrected_sentence": "その店は駅に近いので、昼にいつも混む。", "error_description": "正しくは「近いので」。「ので」の前には終止形・連体形の「近い」が必要で、連用形の「近く」は続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "近ければ", "is_correct": true, "explanation": "正解。「近ければ」の仮定形で、「〜なら」の条件を表す。"}, {"text": "近い", "is_correct": false, "explanation": "終止形・連体形。条件の「ば」に続く形ではないので合わない。"}, {"text": "近さ", "is_correct": false, "explanation": "名詞形。「公園が近さ、」と述語にならず文が成り立たない。"}, {"text": "近くない", "is_correct": false, "explanation": "否定形。「近くなければ」では条件の意味が否定になり、文の意味が変わる。"}], "correct_form": "近ければ", "base_form": "近い", "form_label": "仮定形", "sentence_index": 7, "explanations": {"近ければ": "正解。「近ければ」の仮定形で、「〜なら」の条件を表す。", "近い": "終止形・連体形。条件の「ば」に続く形ではないので合わない。", "近さ": "名詞形。「公園が近さ、」と述語にならず文が成り立たない。", "近くない": "否定形。「近くなければ」では条件の意味が否定になり、文の意味が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38877, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遠い", "is_correct": true, "explanation": "「近い」の対義語。隔たりが大きいことを表す「遠い」が対になる。"}, {"text": "高い", "is_correct": false, "explanation": "「高い」は高さの意味で、「近い」の対義語ではない。"}, {"text": "強い", "is_correct": false, "explanation": "「強い」は力の大きさの意味で、対義語ではない。"}, {"text": "濃い", "is_correct": false, "explanation": "「濃い」は濃度の意味で、対義語ではない。"}], "correct_answer": "遠い", "explanations": {"遠い": "「近い」の対義語。隔たりが大きいことを表す「遠い」が対になる。", "高い": "「高い」は高さの意味で、「近い」の対義語ではない。", "強い": "「強い」は力の大きさの意味で、対義語ではない。", "濃い": "「濃い」は濃度の意味で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38877, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遠い", "is_correct": true, "explanation": "「近い」の対義語。時間の隔たりが大きいことを表す「遠い」が対になる。"}, {"text": "低い", "is_correct": false, "explanation": "「低い」は高さの意味で、時間の隔たりとは関係ない。"}, {"text": "深い", "is_correct": false, "explanation": "「深い」は深さの意味で、対義語ではない。"}, {"text": "厚い", "is_correct": false, "explanation": "「厚い」は厚みの意味で、対義語ではない。"}], "correct_answer": "遠い", "explanations": {"遠い": "「近い」の対義語。時間の隔たりが大きいことを表す「遠い」が対になる。", "低い": "「低い」は高さの意味で、時間の隔たりとは関係ない。", "深い": "「深い」は深さの意味で、対義語ではない。", "厚い": "「厚い」は厚みの意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38877, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "空間的・時間的・心理的な隔たりが少ないさま。", "primary_collocate": null, "pronunciation": "ちかい", "ipa": "tɕikai", "syllable_count": 3, "sentences": [{"text": "試験の日が近いので、毎晩遅くまで勉強している。", "target_word": "近い", "complexity_tier": "T3", "furigana": "試験[しけん]の日[ひ]が近[ちか]いので、毎晩[まいばん]遅[おそ]くまで勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "彼とは年が近いせいか、話がよく合う。", "target_word": "近い", "complexity_tier": "T3", "furigana": "彼[かれ]とは年[とし]が近[ちか]いせいか、話[はなし]がよく合[あ]う。", "sentence_source": "generated"}, {"text": "完成が近いと聞いて、みんな楽しみにしている。", "target_word": "近い", "complexity_tier": "T3", "furigana": "完成[かんせい]が近[ちか]いと聞[き]いて、みんな楽[たの]しみにしている。", "sentence_source": "generated"}, {"text": "二人の考え方は近いので、意見がぶつかることは少ない。", "target_word": "近い", "complexity_tier": "T3", "furigana": "二人[ふたり]の考[かんが]え方[かた]は近[ちか]いので、意見[いけん]がぶつかることは少[すく]ない。", "sentence_source": "generated"}, {"text": "私たちは好みが近いので、一緒に映画をよく見に行く。", "target_word": "近い", "complexity_tier": "T3", "furigana": "私[わたし]たちは好[この]みが近[ちか]いので、一緒[いっしょ]に映画[えいが]をよく見[み]に行[い]く。", "sentence_source": "generated"}, {"text": "夜明けが近いのか、空が少し明るくなってきた。", "target_word": "近い", "complexity_tier": "T3", "furigana": "夜明[よあ]けが近[ちか]いのか、空[そら]が少[すこ]し明[あか]るくなってきた。", "sentence_source": "generated"}, {"text": "彼女は私にとって姉に近い存在だ。", "target_word": "近い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は私[わたし]にとって姉[あね]に近[ちか]い存在[そんざい]だ。", "sentence_source": "generated"}, {"text": "私の気持ちに近い言葉を、辞書で探した。", "target_word": "近い", "complexity_tier": "T3", "furigana": "私[わたし]の気持[きも]ちに近[ちか]い言葉[ことば]を、辞書[じしょ]で探[さが]した。", "sentence_source": "generated"}, {"text": "締め切りが近かったので、徹夜で仕上げた。", "target_word": "近かった", "complexity_tier": "T3", "furigana": "締[し]め切[き]りが近[ちか]かったので、徹夜[てつや]で仕上[しあ]げた。", "sentence_source": "generated"}, {"text": "選挙が近くなると、町にポスターが増える。", "target_word": "近く", "complexity_tier": "T3", "furigana": "選挙[せんきょ]が近[ちか]くなると、町[まち]にポスターが増[ふ]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "近い", "label": "終止形・連体形"}, {"form": "近く", "label": "連用形"}, {"form": "近かった", "label": "過去形"}, {"form": "近ければ", "label": "仮定形"}, {"form": "近くない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "日付・年齢・考え方・気持ちなど、時間や心の隔たりが小さい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80324491-1491-4ee3-96f9-8789a18dac12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38877, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近い", "is_correct": true, "explanation": "正解。「試験の日が近い」で、時間が近づいていることを表す。"}, {"text": "重い", "is_correct": false, "explanation": "「重い」は重さの意味で、試験の日には合わない。"}, {"text": "赤い", "is_correct": false, "explanation": "「赤い」は色の意味で、時間の隔たりを表せない。"}, {"text": "太い", "is_correct": false, "explanation": "「太い」は太さの意味で、時間の隔たりには使えない。"}], "explanations": {"近い": "正解。「試験の日が近い」で、時間が近づいていることを表す。", "重い": "「重い」は重さの意味で、試験の日には合わない。", "赤い": "「赤い」は色の意味で、時間の隔たりを表せない。", "太い": "「太い」は太さの意味で、時間の隔たりには使えない。"}, "sentence_index": 0, "correct_answer": "近い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "返事が近いので、みんな心配していた。", "explanation": "ここは〈遅い〉の意味。返事の遅さは〈遅い〉で表し、〈近い〉は隔たりの小ささを表すので合わない。"}, {"text": "彼の知識は近いので、何でも答えられる。", "explanation": "ここは〈広い〉の意味。知識の範囲の広さは〈広い〉で表すので、〈近い〉は合わない。"}, {"text": "荷物が近いので、タクシーで帰った。", "explanation": "ここは〈重い〉の意味。荷物の重さは〈重い〉で表し、〈近い〉では帰り方を選んだ理由にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38877, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近い", "is_correct": true, "explanation": "正解。「姉に近い存在」で、心理的な隔たりが小さいことを表す。"}, {"text": "柔らかい", "is_correct": false, "explanation": "「柔らかい」は性質の意味で、人との隔たりを表す文には合わない。"}, {"text": "寒い", "is_correct": false, "explanation": "「寒い」は温度の意味で、人との関係には合わない。"}, {"text": "固い", "is_correct": false, "explanation": "「固い」は硬さの意味で、人との心理的な隔たりを表せない。"}], "explanations": {"近い": "正解。「姉に近い存在」で、心理的な隔たりが小さいことを表す。", "柔らかい": "「柔らかい」は性質の意味で、人との隔たりを表す文には合わない。", "寒い": "「寒い」は温度の意味で、人との関係には合わない。", "固い": "「固い」は硬さの意味で、人との心理的な隔たりを表せない。"}, "sentence_index": 6, "correct_answer": "近い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "声が近いので、遠くまで聞こえる。", "explanation": "ここは〈大きい〉の意味。声の大きさは〈大きい〉で表し、〈近い〉は隔たりの小ささを表すので合わない。"}, {"text": "このパンは近いので、かみ切れない。", "explanation": "ここは〈硬い〉の意味。パンの硬さは〈硬い〉で表し、〈近い〉は距離や隔たりに使うので合わない。"}, {"text": "紙が近いので、すぐ破れる。", "explanation": "ここは〈薄い〉の意味。紙の薄さは〈薄い〉で表し、〈近い〉では破れやすさの理由にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38877, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "締め切りが近くので、毎晩遅くまで作業している。", "corrected_sentence": "締め切りが近いので、毎晩遅くまで作業している。", "error_description": "正しくは「近いので」。「ので」の前には終止形・連体形の「近い」が必要で、連用形の「近く」は続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "近い", "is_correct": true, "explanation": "正解。「年が近いせいか」の形。終止形・連体形で、原因を表す「せい」に続く。"}, {"text": "近く", "is_correct": false, "explanation": "連用形。「年が近くせいか」とは続かないので合わない。"}, {"text": "近さ", "is_correct": false, "explanation": "名詞形。「年が近させいか」と続かず文が成り立たない。"}, {"text": "近ければ", "is_correct": false, "explanation": "仮定形。原因を表す「せい」の文には、条件を表す仮定形は合わない。"}], "correct_form": "近い", "base_form": "近い", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"近い": "正解。「年が近いせいか」の形。終止形・連体形で、原因を表す「せい」に続く。", "近く": "連用形。「年が近くせいか」とは続かないので合わない。", "近さ": "名詞形。「年が近させいか」と続かず文が成り立たない。", "近ければ": "仮定形。原因を表す「せい」の文には、条件を表す仮定形は合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38877, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は私にとって兄を近い友人だ。", "corrected_sentence": "彼は私にとって兄に近い友人だ。", "error_description": "正しくは「兄に近い」。「近い」は比べる基準を助詞「に」で示すので、「兄を」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "近い", "is_correct": true, "explanation": "正解。連体形（終止形と同じ形）で、「言葉」を修飾している。"}, {"text": "近かろう", "is_correct": false, "explanation": "推量形。名詞「言葉」を直接修飾できず、文が成り立たない。"}, {"text": "近さ", "is_correct": false, "explanation": "名詞形。「私の気持ちに近さ言葉」と続かず文が成り立たない。"}, {"text": "近くて", "is_correct": false, "explanation": "て形（連用形）。名詞「言葉」を直接修飾できず、「近くて言葉を」とは続かない。"}], "correct_form": "近い", "base_form": "近い", "form_label": "終止形・連体形", "sentence_index": 7, "explanations": {"近い": "正解。連体形（終止形と同じ形）で、「言葉」を修飾している。", "近かろう": "推量形。名詞「言葉」を直接修飾できず、文が成り立たない。", "近さ": "名詞形。「私の気持ちに近さ言葉」と続かず文が成り立たない。", "近くて": "て形（連用形）。名詞「言葉」を直接修飾できず、「近くて言葉を」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38880, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無用", "is_correct": true, "explanation": "「有用」の対義語。役に立たないことを表す「無用」が対になる。"}, {"text": "安全", "is_correct": false, "explanation": "「安全」は危険がないことを表し、対義語ではない。"}, {"text": "簡単", "is_correct": false, "explanation": "「簡単」は手間がかからないことを表し、対義語ではない。"}, {"text": "静か", "is_correct": false, "explanation": "「静か」は音が少ない様子を表し、対義語ではない。"}], "correct_answer": "無用", "explanations": {"無用": "「有用」の対義語。役に立たないことを表す「無用」が対になる。", "安全": "「安全」は危険がないことを表し、対義語ではない。", "簡単": "「簡単」は手間がかからないことを表し、対義語ではない。", "静か": "「静か」は音が少ない様子を表し、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38880, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無用", "is_correct": true, "explanation": "「有用」の対義語。役に立たないことを表す「無用」が対になる。"}, {"text": "丁寧", "is_correct": false, "explanation": "「丁寧」は細かく注意を払う様子で、対義語ではない。"}, {"text": "大切", "is_correct": false, "explanation": "「大切」は重要なことを表し、対義語ではない。"}, {"text": "確実", "is_correct": false, "explanation": "「確実」は間違いないことを表し、対義語ではない。"}], "correct_answer": "無用", "explanations": {"無用": "「有用」の対義語。役に立たないことを表す「無用」が対になる。", "丁寧": "「丁寧」は細かく注意を払う様子で、対義語ではない。", "大切": "「大切」は重要なことを表し、対義語ではない。", "確実": "「確実」は間違いないことを表し、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38880, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても役に立つこと。", "primary_collocate": null, "pronunciation": "ゆうよう", "ipa": "jɯːjoː", "syllable_count": 4, "sentences": [{"text": "このアプリは旅行中にとても有用だった。", "target_word": "有用", "complexity_tier": "T3", "furigana": "このアプリは旅行[りょこう]中[ちゅう]にとても有用[ゆうよう]だった。", "sentence_source": "generated"}, {"text": "先生の助言は、就職活動で有用だった。", "target_word": "有用", "complexity_tier": "T3", "furigana": "先生[せんせい]の助言[じょげん]は、就職[しゅうしょく]活動[かつどう]で有用[ゆうよう]だった。", "sentence_source": "generated"}, {"text": "山で道に迷ったとき、この地図は有用だ。", "target_word": "有用", "complexity_tier": "T3", "furigana": "山[やま]で道[みち]に迷[まよ]ったとき、この地図[ちず]は有用[ゆうよう]だ。", "sentence_source": "generated"}, {"text": "有用な情報が多いので、このサイトを毎日見ている。", "target_word": "有用", "complexity_tier": "T3", "furigana": "有用[ゆうよう]な情報[じょうほう]が多[おお]いので、このサイトを毎日[まいにち]見[み]ている。", "sentence_source": "generated"}, {"text": "古い雑誌でも、料理の記事は今も有用だ。", "target_word": "有用", "complexity_tier": "T3", "furigana": "古[ふる]い雑誌[ざっし]でも、料理[りょうり]の記事[きじ]は今[いま]も有用[ゆうよう]だ。", "sentence_source": "generated"}, {"text": "英語は世界中で通じるので、とても有用な言語だ。", "target_word": "有用", "complexity_tier": "T3", "furigana": "英語[えいご]は世界中[せかいじゅう]で通[つう]じるので、とても有用[ゆうよう]な言語[げんご]だ。", "sentence_source": "generated"}, {"text": "彼のメモは短いが、会議の準備に有用だった。", "target_word": "有用", "complexity_tier": "T3", "furigana": "彼[かれ]のメモは短[みじか]いが、会議[かいぎ]の準備[じゅんび]に有用[ゆうよう]だった。", "sentence_source": "generated"}, {"text": "この道具は小さいわりに有用で、一つあると便利だ。", "target_word": "有用", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は小[ちい]さいわりに有用[ゆうよう]で、一[ひと]つあると便利[べんり]だ。", "sentence_source": "generated"}, {"text": "災害のとき、ラジオは有用な情報源になる。", "target_word": "有用", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、ラジオは有用[ゆうよう]な情報源[じょうほうげん]になる。", "sentence_source": "generated"}, {"text": "有用な本を選んで、友だちに貸してあげた。", "target_word": "有用", "complexity_tier": "T3", "furigana": "有用[ゆうよう]な本[ほん]を選[えら]んで、友[とも]だちに貸[か]してあげた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "有用だ", "label": "終止形"}, {"form": "有用な", "label": "連体形"}, {"form": "有用で", "label": "連用形"}, {"form": "有用だった", "label": "過去形"}, {"form": "有用に", "label": "連用形（に）"}], "register": "formal", "sense_fingerprint": "道具・情報・助言などが、実際にとても役に立つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80324491-1491-4ee3-96f9-8789a18dac12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38880, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有用", "is_correct": true, "explanation": "正解。「旅行中にとても有用だった」で、役に立ったことを表す。"}, {"text": "冷静", "is_correct": false, "explanation": "「冷静」は落ち着いた態度を表し、アプリの性質には合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気」は明るい人柄を表し、アプリには当てはまらない。"}, {"text": "正直", "is_correct": false, "explanation": "「正直」は人の誠実さを表し、アプリには使えない。"}], "explanations": {"有用": "正解。「旅行中にとても有用だった」で、役に立ったことを表す。", "冷静": "「冷静」は落ち着いた態度を表し、アプリの性質には合わない。", "陽気": "「陽気」は明るい人柄を表し、アプリには当てはまらない。", "正直": "「正直」は人の誠実さを表し、アプリには使えない。"}, "sentence_index": 0, "correct_answer": "有用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この切符は今日まで有用だ。", "explanation": "ここは〈有効〉の意味。期限内で使えることは〈有効〉で表し、〈有用〉は役に立つ意味なので合わない。"}, {"text": "この画家は国内で有用だ。", "explanation": "ここは〈有名〉の意味。広く知られていることは〈有名〉で表し、〈有用〉は役に立つ意味で合わない。"}, {"text": "この公園は入場が有用だ。", "explanation": "ここは〈有料〉の意味。料金がかかることは〈有料〉で表し、〈有用〉は役に立つ意味で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38880, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有用", "is_correct": true, "explanation": "正解。「会議の準備に有用だった」で、準備の役に立ったことを表す。"}, {"text": "高価", "is_correct": false, "explanation": "「高価」は値段の高さを表し、準備の役立ち方には合わない。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔」は汚れがない様子を表し、準備には当てはまらない。"}, {"text": "上品", "is_correct": false, "explanation": "「上品」は品のよさを表し、役に立つことは表せない。"}], "explanations": {"有用": "正解。「会議の準備に有用だった」で、準備の役に立ったことを表す。", "高価": "「高価」は値段の高さを表し、準備の役立ち方には合わない。", "清潔": "「清潔」は汚れがない様子を表し、準備には当てはまらない。", "上品": "「上品」は品のよさを表し、役に立つことは表せない。"}, "sentence_index": 6, "correct_answer": "有用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は有用野菜を売っている。", "explanation": "ここは〈有機〉の意味。化学肥料に頼らない栽培は〈有機〉で表し、〈有用〉は役に立つ意味で合わない。"}, {"text": "裁判で有用な判決が出た。", "explanation": "ここは〈有罪〉の意味。罪が認められた判決は〈有罪〉で表し、〈有用〉は役に立つ意味で合わない。"}, {"text": "有用休暇を取って、遊びに行った。", "explanation": "ここは〈有給〉の意味。給料が支払われる休暇は〈有給〉で表し、〈有用〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38880, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この辞書は初心者に有用なだ。", "corrected_sentence": "この辞書は初心者に有用だ。", "error_description": "正しくは「有用だ」。「有用」は「だ」で言い切る形なので、「有用なだ」は誤り。「な」は名詞を修飾する形で、述語には付かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "有用", "is_correct": true, "explanation": "正解。「有用だった」の語幹で、基になる部分。"}, {"text": "有用に", "is_correct": false, "explanation": "連用形（に）。「就職活動で有用にだった」とは続かず、文の述語にならない。"}, {"text": "有用で", "is_correct": false, "explanation": "連用形（で）。「有用でだった」となり、文末の「だった」と続かない。"}, {"text": "有用な", "is_correct": false, "explanation": "連体形。名詞の前に付く形で、「だった」の述語にはならない。"}], "correct_form": "有用", "base_form": "有用だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"有用": "正解。「有用だった」の語幹で、基になる部分。", "有用に": "連用形（に）。「就職活動で有用にだった」とは続かず、文の述語にならない。", "有用で": "連用形（で）。「有用でだった」となり、文末の「だった」と続かない。", "有用な": "連体形。名詞の前に付く形で、「だった」の述語にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38880, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工具は作業を有用で、よく役に立つ。", "corrected_sentence": "この工具は作業に有用で、よく役に立つ。", "error_description": "正しくは「作業に有用」。「有用」は「に」で対象を示すので、「作業を」は誤り。助詞「に」が「を」になっている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "有用", "is_correct": true, "explanation": "正解。語幹で、「有用で」の基になる部分。"}, {"text": "有用性", "is_correct": false, "explanation": "名詞形。「小さいわりに有用性、」と述語で切れず、文が成り立たない。"}, {"text": "有用ならば", "is_correct": false, "explanation": "仮定形。「わりに」に続く述語にならず、文が成り立たない。"}, {"text": "有用さ", "is_correct": false, "explanation": "名詞形。「わりに」に続く述語にならず文が成り立たない。"}], "correct_form": "有用", "base_form": "有用だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"有用": "正解。語幹で、「有用で」の基になる部分。", "有用性": "名詞形。「小さいわりに有用性、」と述語で切れず、文が成り立たない。", "有用ならば": "仮定形。「わりに」に続く述語にならず、文が成り立たない。", "有用さ": "名詞形。「わりに」に続く述語にならず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38881, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無用", "is_correct": true, "explanation": "「有用」の対義語。効果がないことを表す「無用」が対になる。"}, {"text": "厳格", "is_correct": false, "explanation": "「厳格」は規則に厳しい様子を表し、対義語ではない。"}, {"text": "地味", "is_correct": false, "explanation": "「地味」は目立たない様子を表し、対義語ではない。"}, {"text": "重大", "is_correct": false, "explanation": "「重大」は影響が大きい様子を表し、対義語ではない。"}], "correct_answer": "無用", "explanations": {"無用": "「有用」の対義語。効果がないことを表す「無用」が対になる。", "厳格": "「厳格」は規則に厳しい様子を表し、対義語ではない。", "地味": "「地味」は目立たない様子を表し、対義語ではない。", "重大": "「重大」は影響が大きい様子を表し、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
