INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38881, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "役に立つ、または効果がある様子。", "primary_collocate": null, "pronunciation": "ゆうよう", "ipa": "jɯːjoː", "syllable_count": 4, "sentences": [{"text": "雨水を庭にまくのは、水の節約に有用な方法だ。", "target_word": "有用", "complexity_tier": "T3", "furigana": "雨水[あまみず]を庭[にわ]にまくのは、水[みず]の節約[せつやく]に有用[ゆうよう]な方法[ほうほう]だ。", "sentence_source": "generated"}, {"text": "この練習は、発音を直すのに有用だ。", "target_word": "有用", "complexity_tier": "T3", "furigana": "この練習[れんしゅう]は、発音[はつおん]を直[なお]すのに有用[ゆうよう]だ。", "sentence_source": "generated"}, {"text": "短い昼寝は、午後の仕事の効率を上げるのに有用だ。", "target_word": "有用", "complexity_tier": "T3", "furigana": "短[みじか]い昼寝[ひるね]は、午後[ごご]の仕事[しごと]の効率[こうりつ]を上[あ]げるのに有用[ゆうよう]だ。", "sentence_source": "generated"}, {"text": "有用な対策を早く考えなければならない。", "target_word": "有用", "complexity_tier": "T3", "furigana": "有用[ゆうよう]な対策[たいさく]を早[はや]く考[かんが]えなければならない。", "sentence_source": "generated"}, {"text": "運動は健康づくりに有用であると言われている。", "target_word": "有用", "complexity_tier": "T3", "furigana": "運動[うんどう]は健康[けんこう]づくりに有用[ゆうよう]であると言[い]われている。", "sentence_source": "generated"}, {"text": "面接の練習は、緊張をやわらげるのに有用だった。", "target_word": "有用", "complexity_tier": "T3", "furigana": "面接[めんせつ]の練習[れんしゅう]は、緊張[きんちょう]をやわらげるのに有用[ゆうよう]だった。", "sentence_source": "generated"}, {"text": "薬だけでなく、生活習慣の改善も有用だ。", "target_word": "有用", "complexity_tier": "T3", "furigana": "薬[くすり]だけでなく、生活[せいかつ]習慣[しゅうかん]の改善[かいぜん]も有用[ゆうよう]だ。", "sentence_source": "generated"}, {"text": "その方法は有用だと証明されている。", "target_word": "有用", "complexity_tier": "T3", "furigana": "その方法[ほうほう]は有用[ゆうよう]だと証明[しょうめい]されている。", "sentence_source": "generated"}, {"text": "古い知識でも、基礎を学ぶには有用だ。", "target_word": "有用", "complexity_tier": "T3", "furigana": "古[ふる]い知識[ちしき]でも、基礎[きそ]を学[まな]ぶには有用[ゆうよう]だ。", "sentence_source": "generated"}, {"text": "今回の研究で、有用な結果が得られた。", "target_word": "有用", "complexity_tier": "T3", "furigana": "今回[こんかい]の研究[けんきゅう]で、有用[ゆうよう]な結果[けっか]が得[え]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "有用だ", "label": "終止形"}, {"form": "有用な", "label": "連体形"}, {"form": "有用で", "label": "連用形"}, {"form": "有用だった", "label": "過去形"}, {"form": "有用に", "label": "連用形（に）"}], "register": "formal", "sense_fingerprint": "方法・練習・対策などが、目的に対して効果がある", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80324491-1491-4ee3-96f9-8789a18dac12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38881, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有用", "is_correct": true, "explanation": "正解。「水の節約に有用な方法」で、節約に効果がある方法を表す。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気」は明るい人柄の意味で、方法の効果には合わない。"}, {"text": "上品", "is_correct": false, "explanation": "「上品」は品のよさを表し、節約に効果があることは表せない。"}, {"text": "派手", "is_correct": false, "explanation": "「派手」は人目を引く様子で、節約の効果には合わない。"}], "explanations": {"有用": "正解。「水の節約に有用な方法」で、節約に効果がある方法を表す。", "陽気": "「陽気」は明るい人柄の意味で、方法の効果には合わない。", "上品": "「上品」は品のよさを表し、節約に効果があることは表せない。", "派手": "「派手」は人目を引く様子で、節約の効果には合わない。"}, "sentence_index": 0, "correct_answer": "有用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この駐車場は料金が有用だ。", "explanation": "ここは〈有料〉の意味。料金がかかることは〈有料〉で表し、〈有用〉は効果がある意味で合わない。"}, {"text": "この町は有用放送で防災情報を流している。", "explanation": "ここは〈有線〉の意味。電線で送る放送は〈有線〉で表し、〈有用〉は効果がある意味で合わない。"}, {"text": "この木の実は有用なので、子どもに食べさせないでください。", "explanation": "ここは〈有毒〉の意味。体に害がある性質は〈有毒〉で表し、〈有用〉は役に立つ意味で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38881, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有用", "is_correct": true, "explanation": "正解。「生活習慣の改善も有用だ」で、改善が役に立つことを表す。"}, {"text": "豪快", "is_correct": false, "explanation": "「豪快」は大胆で力強い様子の意味で、改善の効果には合わない。"}, {"text": "華麗", "is_correct": false, "explanation": "「華麗」は美しく華やかな様子を表し、効果を表せない。"}, {"text": "無邪気", "is_correct": false, "explanation": "「無邪気」は素直で悪気のない様子で、改善には当てはまらない。"}], "explanations": {"有用": "正解。「生活習慣の改善も有用だ」で、改善が役に立つことを表す。", "豪快": "「豪快」は大胆で力強い様子の意味で、改善の効果には合わない。", "華麗": "「華麗」は美しく華やかな様子を表し、効果を表せない。", "無邪気": "「無邪気」は素直で悪気のない様子で、改善には当てはまらない。"}, "sentence_index": 6, "correct_answer": "有用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この畑は有用肥料で野菜を育てている。", "explanation": "ここは〈有機〉の意味。化学肥料を使わない肥料は〈有機〉で表し、〈有用〉は効果がある意味で合わない。"}, {"text": "被告は有用判決を受けた。", "explanation": "ここは〈有罪〉の意味。罪が認められた判決は〈有罪〉で表し、〈有用〉は合わない。"}, {"text": "このチケットは有用期限が切れた。", "explanation": "ここは〈有効〉の意味。期限内で使えることは〈有効期限〉で表し、〈有用〉は効果がある意味で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38881, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この薬は咳を止めるのに有用なだ。", "corrected_sentence": "この薬は咳を止めるのに有用だ。", "error_description": "正しくは「有用だ」。「有用」は「だ」で言い切る形なので、「有用なだ」は誤り。「な」は連体形で、述語には付かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "有用", "is_correct": true, "explanation": "正解。語幹で、「有用だ」の基になる部分。"}, {"text": "有用な", "is_correct": false, "explanation": "連体形。「直すのに有用な」で止まり、「だ」の述語にならない。"}, {"text": "有用で", "is_correct": false, "explanation": "連用形（で）。述語として完結せず、「だ」の文と合わない。"}, {"text": "有用に", "is_correct": false, "explanation": "連用形（に）。「直すのに有用に」は文の述語にならず、意味も通らない。"}], "correct_form": "有用", "base_form": "有用だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"有用": "正解。語幹で、「有用だ」の基になる部分。", "有用な": "連体形。「直すのに有用な」で止まり、「だ」の述語にならない。", "有用で": "連用形（で）。述語として完結せず、「だ」の文と合わない。", "有用に": "連用形（に）。「直すのに有用に」は文の述語にならず、意味も通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38881, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この練習は子どもを有用だ。", "corrected_sentence": "この練習は子どもに有用だ。", "error_description": "正しくは「子どもに有用だ」。「有用」は「に」で対象を示すので、「子どもを」は誤り。助詞「に」が「を」になっている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "有用", "is_correct": true, "explanation": "正解。語幹で、「有用だ」の基になる部分。"}, {"text": "有用だ", "is_correct": false, "explanation": "終止形。「その方法は有用だだと」となり、「だと」の前で「だ」が重なって文が成り立たない。"}, {"text": "有用さ", "is_correct": false, "explanation": "名詞形。「有用さだと」は文の述語として成り立たず、文が不自然。"}, {"text": "有用ならば", "is_correct": false, "explanation": "仮定形。「と証明」と続かず、文が成り立たない。"}], "correct_form": "有用", "base_form": "有用だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"有用": "正解。語幹で、「有用だ」の基になる部分。", "有用だ": "終止形。「その方法は有用だだと」となり、「だと」の前で「だ」が重なって文が成り立たない。", "有用さ": "名詞形。「有用さだと」は文の述語として成り立たず、文が不自然。", "有用ならば": "仮定形。「と証明」と続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e601ef-ac29-4d1f-b692-c9113a631be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38882, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「入れる」の対象（入れるもの）を示す。正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞だが、トマトは入れられる物なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「サラダに」の「に」がすでにあり、続けて置くと不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を表すが、入れる対象は「を」で示すので合わない。"}], "correct_answer": "を", "explanations": {"を": "「入れる」の対象（入れるもの）を示す。正しい。", "が": "主語を示す助詞だが、トマトは入れられる物なので合わない。", "に": "「サラダに」の「に」がすでにあり、続けて置くと不自然。", "で": "手段を表すが、入れる対象は「を」で示すので合わない。"}, "error_tags": {"が": "主語（入れられる物ではない）", "に": "格助詞の重複（サラダに）", "で": "手段（対象ではない）"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38882, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「切る」の対象（切られるもの）を示す。正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、切る対象は「を」で示すので合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、ここは切られる対象が一つなので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示すが、ここは切る対象を示す場面なので合わない。"}], "correct_answer": "を", "explanations": {"を": "「切る」の対象（切られるもの）を示す。正しい。", "へ": "方向を示すが、切る対象は「を」で示すので合わない。", "と": "並列を示すが、ここは切られる対象が一つなので合わない。", "より": "比較の基準を示すが、ここは切る対象を示す場面なので合わない。"}, "error_tags": {"へ": "方向（切る対象ではない）", "と": "並列（切る対象は一つ）", "より": "比較（切る対象ではない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38882, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あかいやさいで、サラダやスープにいれてたべます。", "primary_collocate": null, "pronunciation": "とまと", "ipa": "tomato", "syllable_count": 3, "sentences": [{"text": "サラダにトマトを入れました。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "サラダにトマトを入[い]れました。", "sentence_source": "generated"}, {"text": "赤いトマトを二つ買いました。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "赤[あか]いトマトを二[ふた]つ買[か]いました。", "sentence_source": "generated"}, {"text": "このトマトはとても甘いです。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "このトマトはとても甘[あま]いです。", "sentence_source": "generated"}, {"text": "庭でトマトを育てています。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "庭[にわ]でトマトを育[そだ]てています。", "sentence_source": "generated"}, {"text": "弟はトマトが苦手で、いつも残します。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "弟[おとうと]はトマトが苦手[にがて]で、いつも残[のこ]します。", "sentence_source": "generated"}, {"text": "トマトをよく洗ってから食べます。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "トマトをよく洗[あら]ってから食[た]べます。", "sentence_source": "generated"}, {"text": "スーパーでトマトが安かったので、たくさん買いました。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "スーパーでトマトが安[やす]かったので、たくさん買[か]いました。", "sentence_source": "generated"}, {"text": "トマトを半分に切って、お皿に置きます。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "トマトを半分[はんぶん]に切[き]って、お皿[さら]に置[お]きます。", "sentence_source": "generated"}, {"text": "夏になると、庭のトマトが赤くなります。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "夏[なつ]になると、庭[にわ]のトマトが赤[あか]くなります。", "sentence_source": "generated"}, {"text": "母はトマトでスープを作ってくれました。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "母[はは]はトマトでスープを作[つく]ってくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "トマト", "label": "基本形"}], "register": "中立", "sense_fingerprint": "赤い実の野菜。サラダやスープに入れて食べる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6435f60-912e-4507-b563-edf7dbd7d03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38882, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "トマト", "is_correct": true, "explanation": "サラダに入れる材料になる野菜で、空欄に入るのはこの語だけ。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下はサラダに入れる食材ではないので、文が成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は食べ物ではなく、サラダに入れると意味が通らない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は食べられないもので、サラダに入れる材料にはならない。"}], "explanations": {"トマト": "サラダに入れる材料になる野菜で、空欄に入るのはこの語だけ。", "靴下": "靴下はサラダに入れる食材ではないので、文が成り立たない。", "手紙": "手紙は食べ物ではなく、サラダに入れると意味が通らない。", "切手": "切手は食べられないもので、サラダに入れる材料にはならない。"}, "sentence_index": 0, "correct_answer": "トマト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "トマトは、ごはんにかけて食べる、ねばねばした豆です。", "explanation": "ここは〈納豆〉の説明。トマトは豆ではなく、ねばねばした食べ物でもない。"}, {"text": "トマトは、牛乳から作る白い食品で、朝ごはんに食べます。", "explanation": "ここは〈ヨーグルト〉の材料と食べ方の説明。トマトは野菜で、牛乳からは作らない。"}, {"text": "トマトは、海苔で包んで食べる、ごはんのかたまりです。", "explanation": "ここは〈おにぎり〉の説明。トマトはごはんではなく、海苔で包むものでもない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38882, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "トマト", "is_correct": true, "explanation": "スーパーで安く売られている野菜で、空欄に入るのはこの語だけ。"}, {"text": "富士山", "is_correct": false, "explanation": "富士山はスーパーで売られるものではないので、文が成り立たない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は空にあるもので、スーパーでは売っていない。"}, {"text": "太陽", "is_correct": false, "explanation": "太陽はスーパーで買えるものではなく、文の意味が通らない。"}], "explanations": {"トマト": "スーパーで安く売られている野菜で、空欄に入るのはこの語だけ。", "富士山": "富士山はスーパーで売られるものではないので、文が成り立たない。", "雲": "雲は空にあるもので、スーパーでは売っていない。", "太陽": "太陽はスーパーで買えるものではなく、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "トマト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "トマトは白くて細長く、おろしにして食べます。", "explanation": "ここは〈大根〉の色と形、食べ方の説明。トマトは赤い実なので、白くはない。"}, {"text": "トマトは、牛乳と卵で焼いて、メープルシロップをかけて食べる菓子です。", "explanation": "ここは〈パンケーキ〉の説明。トマトは野菜で、牛乳と卵で焼く菓子ではない。"}, {"text": "トマトは正月に食べる、柔らかい食べ物です。", "explanation": "ここは〈餅〉の説明。トマトは正月の食べ物ではなく、サラダやスープに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38882, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭でトマトに一つ収穫しました。", "corrected_sentence": "庭でトマトを一つ収穫しました。", "error_description": "「収穫する」の目的語は「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38882, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "トマトがたくさん洗って、冷やしておきます。", "corrected_sentence": "トマトをたくさん洗って、冷やしておきます。", "error_description": "「洗う」の目的語は「を」で示す。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38883, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「切る」「食べる」の対象を示す。正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、トマトは食べられる物なので対象は「を」で示す。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表すが、切られる対象は「を」で示すので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、切る対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「切る」「食べる」の対象を示す。正しい。", "が": "主語を示すが、トマトは食べられる物なので対象は「を」で示す。", "で": "手段・場所を表すが、切られる対象は「を」で示すので合わない。", "へ": "方向を表すので、切る対象にはならない。"}, "error_tags": {"が": "主語（食べられる物ではない）", "で": "手段・場所（対象ではない）", "へ": "方向（対象ではない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38883, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「熟す」の主語を示す。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「熟す」は目的語を取らない自動詞なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を表すが、熟す主体は「が」で示すので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表すので、熟す主体にはならない。"}], "correct_answer": "が", "explanations": {"が": "「熟す」の主語を示す。正しい。", "を": "「熟す」は目的語を取らない自動詞なので合わない。", "に": "相手や場所を表すが、熟す主体は「が」で示すので合わない。", "で": "手段・場所を表すので、熟す主体にはならない。"}, "error_tags": {"を": "自動詞に目的語（熟す）", "に": "相手・場所（主体ではない）", "で": "手段・場所（主体ではない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38883, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "赤くて丸い野菜の一種。生で食べたり、料理に使ったりする。", "primary_collocate": null, "pronunciation": "とまと", "ipa": "tomato", "syllable_count": 3, "sentences": [{"text": "トマトは生で食べてもおいしい野菜です。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "トマトは生[なま]で食[た]べてもおいしい野菜[やさい]です。", "sentence_source": "generated"}, {"text": "昼ごはんにトマトを切って食べました。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "昼[ひる]ごはんにトマトを切[き]って食[た]べました。", "sentence_source": "generated"}, {"text": "トマトを煮て、ソースを作ります。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "トマトを煮[に]て、ソースを作[つく]ります。", "sentence_source": "generated"}, {"text": "このトマトは大きくて丸いです。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "このトマトは大[おお]きくて丸[まる]いです。", "sentence_source": "generated"}, {"text": "畑でトマトを収穫しました。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "畑[はたけ]でトマトを収穫[しゅうかく]しました。", "sentence_source": "generated"}, {"text": "トマトの種をまいて、水をやりました。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "トマトの種[たね]をまいて、水[みず]をやりました。", "sentence_source": "generated"}, {"text": "冷蔵庫にトマトが三つ残っています。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]にトマトが三[みっ]つ残[のこ]っています。", "sentence_source": "generated"}, {"text": "トマトが熟したので、すぐに食べましょう。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "トマトが熟[じゅく]したので、すぐに食[た]べましょう。", "sentence_source": "generated"}, {"text": "サンドイッチにトマトとレタスを入れます。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "サンドイッチにトマトとレタスを入[い]れます。", "sentence_source": "generated"}, {"text": "店で新鮮なトマトを選びました。", "target_word": "トマト", "complexity_tier": "T3", "furigana": "店[みせ]で新鮮[しんせん]なトマトを選[えら]びました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "トマト", "label": "基本形"}], "register": "中立", "sense_fingerprint": "赤くて丸い野菜。生食や料理に使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6435f60-912e-4507-b563-edf7dbd7d03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38883, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "トマト", "is_correct": true, "explanation": "生で食べてもおいしい野菜で、空欄に入るのはこの語だけ。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は食べられないので、生で食べておいしい野菜にはならない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は書くための道具で、野菜ではない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は座るためのもので、野菜ではない。"}], "explanations": {"トマト": "生で食べてもおいしい野菜で、空欄に入るのはこの語だけ。", "石鹸": "石鹸は食べられないので、生で食べておいしい野菜にはならない。", "鉛筆": "鉛筆は書くための道具で、野菜ではない。", "座布団": "座布団は座るためのもので、野菜ではない。"}, "sentence_index": 0, "correct_answer": "トマト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "トマトは、小さくて黒い粒で、すりつぶしてごはんにかけます。", "explanation": "ここは〈ごま〉の形と使い方の説明。トマトは赤い野菜で、すりつぶしてごはんにかけるものではない。"}, {"text": "トマトは海の中で育つ海藻で、味噌汁に入れます。", "explanation": "ここは〈わかめ〉の説明。トマトは陸で育つ野菜で、海藻ではない。"}, {"text": "トマトは、紙に字を書く、細長い棒です。", "explanation": "ここは〈えんぴつ〉の形と使い道の説明。トマトは食べ物で、字を書く道具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38883, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "トマト", "is_correct": true, "explanation": "冷蔵庫に残っていた野菜で、空欄に入るのはこの語だけ。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は冷蔵庫には入らないので、文が成り立たない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は冷蔵庫には入らないので、文の意味が通らない。"}, {"text": "自転車", "is_correct": false, "explanation": "自転車は冷蔵庫には入らないので、残っているという文にならない。"}], "explanations": {"トマト": "冷蔵庫に残っていた野菜で、空欄に入るのはこの語だけ。", "教科書": "教科書は冷蔵庫には入らないので、文が成り立たない。", "座布団": "座布団は冷蔵庫には入らないので、文の意味が通らない。", "自転車": "自転車は冷蔵庫には入らないので、残っているという文にならない。"}, "sentence_index": 6, "correct_answer": "トマト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "トマトは牛乳から作る乳製品で、パンに載せます。", "explanation": "ここは〈チーズ〉の材料と食べ方の説明。トマトは野菜で、牛乳からは作らない。"}, {"text": "トマトは白くて甘い調味料で、紅茶に入れます。", "explanation": "ここは〈砂糖〉の説明。トマトは調味料ではなく、白くもない。"}, {"text": "トマトは、雨の日に広げてさす、布の道具です。", "explanation": "ここは〈傘〉の説明。トマトは食べ物で、雨をよける道具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38883, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝ごはんに、トマトへ一つ食べました。", "corrected_sentence": "朝ごはんに、トマトを一つ食べました。", "error_description": "「食べる」の目的語は「を」で示す。「へ」は方向を表すので誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38883, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "トマトでお皿に並べて、食べましょう。", "corrected_sentence": "トマトをお皿に並べて、食べましょう。", "error_description": "「並べる」の目的語は「を」で示す。「で」は手段を表すので誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38884, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ハーブのおちゃ」と名詞を修飾する「の」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「ハーブがおちゃを飲む」では植物が飲むことになり不自然。"}, {"text": "を", "is_correct": false, "explanation": "「ハーブをおちゃを」と「を」が重なり、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「ハーブにおちゃを飲む」では、飲む相手を示す形が合わない。"}], "correct_answer": "の", "explanations": {"の": "「ハーブのおちゃ」と名詞を修飾する「の」が正しい。", "が": "「ハーブがおちゃを飲む」では植物が飲むことになり不自然。", "を": "「ハーブをおちゃを」と「を」が重なり、不自然。", "に": "「ハーブにおちゃを飲む」では、飲む相手を示す形が合わない。"}, "error_tags": {"が": "主語を示す", "を": "目的語の重複", "に": "相手・対象を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
