INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38884, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "くさやはっぱで、いいにおいがするもの。おちゃやりょうりに使うよ。", "primary_collocate": null, "pronunciation": "はーぶ", "ipa": "haːbɯ", "syllable_count": 3, "sentences": [{"text": "にわで、いいにおいのハーブをそだてています。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "にわで、いいにおいのハーブをそだてています。", "sentence_source": "generated"}, {"text": "ハーブのおちゃを飲むと、ゆっくりできます。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "ハーブのおちゃを飲[の]むと、ゆっくりできます。", "sentence_source": "generated"}, {"text": "このハーブは、さかなりょうりによく合います。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "このハーブは、さかなりょうりによく合[あ]います。", "sentence_source": "generated"}, {"text": "まどの近くに、小さなハーブのはちを置いた。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "まどの近[ちか]くに、小[ちい]さなハーブのはちを置[お]いた。", "sentence_source": "generated"}, {"text": "ハーブの葉をつぶすと、すずしいにおいがします。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "ハーブの葉[は]をつぶすと、すずしいにおいがします。", "sentence_source": "generated"}, {"text": "スープにハーブを入れたら、おいしくなった。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "スープにハーブを入[い]れたら、おいしくなった。", "sentence_source": "generated"}, {"text": "おばあちゃんはハーブをほして、ふくろに入れた。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "おばあちゃんはハーブをほして、ふくろに入[い]れた。", "sentence_source": "generated"}, {"text": "ハーブは日あたりのよいところでよく育ちます。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "ハーブは日[ひ]あたりのよいところでよく育[そだ]ちます。", "sentence_source": "generated"}, {"text": "パンにハーブをのせて、オーブンでやきました。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "パンにハーブをのせて、オーブンでやきました。", "sentence_source": "generated"}, {"text": "スーパーで、新しいハーブを二種類買いました。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "スーパーで、新[あたら]しいハーブを二種類[にしゅるい]買[か]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ハーブ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "においのよい草や葉で、お茶や料理に使うもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ce4cc5-c8da-46a3-b4ee-7c87b1d3a9d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38884, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ハーブ", "is_correct": true, "explanation": "香りのよい草として、庭で育てるものに合う。"}, {"text": "石", "is_correct": false, "explanation": "石は育てる対象ではなく、いいにおいもしないので合わない。"}, {"text": "電池", "is_correct": false, "explanation": "電池は育てられないので、庭でそだてる文には入らない。"}, {"text": "本", "is_correct": false, "explanation": "本は育てられず、いいにおいもしないので合わない。"}], "explanations": {"ハーブ": "香りのよい草として、庭で育てるものに合う。", "石": "石は育てる対象ではなく、いいにおいもしないので合わない。", "電池": "電池は育てられないので、庭でそだてる文には入らない。", "本": "本は育てられず、いいにおいもしないので合わない。"}, "sentence_index": 0, "correct_answer": "ハーブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方、ハーブの電車に乗って家へ帰った。", "explanation": "ここは乗り物の意味。ハーブは植物を指す語で、電車の名前にはならない。"}, {"text": "兄はハーブで、いつも周りを笑わせる。", "explanation": "ここは人を表す意味ではない。ハーブは植物を指す語で、人の性格には使わない。"}, {"text": "大雨で、古いハーブの小屋が流された。", "explanation": "ここは建物の意味ではない。ハーブは植物で、小屋を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38884, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ハーブ", "is_correct": true, "explanation": "干して袋に入れる植物として、この文に合う。"}, {"text": "車", "is_correct": false, "explanation": "車は干せないので、「ほして」と続かない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は干す対象ではなく、ほして袋に入れる文に合わない。"}, {"text": "皿", "is_correct": false, "explanation": "皿は干して袋に入れる物ではなく、この文には合わない。"}], "explanations": {"ハーブ": "干して袋に入れる植物として、この文に合う。", "車": "車は干せないので、「ほして」と続かない。", "手紙": "手紙は干す対象ではなく、ほして袋に入れる文に合わない。", "皿": "皿は干して袋に入れる物ではなく、この文には合わない。"}, "sentence_index": 6, "correct_answer": "ハーブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テストが終わって、ハーブの点数が三十点だった。", "explanation": "ここは点数の意味ではない。ハーブは植物を指す語で、数値の結果には使わない。"}, {"text": "ハーブの試合で、チームが勝った。", "explanation": "ここは競技の意味ではない。ハーブは植物で、試合の名前にはならない。"}, {"text": "夜、ハーブを鳴らして、犬を呼び戻した。", "explanation": "ここは〈鈴〉を鳴らす場面。ハーブは香りのある植物で、音を出す物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38884, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お茶は、ハーブを香りでリラックスできる。", "corrected_sentence": "お茶は、ハーブの香りでリラックスできる。", "error_description": "正しくは「の」（修飾）。「を」は目的語を示すので、「香り」を修飾する必要がある箇所では誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38884, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ハーブに乾かして、瓶に入れた。", "corrected_sentence": "ハーブを乾かして、瓶に入れた。", "error_description": "「に」は誤り。「乾かす」は目的語に「を」を取るので、「ハーブを」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
