INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38885, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "料理やお茶、薬などに使われる、香りのある草や葉のこと。", "primary_collocate": null, "pronunciation": "はーぶ", "ipa": "haːbɯ", "syllable_count": 3, "sentences": [{"text": "ミントは、お茶や菓子に使われる代表的なハーブです。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "ミントは、お茶[ちゃ]や菓子[かし]に使[つか]われる代表的[だいひょうてき]なハーブです。", "sentence_source": "generated"}, {"text": "風邪のときは、ハーブのお茶で体を温めます。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "風邪[かぜ]のときは、ハーブのお茶[ちゃ]で体[からだ]を温[あたた]めます。", "sentence_source": "generated"}, {"text": "肉の臭みを消すために、ハーブを加えて煮込んだ。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "肉[にく]の臭[くさ]みを消[け]すために、ハーブを加[くわ]えて煮込[にこ]んだ。", "sentence_source": "generated"}, {"text": "ハーブには、昔から薬として使われてきたものも多い。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "ハーブには、昔[むかし]から薬[くすり]として使[つか]われてきたものも多[おお]い。", "sentence_source": "generated"}, {"text": "ベランダでハーブを育てると、料理のときにすぐ使える。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "ベランダでハーブを育[そだ]てると、料理[りょうり]のときにすぐ使[つか]える。", "sentence_source": "generated"}, {"text": "このサラダは、ハーブの香りが強くて食べやすい。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "このサラダは、ハーブの香[かお]りが強[つよ]くて食[た]べやすい。", "sentence_source": "generated"}, {"text": "乾燥させたハーブは、瓶に入れて保存します。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "乾燥[かんそう]させたハーブは、瓶[びん]に入[い]れて保存[ほぞん]します。", "sentence_source": "generated"}, {"text": "寝る前にハーブを使ったお茶を飲む人が増えている。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "寝[ね]る前[まえ]にハーブを使[つか]ったお茶[ちゃ]を飲[の]む人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "ハーブの種類によって、香りも効果もちがう。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "ハーブの種類[しゅるい]によって、香[かお]りも効果[こうか]もちがう。", "sentence_source": "generated"}, {"text": "魚にハーブをのせて焼くと、香りがよくなります。", "target_word": "ハーブ", "complexity_tier": "T3", "furigana": "魚[さかな]にハーブをのせて焼[や]くと、香[かお]りがよくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ハーブ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "香りがあり料理・お茶・薬に使う草や葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ce4cc5-c8da-46a3-b4ee-7c87b1d3a9d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38885, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ハーブ", "is_correct": true, "explanation": "代表的な香りの草として、文の主題に合う。"}, {"text": "家電", "is_correct": false, "explanation": "家電は電気製品で、お茶や菓子に使う植物の分類には合わない。"}, {"text": "楽器", "is_correct": false, "explanation": "楽器は音を出す道具で、ミントの分類としては成り立たない。"}, {"text": "文房具", "is_correct": false, "explanation": "文房具は書くための道具で、ミントの説明には合わない。"}], "explanations": {"ハーブ": "代表的な香りの草として、文の主題に合う。", "家電": "家電は電気製品で、お茶や菓子に使う植物の分類には合わない。", "楽器": "楽器は音を出す道具で、ミントの分類としては成り立たない。", "文房具": "文房具は書くための道具で、ミントの説明には合わない。"}, "sentence_index": 0, "correct_answer": "ハーブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜、窓から見える空に、ハーブの星が三つ光った。", "explanation": "ここは〈星〉の意味。ハーブは植物を指す語で、天体の名前にはならない。"}, {"text": "試験の前に、ハーブを一気に読んだ。", "explanation": "ここは本の意味ではない。ハーブは植物で、読む対象にはならない。"}, {"text": "大雨で、古いハーブの橋が流された。", "explanation": "ここは建造物の意味ではない。ハーブは植物で、橋を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38885, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ハーブ", "is_correct": true, "explanation": "乾燥させて瓶に保存する植物として、この文に合う。"}, {"text": "切手", "is_correct": false, "explanation": "切手は紙の証票で、乾燥させて瓶に保存する物ではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は筆記具で、乾燥させて瓶に保存するという文に合わない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は道具で、乾燥させて保存する対象ではない。"}], "explanations": {"ハーブ": "乾燥させて瓶に保存する植物として、この文に合う。", "切手": "切手は紙の証票で、乾燥させて瓶に保存する物ではない。", "鉛筆": "鉛筆は筆記具で、乾燥させて瓶に保存するという文に合わない。", "時計": "時計は道具で、乾燥させて保存する対象ではない。"}, "sentence_index": 6, "correct_answer": "ハーブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜、ハーブの教室で先生に質問をした。", "explanation": "ここは教室（場所）の意味。ハーブは植物を指す語で、部屋の名前にはならない。"}, {"text": "寝る前に、ハーブを閉めて、部屋を暗くした。", "explanation": "ここは〈カーテン〉を閉める場面。ハーブは植物で、閉めて部屋を暗くするものではないので合わない。"}, {"text": "夏は、ハーブの服を着て、外で遊ぶ。", "explanation": "ここは衣類の意味ではない。ハーブは植物で、服の名前にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38885, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ハーブをお茶は、寝る前に飲むと落ち着く。", "corrected_sentence": "ハーブのお茶は、寝る前に飲むと落ち着く。", "error_description": "正しくは「の」（修飾）。「を」は目的語を示すため、「お茶」を修飾する箇所では誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38885, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ハーブに種類を、本に書いておいた。", "corrected_sentence": "ハーブの種類を、本に書いておいた。", "error_description": "「に」は誤り。「種類」を修飾するには「の」が必要で、「ハーブの種類」となる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38886, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「雨水を保水する」で、保水する対象を示す格助詞。正解。"}, {"text": "に", "is_correct": false, "explanation": "「雨水に保水する」は成り立たない。「に」は位置や相手を示すので、対象を示す「を」が合う。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す助詞。「雨水へ保水する」は対象を表せず、不自然になる。"}, {"text": "か", "is_correct": false, "explanation": "「か」は選択・疑問を示す。「雨水か保水する」では保水の対象を示せず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「雨水を保水する」で、保水する対象を示す格助詞。正解。", "に": "「雨水に保水する」は成り立たない。「に」は位置や相手を示すので、対象を示す「を」が合う。", "へ": "「へ」は方向を示す助詞。「雨水へ保水する」は対象を表せず、不自然になる。", "か": "「か」は選択・疑問を示す。「雨水か保水する」では保水の対象を示せず、文が成り立たない。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "か": "選択・疑問"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38886, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38886, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "水をよく保つこと。", "primary_collocate": null, "pronunciation": "ほすい", "ipa": "hosɯi", "syllable_count": 3, "sentences": [{"text": "森は雨水をためて、保水の役割を果たしている。", "target_word": "保水", "complexity_tier": "T3", "furigana": "森(もり)は雨水(あまみず)をためて、保水(ほすい)の役割(やくわり)を果(は)たしている。", "sentence_source": "generated"}, {"text": "田んぼには大雨のときに雨水を保水する働きがある。", "target_word": "保水", "complexity_tier": "T3", "furigana": "田[た]んぼには大雨[おおあめ]のときに雨水[あまみず]を保水[ほすい]する働[はたら]きがある。", "sentence_source": "generated"}, {"text": "乾燥した季節は、土の保水が大切になる。", "target_word": "保水", "complexity_tier": "T3", "furigana": "乾燥(かんそう)した季節(きせつ)は、土(つち)の保水(ほすい)が大切(たいせつ)になる。", "sentence_source": "generated"}, {"text": "畑に落ち葉をかぶせると、保水ができて水やりが減る。", "target_word": "保水", "complexity_tier": "T3", "furigana": "畑(はたけ)に落(お)ち葉(ば)をかぶせると、保水(ほすい)ができて水(みず)やりが減(へ)る。", "sentence_source": "generated"}, {"text": "山の木が切られて、保水がうまくできなくなった。", "target_word": "保水", "complexity_tier": "T3", "furigana": "山(やま)の木(き)が切(き)られて、保水(ほすい)がうまくできなくなった。", "sentence_source": "generated"}, {"text": "森の土は雨を保水するので、川の水があふれにくくなる。", "target_word": "保水", "complexity_tier": "T3", "furigana": "森[もり]の土[つち]は雨[あめ]を保水[ほすい]するので、川[かわ]の水[みず]があふれにくくなる。", "sentence_source": "generated"}, {"text": "公園の地面を土にして、雨の保水を助けている。", "target_word": "保水", "complexity_tier": "T3", "furigana": "公園(こうえん)の地面(じめん)を土(つち)にして、雨(あめ)の保水(ほすい)を助(たす)けている。", "sentence_source": "generated"}, {"text": "農家は、夏の暑さに備えて畑の保水に力を入れている。", "target_word": "保水", "complexity_tier": "T3", "furigana": "農家(のうか)は、夏(なつ)の暑(あつ)さに備(そな)えて畑(はたけ)の保水(ほすい)に力(ちから)を入(い)れている。", "sentence_source": "generated"}, {"text": "屋上に草を植えると、雨水を保水できる。", "target_word": "保水", "complexity_tier": "T3", "furigana": "屋上(おくじょう)に草(くさ)を植(う)えると、雨水(あまみず)を保水(ほすい)できる。", "sentence_source": "generated"}, {"text": "保水が足りないと、田んぼの稲は枯れてしまう。", "target_word": "保水", "complexity_tier": "T3", "furigana": "保水(ほすい)が足(た)りないと、田(た)んぼの稲(いね)は枯(か)れてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "保水する", "label": "する動詞 終止形"}, {"form": "保水した", "label": "過去形"}, {"form": "保水して", "label": "て形"}, {"form": "保水できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "土や森などが水をためて保つはたらき・行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0ba49d-53ab-4293-8df9-17352c973537') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38886, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保水", "is_correct": true, "explanation": "「森は雨水をためて、〇〇の役割を果たしている」の空所に入る語。雨水をためる働きを指すので文脈に合う。"}, {"text": "流出", "is_correct": false, "explanation": "流出は水が外へ流れ出ること。雨水をためるという文脈と逆になるので合わない。"}, {"text": "蒸発", "is_correct": false, "explanation": "蒸発は水分が気体になって消えること。水をためて役立てる役割とは逆になる。"}, {"text": "排水", "is_correct": false, "explanation": "排水は余分な水を外へ流すこと。雨水をためる役割とは逆向きの働きになる。"}], "explanations": {"保水": "「森は雨水をためて、〇〇の役割を果たしている」の空所に入る語。雨水をためる働きを指すので文脈に合う。", "流出": "流出は水が外へ流れ出ること。雨水をためるという文脈と逆になるので合わない。", "蒸発": "蒸発は水分が気体になって消えること。水をためて役立てる役割とは逆になる。", "排水": "排水は余分な水を外へ流すこと。雨水をためる役割とは逆向きの働きになる。"}, "sentence_index": 0, "correct_answer": "保水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このポットは中のお湯を保水するので、一日じゅう熱いままだ。", "explanation": "ここは〈保温〉の意味。保水は水分をためて保つことで、熱を保つ意味にはならないので合わない。"}, {"text": "台風が来る前に、窓ガラスを保水しておいた。", "explanation": "ここは〈保護〉の意味。保水は水を保つことで、物を衝撃から守る意味にはならないので合わない。"}, {"text": "倉庫には、去年の書類を保水してある。", "explanation": "ここは〈保管〉の意味。保水は水分を保つことで、書類をしまっておく意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38886, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保水", "is_correct": true, "explanation": "「雨の〇〇を助けている」の空所に入る語。土にして雨をためる働きを助けるという文脈に合う。"}, {"text": "舗装", "is_correct": false, "explanation": "舗装は道路などを固めること。雨の働きを助ける文脈とはつながらない。"}, {"text": "日照", "is_correct": false, "explanation": "日照は日の光が当たること。雨の何を助けるのか合わず、文が成り立たない。"}, {"text": "乾燥", "is_correct": false, "explanation": "乾燥は水分がなくなること。雨を助けるという文脈と逆になる。"}], "explanations": {"保水": "「雨の〇〇を助けている」の空所に入る語。土にして雨をためる働きを助けるという文脈に合う。", "舗装": "舗装は道路などを固めること。雨の働きを助ける文脈とはつながらない。", "日照": "日照は日の光が当たること。雨の何を助けるのか合わず、文が成り立たない。", "乾燥": "乾燥は水分がなくなること。雨を助けるという文脈と逆になる。"}, "sentence_index": 6, "correct_answer": "保水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い機械は、毎月保水すれば故障しにくくなる。", "explanation": "ここは〈保守〉の意味。保水は水を保つことで、機械を点検・整備する意味にはならないので合わない。"}, {"text": "その件の返事は、来週まで保水しておいてください。", "explanation": "ここは〈保留〉の意味。保水は水分を保つことで、結論や返事を先送りする意味にはならない。"}, {"text": "この車は、事故に備えて保水に入っている。", "explanation": "ここは〈保険〉の意味。保水は水を保つことで、万一に備える契約の意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38886, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "森は雨水に保水して、川の水が急に増えるのを防ぐ。", "corrected_sentence": "森は雨水を保水して、川の水が急に増えるのを防ぐ。", "error_description": "「雨水を保水する」のように、保水する対象は「を」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38886, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地面は保水を乏しいので、大雨のあとすぐに水があふれる。", "corrected_sentence": "この地面は保水に乏しいので、大雨のあとすぐに水があふれる。", "error_description": "「乏しい」は「に」で続ける。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
