INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38887, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物質が水分を保持する性質や能力。", "primary_collocate": null, "pronunciation": "ほすい", "ipa": "hosɯi", "syllable_count": 3, "sentences": [{"text": "このスポンジは保水に優れていて、水をたくさん吸う。", "target_word": "保水", "complexity_tier": "T3", "furigana": "このスポンジは保水(ほすい)に優(すぐ)れていて、水(みず)をたくさん吸(す)う。", "sentence_source": "generated"}, {"text": "砂は保水に乏しいので、すぐに水が下へ流れてしまう。", "target_word": "保水", "complexity_tier": "T3", "furigana": "砂(すな)は保水(ほすい)に乏(とぼ)しいので、すぐに水(みず)が下(した)へ流(なが)れてしまう。", "sentence_source": "generated"}, {"text": "黒い土は保水がよく、花が長く元気に育つ。", "target_word": "保水", "complexity_tier": "T3", "furigana": "黒(くろ)い土(つち)は保水(ほすい)がよく、花(はな)が長(なが)く元気(げんき)に育(そだ)つ。", "sentence_source": "generated"}, {"text": "この培養土は保水に優れていて、鉢植えの水切れを防ぐ。", "target_word": "保水", "complexity_tier": "T3", "furigana": "この培養土[ばいようど]は保水[ほすい]に優[すぐ]れていて、鉢植[はちう]えの水切[みずぎ]れを防[ふせ]ぐ。", "sentence_source": "generated"}, {"text": "この土壌改良材は保水に優れ、乾燥した畑でも水分を保つ。", "target_word": "保水", "complexity_tier": "T3", "furigana": "この土壌改良材[どじょうかいりょうざい]は保水[ほすい]に優[すぐ]れ、乾燥[かんそう]した畑[はたけ]でも水分[すいぶん]を保[たも]つ。", "sentence_source": "generated"}, {"text": "ガーデニングでは、保水と水はけの両方を考えて土を選ぶ。", "target_word": "保水", "complexity_tier": "T3", "furigana": "ガーデニングでは、保水(ほすい)と水(みず)はけの両方(りょうほう)を考(かんが)えて土(つち)を選(えら)ぶ。", "sentence_source": "generated"}, {"text": "古い土は保水が弱くなり、水やりをしてもすぐ乾く。", "target_word": "保水", "complexity_tier": "T3", "furigana": "古[ふる]い土[つち]は保水[ほすい]が弱[よわ]くなり、水[みず]やりをしてもすぐ乾[かわ]く。", "sentence_source": "generated"}, {"text": "苔は保水に優れた植物で、雨のあとも長く湿っている。", "target_word": "保水", "complexity_tier": "T3", "furigana": "苔(こけ)は保水(ほすい)に優(すぐ)れた植物(しょくぶつ)で、雨(あめ)のあとも長(なが)く湿(しめ)っている。", "sentence_source": "generated"}, {"text": "鉢植えの土を選ぶときは、保水のよさを比べるとよい。", "target_word": "保水", "complexity_tier": "T3", "furigana": "鉢植(はちう)えの土(つち)を選(えら)ぶときは、保水(ほすい)のよさを比(くら)べるとよい。", "sentence_source": "generated"}, {"text": "保水の弱い土では、毎日水をやらないと花が枯れる。", "target_word": "保水", "complexity_tier": "T3", "furigana": "保水(ほすい)の弱(よわ)い土(つち)では、毎日(まいにち)水(みず)をやらないと花(はな)が枯(か)れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "保水する", "label": "する動詞 終止形"}, {"form": "保水した", "label": "過去形"}, {"form": "保水して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "土・布・スポンジなど物質が持つ水分を抱える性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0ba49d-53ab-4293-8df9-17352c973537') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38887, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保水", "is_correct": true, "explanation": "「このスポンジは〇〇に優れていて、水をたくさん吸う」の空所に入る語。水分を抱える性質を表し、文脈に合う。"}, {"text": "撥水", "is_correct": false, "explanation": "撥水は水をはじく性質。水をたくさん吸うという後半と逆になるので合わない。"}, {"text": "排水", "is_correct": false, "explanation": "排水は余分な水を外へ流すこと。水をたくさん吸うという後半と逆になるので合わない。"}, {"text": "硬度", "is_correct": false, "explanation": "硬度は物の硬さ。水を吸う性質を説明する文脈には合わない。"}], "explanations": {"保水": "「このスポンジは〇〇に優れていて、水をたくさん吸う」の空所に入る語。水分を抱える性質を表し、文脈に合う。", "撥水": "撥水は水をはじく性質。水をたくさん吸うという後半と逆になるので合わない。", "排水": "排水は余分な水を外へ流すこと。水をたくさん吸うという後半と逆になるので合わない。", "硬度": "硬度は物の硬さ。水を吸う性質を説明する文脈には合わない。"}, "sentence_index": 0, "correct_answer": "保水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この毛布は綿でできていて、体温を保水する性質がある。", "explanation": "ここは〈保温〉の意味。保水は水分を抱える性質で、体温を保つ意味にはならないので合わない。"}, {"text": "この強化ガラスは、外からの衝撃を保水する力が高い。", "explanation": "ここは〈保護〉の意味。保水は水分を抱える力で、衝撃から守る意味にはならないので合わない。"}, {"text": "この貯金箱は、小銭を長く保水しておける。", "explanation": "ここは〈保管〉の意味。保水は水分を抱える性質で、物をしまっておく意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38887, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保水", "is_correct": true, "explanation": "「古い土は〇〇が弱くなり、水やりをしてもすぐ乾く」の空所に入る語。水分を抱える力が弱まると乾きやすくなる文脈に合う。"}, {"text": "粘度", "is_correct": false, "explanation": "粘度は液体のねばり具合を表す。土が乾く仕組みとは関係しないので合わない。"}, {"text": "防音", "is_correct": false, "explanation": "防音は音を遮ること。水分が乾くことには関係しないので合わない。"}, {"text": "光沢", "is_correct": false, "explanation": "光沢は表面の艶。土が乾く仕組みを述べる文脈には合わない。"}], "explanations": {"保水": "「古い土は〇〇が弱くなり、水やりをしてもすぐ乾く」の空所に入る語。水分を抱える力が弱まると乾きやすくなる文脈に合う。", "粘度": "粘度は液体のねばり具合を表す。土が乾く仕組みとは関係しないので合わない。", "防音": "防音は音を遮ること。水分が乾くことには関係しないので合わない。", "光沢": "光沢は表面の艶。土が乾く仕組みを述べる文脈には合わない。"}, "sentence_index": 6, "correct_answer": "保水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は保水を考えて、本当のことを言わなかった。", "explanation": "ここは〈保身〉の意味。保水は水分を抱える性質で、自分を守るための判断の意味にはならないので合わない。"}, {"text": "その契約の判断は、保水しておこう。", "explanation": "ここは〈保留〉の意味。保水は水分を保つことで、判断を先送りする意味にはならないので合わない。"}, {"text": "学校では、毎朝子どもたちの保水をしている。", "explanation": "ここは〈保健〉の意味。保水は水分を抱える性質で、子どもの健康を管理する意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38887, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この布は保水を優れていて、汗をすばやく吸う。", "corrected_sentence": "この布は保水に優れていて、汗をすばやく吸う。", "error_description": "「優れる」は「に」で続けるので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38887, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "堆肥を混ぜると、保水をよくなり、水やりの回数が減る。", "corrected_sentence": "堆肥を混ぜると、保水がよくなり、水やりの回数が減る。", "error_description": "「よくなる」は「が」で続けるので、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
