INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38889, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "いちじるしいこと。よく目立つこと。", "primary_collocate": null, "pronunciation": "けんちょ", "ipa": "keɲtɕo", "syllable_count": 3, "sentences": [{"text": "彼女は新人の中でも、顕著な活躍をした。", "target_word": "顕著", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は新人(しんじん)の中(なか)でも、顕著(けんちょ)な活躍(かつやく)をした。", "sentence_source": "generated"}, {"text": "このチームは、守りの強さが顕著な特徴だ。", "target_word": "顕著", "complexity_tier": "T3", "furigana": "このチームは、守(まも)りの強(つよ)さが顕著(けんちょ)な特徴(とくちょう)だ。", "sentence_source": "generated"}, {"text": "顕著な業績をあげた研究者が、賞を受けた。", "target_word": "顕著", "complexity_tier": "T3", "furigana": "顕著(けんちょ)な業績(ぎょうせき)をあげた研究者(けんきゅうしゃ)が、賞(しょう)を受(う)けた。", "sentence_source": "generated"}, {"text": "都市部では、人口の高齢化が顕著になっている。", "target_word": "顕著", "complexity_tier": "T3", "furigana": "都市部(としぶ)では、人口(じんこう)の高齢化(こうれいか)が顕著(けんちょ)になっている。", "sentence_source": "generated"}, {"text": "この魚は、背中の青い模様が顕著で、遠くからでもすぐ分かる。", "target_word": "顕著", "complexity_tier": "T3", "furigana": "この魚(さかな)は、背中(せなか)の青(あお)い模様(もよう)が顕著(けんちょ)で、遠(とお)くからでもすぐ分(わ)かる。", "sentence_source": "generated"}, {"text": "この地方の方言は、語尾の変化が顕著だ。", "target_word": "顕著", "complexity_tier": "T3", "furigana": "この地方(ちほう)の方言(ほうげん)は、語尾(ごび)の変化(へんか)が顕著(けんちょ)だ。", "sentence_source": "generated"}, {"text": "今年の新入生は、女子の割合の増加が顕著だった。", "target_word": "顕著", "complexity_tier": "T3", "furigana": "今年(ことし)の新入生(しんにゅうせい)は、女子(じょし)の割合(わりあい)の増加(ぞうか)が顕著(けんちょ)だった。", "sentence_source": "generated"}, {"text": "売り上げの伸びでは、ネット販売が顕著だった。", "target_word": "顕著", "complexity_tier": "T3", "furigana": "売(う)り上(あ)げの伸(の)びでは、ネット販売(はんばい)が顕著(けんちょ)だった。", "sentence_source": "generated"}, {"text": "彼の絵には、明るい色づかいという顕著な個性がある。", "target_word": "顕著", "complexity_tier": "T3", "furigana": "彼(かれ)の絵(え)には、明(あか)るい色(いろ)づかいという顕著(けんちょ)な個性(こせい)がある。", "sentence_source": "generated"}, {"text": "他の店と比べて、この店の安さは顕著だ。", "target_word": "顕著", "complexity_tier": "T3", "furigana": "他(ほか)の店(みせ)と比(くら)べて、この店(みせ)の安(やす)さは顕著(けんちょ)だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "顕著だ", "label": "終止形"}, {"form": "顕著な", "label": "連体形"}, {"form": "顕著に", "label": "連用形"}, {"form": "顕著で", "label": "て形・中止形"}, {"form": "顕著だった", "label": "過去形"}], "register": "neutral-formal (plain written style)", "sense_fingerprint": "特徴・活躍・傾向などが他と比べて際立って目立つようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: 色づか (Zipf 1.64)']::text[], '9a0ba49d-53ab-4293-8df9-17352c973537') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38889, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顕著", "is_correct": true, "explanation": "「彼女は新人の中でも、〇〇な活躍をした」の空所に入る語。新人の中でも目立つ活躍を表し、文脈に合う。"}, {"text": "平凡", "is_correct": false, "explanation": "平凡は特に目立たないこと。「新人の中でも」という目立つ文脈と逆になる。"}, {"text": "軽微", "is_correct": false, "explanation": "軽微は程度が小さいこと。際立った活躍という文脈とは合わない。"}, {"text": "不明瞭", "is_correct": false, "explanation": "不明瞭ははっきりしないこと。目立つ活躍を述べる文脈と合わない。"}], "explanations": {"顕著": "「彼女は新人の中でも、〇〇な活躍をした」の空所に入る語。新人の中でも目立つ活躍を表し、文脈に合う。", "平凡": "平凡は特に目立たないこと。「新人の中でも」という目立つ文脈と逆になる。", "軽微": "軽微は程度が小さいこと。際立った活躍という文脈とは合わない。", "不明瞭": "不明瞭ははっきりしないこと。目立つ活躍を述べる文脈と合わない。"}, "sentence_index": 0, "correct_answer": "顕著"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は顕著に取り組んでいる。", "explanation": "ここは〈熱心〉の意味。顕著は目立つことで、意欲が強く一生懸命な様子は表さないので合わない。"}, {"text": "店員は客の質問に顕著に答えた。", "explanation": "ここは〈丁寧〉の意味。顕著は目立つことで、ていねいに対応する意味にはならないので合わない。"}, {"text": "彼は顕著な勧誘に押され、断りきれなかった。", "explanation": "ここは〈強引〉の意味。顕著は目立つことで、無理に押し通す様子は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38889, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顕著", "is_correct": true, "explanation": "「女子の割合の増加が〇〇だった」の空所に入る語。目立って増えたという文脈に合う。"}, {"text": "皆無", "is_correct": false, "explanation": "皆無は全くないこと。増加があったという文と矛盾するので合わない。"}, {"text": "不変", "is_correct": false, "explanation": "不変は変わらないこと。増加があったという文と矛盾するので合わない。"}, {"text": "雑多", "is_correct": false, "explanation": "雑多は種類が入り混じっていること。割合の増加を述べる文脈には合わない。"}], "explanations": {"顕著": "「女子の割合の増加が〇〇だった」の空所に入る語。目立って増えたという文脈に合う。", "皆無": "皆無は全くないこと。増加があったという文と矛盾するので合わない。", "不変": "不変は変わらないこと。増加があったという文と矛盾するので合わない。", "雑多": "雑多は種類が入り混じっていること。割合の増加を述べる文脈には合わない。"}, "sentence_index": 6, "correct_answer": "顕著"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店員は顕著な対応をしたが、客の顔も見ずに機械的に手続きを進めた。", "explanation": "ここは〈誠実〉の意味。顕著は目立つことで、心のこもった誠実な態度は表さないので合わない。"}, {"text": "彼は顕著に計画を立てた。", "explanation": "ここは〈慎重〉の意味。顕著は目立つことで、注意深く行う意味にはならないので合わない。"}, {"text": "彼は顕著な食べっぷりで、皆を驚かせた。", "explanation": "ここは〈豪快〉の意味。顕著は目立つことで、勢いよく大胆に振る舞う意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38889, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この選手は、リーグ戦で顕著活躍を見せた。", "corrected_sentence": "この選手は、リーグ戦で顕著な活躍を見せた。", "error_description": "名詞「活躍」を修飾するには連体形の「な」が要る。「な」が抜けているのが誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "顕著な", "is_correct": true, "explanation": "連体形。「守りの強さが顕著な特徴だ」と名詞を修飾するので正解。"}, {"text": "顕著だ", "is_correct": false, "explanation": "終止形。「顕著だ特徴」と名詞の前に置けず、成り立たない。"}, {"text": "顕著ならば", "is_correct": false, "explanation": "条件形（〜ならば）。名詞「特徴」の前には置けず、「顕著ならば特徴だ」は成り立たない。"}, {"text": "顕著に", "is_correct": false, "explanation": "連用形。名詞を修飾できず、「顕著に特徴」は成り立たない。"}], "correct_form": "顕著な", "base_form": "顕著だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"顕著な": "連体形。「守りの強さが顕著な特徴だ」と名詞を修飾するので正解。", "顕著だ": "終止形。「顕著だ特徴」と名詞の前に置けず、成り立たない。", "顕著ならば": "条件形（〜ならば）。名詞「特徴」の前には置けず、「顕著ならば特徴だ」は成り立たない。", "顕著に": "連用形。名詞を修飾できず、「顕著に特徴」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38889, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店の客足は、夜に顕著が増えた。", "corrected_sentence": "この店の客足は、夜に顕著に増えた。", "error_description": "動詞「増えた」を修飾するには連用形の「に」が要る。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "顕著だった", "is_correct": true, "explanation": "過去形。「ネット販売が顕著だった。」と文末で述語になるので正解。"}, {"text": "顕著なら", "is_correct": false, "explanation": "条件の形（〜なら）。文末で切れず、「ネット販売が顕著なら。」は述語として完結しない。"}, {"text": "顕著であれば", "is_correct": false, "explanation": "仮定形。条件を表すので、ここで文が切れず「顕著であれば。」は不完全になる。"}, {"text": "顕著であって", "is_correct": false, "explanation": "て形（である系）。後ろに続けないと文が切れず、「ネット販売が顕著であって。」は不完全になる。"}], "correct_form": "顕著だった", "base_form": "顕著だ", "form_label": "過去形", "sentence_index": 7, "explanations": {"顕著だった": "過去形。「ネット販売が顕著だった。」と文末で述語になるので正解。", "顕著なら": "条件の形（〜なら）。文末で切れず、「ネット販売が顕著なら。」は述語として完結しない。", "顕著であれば": "仮定形。条件を表すので、ここで文が切れず「顕著であれば。」は不完全になる。", "顕著であって": "て形（である系）。後ろに続けないと文が切れず、「ネット販売が顕著であって。」は不完全になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e9de33-42bc-4c5d-8d25-170fc957d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
