INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38890, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「原資を集める」の目的語を示し、集める対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "主格を示すが、集める対象にはならない。"}, {"text": "や", "is_correct": false, "explanation": "並列の「や」は単独の名詞に続けると「集める」の対象にならず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、集める対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「原資を集める」の目的語を示し、集める対象を表す。", "が": "主格を示すが、集める対象にはならない。", "や": "並列の「や」は単独の名詞に続けると「集める」の対象にならず、文が成り立たない。", "の": "連体修飾の助詞で、集める対象にはならない。"}, "error_tags": {"が": "主格（主語）", "や": "並列（不完全）", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38890, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを作るもとになるお金やもののこと。", "primary_collocate": null, "pronunciation": "げんし", "ipa": "ɡeɲɕi", "syllable_count": 3, "sentences": [{"text": "新しい店を開く原資は、長年の貯金だった。", "target_word": "原資", "complexity_tier": "T3", "furigana": "あたらしいみせをひらくげんしは、ながねんのちょきんだった。", "sentence_source": "generated"}, {"text": "この基金の原資は、市民からの寄付である。", "target_word": "原資", "complexity_tier": "T3", "furigana": "このききんのげんしは、しみんからのきふである。", "sentence_source": "generated"}, {"text": "原資が足りなくて、計画を始められなかった。", "target_word": "原資", "complexity_tier": "T3", "furigana": "げんしがたりなくて、けいかくをはじめられなかった。", "sentence_source": "generated"}, {"text": "年金の原資を守るために、国は運用を見直した。", "target_word": "原資", "complexity_tier": "T3", "furigana": "ねんきんのげんしをまもるために、くにはうんようをみなおした。", "sentence_source": "generated"}, {"text": "彼は祖父からもらった遺産を原資にして、小さな会社を作った。", "target_word": "原資", "complexity_tier": "T3", "furigana": "かれはそふからもらったいさんをげんしにして、ちいさなかいしゃをつくった。", "sentence_source": "generated"}, {"text": "研究の原資は、会社が出してくれることになった。", "target_word": "原資", "complexity_tier": "T3", "furigana": "けんきゅうのげんしは、かいしゃがだしてくれることになった。", "sentence_source": "generated"}, {"text": "原資が少ないので、まず小さな商品から作ることにした。", "target_word": "原資", "complexity_tier": "T3", "furigana": "げんしがすくないので、まずちいさなしょうひんからつくることにした。", "sentence_source": "generated"}, {"text": "学校の建て直しの原資を集めるため、バザーが開かれた。", "target_word": "原資", "complexity_tier": "T3", "furigana": "がっこうのたてなおしのげんしをあつめるため、バザーがひらかれた。", "sentence_source": "generated"}, {"text": "税金を原資とする事業は、使い道を公開する必要がある。", "target_word": "原資", "complexity_tier": "T3", "furigana": "ぜいきんをげんしとするじぎょうは、つかいみちをこうかいするひつようがある。", "sentence_source": "generated"}, {"text": "町の祭りの原資は、店の人たちの会費でまかなわれている。", "target_word": "原資", "complexity_tier": "T3", "furigana": "まちのまつりのげんしは、みせのひとたちのかいひでまかなわれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原資", "label": "基本形"}], "register": "formal", "sense_fingerprint": "事業や基金などを成り立たせるもとになるお金や財産", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2bc8fb-5cad-4828-a8e5-f8d473bc523b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
